/* ============================================================================
   Design tokens — every colour in this file resolves through one of these
   semantic vars. Light is the default :root; [data-theme="dark"] re-points the
   same names. AntD components are themed separately in theme.ts (darkAlgorithm).
   ========================================================================== */
:root {
  color-scheme: light;
  /* surfaces: base = canvas, raised = cards/nav/rows/popovers (in dark, higher = lighter) */
  --bg-base: #ffffff;
  --bg-raised: #ffffff;
  --bg-subtle: #fafbfc;
  --bg-sunken: #f7f8fa;
  --bg-hover: #f5f6f7;
  --bg-hover-strong: #e3e6eb;
  --fill-muted: #f1f1f4;
  /* A panel sunk into whatever surface it sits on. Deliberately translucent, unlike --bg-sunken:
     the opaque one only reads as recessed against the one surface it was picked for, and lands
     as a bright hole on any tinted card (a warning's amber, notably). Alpha per theme because
     one value cannot span "white page" and "dark card". */
  --fill-inset: rgba(0, 0, 0, 0.05);
  --border: #dee0e3;
  --border-subtle: #eceef1;
  --scrollbar-hover: #c9cdd4;
  /* text, four steps + idle dot */
  --text-1: #1f2329;
  --text-2: #646a73;
  --text-3: #8f959e;
  --text-4: #a8acb3;
  --dot-idle: #c0c4cc;
  /* brand */
  --brand: #3370ff;
  --brand-strong: #245ae0;
  --brand-tint: #eaf1ff;
  --brand-tint-hover: #e1ebff;
  --brand-border: #bcd3ff;
  /* status: fg / solid dot / tint bg / border */
  --success: #1a7f37;
  --success-solid: #2ea121;
  --success-bg: #e8f6ec;
  --success-border: #b6e7c4;
  --error: #cf3b35;
  --error-solid: #d4380d;
  --error-bg: #fdeceb;
  --error-border: #ffccc7;
  --warning: #c2710c;
  --warning-solid: #fa8c16;
  --warning-bg: #fff4e6;
  --warning-border: #ffd591;
  /* what smart model selection would have picked, on a run that kept the agent's own model */
  --route-shadow: #5b2fb8;
  /* high-contrast inverted button (dark CTA on light, light CTA on dark) */
  --invert-surface: #1f2329;
  --invert-surface-hover: #000000;
  --invert-text: #ffffff;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg-base: #202023;
  --bg-raised: #2b2b2e;
  --bg-subtle: #252528;
  --bg-sunken: #17171a;
  --bg-hover: #343437;
  --bg-hover-strong: #424246;
  --fill-muted: #38383c;
  /* 0.25 so a panel on --bg-raised lands where --bg-base used to: the depth dark mode already
     had, now reproduced on tinted cards too. */
  --fill-inset: rgba(0, 0, 0, 0.25);
  --border: #424246;
  --border-subtle: #343437;
  --scrollbar-hover: #565a62;
  --text-1: #c9ced5;
  --text-2: #a7adb6;
  --text-3: #8b9099;
  --text-4: #71767f;
  --dot-idle: #4a4e56;
  --brand: #5b8cff;
  --brand-strong: #7aa2ff;
  --brand-tint: rgba(91, 140, 255, 0.16);
  --brand-tint-hover: rgba(91, 140, 255, 0.24);
  --brand-border: rgba(91, 140, 255, 0.32);
  --success: #4ac26b;
  --success-solid: #3fb45b;
  --success-bg: rgba(46, 161, 33, 0.18);
  --success-border: rgba(46, 161, 33, 0.35);
  --error: #f0837b;
  --error-solid: #e5613c;
  --error-bg: rgba(245, 74, 69, 0.16);
  --error-border: rgba(245, 74, 69, 0.38);
  --warning: #e0a23b;
  --warning-solid: #e0902b;
  --warning-bg: rgba(250, 140, 22, 0.15);
  --warning-border: rgba(250, 140, 22, 0.38);
  --route-shadow: #b69cf5;
  --invert-surface: #e6e8eb;
  --invert-surface-hover: #ffffff;
  --invert-text: #16171a;
}

/* dark adjustments for things that can't be a single token */
:root[data-theme='dark'] .chat-tool-card {
  --tone: #47474c;
  --tone-bg: #343437;
}
:root[data-theme='dark'] .chat-tone-read {
  --tone: #5b8cff;
  --tone-bg: rgba(91, 140, 255, 0.16);
}
:root[data-theme='dark'] .chat-tone-exec {
