  --tone-bg: rgba(13, 148, 136, 0.18);
}
:root[data-theme='dark'] .chat-tone-write {
  --tone: #e0a23b;
  --tone-bg: rgba(217, 119, 6, 0.18);
}
:root[data-theme='dark'] .chat-tone-agent {
  --tone: #a78bfa;
  --tone-bg: rgba(124, 58, 237, 0.22);
}
:root[data-theme='dark'] .chat-tool-task .chat-tool-row {
