}
:root[data-theme='dark'] .chat-tool-task .chat-tool-row:hover {
  background: rgba(124, 58, 237, 0.16);
}
/* elevated popovers need a deeper shadow to read against a dark surface */
:root[data-theme='dark'] .composer-slash-menu {
