}
:root[data-theme='dark'] .hljs-keyword,
:root[data-theme='dark'] .hljs-selector-tag,
:root[data-theme='dark'] .hljs-literal,
:root[data-theme='dark'] .hljs-type {
  color: #ff7b72;
}
:root[data-theme='dark'] .hljs-string,
:root[data-theme='dark'] .hljs-meta .hljs-string,
:root[data-theme='dark'] .hljs-regexp {
  color: #a5d6ff;
}
:root[data-theme='dark'] .hljs-number,
:root[data-theme='dark'] .hljs-symbol,
:root[data-theme='dark'] .hljs-attr,
:root[data-theme='dark'] .hljs-template-variable,
:root[data-theme='dark'] .hljs-variable {
  color: #79c0ff;
}
:root[data-theme='dark'] .hljs-title,
:root[data-theme='dark'] .hljs-section,
:root[data-theme='dark'] .hljs-function .hljs-title {
  color: #d2a8ff;
}
:root[data-theme='dark'] .hljs-built_in,
:root[data-theme='dark'] .hljs-name,
:root[data-theme='dark'] .hljs-attribute {
  color: #ffa657;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* The height every full-viewport shell measures itself against. It has to be the *small*
   viewport: iOS Safari resolves both `height: 100%` (against the ICB) and `100dvh` to the
   LARGE viewport — the height with the browser toolbars collapsed — so a shell sized either
   way runs ~110px past the fold on an iPhone and the tail of any inner scroller (the session
   list) can never be scrolled into view. `svh` is the height that is always visible; because
   these shells own their scrolling and never let the document scroll, the toolbars never
   collapse, so svh stays exact and leaves no dead band. Use it for anything full-height. */
:root {
  --app-vh: 100svh;
}

html,
body,
#root {
  height: var(--app-vh);
  margin: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Hiragino Sans GB',
    'Microsoft YaHei', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  color: var(--text-1);
  background: var(--bg-base);
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-hover);
}
/* A list marked .autohide-scrollbar shows its thumb only while it scrolls (lib/scrollbarAutohide
   sets data-scrolling for that long) or while the pointer is on it, to grab it. The gutter stays
   either way, so nothing shifts when the thumb appears. */
.autohide-scrollbar:not([data-scrolling])::-webkit-scrollbar-thumb {
  background: transparent;
}
.autohide-scrollbar::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-hover);
}

/* Off-screen but still in the accessibility tree — the toast live region (see lib/toast.tsx). */
.sr-only {
  position: absolute;
  overflow: hidden;
  clip-path: inset(50%);
  width: 1px;
  height: 1px;
  white-space: nowrap;
}

/* ---- Toasts (components/ToastViewport.tsx, docs/mocks/toast-system) ----
   One column in the top-right corner. The transcript is a growing content stream, so a centred
   overlay lands right on whatever you just scrolled to; the corner keeps the conversation column
   and the session title clear. What waits for you — a failure — is pinned at the top of the column
   and stays until its ×; what passes stacks under it, newest last. A phone centres the column under
   its top bar instead. The column takes no clicks, and neither does a pill that names nothing:
   they float over the header band, whose controls stay live. Toasts that do something opt back in
   (`.toast--live`). */
.toast-layer {
  position: fixed; inset: 0; margin: 0; padding: 0; border: 0;
  width: auto; height: auto; overflow: visible; background: transparent; color: inherit;
  pointer-events: none;
}
.toast-layer::backdrop { background: transparent; pointer-events: none; }
.toast-viewport {
  /* A modal may own the portal; keep the body's typography for stack controls. */
  font-size: 1rem;
  line-height: 1.15;
  position: fixed;
  z-index: 2050;
  top: calc(env(safe-area-inset-top, 0px) + 16px);
  right: max(16px, env(safe-area-inset-right, 0px));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  width: 360px;
  max-width: calc(100vw - 32px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
  pointer-events: none;
}
.toast-viewport--narrow {
  top: calc(env(safe-area-inset-top, 0px) + 56px);
  left: max(16px, env(safe-area-inset-left, 0px));
  width: auto;
  max-width: none;
  align-items: center;
}
.toast-slot {
  width: fit-content;
  max-width: 100%;
  animation: orbit-toast-enter 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.toast-slot:has(.toast--card) {
  width: 100%;
}
.toast-slot--leaving .toast {
  pointer-events: none;
}
.toast {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  border: 1px solid var(--border-subtle);
  background: var(--bg-raised);
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.12);
  color: var(--text-1);
  font: inherit;
  font-size: 14px;
  line-height: 20px;
  text-align: start;
  /* Keep the original card's rasterization when its host enters the top layer. */
  will-change: transform;
}
:root[data-theme='dark'] .toast {
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.4);
}
.toast--live {
  pointer-events: auto;
}
/* ① a confirmation and a progress line: a pill that hugs its words. */
.toast--pill {
  gap: 8px;
  max-width: 100%;
  min-height: 36px;
  padding: 7px 16px 7px 10px;
  border-radius: 999px;
}
button.toast--pill {
  cursor: pointer;
}
button.toast--pill:hover {
  background: var(--bg-hover);
}
/* ② and ③: a card as wide as the column. */
.toast--card {
  width: 100%;
  min-height: 56px;
  padding: 12px 12px 12px 14px;
  border-radius: 12px;
}
/* ③: tinted over the raised surface (the dark theme's tints are translucent), the server's words
   in a block of their own, and selectable — the thing you read twice and paste somewhere. */
.toast--attention {
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
  user-select: text;
}
.toast--error {
  border-color: var(--error-border);
  background: linear-gradient(var(--error-bg), var(--error-bg)), var(--bg-raised);
}
.toast--warning {
  border-color: var(--warning-border);
  background: linear-gradient(var(--warning-bg), var(--warning-bg)), var(--bg-raised);
}
.toast-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.toast-glyph {
  flex: none;
  font-size: 20px;
  line-height: 0;
}
.toast--pill .toast-glyph {
  font-size: 18px;
}
.toast-glyph--success {
  color: var(--success-solid);
}
.toast-glyph--info {
  color: var(--brand);
}
.toast-glyph--neutral {
  color: var(--text-3);
}
.toast-glyph--warning {
  color: var(--warning-solid);
}
.toast-glyph--error {
  color: var(--error-solid);
}
.toast-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.toast--pill .toast-copy {
  flex: 0 1 auto;
  gap: 0;
}
.toast-copy--link {
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
}
.toast-copy--link:hover .toast-head {
  color: var(--brand);
}
.toast-head {
  font-weight: 600;
  overflow-wrap: anywhere;
}
.toast-sub {
  overflow: hidden;
  color: var(--text-3);
  font-size: 13px;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.toast-detail {
  color: var(--text-2);
  font-size: 13px;
  line-height: 18px;
  overflow-wrap: anywhere;
}
.toast-reason {
  max-height: 108px;
  margin-left: 32px;
  overflow: auto;
  padding: 7px 10px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-raised);
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12px;
  line-height: 18px;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}
.toast-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-left: 32px;
}
.toast-action {
  flex: none;
  height: 28px;
  padding: 0 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  background: var(--bg-raised);
  color: var(--text-1);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.toast-action:hover {
  background: var(--bg-hover);
}
.toast-action--primary {
  border-color: var(--brand);
  background: var(--brand);
  color: #fff;
}
.toast-action--primary:hover {
  border-color: var(--brand-strong);
  background: var(--brand-strong);
}
/* A result card's one action — Undo — in the tint the lifecycle card's Undo always had. */
.toast--card:not(.toast--attention) > .toast-action {
  border-color: var(--brand-tint);
  background: var(--brand-tint);
  color: var(--brand);
}
.toast--card:not(.toast--attention) > .toast-action:hover {
  background: var(--brand-tint-hover);
}
.toast-close {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 20px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-3);
  font-size: 13px;
  cursor: pointer;
}
.toast-close:hover {
  color: var(--text-1);
}
.toast-count {
  flex: none;
  padding: 0 7px;
  border-radius: 9px;
  background: var(--error-solid);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  line-height: 18px;
}
.toast-chev {
  flex: none;
  color: var(--text-3);
  font-size: 11px;
}
.toast-more {
  pointer-events: auto;
  margin-top: -2px;
  padding: 3px 12px;
  border: 1px solid var(--error-border);
  border-radius: 999px;
  background: linear-gradient(var(--error-bg), var(--error-bg)), var(--bg-raised);
  color: var(--error);
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
}
.toast-copy--link:focus-visible,
.toast-action:focus-visible,
.toast-close:focus-visible,
.toast-more:focus-visible,
button.toast--pill:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}

/* Cards in the corner arrive from the side the corner is on, subtly — anchored to the header rather
   than flying in from off-screen; a phone's centred column drops in from under its top bar. */
@keyframes orbit-toast-enter {
  from {
    opacity: 0;
    transform: translate3d(16px, 0, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes orbit-toast-drop {
  from {
    opacity: 0;
    transform: translate3d(0, -12px, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.toast-viewport--narrow .toast-slot {
  animation-name: orbit-toast-drop;
}
.toast-viewport .toast-slot--leaving {
  animation: orbit-toast-exit 250ms ease-in forwards;
}

@keyframes orbit-toast-exit {
  from { opacity: 1; transform: none; }
  to { opacity: 0; transform: translate3d(0, -12px, 0); }
}
@keyframes orbit-toast-fade {
  from { opacity: 1; }
  to { opacity: 0; }
}

@media (pointer: coarse) {
  .toast-action {
    min-height: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast-viewport .toast-slot {
    animation: none;
  }
  .toast-viewport .toast-slot--leaving {
    animation: orbit-toast-fade 250ms ease-in forwards;
  }
}

/* ---- App shell: side nav | main region (master/detail) ---- */
.app-shell {
  display: flex;
  height: var(--app-vh);
}
.app-main {
  flex: 1;
  min-width: 0;
  height: var(--app-vh);
  overflow: hidden;
}
/* A view fills the main region. .app-view--doc adds the page gutter and owns its
   scroll; the bare class is full-bleed (the agent console / runner install guide). */
.app-view {
  height: 100%;
  min-width: 0;
}
.app-view--doc {
  overflow: auto;
  padding: 24px 32px;
}
/* The task list splits that scroll in two: its header (title · progress · filters) is
   pinned and only the rows below it scroll — see .tasks-header / .tasks-body. */
.app-view--tasks {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Mobile chrome: a top bar with a hamburger that opens the off-canvas nav drawer, plus
   the drawer's backdrop. All hidden on desktop — the @media block at the foot of this
   file turns them on (and turns the nav into the drawer) below the 768px breakpoint. */
.app-topbar,
.app-nav-toggle,
.app-nav-backdrop {
  display: none;
}

/* ---- App side nav (static scaffold) ---- */
.app-nav {
  position: relative;
  width: 264px;
  flex: none;
  height: var(--app-vh);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border-subtle);
  background: var(--bg-raised);
}
/* draggable handle straddling the panel's right border */
.tp-resizer {
  position: absolute;
  top: 0;
  right: -3px;
  width: 6px;
  height: 100%;
  z-index: 5;
  cursor: col-resize;
}
.tp-resizer:hover {
  background: rgba(51, 112, 255, 0.12);
}
.tp-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 52px;
  flex: none;
  padding: 0 16px;
}
.tp-brand-logo {
  font-size: 22px;
  line-height: 1;
}
.tp-brand-name {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-1);
}
.tp-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding-bottom: 12px;
}
.tp-section {
  padding: 0 8px;
}
.tp-item {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 36px;
  padding: 0 8px;
  border-radius: 6px;
  cursor: pointer;
  color: var(--text-1);
  font-size: 14px;
}
.tp-item:hover {
  background: var(--bg-hover);
}
.tp-item.active {
  background: var(--brand-tint);
  color: var(--brand);
}
.tp-item:focus {
  outline: none;
}
.tp-item:focus-visible,
.tp-rail-item:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: -2px;
}
.tp-ico {
  display: flex;
  font-size: 16px;
  color: var(--text-2);
  flex: none;
}
.tp-item.active .tp-ico {
  color: var(--brand);
}
.tp-label {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Workspace identity and its runner now share one compact line. The runner is secondary metadata:
   it absorbs truncation first, while the workspace name keeps as much room as possible. */
.tp-workspace-label {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  text-overflow: clip;
}
.tp-workspace-name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tp-workspace-separator {
  flex: none;
  color: var(--text-3);
}
.tp-workspace-runner {
  flex: 1 8 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-3);
}
.tp-workspace-icon {
  position: relative;
}
/* The Session list owns the live spinner. Keep Workspace identity stable and reduce the duplicate
   motion to a small, static aggregate mark on the folder — on the desktop sidebar and the <=960px
   drawer alike, so every row's mark sits in the same column and a needs-you count keeps the row's
   far end to itself. */
.tp-workspace-icon-running {
  position: absolute;
  right: -3px;
  bottom: -2px;
  z-index: 2;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
  box-shadow: 0 0 0 1.5px var(--bg-raised);
}
.tp-item:hover .tp-workspace-icon-running {
  box-shadow: 0 0 0 1.5px var(--bg-hover);
}
.tp-item.active .tp-workspace-icon-running {
  /* Keep an opaque cutout between two brand-blue strokes, including in the dark theme where
     --brand-tint is translucent and would visually merge the dot back into the folder. */
  box-shadow: 0 0 0 1.5px var(--bg-raised);
}
/* The second activity mark: this workspace has a background JOB in flight (a bg_run that will
   end), not a process it merely left up. Same slot, same dot, same brand blue — a workspace with
   work in it reads as active whether or not somebody is generating — and breathing rather than
   still, which is the whole vocabulary here (see the session row's terminal glyph, which breathes
   for the same reason). Motion is what separates it from the dot above at a glance; without it the
   two would be the same shape in the same blue. */
@keyframes status-glyph-breathe {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.42; }
}
.status-glyph-active {
  animation: status-glyph-breathe 2.4s ease-in-out infinite;
}
.tp-workspace-icon-jobs {
  position: absolute;
  right: -3px;
  bottom: -2px;
  z-index: 2;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
  box-shadow: 0 0 0 1.5px var(--bg-raised);
  animation: status-glyph-breathe 2.4s ease-in-out infinite;
}
.tp-item:hover .tp-workspace-icon-jobs {
  box-shadow: 0 0 0 1.5px var(--bg-hover);
}
.tp-item.active .tp-workspace-icon-jobs {
  box-shadow: 0 0 0 1.5px var(--bg-raised);
}
@media (prefers-reduced-motion: reduce) {
  .status-glyph-active,
  .tp-workspace-icon-jobs {
    animation: none;
  }
}
/* Runner availability belongs to the Workspace identity: a tiny disconnect badge overlays the
   folder only when that Runner is explicitly offline. Online folders stay visually quiet. */
.tp-workspace-icon-offline {
  position: absolute;
  right: -6px;
  bottom: -5px;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bg-raised);
  box-shadow: 0 0 0 1px var(--bg-raised);
  color: var(--text-3);
  font-size: 9px;
}
.tp-item.active .tp-workspace-icon-offline {
  background: var(--brand-tint);
  box-shadow: 0 0 0 1px var(--brand-tint);
  color: var(--text-3);
}
.tp-count {
  color: var(--text-3);
  font-size: 13px;
}
.tp-item.active .tp-count {
  color: var(--brand);
}
/* Shortcut hints are useful on the keyboard-driven desktop sidebar. The mobile drawer has no
   persistent hardware-key context, so it leaves the trailing slot to navigation status alone. */
.tp-workspace-shortcut,
.tp-nav-shortcut {
  display: none;
  flex: none;
  font-family: inherit;
  font-size: 12px;
  font-weight: 400;
  line-height: 1;
  white-space: nowrap;
}
/* "Needs you": one or more of an agent's active sessions are blocked on an approval the user
   must act on. An amber pill on the agent's sidebar row speaks the "waiting on you" language,
   visible from any page. */
.tp-count.needs-you {
  color: var(--warning);
  background: var(--warning-bg);
  border-radius: 999px;
  padding: 1px 7px;
  font-weight: 600;
  font-size: 12px;
}
/* Hold the amber even when the row is selected (which otherwise tints counts blue). */
.tp-item.active .tp-count.needs-you {
  color: var(--warning);
}
/* Status dot for a task list (the Tasks page's scope menu) and an open project (the rail's
   Projects group). Grey + static by default; turns blue and breathes while work is executing right
   now (a list's runningTasks > 0; a project's running task or working coordinator); turns green and
   static once a list is finished (every task DONE). */
.tp-list-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--dot-idle);
  flex: none;
  margin-right: 8px;
}
/* An open project's dot sits in the icon column, centred where the Workspace folders stand, so its
   title lines up with the Workspace names instead of indenting past them. */
.tp-project-mark {
  width: 16px;
  justify-content: center;
  align-items: center;
}
.tp-project-mark .tp-list-dot {
  margin-right: 0;
}
.tp-list-dot.running {
  background: var(--brand);
  animation: tp-list-dot-pulse 1.4s ease-in-out infinite;
}
.tp-list-dot.done {
  background: var(--success-solid);
}
@keyframes tp-list-dot-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(51, 112, 255, 0.5);
    opacity: 1;
  }
  50% {
    box-shadow: 0 0 0 4px rgba(51, 112, 255, 0);
    opacity: 0.6;
  }
}
/* Per-runner "more actions" trigger: hidden until the row is hovered or its
   menu is open, where it swaps in for the ⌘N shortcut hint. */
.tp-kebab {
  display: none;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  margin-right: -2px;
  border-radius: 4px;
  color: var(--text-3);
  font-size: 15px;
  flex: none;
}
.tp-kebab:hover {
  background: var(--bg-hover-strong);
  color: var(--text-1);
}
.tp-item.inset:hover .tp-count,
.tp-item.inset.menu-open .tp-count {
  display: none;
}
/* ...but the "needs you" attention badge stays put on hover — you hover the row to
   click into it, and the whole point is to keep that count visible while you do. */
.tp-item.inset:hover .tp-count.needs-you,
.tp-item.inset.menu-open .tp-count.needs-you {
  display: inline;
}
.tp-item.inset:hover .tp-kebab,
.tp-item.inset.menu-open .tp-kebab {
  display: flex;
}
.tp-item.active .tp-kebab {
  color: var(--brand);
}
.tp-divider {
  height: 1px;
  background: var(--border-subtle);
  margin: 8px 16px;
}
.tp-group + .tp-divider {
  background: transparent;
}
.tp-group {
  padding: 0 8px;
}
.tp-group-head {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 8px;
  cursor: pointer;
}
.tp-caret {
  font-size: 12px;
  color: var(--text-3);
  opacity: 0;
  transition: transform 0.15s ease, opacity 0.15s ease;
}
.tp-group-head:hover .tp-caret {
  opacity: 1;
}
.tp-caret.collapsed {
  transform: rotate(-90deg);
}
.tp-group-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-2);
}
/* The Workspaces head's one action: Edit, then Done while the rows are arranged. It shows on hover
   like the caret beside it (opacity, so the keyboard can still reach it), and always in the touch
   drawer, which has no hover. */
.tp-group-action {
  margin-left: auto;
  padding: 1px 6px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-3);
  font: inherit;
  font-size: 13px;
  line-height: 20px;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease;
}
.tp-group-head:hover .tp-group-action,
.tp-group-action:focus-visible,
.tp-group-action.editing {
  opacity: 1;
}
.tp-group-action:hover,
.tp-group-action:focus-visible {
  background: var(--bg-hover-strong);
  color: var(--text-1);
  outline: none;
}
.tp-group-action.editing {
  color: var(--brand);
  font-weight: 600;
}
@media (max-width: 960px) {
  .tp-group-action {
    opacity: 1;
  }
}
/* A Workspace row while the list is arranged: it opens nothing, and the Runners page's drag handle
   stands in the folder's column. */
.tp-item.editing {
  cursor: default;
}
.tp-workspace-handle {
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 28px;
  margin: 0 -2px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-4);
  font-size: 15px;
  cursor: grab;
  touch-action: none;
}
.tp-workspace-handle:hover,
.tp-workspace-handle:focus-visible {
  background: var(--bg-hover-strong);
  color: var(--text-2);
  outline: none;
}
.tp-workspace-handle:active {
  cursor: grabbing;
}
.tp-workspace-handle:disabled {
  cursor: default;
  opacity: 0.45;
}
.tp-workspace-sortable.dragging {
  position: relative;
  z-index: 1;
}
.tp-workspace-sortable.dragging .tp-item {
  background: var(--bg-raised);
  box-shadow: 0 8px 24px rgba(31, 35, 41, 0.16), 0 0 0 1px var(--brand-border);
}
.tp-add {
  color: var(--text-3);
  font-size: 14px;
  cursor: pointer;
}
.tp-add:hover {
  color: var(--brand);
}
.tp-user {
  flex: none;
  border-top: 1px solid var(--border-subtle);
  padding: 8px;
}
.tp-user-trigger {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 44px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.tp-user-trigger:hover,
.tp-user-trigger.open {
  background: var(--bg-hover);
}
.tp-user-trigger:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: -2px;
}
.tp-user-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-1);
}
.ant-dropdown-menu.tp-account-menu {
  width: 280px;
  max-width: calc(100vw - 16px);
}
.tp-account-menu .ant-dropdown-menu-item,
.tp-account-menu .ant-dropdown-menu-submenu-title {
  display: flex;
  align-items: center;
  min-height: 44px;
}
.tp-account-menu .ant-dropdown-menu-title-content {
  flex: 1;
  min-width: 0;
}
.tp-account-menu .ant-dropdown-menu-item.tp-account-profile {
  min-height: 64px;
}
.tp-account-profile-content {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.tp-account-identity {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  line-height: 1.35;
}
.tp-account-name,
.tp-account-detail {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tp-account-name {
  color: var(--text-1);
  font-weight: 600;
}
.tp-account-detail,
.tp-account-current-theme {
  color: var(--text-2);
  font-size: 12px;
}
.tp-account-appearance-label {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
  width: 100%;
}
.tp-account-current-theme {
  margin-left: auto;
}
.tp-account-menu .ant-dropdown-menu-item-danger,
.tp-account-menu .ant-dropdown-menu-item-danger .ant-dropdown-menu-item-icon {
  color: var(--error);
}

/* ---- Collapsible sidebar ---- */
/* Collapse/expand toggle in the brand row: pinned to the right edge when expanded,
   the lone centered control when collapsed. */
.tp-collapse-btn {
  margin-left: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex: none;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-3);
  font-size: 15px;
  cursor: pointer;
}
.tp-collapse-btn:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}
/* Drop the focus ring on mouse click; keep it for keyboard navigation. */
.tp-collapse-btn:focus {
  outline: none;
}
.tp-collapse-btn:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
/* The icon rail that stands in for the full panel when collapsed. Hidden until the
   desktop media query below turns it on. */
.tp-rail {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 0;
}
.tp-rail-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  cursor: pointer;
}
.tp-rail-item:hover {
  background: var(--bg-hover);
}
.tp-rail-item.active {
  background: var(--brand-tint);
}
.tp-rail-item.active .tp-ico {
  color: var(--brand);
}
/* Count pill tucked into the icon's top-right corner — amber for "needs you"
   (mirrors .tp-count.needs-you), brand blue for the plain live count. */
.tp-rail-badge {
  position: absolute;
  top: 1px;
  right: 1px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  box-sizing: border-box;
  border-radius: 999px;
  background: var(--brand);
  color: #fff;
  font-size: 11px;
  line-height: 16px;
  text-align: center;
  font-weight: 600;
}
.tp-rail-badge.needs-you {
  background: var(--warning-solid);
}
/* Workspace entries in the collapsed rail: a round monogram avatar plus only exceptional/activity
   status, so the user's ordered workspaces (⌘1‒9) stay one click away without a column of green. */
.tp-rail-divider {
  width: 24px;
  height: 1px;
  flex: none;
  margin: 4px 0;
  background: var(--border-subtle);
}
.tp-rail-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-hover-strong);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
}
.tp-rail-item.active .tp-rail-avatar {
  background: var(--brand);
  color: #fff;
}
.tp-rail-running {
  position: absolute;
  right: 1px;
  bottom: 1px;
  border-radius: 50%;
  background: var(--bg-raised);
}
.tp-rail-offline {
  position: absolute;
  right: 1px;
  bottom: 1px;
  border-radius: 50%;
  background: var(--bg-raised);
}
/* The collapsed rail's own slot for the background-work mark — same corner as the spinner. */
.tp-rail-jobs {
  position: absolute;
  right: 1px;
  bottom: 1px;
  border-radius: 50%;
  background: var(--bg-raised);
}

/* Desktop collapse behaviour. Scoped to >960px so the ≤960 off-canvas drawer
   (which toggles on .open, not .collapsed) is never touched — there the panel
   always opens as the full list. */
@media (min-width: 961px) {
  /* Workspace-level activity keeps one stable visual language: the quiet dot the expanded folder
     shows at every width, here on the collapsed avatar. Session rows remain the only rotating
     indicators. */
  .app-shell .app-nav:not(.collapsed) .tp-workspace-shortcut {
    display: inline;
  }
  .app-shell .app-nav:not(.collapsed) .tp-nav-shortcut {
    display: inline;
  }
  .app-shell .app-nav.collapsed .tp-rail-running {
    background: transparent;
    animation: none !important;
  }
  /* Both activity kinds speak the same shape in the collapsed rail — a brand-blue dot on the
     avatar's corner — and differ by motion: still for the agent generating, breathing for
     background work. */
  .app-shell .app-nav.collapsed .tp-rail-jobs {
    background: transparent;
    animation: none !important;
  }
  .app-shell .app-nav.collapsed .tp-rail-jobs > svg {
    visibility: hidden;
    animation: none !important;
  }
  .app-shell .app-nav.collapsed .tp-rail-jobs::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--brand);
    box-shadow: 0 0 0 1.5px var(--bg-raised);
    transform: translate(-50%, -50%);
    animation: status-glyph-breathe 2.4s ease-in-out infinite;
  }
  .app-shell .app-nav.collapsed .tp-rail-running > svg {
    visibility: hidden;
    animation: none !important;
  }
  .app-shell .app-nav.collapsed .tp-rail-running::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--brand);
    box-shadow: 0 0 0 1.5px var(--bg-raised);
    transform: translate(-50%, -50%);
  }

  /* Animate the collapse/expand width change so the panel glides between the full
     list and the 56px rail. Suppressed during a drag-resize (.resizing) so the edge
     tracks the cursor 1:1 instead of rubber-banding behind the transition. */
  .app-nav {
    transition: width 0.2s ease;
  }
  .app-nav.resizing {
    transition: none;
  }
  .app-nav.collapsed {
    width: 56px;
  }
  .app-nav.collapsed .tp-scroll,
  .app-nav.collapsed .tp-resizer,
  .app-nav.collapsed .tp-brand-logo,
  .app-nav.collapsed .tp-brand-name,
  .app-nav.collapsed .tp-user-name {
    display: none;
  }
  /* Rail takes over the flex:1 "spacer" role the hidden .tp-scroll played, so the
     user footer stays pinned to the bottom (icons sit at the top of the rail). It
     scrolls on its own when the agent list is long; scrollbar hidden to stay clean. */
  .app-nav.collapsed .tp-rail {
    display: flex;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    scrollbar-width: none;
  }
  .app-nav.collapsed .tp-rail::-webkit-scrollbar {
    display: none;
  }
  .app-nav.collapsed .tp-brand {
    justify-content: center;
    padding: 0;
  }
  .app-nav.collapsed .tp-collapse-btn {
    margin-left: 0;
  }
  .app-nav.collapsed .tp-user-trigger {
    justify-content: center;
  }
}

/* The collapse control is desktop-only; the ≤960 drawer is driven by the hamburger. */
@media (max-width: 960px) {
  .tp-collapse-btn {
    display: none;
  }
}

/* ---- Tasks page ---- */
/* Header block that stays put while the list scrolls; .tasks-body is the scroll
   container the rows (and the sticky .col-head-row) live in. */
.tasks-header {
  flex: none;
}
.tasks-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
/* The list heading and its console entry on one line. `.page-title` is a block-level h1, so
   without this row the button lands under the title instead of beside it. */
.tasks-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.page-title {
  font-size: 20px;
  font-weight: 600;
  margin: 0;
  color: var(--text-1);
}
/* The Tasks page's title is also its scope picker: every task, the tasks in no list, or one list.
   A button in the heading's own type, so it reads as the title and presses as the menu. */
.tasks-scope-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: -6px;
  padding: 2px 6px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.tasks-scope-trigger:hover {
  background: var(--bg-hover);
}
.tasks-scope-caret {
  font-size: 12px;
  color: var(--text-3);
}
/* Qualified by antd's own class: its injected menu styles outrank a single-class rule. */
.ant-dropdown-menu.tasks-scope-menu {
  min-width: 260px;
  max-width: min(460px, calc(100vw - 24px));
  max-height: 70vh;
  overflow-y: auto;
}
.tasks-scope-row {
  display: flex;
  align-items: center;
  min-width: 0;
}
.tasks-scope-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tasks-scope-count {
  flex: none;
  margin-left: 16px;
  color: var(--text-3);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.tasks-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin: 16px 0 8px;
}
.tasks-search {
  width: 200px;
}
/* Muted chip surfacing context dropped from the rows: when every task shares one assignee,
   that assignee. */
.task-assignee-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-3);
  background: var(--fill-muted);
  border-radius: 6px;
  padding: 2px 8px;
  white-space: nowrap;
}
/* The session scope `?createdIn=` puts on the page: named, so it can be taken off, and cut short
   rather than letting a long session title push the rest of the toolbar around. */
.tasks-toolbar .tasks-createdin {
  display: inline-flex;
  align-items: center;
  max-width: 320px;
}
.tasks-createdin-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Inline bar with batch actions, shown only while rows are selected. */
.tasks-bulkbar {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 100%;
  overflow-x: auto;
  padding: 4px 10px;
  background: var(--brand-tint);
  border: 1px solid var(--brand-border);
  border-radius: 8px;
}
.tasks-bulkbar-count {
  flex: none;
  font-size: 13px;
  color: var(--text-1);
  white-space: nowrap;
}

/* Progress overview under the list title: done (green) + in-progress (blue) over the total. */
/* The one sentence the Tasks page says about the work it does not list: the tasks on project pages. */
.tasks-scope-note {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 10px;
  font-size: 12.5px;
  color: var(--text-3);
}
.tasks-scope-note b {
  color: var(--text-2);
  font-weight: 600;
}
.tasks-scope-note a {
  color: var(--brand);
  cursor: pointer;
  white-space: nowrap;
}
.tasks-scope-note .anticon {
  font-size: 13px;
  flex: none;
}

.task-progress {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 14px 0 4px;
}
.task-progress-track {
  flex: 1;
  display: flex;
  height: 8px;
  border-radius: 999px;
  background: var(--border-subtle);
  overflow: hidden;
}
.task-progress-seg.done {
  background: var(--success-solid);
}
.task-progress-seg.ongoing {
  background: var(--brand);
  opacity: 0.85;
}
.task-progress-text {
  font-size: 13px;
  color: var(--text-2);
  white-space: nowrap;
}
.task-progress-text b {
  color: var(--text-1);
  font-weight: 650;
}
.task-progress-text .sep {
  margin: 0 8px;
  color: var(--border);
}

.tasks-loadmore {
  grid-column: 1 / -1;
  padding: 16px;
  text-align: center;
}

/* The pinned strip of work that is actually happening. It sits inside .orbit-tasklist so its
   rows inherit the same column grid as the list below — the header governs both. */
.task-active-strip {
  background: var(--bg-subtle);
  border-bottom: 1px solid var(--border);
}
.task-active-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 7px 16px 5px;
}
.task-active-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-2);
}
.task-active-hint {
  font-size: 11.5px;
  color: var(--text-3);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The Batches view: one row per label, each carrying the same meter as the header above. */
.tasks-viewswitch {
  margin: 10px 0 0;
}
.tasks-labelfilter {
  min-width: 168px;
  max-width: 320px;
}
.tasks-labelopt {
  display: flex;
  align-items: center;
  gap: 10px;
}
.tasks-labelopt-name {
  flex: 1;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12.5px;
}
.tasks-labelopt-count {
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
  font-size: 12px;
}
.orbit-batchlist .col-head-row,
.batch-row {
  display: grid;
  /* The trailing 1fr absorbs the spare width instead of the meter doing it: stretched across a
     wide window the bar becomes a rule the eye has to travel before reaching its own numbers. */
  grid-template-columns: minmax(150px, 220px) minmax(120px, 460px) 76px 76px 76px 1fr;
  align-items: center;
  gap: 12px;
  padding: 0 16px;
}
.orbit-batchlist .col-head-row {
  height: 34px;
  border-bottom: 1px solid var(--border-subtle);
}
.orbit-batchlist .col-head {
  font-size: 12px;
  color: var(--text-3);
  white-space: nowrap;
}
.orbit-batchlist .col-head.batch-num {
  text-align: right;
}
.orbit-batchlist .col-head.sorted {
  color: var(--text-2);
}
.batch-sort-caret {
  margin-left: 4px;
  font-size: 10px;
}
.batch-row {
  height: 34px;
  border-bottom: 1px solid var(--border-subtle);
}
.batch-row.clickable {
  cursor: pointer;
}
.batch-row.clickable:hover {
  background: var(--bg-hover);
}
.batch-name {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12.5px;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.batch-meter .task-progress-track {
  height: 6px;
}
/* tabular-nums only where digits stack — these columns are read down, not across. */
.batch-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-size: 12.5px;
  color: var(--text-2);
}
.batch-num.strong {
  color: var(--text-1);
  font-weight: 550;
}
.batch-num.muted {
  color: var(--text-3);
}
.batch-truncated {
  padding: 10px 16px;
  font-size: 12px;
  color: var(--text-3);
}

/* Filter tab labels carry a count badge (counts come from the unfiltered view). */
.seg-opt {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.seg-count {
  font-size: 11px;
  line-height: 16px;
  color: var(--text-3);
  background: rgba(0, 0, 0, 0.05);
  border-radius: 999px;
  padding: 0 6px;
  min-width: 18px;
  text-align: center;
}
.ant-segmented-item-selected .seg-count {
  background: var(--brand-tint);
  color: var(--brand);
}
/* Failed filter with a non-zero count leads in red — a failure is a signal, not a tab. */
.seg-opt--danger,
.seg-opt--danger .seg-count {
  color: var(--error);
}
.seg-opt--danger .seg-count {
  background: var(--error-bg);
}

/* ---- Runners page (the runner list, moved out of the sidebar) ---- */
.runners-head {
  max-width: 920px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.runners-empty {
  max-width: 920px;
  margin: 24px auto 0;
  color: var(--text-3);
  font-size: 14px;
}
.runners-list {
  max-width: 920px;
  margin: 16px auto 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.runner-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  cursor: pointer;
  background: var(--bg-raised);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.runner-card:hover {
  border-color: var(--brand-border);
  box-shadow: 0 2px 8px rgba(51, 112, 255, 0.08);
}
.runner-card.dragging {
  border-color: var(--brand-border);
  box-shadow: 0 8px 24px rgba(31, 35, 41, 0.16);
  opacity: 0.78;
}
.runner-drag-handle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 28px;
  margin-left: -5px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-4);
  font-size: 15px;
  cursor: grab;
  touch-action: none;
  flex: none;
}
.runner-drag-handle:hover,
.runner-drag-handle:focus-visible {
  background: var(--bg-hover-strong);
  color: var(--text-2);
  outline: none;
}
.runner-drag-handle:active {
  cursor: grabbing;
}
.runner-drag-handle:disabled {
  cursor: default;
  opacity: 0.45;
}
.runner-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex: none;
  align-self: flex-start;
  margin-top: 5px;
}
.runner-meta {
  flex: 1;
  min-width: 0;
}
.runner-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.runner-sub {
  font-size: 12px;
  color: var(--text-3);
  margin-top: 2px;
}
.runner-kebab {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 4px;
  color: var(--text-3);
  font-size: 15px;
  flex: none;
  /* Always reserve the slot so revealing the kebab on hover doesn't shift
     the version number and chevron; only fade visibility. */
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.15s ease, visibility 0.15s ease;
}
.runner-kebab:hover {
  background: var(--bg-hover-strong);
  color: var(--text-1);
}
.runner-card:hover .runner-kebab,
.runner-card.menu-open .runner-kebab {
  visibility: visible;
  opacity: 1;
}
/* Slot utilization: a thin track with a fill proportional to live sessions. */
.runner-util {
  margin-top: 6px;
  width: 100%;
  max-width: 200px;
  height: 4px;
  border-radius: 2px;
  background: var(--border-subtle);
  overflow: hidden;
}
.runner-util-fill {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--brand);
  transition: width 0.2s ease;
}
.runner-util.full .runner-util-fill {
  background: var(--warning-solid);
}
.runner-tags {
  font-size: 12px;
  color: var(--text-4);
  margin-top: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The third line: what this machine needs a person for. When it wraps on a narrow screen, the
   triangle stays with its first line. */
.runner-attention {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 5px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
}
.runner-attention.bad {
  color: var(--error);
}
.runner-attention.warn {
  color: var(--warning);
}
.runner-attention .anticon {
  flex: none;
  margin-top: 2.5px;
  font-size: 11px;
}
.runner-version {
  font-size: 12px;
  color: var(--text-3);
  flex: none;
}
/* Always-visible navigation affordance; the whole card is clickable. */
.runner-chevron {
  color: var(--dot-idle);
  font-size: 12px;
  flex: none;
}
.runner-token-box {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
  word-break: break-all;
  background: var(--bg-sunken);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  padding: 10px 12px;
  color: var(--text-1);
}

/* ---- Skills page (skills/commands a runner reported, grouped per machine) ---- */
/* Center the content column to match Runners / session pages (920px). */
.skills-page {
  max-width: 920px;
  margin: 0 auto;
}
.skills-empty {
  margin-top: 24px;
  color: var(--text-3);
  font-size: 14px;
}
.skills-empty code {
  background: var(--bg-hover);
  border-radius: 4px;
  padding: 1px 5px;
  font-size: 12px;
}
.skills-search {
  margin-top: 16px;
  width: 100%;
  max-width: 360px;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 7px 12px;
  font-size: 13px;
  color: var(--text-1);
  outline: none;
}
.skills-search:focus {
  border-color: var(--brand);
}
.skills-search::placeholder {
  color: var(--text-4);
}
.skills-no-match {
  margin-top: 16px;
  font-size: 13px;
  color: var(--text-3);
}
.skills-list {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
/* One collapsible scope group (an agent, or a runner's "Shared" host bucket). */
.skills-group-card {
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--bg-raised);
  overflow: hidden;
}
.skills-group-head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 12px 14px;
  border: none;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.skills-group-head:hover {
  background: var(--bg-hover);
}
.skills-caret {
  flex: none;
  font-size: 11px;
  color: var(--text-3);
  transition: transform 0.15s;
}
.skills-caret.open {
  transform: rotate(90deg);
}
.skills-group-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
}
.skills-group-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-3);
}
.skills-group-count {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}
.skills-group-body {
  padding: 0 14px 12px;
}
.skills-group {
  margin-top: 12px;
}
.skills-group-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-3);
  margin-bottom: 6px;
}
.skill-item {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 5px 0;
}
.skill-name {
  flex: none;
  min-width: 132px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
  color: var(--brand);
}
.skill-desc-wrap {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}
.skill-desc {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-2);
  max-width: 68ch;
}
.skill-desc.expanded {
  -webkit-line-clamp: unset;
  overflow: visible;
}
.skill-desc-toggle {
  border: none;
  background: none;
  padding: 0;
  font-size: 12px;
  color: var(--brand);
  cursor: pointer;
}
.skill-desc-toggle:hover {
  text-decoration: underline;
}
/* ---- Runner detail / settings page ---- */
.rd-head {
  margin-bottom: 8px;
}
.rd-back,
.rd-link {
  color: var(--text-2);
  font-size: 13px;
  cursor: pointer;
}
.rd-back:hover,
.rd-link:hover {
  color: var(--brand);
}
.rd-back .anticon {
  margin-right: 4px;
}
.rd-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.rd-sub {
  font-size: 13px;
  color: var(--text-3);
}
.rd-page {
  max-width: 920px;
  margin: 0 auto;
}
.rd-section {
  margin-top: 28px;
}
.rd-section-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-1);
}
.rd-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
/* A section heading with more than one control: they stay one group at the right edge
   rather than pushing the title around. */
.rd-section-actions {
  display: flex;
  gap: 8px;
}
/* The runner's identity line: status/slots/version/host as one scannable row, so the
   agent list clears the fold instead of sitting under an eight-field grid. */
.rd-metaline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0 8px;
  margin: 6px 0 0 19px;
  font-size: 13px;
  color: var(--text-3);
}
.rd-metaline > span + span::before {
  content: '·';
  margin-right: 8px;
  color: var(--text-4);
}
.rd-meta-ok {
  color: var(--success);
}
/* Needs Attention: one card per item, under the title and across both columns — two abreast on a
   desktop, one alone taking the row. Amber for a warning, red for what already stops sessions, grey
   for an offline machine (a state, not a fault). */
.rd-attention {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 18px;
}
.rd-attention-card {
  display: flex;
  gap: 11px;
  padding: 12px 14px;
  border-radius: 10px;
  background: var(--warning-bg);
  border: 1px solid var(--warning-border);
}
.rd-attention-card:only-child {
  grid-column: 1 / -1;
}
.rd-attention-card.bad {
  background: var(--error-bg);
  border-color: var(--error-border);
}
.rd-attention-card.idle {
  background: var(--bg-subtle);
  border-color: var(--border-subtle);
}
.rd-attention-icon {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: rgba(250, 140, 22, 0.16);
  color: var(--warning);
  font-size: 14px;
}
.rd-attention-card.bad .rd-attention-icon {
  background: rgba(245, 74, 69, 0.14);
  color: var(--error);
}
.rd-attention-card.idle .rd-attention-icon {
  background: var(--fill-muted);
  color: var(--text-3);
}
.rd-attention-main {
  min-width: 0;
}
.rd-attention-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
}
.rd-attention-detail {
  margin-top: 3px;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--text-2);
}
.rd-attention-action {
  margin-top: 9px;
}
/* The machine's contents on the left, its settings and facts in a narrower column on the right. */
.rd-cols {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 290px;
  gap: 0 24px;
  align-items: start;
}
.rd-col {
  min-width: 0;
}
/* A settings panel: label left, value or control right, hairlines between rows — Capacity and
   About. */
.rd-box {
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--bg-raised);
}
.rd-box > * + * {
  border-top: 1px solid var(--border-subtle);
}
.rd-kv,
.rd-kv-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 13px;
}
.rd-kv {
  min-height: 42px;
  padding: 7px 14px;
}
.rd-kv-label {
  flex: none;
  color: var(--text-2);
}
.rd-kv-value {
  min-width: 0;
  color: var(--text-1);
  text-align: right;
  overflow-wrap: anywhere;
}
.rd-kv-value small {
  margin-left: 5px;
  font-size: 12px;
  color: var(--text-3);
}
.rd-kv-value small.warn {
  color: var(--warning);
  font-weight: 500;
}
.rd-inline-link {
  margin-left: 8px;
  padding: 0;
  border: none;
  background: none;
  font: inherit;
  font-size: 12.5px;
  color: var(--brand);
  cursor: pointer;
}
.rd-inline-link:hover {
  color: var(--brand-strong);
}
.rd-max-concurrent {
  width: 72px;
}
.rd-keep-free {
  min-width: 96px;
}
.rd-disk {
  padding: 11px 14px 12px;
}
.rd-disk-bar {
  height: 6px;
  margin-top: 8px;
  border-radius: 3px;
  background: var(--border-subtle);
  overflow: hidden;
}
.rd-disk-bar > span {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: var(--brand);
}
.rd-disk-bar.warn > span {
  background: var(--warning-solid);
}
/* The footnote under a panel. */
.rd-hint {
  margin: 8px 2px 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-3);
}
.rd-empty {
  color: var(--text-3);
  font-size: 14px;
  padding: 20px;
  border: 1px dashed var(--border);
  border-radius: 10px;
  text-align: center;
}
/* The engine CLIs on this machine. Same panel-with-hairlines shape as the agent list below:
   both answer "what is on this machine", so they read as one page rather than two widgets. */
.rd-engine-list {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--bg-raised);
  overflow: hidden;
}
.rd-engine-list > * + * {
  border-top: 1px solid var(--border-subtle);
}
.rd-engine-row {
  display: grid;
  grid-template-columns: 24px minmax(0, 1.1fr) minmax(0, 1fr) 190px 12px;
  grid-template-areas: 'mark main auth quota chevron';
  gap: 12px;
  align-items: center;
  padding: 11px 14px;
  color: inherit;
  transition: background 0.12s ease;
}
.rd-engine-row:hover {
  color: inherit;
  background: var(--bg-hover);
}
.rd-engine-row > .provider-tile {
  grid-area: mark;
}
.rd-engine-main {
  grid-area: main;
  min-width: 0;
}
.rd-engine-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-1);
}
.rd-engine-version {
  margin-top: 1px;
  font-size: 12.5px;
  color: var(--text-3);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Same amber as the Providers row's note, for the same reason: drift needs a person eventually,
   which is not the same as being down. */
.rd-engine-note {
  color: var(--text-4);
}
.rd-engine-note.warn {
  color: var(--warning);
  font-weight: 500;
}
.rd-engine-auth {
  grid-area: auth;
  font-size: 12.5px;
}
.rd-engine-auth.ok {
  color: var(--success);
}
.rd-engine-auth.warn {
  color: var(--warning);
  font-weight: 500;
}
.rd-engine-auth.muted,
.rd-engine-muted {
  color: var(--text-3);
}
.rd-engine-quota {
  grid-area: quota;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  font-size: 12.5px;
}
/* Whose windows these are, when the engine has several accounts: the one a new session starts on. */
.rd-quota-next {
  margin-bottom: 4px;
  font-size: 11px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rd-quota-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 11.5px;
  color: var(--text-2);
}
.rd-quota.near .rd-quota-pct {
  color: var(--warning);
  font-weight: 600;
}
.rd-quota-bar {
  height: 4px;
  margin-top: 3px;
  border-radius: 2px;
  background: var(--border-subtle);
  overflow: hidden;
}
.rd-quota-bar > span {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--brand);
}
.rd-quota.near .rd-quota-bar > span {
  background: var(--warning-solid);
}
.rd-engine-chevron {
  grid-area: chevron;
  font-size: 11px;
  color: var(--text-4);
}
/* An engine row needs about 560px for its five columns. Narrower — a phone, or the left column
   beside Capacity on a tablet — its quota takes a line of its own, and a quota line that would only
   hold "—" is left out. Measured on the section, not the viewport: the column it sits in is what
   runs out of room. */
.rd-engines {
  container: rd-engines / inline-size;
}
@container rd-engines (max-width: 560px) {
  .rd-engine-row {
    grid-template-columns: 24px minmax(0, 1fr) auto 12px;
    grid-template-areas:
      'mark main auth chevron'
      '. quota quota .';
    row-gap: 8px;
  }
  .rd-engine-quota.empty {
    display: none;
  }
}
/* The run's report sits above the rows it summarizes, not inside any one of them. */
.rd-engine-relay {
  margin-bottom: 12px;
  padding: 12px 13px;
  border-radius: 10px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-subtle);
}
.rd-engine-relay.bad {
  background: var(--error-bg);
  border-color: var(--error-border);
}
.rd-engine-relay-row {
  font-size: 12.5px;
  color: var(--text-2);
  white-space: pre-wrap;
}
.rd-engine-relay.bad .rd-engine-relay-row {
  color: var(--error);
  font-weight: 500;
}
.rd-engine-relay-hint {
  margin-top: 7px;
  font-size: 11.5px;
  color: var(--text-3);
}
.rd-workspace-list {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--bg-raised);
  overflow: hidden;
}
/* One panel with hairline dividers between rows, instead of boxing each row —
   denser and faster to scan. */
.rd-workspace-list > * + * {
  border-top: 1px solid var(--border-subtle);
}
/* The row is the click target for its config — the settings it shows are the ones the
   editor holds, so aiming at the row is the natural move. */
.rd-workspace-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  cursor: pointer;
  transition: background 0.12s ease;
}
.rd-workspace-row:hover,
.rd-workspace-row.is-open {
  background: var(--bg-hover);
}
.rd-workspace-row.is-disabled .rd-workspace-ico {
  background: var(--fill-muted);
  color: var(--text-4);
}
.rd-workspace-row.is-disabled .rd-workspace-name,
.rd-workspace-row.is-disabled .rd-workspace-meta {
  color: var(--text-4);
}
/* Quiet by default: the caret appears on hover, or stays while this row's editor is open,
   so a resting list isn't a column of chevrons. */
.rd-row-caret {
  font-size: 11px;
  color: var(--text-4);
  opacity: 0;
  transition:
    opacity 0.15s ease,
    transform 0.18s ease;
}
.rd-workspace-row:hover .rd-row-caret {
  opacity: 1;
}
.rd-workspace-row.is-open .rd-row-caret {
  opacity: 1;
  color: var(--text-2);
  transform: rotate(180deg);
}
.rd-workspace-ico {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--brand-tint);
  color: var(--brand);
  flex: none;
}
.rd-workspace-main {
  flex: 1;
  min-width: 0;
}
.rd-workspace-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-1);
}
.rd-workspace-meta {
  font-size: 12px;
  color: var(--text-3);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Sessions of this workspace running right now — the sidebar's own count. */
.rd-workspace-running {
  flex: none;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--brand-tint);
  color: var(--brand);
  font-size: 12px;
  font-weight: 500;
}
.rd-form-field {
  margin-bottom: 14px;
}
.rd-form-label {
  font-size: 13px;
  color: var(--text-1);
  margin-bottom: 6px;
}
/* Agent env-var editor: KEY input | value input | delete button per row. */
.rd-env-row {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}
.rd-env-row > .ant-input:first-child {
  flex: 0 0 38%;
}
/* Import-a-Claude-session row: uuid input | Import button. */
.rd-import-row {
  display: flex;
  gap: 8px;
  margin-bottom: 6px;
}
.rd-import-row .ant-input {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}
/* Standing "always allow" grants: a monospace token per grant, with revoke on the right. */
.rd-rule-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.rd-rule-token {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
  padding: 3px 8px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: var(--bg-sunken, var(--bg-raised));
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
  color: var(--text-2);
}
.rd-rule-empty {
  font-size: 12px;
  color: var(--text-3);
  line-height: 1.55;
}
/* In-place agent editor card — replaces the old modal; lives inside the list. */
.rd-workspace-form {
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--bg-raised);
  padding: 16px 16px 14px;
}
.rd-workspace-form-new {
  box-shadow: inset 3px 0 0 var(--brand);
}
/* Two-column grid for the short fields; long fields below span full width. */
.rd-form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 16px;
}
.rd-form-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--border-subtle);
}
/* Section headers inside the editor: Essentials / Defaults, with Advanced folded below. */
.rd-form-section {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--text-3);
  margin: 16px 0 10px;
}
.rd-form-section:first-child {
  margin-top: 12px;
}
/* Model isn't an agent field — it resolves from the runtime. Stated rather than shown as a
   disabled control, which would read as a setting that failed to load. */
.rd-form-derived {
  font-size: 12px;
  color: var(--text-3);
  line-height: 1.55;
  margin: 12px 0 2px;
}
.rd-form-derived b {
  color: var(--text-2);
  font-weight: 500;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
}
.rd-dirty-note {
  font-size: 12px;
  color: var(--warning);
  margin-right: 4px;
}
/* What the runner last saw at the agent's working directory — answered from its own disk, so a
   typo is caught here instead of when a session fails to start. */
.rd-path-hint {
  font-size: 12px;
  margin-top: 6px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  line-height: 1.5;
}
.rd-path-hint .anticon {
  margin-top: 2px;
  flex: none;
}
.rd-path-ok {
  color: var(--success);
}
.rd-path-warn {
  color: var(--warning);
}
.rd-path-muted {
  color: var(--text-3);
}
/* The offer made when a directory already has Claude Code conversations recorded in it. Its height
   is fixed by construction — one statistic, three choices, one warning — so a directory holding six
   hundred conversations takes up exactly as much of the form as one holding six. */
.rd-history-panel {
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 2px;
}
/* Only the statistic loses its top margin; the warning keeps one, or it reads as a fourth choice
   rather than as the caveat under all three. */
.rd-history-panel > .rd-path-hint:first-child {
  margin-top: 0;
}
/* Every rule below is deliberately qualified with .rd-history-panel: antd's own `.ant-radio-group`
   and `.ant-radio` rules are single-class too, and they are injected after this stylesheet, so a
   plain `.rd-history-choices { margin }` ties on specificity and loses on order — measured as a
   computed margin of 0 and three choices with no air between them and the lines around them. */
.rd-history-panel .rd-history-choices {
  display: block;
  margin: 12px 0 14px;
}
.rd-history-panel .rd-history-choices .ant-radio-wrapper {
  display: flex;
  align-items: flex-start;
  margin: 0 0 10px;
}
.rd-history-panel .rd-history-choices .ant-radio-wrapper:last-child {
  margin-bottom: 0;
}
/* antd centres the control against the whole wrapper, which for a two-line choice parks the dot
   between the label and its explanation, belonging to neither. */
.rd-history-panel .rd-history-choices .ant-radio {
  align-self: flex-start;
  margin-top: 2px;
}
/* The label and its explanation stack; antd puts both inside the wrapper's second span. */
.rd-history-choice,
.rd-history-choice .rd-set-label,
.rd-history-choice .rd-set-desc {
  display: block;
}
.rd-history-removal {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
}
.rd-quiet-btn {
  color: var(--text-3);
}
.rd-quiet-btn:hover {
  color: var(--text-1);
}
/* Settings-row toggle: label + explanation left, control right-aligned. */
.rd-set-row {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 11px 0;
  border-top: 1px solid var(--border-subtle);
}
.rd-set-main {
  flex: 1;
  min-width: 0;
}
.rd-set-label {
  font-size: 13px;
  color: var(--text-1);
}
.rd-set-desc {
  font-size: 12px;
  color: var(--text-3);
  margin-top: 3px;
  line-height: 1.5;
}
.rd-set-row .ant-switch {
  margin-top: 2px;
  flex: none;
}
/* The engines smart selection may move a task run to (model routing §6), under the switch's own
   explanation: one chip per engine, the agent's own ticked and fixed. Qualified with .rd-engines-list
   so antd's single-class checkbox rules, injected after this stylesheet, do not win on order. */
.rd-route-engines {
  margin-top: 10px;
}
.rd-engines-label {
  font-size: 12px;
  color: var(--text-2);
}
.rd-engines-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}
.rd-engines-list .ant-checkbox-wrapper {
  margin-inline-start: 0;
  padding: 2px 9px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-2);
}
.rd-engines-list .ant-checkbox-wrapper.is-on {
  border-color: var(--brand-border);
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-weight: 600;
}
/* The agent's own engine cannot be unticked, but it is ticked: drawn as on, not as greyed out. */
.rd-engines-list .ant-checkbox-wrapper-disabled.is-on {
  cursor: default;
}
.rd-engines-list .ant-checkbox-wrapper-disabled.is-on .ant-checkbox-inner {
  background: var(--brand);
  border-color: var(--brand);
}
.rd-engines-list .ant-checkbox-wrapper-disabled.is-on .ant-checkbox-inner::after {
  border-color: #fff;
}
.rd-engines-list .ant-checkbox-wrapper-disabled.is-on .ant-checkbox + span {
  color: var(--brand-strong);
}
.rd-engines-note {
  font-size: 12px;
  color: var(--text-3);
  margin-top: 6px;
  line-height: 1.5;
}
/* Advanced disclosure — folded by default, but it has to admit when it hides something. */
.rd-adv-toggle {
  display: flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
  user-select: none;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--text-3);
  margin-top: 16px;
  padding: 6px 0;
}
.rd-adv-toggle:hover {
  color: var(--text-1);
}
.rd-adv-caret {
  font-size: 10px;
  transition: transform 0.18s ease;
}
.rd-adv-toggle.open .rd-adv-caret {
  transform: rotate(180deg);
}
.rd-adv-badge {
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--fill-muted);
  color: var(--text-3);
}
.rd-adv-body {
  padding-top: 6px;
}
/* Which Codex account the workspace runs on: each option is the account, with its own quota and
   sign-in on a quieter line under it. */
.rd-codex-account {
  width: 100%;
}
.rd-codex-account-status {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--text-3);
  margin-top: 1px;
}
@media (max-width: 600px) {
  .rd-form-grid {
    grid-template-columns: 1fr;
  }
}
/* A phone's width: one column, in the order the iPhone's runner page reads — Needs Attention,
   Capacity, Engines, Workspaces, About. The two column boxes step aside (display: contents) so
   their sections can be ordered as one list. */
@media (max-width: 640px) {
  .rd-attention {
    grid-template-columns: minmax(0, 1fr);
  }
  .rd-cols {
    display: flex;
    flex-direction: column;
    align-items: stretch;
  }
  .rd-col {
    display: contents;
  }
  .rd-capacity {
    order: 1;
  }
  .rd-engines {
    order: 2;
  }
  .rd-workspaces {
    order: 3;
  }
  .rd-about {
    order: 4;
  }
}
/* Edit-in-place: the clicked row stays as a header and the editor expands below
   it, the two merged into one bordered card. */
.rd-workspace-editing {
  overflow: hidden;
  box-shadow: inset 3px 0 0 var(--brand);
}
.rd-workspace-editing > .rd-workspace-row {
  border: none;
  border-radius: 0;
  background: transparent;
}
.rd-workspace-editing > .rd-workspace-form-wrap > .rd-workspace-form {
  border: none;
  border-radius: 0;
  border-top: 1px solid var(--border-subtle);
}
/* Create form sits inline at the top of the panel — shed its own card frame too. */
.rd-workspace-list > .rd-workspace-form-wrap > .rd-workspace-form {
  border: none;
  border-radius: 0;
  background: transparent;
}
/* Expand the editor open: grow its row track 0fr→1fr while fading in, so the
   rows below slide down smoothly. (Collapse is immediate — React unmounts it.) */
.rd-workspace-form-wrap {
  display: grid;
  grid-template-rows: 1fr;
  animation: rd-form-expand 0.2s ease;
}
.rd-workspace-form-wrap > * {
  min-height: 0;
  overflow: hidden;
}
@keyframes rd-form-expand {
  from {
    grid-template-rows: 0fr;
    opacity: 0;
  }
  to {
    grid-template-rows: 1fr;
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .rd-workspace-form-wrap {
    animation: none;
  }
}

/* shared column grid: check | status | title | assignee */
.orbit-tasklist {
  --cols: 28px 92px minmax(160px, 1fr) 160px;
  border-top: 1px solid var(--border-subtle);
}
/* Detail panel open, or every row shares one assignee → drop the assignee column so the
   title keeps its width. */
.orbit-tasklist.no-assignee {
  --cols: 28px 92px minmax(160px, 1fr);
}
/* Multi-select checkbox column (header + per row). */
.task-check {
  display: flex;
  align-items: center;
  justify-content: center;
}
.col-head-row,
.task-row {
  display: grid;
  grid-template-columns: var(--cols);
  column-gap: 12px;
  align-items: center;
  padding: 0 12px;
}
.col-head-row {
  height: 38px;
  border-bottom: 1px solid var(--border-subtle);
  /* Pin the header so sort/select-all stay reachable while scrolling a long list.
     .tasks-body is the scroll container; an opaque bg + z-index occlude the rows
     passing underneath. */
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--bg-base);
}
.col-head {
  font-size: 12px;
  color: var(--text-3);
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Click-to-sort headers: hover/active darken, active shows a direction caret. */
.col-head.sortable {
  cursor: pointer;
  user-select: none;
  transition: color 0.12s ease;
}
.col-head.sortable:hover,
.col-head.active {
  color: var(--text-1);
}
.col-sort-caret {
  font-size: 11px;
}

.task-row {
  position: relative;
  height: 44px;
  border-bottom: 1px solid var(--bg-hover);
}
.task-row:hover {
  background: var(--bg-hover);
}
.task-cell {
  font-size: 13px;
  color: var(--text-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.task-title-cell {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.task-title {
  color: var(--text-1);
  font-size: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.task-title:hover {
  color: var(--brand);
}
/* A one-shot scheduled start, on the few rows that carry one. Secondary to the title in size and
   colour, and never shrunk: `flex: none` hands the whole cell's shrink to the title beside it, so
   a long title ellipses while the instant stays readable. Inline text, so the 44px row keeps its
   height and the windowing arithmetic above it stays arithmetic. */
.task-run-at {
  flex: none;
  font-size: 12px;
  color: var(--text-3);
  white-space: nowrap;
}
/* The half of that marker only a screen reader reads: ", once, in your own time zone", clipped
   out of the pixels because there is no room on a 44px row for a sentence the visible text can
   imply. CLIPPED, not `display: none` or `visibility: hidden` — those take it out of the
   accessibility tree along with the pixels, which is the whole thing it exists to stay in. Out of
   flow, so it costs the title cell no width and the row no height. Scoped to this one class
   rather than added as a general utility: nothing else here needs it yet. */
.task-run-at-note {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}
@keyframes tp-queued-fade {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
.task-creator {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
/* hover-revealed row actions, floated over the right edge */
.row-actions {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  gap: 2px;
  padding-left: 28px;
  opacity: 0;
  pointer-events: none;
  background: linear-gradient(90deg, rgba(245, 246, 247, 0) 0%, var(--bg-hover) 24%);
  transition: opacity 0.12s ease;
}
.task-row:hover .row-actions {
  opacity: 1;
  pointer-events: auto;
}

/* Status column: a labeled pill (text + shape + color) so status reads without relying
   on color alone. */
.task-status-cell {
  display: flex;
  align-items: center;
  min-width: 0;
}
.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 22px;
  padding: 0 9px 0 7px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.status-pill .status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}
.status-pill .anticon {
  font-size: 12px;
}
.status-pill.done {
  background: var(--success-bg);
  color: var(--success);
}
.status-pill.done .status-dot {
  background: var(--success-solid);
}
/* IN_PROGRESS uses a square dot — a second, color-independent cue vs. the round done/todo. */
.status-pill.ongoing {
  background: var(--brand-tint);
  color: var(--brand-strong);
}
.status-pill.ongoing .status-dot {
  background: var(--brand);
  border-radius: 2px;
}
.status-pill.todo {
  background: var(--fill-muted);
  color: var(--text-2);
}
.status-pill.todo .status-dot {
  background: transparent;
  border: 1.5px solid var(--text-4);
}
.status-pill.failed {
  background: var(--error-bg);
  color: var(--error);
}
.status-pill.failed .status-dot {
  background: var(--error-solid);
}
.status-pill.cancelled {
  background: var(--fill-muted);
  color: var(--text-3);
}
.status-pill.cancelled .status-dot {
  background: transparent;
  border: 1.5px solid var(--border);
}
.status-pill.running {
  background: var(--brand-tint);
  color: var(--brand-strong);
}
/* Queued (a PENDING session, nothing running yet): a gently fading pill, "waiting to run". */
.status-pill.queued {
  background: var(--brand-tint);
  color: var(--text-2);
  animation: tp-queued-fade 1.8s ease-in-out infinite;
}
.status-pill.queued .status-dot {
  background: var(--brand);
}
/* AWAITING_INPUT / INTERRUPTED: amber "needs you" pill, distinct from the blue live states. */
.status-pill.awaiting {
  background: var(--warning-bg);
  color: var(--warning);
}
.status-pill.awaiting .status-dot {
  background: var(--warning-solid);
}

/* ---- Agent console: two-pane master-detail (session list | conversation) ---- */
.workspace-split {
  display: flex;
  height: 100%;
  min-height: 0;
  /* One gutter token drives every horizontal gap. It lives on the panes (.session-col /
     .workspace-view), not here, so page edge → list → divider → conversation stay symmetric:
     each pane is inset --pane-gutter on both sides and the divider (zero margin) centers
     itself in the two panes' padding. The wrapper keeps no padding so the divider (a flex
     child) still stretches the full panel height. A symmetric layout forces the centre seam
     to 2×--pane-gutter — that's inherent, tune the single token to taste. */
  --pane-gutter: 20px;
}
.session-col {
  flex: none;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 24px var(--pane-gutter);
}
/* Draggable divider between the session list and the conversation. The visible
   1px line matches the old column border; ::before widens the grab area. */
.session-resizer {
  flex: none;
  width: 1px;
  margin: 0;
  position: relative;
  background: var(--border-subtle);
  cursor: col-resize;
}
.session-resizer::before {
  content: '';
  position: absolute;
  inset: 0 -6px;
}
.session-resizer:hover,
.session-resizer.resizing {
  background: var(--brand);
}
.session-col-head {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: none;
  height: 40px;
  padding-left: 2px;
}
.session-col-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.session-new {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: none;
  height: 38px;
  margin: 2px 0 8px;
  padding: 0 8px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--brand-tint);
  color: var(--brand);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
}
.session-new:hover {
  background: var(--brand-tint);
  border-color: var(--brand-border);
}
.session-new-kbd {
  margin-left: auto;
  padding: 1px 6px;
  border: 1px solid var(--brand-border);
  border-radius: 5px;
  font: inherit;
  font-size: 12px;
  line-height: 16px;
  color: var(--brand);
  opacity: 0.6;
}
.session-new.active {
  background: var(--brand-tint);
  border-color: var(--brand-border);
}
/* Search row. Shaped like the field it opens instead of a bare magnifier, so it reads as
   "search" without a tooltip, and full-width so it's a real target on touch — the one place
   ⌘K can't be pressed. Sits under New session and stays quiet: same column, lower priority. */
.session-search {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: none;
  height: 34px;
  margin: 0 0 8px;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-sunken);
  color: var(--text-3);
  font-size: 14px;
  cursor: pointer;
}
.session-search:hover {
  background: var(--bg-hover);
  border-color: var(--border);
  color: var(--text-2);
}
/* Drop the focus ring on mouse click; keep it for keyboard navigation. */
.session-search:focus {
  outline: none;
}
.session-search:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
.session-search-kbd {
  margin-left: auto;
  padding: 1px 6px;
  border: 1px solid var(--border);
  border-radius: 5px;
  font: inherit;
  font-size: 12px;
  line-height: 16px;
  color: var(--text-3);
}
.session-col .ant-segmented {
  flex: none;
  margin: 0 0 8px;
}
.session-col-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  /* The desktop session column is user-resizable, so row density follows this content box rather
     than the viewport. 280/220px here correspond roughly to the 320/260px outer column widths
     after its desktop gutters. Browsers without container queries keep the safe one-tag default. */
  container: session-list / inline-size;
  /* overflow-y:auto alone makes the browser compute overflow-x to `auto` too, so the
     few sub-pixels the rows spill once the vertical scrollbar narrows the client width
     surface a stray horizontal scrollbar along the bottom. Pin it hidden — a vertical
     list never scrolls sideways (titles/previews already ellipsize). */
  overflow-x: hidden;
}
/* Recency ("Today", "2–7 days ago", …) / tag section headings over the rows below them.
   Sticky so the heading of the group being scrolled through stays legible, and light enough
   that the rows — not the headings — carry the list's weight. */
.session-section-head {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 2px 4px;
  background: var(--bg-base);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-4);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.session-section-head:first-child {
  padding-top: 2px;
}
.session-col-list > section:not(:first-child) > .session-section-head {
  padding-top: 12px;
}
/* The Pinned heading folds its rows away, as Notes' Pinned does: the whole heading is the button,
   and the chevron at its end points down while the rows show, right once they are folded. */
.session-section-fold {
  width: 100%;
  justify-content: space-between;
  border: 0;
  font-family: inherit;
  line-height: inherit;
  text-align: left;
  cursor: pointer;
}
.session-section-chev {
  font-size: 10px;
  transition: transform 0.15s;
}
.session-section-chev.open {
  transform: rotate(90deg);
}
/* Foot of the list while the next page loads. */
.session-list-more {
  display: flex;
  justify-content: center;
  padding: 12px 0 16px;
}
/* The tag's own colour, so a "Group by Tag" heading reads as that tag at a glance. */
.session-section-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
/* Second line of a row: capped tags, then the reply preview. The preview takes what's left (and
   ellipsizes), so neither wraps the 64px row taller. */
.session-sub {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  margin-top: 4px;
}
/* Per-row tags: one named chip plus a fixed "+N" summary. The group has both a proportional and
   an absolute cap; otherwise two or three ordinary names can consume the reply preview completely
   in a resized column. The colour remains a scan aid only; the adjacent sr-only text carries every
   name independently of colour. */
.session-tag-chips {
  flex: 0 1 auto;
  min-width: 0;
  max-width: min(30%, 112px);
  display: flex;
  align-items: center;
  gap: 5px;
}
.session-tag-named {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
}
.session-tag-chip {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  max-width: 72px;
  height: 18px;
  padding: 0 7px;
  border-radius: 9px;
  font-size: 11.5px;
  line-height: 1;
  color: var(--chip-label, var(--chip));
  background: color-mix(in srgb, var(--chip) 13%, transparent);
}
.session-tag-chip-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
html[data-theme='dark'] .session-tag-chip {
  color: var(--chip-label-dark, var(--chip));
  background: color-mix(in srgb, var(--chip) 22%, transparent);
}
.session-tag-more {
  flex: none;
  font-size: 11px;
  color: var(--text-4);
}
.session-tag-more--total {
  display: none;
}
/* At the default 320px outer column the list content is about 280px wide. Below that, a named tag
   no longer leaves a useful reply preview, so show the exact total instead. */
@container session-list (max-width: 279px) {
  .session-tag-chips {
    flex: none;
    max-width: none;
  }
  .session-tag-named,
  .session-tag-more--remaining {
    display: none;
  }
  .session-tag-more--total {
    display: inline;
  }
}
/* View + tag menu. Names the current view rather than showing a bare icon, so the list is
   never silently scoped; tinted once it's off its defaults so a narrowed list is explained. */
.session-scope-menu {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  flex: none;
  padding: 2px 6px;
  border-radius: 6px;
  color: var(--text-3);
  font-size: 13px;
  cursor: pointer;
}
.session-scope-menu .anticon {
  font-size: 10px;
  color: var(--text-4);
}
.session-scope-menu:hover {
  background: var(--bg-sunken);
  color: var(--text-2);
}
.session-scope-menu.on,
.session-scope-menu.on .anticon {
  color: var(--brand);
}
.session-scope-menu.on {
  background: var(--brand-tint);
}
/* "Filter by Tag" carries the tag it's filtering to on the right, so the current filter
   reads without opening the submenu. Absent (not "All") while unfiltered — the default
   state should stay quiet. */
.scope-menu-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.scope-menu-value {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-4);
  font-size: 12px;
}
.scope-menu-value-text {
  max-width: 100px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Swatch + name for a tag in the filter submenu. */
.scope-tag-label {
  display: flex;
  align-items: center;
  gap: 8px;
}
/* The check sits at the row's trailing edge instead of ahead of the label, so names start on
   the menu's left padding rather than behind two leading columns. Fixed width and always
   present, so selecting a different row doesn't resize the menu. */
.scope-menu-check {
  flex: none;
  width: 12px;
  color: var(--text-2);
  font-size: 12px;
  line-height: 1;
}
.session-row.active {
  background: var(--brand-tint);
  --session-menu-surface: var(--brand-tint);
}
.session-row.active:hover {
  background: var(--brand-tint-hover);
  --session-menu-surface: var(--brand-tint-hover);
}
.workspace-draft {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ---- Agent detail view (conversation pane) ---- */
.workspace-view {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 16px var(--pane-gutter);
  /* Anchor the drag-and-drop overlay (.workspace-dropzone) to the whole pane. */
  position: relative;
}
.workspace-header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: none;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-subtle);
}
.workspace-status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--dot-idle);
  flex: none;
}
.workspace-status-dot.online {
  background: var(--success-solid);
}
.workspace-header-main {
  flex: 1;
  min-width: 0;
}
.workspace-title-line {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.workspace-title-line .workspace-name,
.workspace-title-line .workspace-name-input {
  min-width: 0;
}
.workspace-name {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.coordinator-badge {
  display: inline-flex;
  align-items: center;
  flex: none;
  height: 18px;
  padding: 0 6px;
  border: 1px solid var(--brand-border);
  border-radius: 999px;
  background: var(--brand-tint);
  color: var(--brand);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.01em;
  white-space: nowrap;
}
/* Inline rename editor that replaces .workspace-name on double-click — matches the title's
   type so the swap is seamless, with a brand underline to signal edit mode. */
.workspace-name-input {
  display: block;
  box-sizing: content-box;
  /* width is set inline from the mirror (fits the text); cap so a long title stops at the
     header edge and scrolls instead of overflowing. */
  max-width: 100%;
  min-width: 3ch;
  font-family: inherit;
  font-size: 18px;
  font-weight: 600;
  color: var(--text-1);
  padding: 0;
  margin: 0;
  border: none;
  border-bottom: 1px solid var(--brand);
  background: transparent;
  outline: none;
}
/* Off-screen twin of .workspace-name-input used only to measure the text width. */
.workspace-name-mirror {
  position: absolute;
  left: -9999px;
  top: 0;
  visibility: hidden;
  white-space: pre;
  pointer-events: none;
  font-family: inherit;
  font-size: 18px;
  font-weight: 600;
}
.workspace-header-task {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  margin-bottom: 3px;
  padding: 0;
  border: none;
  background: none;
  font-size: 12px;
  line-height: 1.3;
  color: var(--text-3);
  cursor: pointer;
}
.workspace-header-task:hover {
  color: var(--brand);
}
.workspace-header-task-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-sub {
  font-size: 12.5px;
  color: var(--text-3);
  margin-top: 2px;
}

/* Background-process tray above the composer (BackgroundShellsTray.tsx): the shells the
   agent launched with Bash(run_in_background), collapsed to one line, expandable to a list
   of processes (command · id · age) each showing its latest polled output. Shares the
   collapsed-bar visual language with .wt-bar below. */
.bg-tray {
  margin: 0 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-subtle);
  overflow: hidden;
}
.bg-tray-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 2px 6px 2px 10px;
  font-size: 12px;
  cursor: pointer;
}
.bg-tray-row:hover {
  background: var(--bg-hover);
}
.bg-tray-ico {
  flex: none;
  color: var(--text-3);
}
.bg-tray-title {
  color: var(--text-1);
  font-weight: 500;
}
/* In the body face, as iOS writes both counts: in monospace the Tasks row's sentence ran wide enough
   to leave a phone a few letters of its title. */
.bg-tray-count {
  color: var(--text-3);
}
.bg-tray-list {
  border-top: 1px solid var(--border-subtle);
  padding: 4px 8px 6px;
  max-height: 320px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.bg-shell {
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: var(--bg-raised);
  overflow: hidden;
  /* Keep natural height: as a flex child of the height-capped .bg-tray-list,
     'overflow: hidden' would otherwise let flex-shrink squash an expanded row
     to fit, clipping its output with no scrollbar to reach the rest. */
  flex: none;
}
.bg-shell-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 8px;
  cursor: pointer;
  font-size: 12px;
}
.bg-shell-head:hover {
  background: var(--bg-hover);
}
.bg-shell-cmd {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-1);
  font-family: var(--font-mono, ui-monospace, monospace);
}
.bg-shell-id {
  flex: none;
  color: var(--text-3);
  font-family: var(--font-mono, ui-monospace, monospace);
}
.bg-shell-age {
  flex: none;
  color: var(--text-3);
}
.bg-shell-caret {
  flex: none;
  display: inline-flex;
  color: var(--text-3);
}
.bg-shell-detail {
  border-top: 1px solid var(--border-subtle);
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.bg-shell-empty {
  color: var(--text-3);
  font-size: 12px;
  font-style: italic;
}
.bg-shell-meta {
  color: var(--text-3);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* "Tasks created here" (SessionCreatedTasksStrip.tsx) sits in the tray's shell above; these are
   only what a task list adds to it. Collapsed, the title never wraps and the sentence never gives
   way: beside the sentence the title is what truncates, beside a lone task's name the name does;
   the failed count is red. Opened, one row per task: a fixed status column, the title (with what it
   replaces, in grey), its age; then the links to the rest. */
.ct-head {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ct-head:has(+ .ct-one) {
  flex: none;
}
.ct-count {
  white-space: nowrap;
}
.ct-failed {
  color: var(--error-solid);
}
.ct-one {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--brand);
}
.ct-one + .status-pill,
.ct-row .status-pill {
  height: 20px;
  font-size: 11.5px;
}
.ct-list {
  border-top: 1px solid var(--border-subtle);
  max-height: 320px;
  overflow: auto;
  display: flex;
  flex-direction: column;
}
.ct-row {
  /* Natural height, so a list past its cap scrolls rather than squashing its rows to fit. */
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 31px;
  padding: 0 10px;
  font-size: 12px;
  color: var(--text-1);
  text-decoration: none;
}
.ct-row + .ct-row {
  border-top: 1px solid var(--border-subtle);
}
.ct-row:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}
.ct-pill {
  flex: none;
  width: 82px;
  display: flex;
}
.ct-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ct-replaces {
  color: var(--text-3);
}
.ct-age {
  flex: none;
  color: var(--text-3);
}
.ct-caret {
  flex: none;
  color: var(--text-4);
}
.ct-foot {
  display: flex;
  gap: 18px;
  padding: 8px 10px;
  border-top: 1px solid var(--border-subtle);
  font-size: 12px;
}
.ct-foot a {
  color: var(--brand);
  text-decoration: none;
}

/* Worktree status bar above the composer (SessionOutputs.tsx): the branch this session's
   work lives on + its diff, collapsed to one line, expandable to the changed files. */
.wt-bar {
  margin: 0 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-subtle);
  overflow: hidden;
}
.wt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 2px 6px 2px 10px;
  font-size: 12px;
}
/* Whole-row click target when there's a file list to expand. */
.wt-row-toggle {
  cursor: pointer;
}
.wt-row-toggle:hover {
  background: var(--bg-hover);
}
.wt-branch {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 56%;
  padding: 2px 7px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
  color: var(--text-1);
  font-family: var(--font-mono, ui-monospace, monospace);
  cursor: pointer;
}
.wt-branch:hover {
  background: var(--bg-hover);
}
.wt-branch-ico {
  flex: none;
  color: var(--text-3);
}
.wt-branch-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wt-dim {
  color: var(--text-3);
}
.wt-stat {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono, ui-monospace, monospace);
  color: var(--text-3);
}
.wt-add {
  color: var(--success-solid);
}
.wt-del {
  color: var(--error-solid);
}
.wt-spacer {
  flex: 1 1 auto;
}
.wt-expand {
  flex: none;
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: var(--text-3);
  border-radius: 5px;
  cursor: pointer;
}
.wt-expand:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}
.wt-files-panel {
  border-top: 1px solid var(--border-subtle);
  padding: 7px 10px 8px;
  max-height: 220px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.session-file {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 1px 0;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
}
.session-file-status {
  flex: none;
  width: 16px;
  text-align: center;
  font-weight: 700;
  color: var(--text-3);
}
.session-file-status.st-a {
  color: var(--success-solid);
}
.session-file-status.st-d {
  color: var(--error-solid);
}
.session-file-status.st-r {
  color: var(--warning-solid);
}
.session-file-path {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: baseline;
  overflow: hidden;
  color: var(--text-2);
}
/* Dimmed directory gives up width first (ellipsis); the basename never shrinks, so files in the
   same folder stay distinguishable instead of all truncating to the shared prefix. */
.session-file-dir {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-4);
}
.session-file-name {
  flex: 0 0 auto;
  white-space: nowrap;
}
.session-file-stat {
  flex: none;
  display: inline-flex;
  gap: 6px;
}
.session-file-stat .add {
  color: var(--success-solid);
}
.session-file-stat .del {
  color: var(--error-solid);
}
.session-file-bin {
  flex: none;
  color: var(--text-4);
  font-style: italic;
}
/* In the expanded list and the diff drawer, each file row is a button that opens its diff. */
.session-file-btn {
  width: 100%;
  border: 0;
  background: transparent;
  border-radius: 5px;
  padding: 2px 6px;
  margin: 0 -6px;
  cursor: pointer;
  text-align: left;
  color: inherit;
}
.session-file-btn:hover {
  background: var(--bg-hover);
}
.session-file-btn.active {
  background: var(--bg-active, var(--bg-hover));
}
.session-file-btn.active .session-file-name {
  color: var(--text-1);
}
/* ── Worktree file-diff drawer (click a changed file → its unified diff) ─────── */
.wt-diff-head {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}
.wt-diff-head-sub {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-3);
}
.wt-diff-drawer .ant-drawer-body {
  padding: 0;
}
.wt-diff-body {
  display: flex;
  height: 100%;
  min-height: 0;
}
.wt-diff-list {
  flex: none;
  width: 248px;
  border-right: 1px solid var(--border-subtle);
  padding: 8px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.wt-diff-pane {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.wt-diff-pane-head {
  flex: none;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 14px;
  border-bottom: 1px solid var(--border-subtle);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12.5px;
}
.wt-diff-pane-path {
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--text-1);
}
.wt-diff-pane-stat {
  flex: none;
  display: inline-flex;
  gap: 8px;
}
.wt-diff-pane-stat .add {
  color: var(--success-solid);
}
.wt-diff-pane-stat .del {
  color: var(--error-solid);
}
.wt-diff-view {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  border: 0;
  border-radius: 0;
}
.wt-diff-empty {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  color: var(--text-3);
  font-size: 13px;
}
/* Narrow screens: stack the file list above the diff instead of a side rail. */
@media (max-width: 700px) {
  .wt-diff-body {
    flex-direction: column;
  }
  .wt-diff-list {
    width: auto;
    border-right: 0;
    border-bottom: 1px solid var(--border-subtle);
    max-height: 30vh;
  }
}
.wt-merge {
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px dashed var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 11.5px;
  color: var(--text-3);
}
.wt-merge-cmd {
  align-self: flex-start;
  font-family: var(--font-mono, ui-monospace, monospace);
  background: var(--bg-sunken);
  color: var(--text-2);
  padding: 2px 7px;
  border-radius: 6px;
  cursor: pointer;
}
.wt-merge-cmd:hover {
  background: var(--bg-hover);
}
/* "Merge to main": a compact action button on the bar row; failure detail + the copyable
   manual command live in the expandable panel below (.wt-merge-manual). */
.wt-merge-btn {
  flex: none;
  padding: 2px 10px;
  border: 1px solid var(--brand-border);
  border-radius: 6px;
  background: var(--brand-tint);
  color: var(--brand);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}
.wt-merge-btn:hover:not(:disabled) {
  background: var(--brand-tint-hover);
}
.wt-merge-btn:disabled {
  opacity: 0.55;
  cursor: default;
}
.wt-merge-btn-failed {
  border-color: var(--error-border, var(--error));
  background: var(--error-bg);
  color: var(--error);
}
.wt-merge-done {
  flex: none;
  font-weight: 600;
  color: var(--success);
}
/* Branch divergence: the worktree is on a branch Orbit isn't tracking (an in-worktree checkout -b).
   An amber flag naming the untracked branch, with an Adopt action to re-point the session. */
.wt-diverged {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.wt-diverged-label {
  font-weight: 600;
  color: var(--warning);
  cursor: default;
}
.wt-adopt {
  flex: none;
  padding: 2px 10px;
  border: 1px solid var(--warning-border);
  border-radius: 6px;
  background: var(--warning-bg);
  color: var(--warning);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}
.wt-adopt:hover:not(:disabled) {
  background: var(--bg-hover);
}
.wt-adopt:disabled {
  opacity: 0.55;
  cursor: default;
}
/* Split "Merge to <branch>" button: the main action butted up against a caret that opens a
   dropdown of other branches to merge into. The main button's right border is the divider. */
.wt-merge-split-wrap {
  flex: none;
  display: inline-flex;
  align-items: stretch;
}
.wt-merge-btn-split {
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}
.wt-merge-caret {
  display: inline-flex;
  align-items: center;
  padding: 0 6px;
  border: 1px solid var(--brand-border);
  border-left: none;
  border-top-right-radius: 6px;
  border-bottom-right-radius: 6px;
  background: var(--brand-tint);
  color: var(--brand);
  font-size: 10px;
  line-height: 1;
  cursor: pointer;
}
.wt-merge-caret:hover {
  background: var(--brand-tint-hover);
}
.wt-merge-caret.wt-merge-btn-failed {
  border-color: var(--error-border, var(--error));
  background: var(--error-bg);
  color: var(--error);
}
/* A branch row in the merge-target dropdown: the name + a subtle "default" tag on main/master. */
.wt-merge-target {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.wt-merge-target-name {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
}
.wt-merge-target-tag {
  font-size: 10px;
  color: var(--text-3);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  padding: 0 4px;
}
/* The merge-target dropdown popup: height-capped, and searchable for long branch lists. The panel
   itself carries the elevated surface (antd theme tokens, set inline), so the antd menu inside it is
   flattened to just the scrollable list of branches. */
.wt-merge-menu-panel {
  overflow: hidden;
  min-width: 208px;
}
.wt-merge-menu-search {
  padding: 6px;
}
.wt-merge-menu-list.ant-dropdown-menu {
  max-height: 300px;
  overflow-y: auto;
  box-shadow: none;
  border-radius: 0;
}
.wt-merge-menu-empty {
  padding: 12px 8px;
  text-align: center;
  font-size: 12px;
}
.wt-merge-manual {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.wt-merge-err {
  color: var(--error);
  white-space: pre-wrap;
  word-break: break-word;
}
.wt-merge-or {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
/* Non-git: ran in the shared dir; amber bar with the one-click enable. */
.wt-bar-nogit {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.wt-warn {
  font-weight: 600;
  color: var(--warning);
}
.wt-enable {
  flex: none;
  padding: 3px 11px;
  border: 1px solid var(--warning-border);
  border-radius: 6px;
  background: var(--bg-raised);
  color: var(--warning);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}
.wt-enable:hover:not(:disabled) {
  background: var(--bg-hover);
}
.wt-enable:disabled {
  opacity: 0.55;
  cursor: default;
}
/* The machine's shared checkout is mid-merge/rebase: every session's merge here is blocked, so
   this sits above the per-session bar wearing the same amber as the other "fix this first" state. */
.wt-bar-wedged {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.wt-wedge-detail {
  gap: 8px;
  font-size: 12px;
  color: var(--text-2);
  min-width: 0;
}
.wt-wedge-root {
  font-family: var(--font-mono, ui-monospace, monospace);
  flex: none;
}
.wt-wedge-files {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Connective text between the two halves of the by-hand merge recipe (they run in two dirs). */
.wt-merge-where {
  color: var(--text-3, var(--text-2));
}
/* A failed commit (SessionOutputs CommitFailure): what happened, why and what to do, with git's own
   words behind a toggle. */
.wt-commit-fail {
  display: flex;
  flex-direction: column;
  gap: 4px;
  /* Inset to the row's own left edge (.wt-row), not flush with the bar's border. */
  padding: 0 10px 8px;
}
.wt-commit-fail-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--error);
  font-size: 12.5px;
  font-weight: 600;
}
.wt-commit-fail-icon {
  color: var(--error-solid);
}
.wt-commit-fail-why {
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.5;
  word-break: break-word;
}
.wt-commit-fail-acts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-top: 3px;
}
.wt-commit-fail-toggle {
  padding: 0;
  border: none;
  background: none;
  color: var(--text-2);
  font-size: 12px;
  cursor: pointer;
}
.wt-commit-fail-toggle:hover {
  color: var(--text-1);
}
.wt-commit-fail-git {
  margin: 2px 0 0;
  padding: 7px 9px;
  border-radius: 6px;
  background: var(--bg-sunken);
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}
.workspace-header-count {
  font-size: 13px;
  color: var(--text-2);
  flex: none;
}
.session-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
  flex: none;
  margin: 20px 0 4px;
}
/* Wraps the scroll area so the floating "jump to bottom" button can anchor to its
   bottom edge (= just above the composer) without overlapping the input. */
.workspace-scroll-wrap {
  flex: 1;
  min-height: 0;
  position: relative;
  display: flex;
  flex-direction: column;
}
.workspace-sessions {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  /* The transcript does its own anchoring when a page of older messages lands above the viewport
     (WorkspaceView's prepend anchor). The browser's scroll anchoring adjusts for the same growth,
     one layout later, and the two compensations fight: the reader is thrown a page down from
     wherever they were reading. Ours is the one that can tell a prepend from a fold, so it wins. */
  overflow-anchor: none;
}
/* Canonical completion-repair obligations sit outside the transcript scroller: the command has
   already finished, so burying this behind a stale Running transcript would recreate the product
   failure the obligation exists to explain. Read-only by design — repair actions belong to the
   coordinator protocol, not ad-hoc Cancel/Rerun buttons in this session. */
.completion-ack-obligations {
  flex: none;
  display: grid;
  gap: 8px;
  max-height: 40%;
  overflow-y: auto;
  padding: 10px 18px 0;
}
.completion-ack-obligation {
  padding: 11px 13px;
  border: 1px solid var(--warning-border);
  border-left: 3px solid var(--warning-solid);
  border-radius: 8px;
  background: var(--warning-bg);
  color: var(--text-1);
}
.completion-ack-obligation-head {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--warning);
  font-size: 13.5px;
  font-weight: 650;
}
.completion-ack-obligation-reason {
  margin: 7px 0 9px;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.45;
}
.completion-ack-obligation-facts {
  display: grid;
  gap: 5px;
  margin: 0;
}
.completion-ack-obligation-facts > div {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  gap: 10px;
  font-size: 12.5px;
  line-height: 1.4;
}
.completion-ack-obligation-facts dt {
  color: var(--text-3);
}
.completion-ack-obligation-facts dd {
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
}
.completion-ack-obligation-facts code {
  color: inherit;
}
.completion-ack-obligation-revision {
  margin-left: 8px;
  color: var(--text-3);
  white-space: nowrap;
}
/* Find in session (⌘F). Floats over the top-right of the transcript, browser-find style, and
   sits outside .workspace-sessions so its own text is never part of what it searches. */
.find-bar {
  position: absolute;
  top: 12px;
  right: 20px;
  z-index: 5;
  width: min(420px, calc(100% - 40px));
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-raised);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.14);
  overflow: hidden;
}
.find-head {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 6px 5px 10px;
}
.find-icon {
  color: var(--text-3);
  font-size: 13px;
}
.find-input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-size: 13px;
  color: var(--text-1);
}
.find-input::placeholder {
  color: var(--text-4);
}
/* Tabular figures so stepping through matches doesn't jiggle the buttons beside the count. */
.find-count {
  min-width: 62px;
  text-align: right;
  padding-right: 4px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--text-3);
  white-space: nowrap;
}
.find-count.find-none {
  color: var(--error);
}
.find-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 12px;
  cursor: pointer;
}
.find-btn:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}
/* The server's hits — matches anywhere in the session, including history the transcript hasn't
   loaded and tool bodies that are folded away. Capped so the list never swallows the transcript. */
.find-list {
  max-height: min(46vh, 300px);
  overflow-y: auto;
  border-top: 1px solid var(--border-subtle);
}
.find-row {
  padding: 7px 12px;
  cursor: pointer;
  border-bottom: 1px solid var(--border-subtle);
}
.find-row:last-child {
  border-bottom: none;
}
/* One highlight, driven by the keyboard cursor — hover sets that cursor rather than painting a
   second, competing one (mirrors the ⌘K palette). */
.find-row:hover {
  background: var(--bg-hover);
}
.find-row.active {
  background: var(--brand-tint);
}
.find-row-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: var(--text-3);
}
.find-row-kind {
  font-weight: 600;
  color: var(--text-2);
}
.find-row-snippet {
  margin-top: 2px;
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-1);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.find-row-snippet mark {
  background: rgba(250, 204, 21, 0.45);
  color: inherit;
  padding: 0 1px;
  border-radius: 2px;
}
/* Painted from Ranges via the CSS Custom Highlight API — see SessionFind. ::highlight() only
   accepts a handful of properties (colour, background, text-decoration, text-shadow). */
::highlight(orbit-find) {
  background-color: rgba(250, 204, 21, 0.4);
}
::highlight(orbit-find-current) {
  background-color: #f5a623;
  color: #1f2329;
}
/* Outlines the card a jump landed on. Earns its keep when the match itself is folded away inside
   it (a collapsed tool body), where there is no highlight to look at. */
.find-flash {
  animation: find-flash 1.4s ease-out;
}
@keyframes find-flash {
  from {
    box-shadow: 0 0 0 2px var(--warning-solid);
  }
  to {
    box-shadow: 0 0 0 2px transparent;
  }
}
/* The record a link opened the session at (`?at=`, lib/transcriptDeepLink): tinted and outlined for
   a moment — longer than a find hit's flash, since the page has only just opened on it. */
.record-flash {
  animation: record-flash 2.4s ease-out;
}
@keyframes record-flash {
  0%,
  40% {
    background-color: var(--brand-tint);
    box-shadow: 0 0 0 2px var(--brand-border);
  }
  to {
    background-color: transparent;
    box-shadow: 0 0 0 2px transparent;
  }
}
/* The newer page a window opened at a record is pulling in, over the bottom it arrives under. */
.chat-newer-bottom {
  position: absolute;
  bottom: 60px;
  left: 0;
  right: 0;
  z-index: 4;
  text-align: center;
  pointer-events: none;
}
:root[data-theme='dark'] .find-bar {
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);
}
/* ChatGPT-style snap-to-latest button; only mounted while the tail is out of view — scrolled up
   off it, or stranded below a transcript still pinned to it (WorkspaceView's `stranded`). */
.scroll-to-bottom {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--bg-raised);
  color: var(--text-1);
  font-size: 15px;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  transition: background 0.15s, box-shadow 0.15s;
}
.scroll-to-bottom:hover {
  background: var(--bg-sunken);
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.16);
}
.session-row {
  --session-menu-surface: var(--bg-base);
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 64px;
  padding: 0 8px;
  border-bottom: 1px solid var(--bg-hover);
  cursor: pointer;
  /* Keep the swipe-away content from spilling past the row's edges. */
  overflow: hidden;
}
/* Wraps the row's icon + text so a touch swipe can slide it either way, exposing the swipe
   actions behind it. On desktop it never translates (transform stays 0). */
.session-swipe {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 0;
  transition: transform 0.18s ease;
}
.session-swipe.dragging,
.session-swipe-actions.dragging {
  transition: none; /* track the finger 1:1 mid-drag; only snaps animate */
}
/* Touch swipe actions, laid out like the iOS list: swipe right exposes the leading edge
   (Complete or Move to Open, then Pin), swipe left the trailing one (Delete). Each edge is
   exactly as wide as the gap the sliding content opens, so the two animate as one. */
.session-swipe-actions {
  position: absolute;
  top: 0;
  bottom: 0;
  display: flex;
  overflow: hidden;
  transition: width 0.18s ease;
}
.session-swipe-actions.leading {
  left: 0;
}
.session-swipe-actions.trailing {
  right: 0;
}
.session-swipe-action {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  color: #fff;
  font-size: 20px;
  cursor: pointer;
  transition: flex-grow 0.15s ease;
}
.session-swipe-action[aria-disabled='true'] {
  opacity: 0.45;
}
/* Past the full-swipe mark the first action fills the gap, its icon riding beside the row. */
.session-swipe-actions.armed .session-swipe-action:first-child {
  justify-content: flex-end;
  padding-right: 26px;
}
.session-swipe-actions.armed .session-swipe-action:not(:first-child) {
  flex-grow: 0;
}
/* The iOS system colours the native swipe buttons use. */
.session-swipe-action.complete {
  background: #34c759;
}
.session-swipe-action.restore {
  background: #007aff;
}
.session-swipe-action.pin {
  background: #5856d6;
}
.session-swipe-action.delete,
.session-swipe-action.purge {
  background: #ff3b30;
}
:root[data-theme='dark'] .session-swipe-action.complete {
  background: #30d158;
}
:root[data-theme='dark'] .session-swipe-action.restore {
  background: #0a84ff;
}
:root[data-theme='dark'] .session-swipe-action.pin {
  background: #5e5ce6;
}
:root[data-theme='dark'] .session-swipe-action.delete,
:root[data-theme='dark'] .session-swipe-action.purge {
  background: #ff453a;
}
/* Share and Move sit inside Delete, in the colours the iOS row gives them (blue, indigo). */
.session-swipe-action.share {
  background: #007aff;
}
.session-swipe-action.move {
  background: #5856d6;
}
:root[data-theme='dark'] .session-swipe-action.share {
  background: #0a84ff;
}
:root[data-theme='dark'] .session-swipe-action.move {
  background: #5e5ce6;
}
@media (hover: hover) {
  .session-row:hover {
    background: var(--bg-hover);
    --session-menu-surface: var(--bg-hover);
  }
}
.session-row.menu-open:not(.active) {
  background: var(--bg-hover);
  --session-menu-surface: var(--bg-hover);
}
@media (min-width: 961px) {
  .session-row {
    border-radius: 6px;
  }
}
/* Trash rows are managed, not opened — no pointer affordance. */
.session-row.no-open {
  cursor: default;
}
.session-icon {
  display: flex;
  width: 16px;
  flex: none;
}
.session-main {
  flex: 1;
  min-width: 0;
}
/* Title is the only flexible item; fixed trailing metadata stays visible while it ellipsizes. */
.session-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.session-title {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  color: var(--text-1);
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.session-time {
  flex: none;
  font-size: 12.5px;
  color: var(--text-4);
}
.session-project-row .session-title {
  font-weight: 600;
}
.session-project-icon {
  position: relative;
  color: var(--brand);
  font-size: 16px;
}
.session-project-status {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
  box-shadow: 0 0 0 2px var(--session-menu-surface);
}
.session-project-status.needs-you {
  background: var(--warning);
}
.session-project-status.jobs {
  animation: status-glyph-breathe 2.4s ease-in-out infinite;
}
.session-project-progress {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  height: 18px;
  padding: 0 4px;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-3);
  font-size: 10px;
  line-height: 1;
  background: transparent;
  cursor: pointer;
  font-family: inherit;
}
.session-project-progress.done {
  color: var(--success);
  border-color: var(--success-border);
  background: var(--success-bg);
}
.session-project-progress:hover,
.session-project-progress:focus-visible {
  border-color: var(--brand);
}
.session-project-page-progress {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  color: var(--text-3);
}
.session-project-page-progress a {
  margin-left: auto;
  font-size: 16px;
  color: var(--text-3);
}
.session-project-page-progress a:hover {
  color: var(--brand);
}
.session-project-page-header .session-kebab {
  border: 0;
  background: transparent;
}
.session-project-progress-bar {
  display: flex;
  width: 32px;
  height: 4px;
  overflow: hidden;
  border-radius: 2px;
  background: var(--text-4);
}
.session-project-progress-bar .done {
  background: var(--success);
}
.session-project-progress-bar .running {
  background: var(--brand);
}
.session-project-progress-bar .failed {
  background: var(--error);
}
/* A public link opens this session (the list row's `shared`): a globe beside the time. */
.session-shared {
  display: inline-flex;
  flex: none;
  color: var(--success);
  font-size: 12px;
}
/* The conversation header's "Shared · Live": says the session is public, and opens its dialog. */
.session-shared-pill {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 5px;
  height: 20px;
  padding: 0 8px;
  border: 0;
  border-radius: 999px;
  background: var(--success-bg);
  color: var(--success);
  font: inherit;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
}
.session-shared-pill:hover {
  box-shadow: inset 0 0 0 1px var(--success-border);
}
.session-share-icon-live {
  color: var(--success);
}
/* Merge failed/conflicted on this session's branch — a red nudge so it's noticed even
   when the session isn't open (its status bar, where the reason lives, is then unseen). */
.session-merge-badge {
  flex: none;
  font-size: 12.5px;
  line-height: 1;
  color: var(--error);
}
/* Last assistant reply, flattened to one line. Shares the second line with the row's tags
   (.session-sub owns the spacing above) — darker than the time so it reads as content,
   not metadata. */
.session-preview {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  color: var(--text-2);
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Live status line (in place of a reply, while the agent works). Colour matches the
   status glyph: blue = running, amber = waiting on you, grey = queued, a background
   process the agent left up (which outlives the turn but isn't the agent working), or a
   watch that will resume the session (nothing is running, and nobody is being asked). */
.session-preview.tone-running {
  color: var(--brand);
}
.session-preview.tone-approval {
  color: var(--warning-solid);
}
.session-preview.tone-queued,
.session-preview.tone-background,
.session-preview.tone-watching,
.session-preview.tone-review {
  color: var(--text-3);
}
/* Float above full-width text without changing its layout when actions appear. */
.session-right {
  position: absolute;
  top: 0;
  right: 8px;
  bottom: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  width: 32px;
}
.session-right::before {
  content: '';
  position: absolute;
  inset: 0 -8px 0 -28px;
  /* Composite translucent dark-mode tints onto an opaque surface before fading. */
  background: linear-gradient(var(--session-menu-surface), var(--session-menu-surface)), var(--bg-base);
  mask-image: linear-gradient(to right, transparent, #000 42%);
  pointer-events: none;
}
/* Touch phones use swipes; narrow desktop windows still need the menu for mouse/keyboard. */
@media (max-width: 960px) and (hover: none) and (pointer: coarse) {
  .session-right {
    display: none;
  }
}
.session-actions {
  display: flex;
}
.session-kebab {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  color: var(--text-3);
  font-size: 16px;
  flex: none;
}
/* Folder controls keep their existing expanded target; session actions use a real button. */
.session-folder-more::before,
.session-folder-head-more::before {
  content: '';
  position: absolute;
  top: -18px;
  bottom: -18px;
  left: -10px;
  right: -10px;
}
.session-kebab:hover {
  background: var(--bg-hover-strong);
  color: var(--text-1);
}
.session-actions > .session-kebab {
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  background: var(--bg-hover-strong);
  color: var(--text-1);
  font: inherit;
  font-size: 16px;
  cursor: pointer;
}
/* Hide the button and its fade together, while keeping keyboard access. */
@media (hover: hover) and (pointer: fine) {
  .session-right {
    opacity: 0;
    pointer-events: none;
  }
  .session-row:hover .session-right,
  .session-row:focus-within .session-right,
  .session-row.menu-open .session-right {
    opacity: 1;
    pointer-events: auto;
  }
}
.session-row.active .session-actions > .session-kebab {
  background: color-mix(in srgb, var(--brand) 10%, var(--session-menu-surface));
}
.session-actions > .session-kebab:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
.session-row-menu {
  min-width: 240px;
}
.session-row-menu .session-menu-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.session-row-menu .session-menu-label kbd {
  flex: none;
  color: var(--text-3);
  font: inherit;
  font-size: 12px;
  line-height: 16px;
}
.session-status {
  font-size: 12.5px;
}

/* ---- Session folders (docs/session-folders-move-design.md §3, §7) ---- */
/* A folder row: one line above Pinned and the time sections, shorter than a session row so the
   two read apart at a glance. The folder is indigo — Move's colour, and not the grey folder a
   Workspace row draws in the sidebar. */
.session-folder-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 44px;
  padding: 0 8px;
  border-bottom: 1px solid var(--bg-hover);
  cursor: pointer;
  --row-bg: var(--bg-raised);
}
.session-folder-row.menu-open {
  background: var(--bg-hover);
  --row-bg: var(--bg-hover);
}
.session-folder-row:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: -2px;
}
.session-folder-row.editing {
  height: auto;
  min-height: 44px;
  padding-top: 8px;
  padding-bottom: 8px;
  align-items: flex-start;
  cursor: default;
}
.session-folder-icon {
  position: relative;
  justify-content: center;
  color: #5856d6;
  font-size: 16px;
}
:root[data-theme='dark'] .session-folder-icon {
  color: #7d7aff;
}
.session-folder-row.editing .session-folder-icon {
  margin-top: 5px;
}
/* What the sessions inside are doing, on the folder as the sidebar marks a Workspace: still while
   one runs, breathing while only a background job does. */
.session-folder-activity {
  position: absolute;
  right: -3px;
  bottom: -1px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
  box-shadow: 0 0 0 1.5px var(--row-bg);
}
.session-folder-activity.jobs {
  animation: status-glyph-breathe 2.4s ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) {
  .session-folder-activity.jobs {
    animation: none;
  }
}
.session-folder-name {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.session-folder-needs {
  flex: none;
  padding: 0 7px;
  border-radius: 999px;
  background: var(--warning-bg);
  color: var(--warning);
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
}
.session-folder-count {
  flex: none;
  min-width: 10px;
  text-align: right;
  font-size: 12.5px;
  color: var(--text-4);
  font-variant-numeric: tabular-nums;
}
/* The trailing slot: the chevron at rest, the folder's ⋯ in its place on hover or while its menu
   is open. On touch there is no hover, and the folder's page carries the same ⋯. */
.session-folder-end {
  position: relative;
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 16px;
}
.session-folder-chev {
  color: var(--text-4);
  font-size: 10px;
}
.session-kebab.session-folder-more {
  position: absolute;
  display: none;
  width: 24px;
  height: 24px;
  font-size: 15px;
}
.session-folder-row.menu-open .session-folder-chev {
  display: none;
}
.session-folder-row.menu-open .session-folder-more {
  display: flex;
  background: var(--bg-hover-strong);
  color: var(--text-1);
}
@media (hover: hover) {
  .session-folder-row:hover {
    background: var(--bg-hover);
    --row-bg: var(--bg-hover);
  }
  .session-folder-row:hover .session-folder-chev {
    display: none;
  }
  .session-folder-row:hover .session-folder-more {
    display: flex;
  }
}
/* New Folder… and Rename…: the name is typed where the folder's name goes. */
.session-folder-edit {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.folder-name-input {
  box-sizing: border-box;
  width: 100%;
  height: 28px;
  padding: 0 8px;
  border: 1px solid var(--brand);
  border-radius: 6px;
  background: var(--bg-raised);
  box-shadow: 0 0 0 2px var(--brand-tint);
  color: var(--text-1);
  font: inherit;
  font-size: 14px;
  outline: none;
}
.folder-name-input.error {
  border-color: var(--error);
  box-shadow: 0 0 0 2px var(--error-bg, rgba(255, 77, 79, 0.12));
}
.session-folder-hint {
  font-size: 12px;
  color: var(--text-4);
}
.session-folder-error {
  font-size: 12px;
  line-height: 1.45;
  color: var(--error);
}
.session-folder-head + .session-folder-error {
  margin: -4px 0 6px 30px;
}
/* A folder's page: back to the list · the folder, over the workspace it is in · its ⋯. */
.session-folder-head {
  gap: 4px;
}
.session-folder-back {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin-left: -6px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  cursor: pointer;
}
.session-folder-back:hover {
  background: var(--bg-sunken);
  color: var(--text-1);
}
.session-folder-titles {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}
.session-folder-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 19px;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.session-folder-workspace {
  font-size: 12px;
  line-height: 15px;
  color: var(--text-4);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.session-kebab.session-folder-head-more {
  margin-left: auto;
  cursor: pointer;
}

/* ---- The Move dialog (§4, §5) ---- */
.move-dialog-title {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.move-dialog-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  margin-left: -6px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  cursor: pointer;
}
.move-dialog-back:hover:not(:disabled) {
  background: var(--bg-sunken);
}
.move-dialog-sub {
  margin: -4px 0 14px;
  font-size: 13px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.move-dialog-group {
  margin: 0 0 4px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-4);
}
.move-dialog-list {
  display: flex;
  flex-direction: column;
  margin: 0 -8px 14px;
}
.move-dialog-option {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 36px;
  padding: 6px 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-1);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.move-dialog-option:hover:not(:disabled) {
  background: var(--bg-hover);
}
.move-dialog-option:disabled {
  cursor: default;
}
.move-dialog-option.new,
.move-dialog-option.new .move-dialog-icon {
  color: var(--brand);
}
.move-dialog-option.off .move-dialog-name {
  color: var(--text-4);
}
.move-dialog-option.off .move-dialog-tile {
  opacity: 0.4;
}
.move-dialog-option.editing {
  cursor: default;
}
.move-dialog-icon {
  display: flex;
  flex: none;
  justify-content: center;
  width: 18px;
  color: var(--text-3);
  font-size: 16px;
}
.move-dialog-icon.folder {
  color: #5856d6;
}
:root[data-theme='dark'] .move-dialog-icon.folder {
  color: #7d7aff;
}
.move-dialog-tile {
  display: flex;
  flex: none;
}
.move-dialog-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.move-dialog-name small {
  display: block;
  font-size: 12px;
  line-height: 16px;
  color: var(--text-4);
}
.move-dialog-option.off .move-dialog-name small {
  color: var(--text-3);
}
.move-dialog-count {
  flex: none;
  font-size: 12.5px;
  color: var(--text-4);
}
.move-dialog-check {
  flex: none;
  color: var(--brand);
  font-size: 14px;
}
.move-dialog-chev {
  flex: none;
  color: var(--text-4);
  font-size: 10px;
}
.move-dialog-pill {
  flex: none;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--bg-sunken);
  color: var(--text-3);
  font-size: 11.5px;
}
.move-dialog-note {
  margin: -6px 0 6px;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--text-3);
}
.move-dialog-error {
  margin: 2px 8px 6px 36px;
  font-size: 12px;
  line-height: 1.45;
  color: var(--error);
}
.move-dialog-foot {
  margin: -6px 0 0;
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--text-3);
}
.move-dialog-progress {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  font-size: 13px;
  color: var(--text-2);
}
.move-confirm-body p {
  margin: 0 0 10px;
}
.move-confirm-body p:last-child {
  margin-bottom: 0;
}

/* ---- Add a runner (Option A) ---- */
.runner-guide {
  position: relative;
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.runner-center {
  width: 100%;
  max-width: 640px;
  padding: 48px 0;
}
.runner-center .page-title {
  margin-bottom: 8px;
}
.runner-sub {
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.6;
  margin: 0 0 20px;
}
.runner-os {
  margin-bottom: 28px;
}

/* command box: monospace on light grey + an explicit Copy button */
.runner-cmd {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 10px 10px 14px;
  background: var(--bg-hover);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.runner-cmd-text {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 13px;
  color: var(--text-1);
}
.runner-cmd-prompt {
  margin-right: 8px;
  color: var(--text-3);
  user-select: none;
}
.runner-copy {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: none;
  height: 30px;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-1);
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 6px;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease;
}
.runner-copy:hover {
  color: var(--brand);
  border-color: var(--brand);
}
.runner-copy.copied {
  color: var(--success-solid);
  border-color: var(--success-solid);
}

/* live status bar: waiting (blue) ↔ connected (green) */
.runner-status {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 20px;
  padding: 16px 18px;
  border-radius: 10px;
}
.runner-status.waiting {
  background: rgba(51, 112, 255, 0.07);
  border: 1px solid rgba(51, 112, 255, 0.18);
}
.runner-status.connected {
  background: rgba(46, 161, 33, 0.09);
  border: 1px solid rgba(46, 161, 33, 0.22);
}
.runner-spinner {
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2.5px solid rgba(51, 112, 255, 0.22);
  border-top-color: var(--brand);
  animation: runner-spin 0.7s linear infinite;
}
@keyframes runner-spin {
  to {
    transform: rotate(360deg);
  }
}
.runner-status-icon {
  display: flex;
  flex: none;
  font-size: 24px;
  color: var(--success-solid);
}
.runner-status-text {
  flex: 1;
  min-width: 0;
}
.runner-status-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
}
.runner-status.connected .runner-status-title {
  color: var(--success-solid);
}
.runner-status-sub {
  margin-top: 2px;
  font-size: 13px;
  color: var(--text-2);
}
.runner-help-link {
  flex: none;
  font-size: 13px;
  color: var(--brand);
  cursor: pointer;
}
.runner-help-link:hover {
  text-decoration: underline;
}
.runner-done-btn {
  flex: none;
  height: 34px;
  padding: 0 18px;
  font-size: 14px;
  font-weight: 500;
  color: var(--invert-text);
  background: var(--invert-surface);
  border: none;
  border-radius: 6px;
  cursor: pointer;
}
.runner-done-btn:hover {
  background: var(--invert-surface-hover);
}
.workspace-composer {
  flex: none;
  border-top: 1px solid var(--border-subtle);
  padding-top: 12px;
  margin-top: 8px;
}
/* Where this task's current run is — the composer's answer to "you are not the run that has
   this task any more", and the transcript card's. One rule set for both, because a reader meeting
   the situation in two places is meeting one situation. Tinted by what is being asked of them:
   nothing (the message landed), wait (it is letting go), or a decision. */
.run-handoff {
  margin-bottom: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-raised);
  font-size: 12.5px;
  line-height: 1.5;
}
.run-handoff-sent {
  border-color: var(--success-border);
  background: var(--success-bg);
}
.run-handoff-held,
.run-handoff-ending {
  border-color: var(--brand-border);
  background: var(--brand-tint);
}
.run-handoff-pin,
.run-handoff-confirm_switch {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.run-handoff-title {
  color: var(--text-1);
  font-weight: 600;
}
.run-handoff-body {
  margin-top: 3px;
  color: var(--text-2);
}
.run-handoff-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 9px;
}
.run-handoff-actions:empty {
  display: none;
}
.run-handoff-open,
.run-handoff-btn,
.run-handoff-stop {
  padding: 3px 11px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-base);
  color: var(--text-1);
  font: inherit;
  line-height: 1.5;
  cursor: pointer;
}
.run-handoff-open {
  border-color: var(--brand);
  background: var(--brand);
  color: #fff;
  font-weight: 600;
  text-decoration: none;
}
.run-handoff-open:hover {
  background: var(--brand-strong);
  color: #fff;
}
/* Solid and red because it ENDS a run that is doing work: destructive, and never the resting
   state of anything — it exists only inside a confirmation the reader opened by picking another
   provider. Its sibling ("Keep it running") is the quiet one on purpose. */
.run-handoff-stop {
  border-color: var(--error-solid);
  background: var(--error-solid);
  color: #fff;
  font-weight: 600;
}
.run-handoff-btn:hover {
  background: var(--bg-hover);
}
/* Inside an auto-retry card the block is the card's last row, not a strip above something. */
.chat-quota .chat-quota-handoff {
  margin: 9px 0 0;
}
/* When a provider pick takes effect. Quiet: it reports, it does not ask. */
.composer-provider-note {
  margin-bottom: 8px;
  padding: 0 2px;
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.45;
}
.composer-project-intent {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  padding: 8px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--brand-tint);
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.45;
}
.composer-project-intent b {
  flex: none;
  color: var(--text-1);
  font-weight: 600;
}
.composer-project-intent-close {
  flex: none;
  margin-left: auto;
  padding: 2px 0 2px 8px;
  border: 0;
  background: transparent;
  color: var(--text-3);
  font: inherit;
  line-height: 1;
  cursor: pointer;
}
.composer-project-intent-close:hover {
  color: var(--text-1);
}
.composer-project-intent-close:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
/* The composer is one card: staged attachments, then the text across the whole width, then a
   row of controls pinned to its foot (`.composer-toolbar`), so the text grows upward and never
   moves the `+` or Send. 24px corners, and 24px is also where everything inside starts: the
   corner's curve meets the straight edge 24px in, and the thumbnails, the text and the `+`'s left
   arm all begin on that line (see `.composer-field` and `.composer-toolbar`). Focus deepens
   the rim instead of turning it blue: the only coloured rim a composer has is shell mode's. */
.composer-box {
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: var(--bg-raised);
  box-shadow:
    0 2px 10px rgba(31, 35, 41, 0.05),
    0 10px 30px rgba(31, 35, 41, 0.04);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.composer-box:focus-within {
  border-color: color-mix(in srgb, var(--text-1) 28%, var(--border));
  box-shadow:
    0 3px 14px rgba(31, 35, 41, 0.08),
    0 12px 34px rgba(31, 35, 41, 0.05);
}
/* `!cmd` shell mode: the whole box reads as a command line, not a message box. Unlike the
   focus rim above this holds whether or not the composer is focused — the mode is a property
   of the draft, so clicking away and back must not make it look like an ordinary message
   again. Listed after :focus-within (equal specificity) so it wins over the focused rim. */
.composer-box-shell,
.composer-box-shell:focus-within {
  border-color: var(--error);
}
/* Drop-to-upload hint: covers the whole session pane while files are dragged over it. Sits
   inset from the pane edges with a translucent scrim so the conversation still shows through. */
.workspace-dropzone {
  position: absolute;
  inset: 12px;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 14px;
  border: 2px dashed var(--brand);
  background: color-mix(in srgb, var(--bg-base) 78%, transparent);
  color: var(--brand);
  font-size: 15px;
  font-weight: 600;
  pointer-events: none;
}
/* Reply-context chip: shown above the box when "Chat about this" hands a question reply
   off to the composer. Brand-tinted to echo the approval card it came from. */
.composer-replyto {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  padding: 6px 10px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--brand-tint);
  font-size: 12.5px;
  color: var(--text-2);
}
.composer-replyto-icon {
  flex: none;
  color: var(--brand);
  font-weight: 600;
}
.composer-replyto-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.composer-replyto-cancel {
  flex: none;
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border: none;
  background: transparent;
  color: var(--text-3);
  cursor: pointer;
  border-radius: 4px;
}
.composer-replyto-cancel:hover {
  color: var(--text-1);
  background: var(--bg-hover);
}
/* The `+` and Send are the toolbar's two ends: 32px circles, placed by the toolbar's side padding
   so the `+`'s left arm starts on the text's line (see `.composer-toolbar`). */
.composer-box .composer-attach-btn.ant-btn,
.composer-box .composer-send.ant-btn {
  flex: none;
  width: 32px;
  min-width: 32px;
  height: 32px;
  border-radius: 50%;
}
.composer-box .composer-attach-btn.ant-btn {
  color: var(--text-1);
  font-size: 16px;
}
/* A Send with nothing to send is a quiet grey disc, not antd's outlined ghost: the circle keeps
   its place and shape, and only the colour says it is waiting for text. */
.composer-box .composer-send.ant-btn:disabled {
  border-color: transparent;
  background: var(--border);
  color: var(--bg-raised);
}
/* The `+` becomes a shell prompt while the draft is a `!cmd` — same 32px slot, so the
   composer doesn't reflow on the mode switch. Clicking it leaves shell mode (see exitShell);
   antd tints a text button's label on hover, so the colour is pinned through :hover too. */
.composer-box .composer-shell-btn.ant-btn,
.composer-box .composer-shell-btn.ant-btn:hover {
  color: var(--error);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-weight: 700;
}
.composer-box .composer-shell-btn.ant-btn:hover {
  background: var(--error-bg);
}
/* ── Composer chips ───────────────────────────────────────────────────────────────────────
   A textarea cannot hold styled elements, so `#`-references and `@`-mentions are drawn by
   ComposerMirror sitting behind a transparent input. The two layers only stay aligned while
   they share every metric that affects where a glyph lands, so the shared declarations live in
   one place and BOTH selectors below claim them. Changing one without the other drifts the
   caret away from the text the user sees — invisibly, because the real text is transparent. */
.composer-field {
  position: relative;
  min-width: 0;
}
.composer-field .composer-mirror,
.composer-field textarea.ant-input {
  font: inherit;
  font-size: 15px;
  line-height: 1.6;
  letter-spacing: normal;
  /* 1px of border + 23 = 24: the text starts where the card's corner stops curving. */
  padding: 12px 23px 2px;
  border: 0;
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: break-word;
  box-sizing: border-box;
}
.composer-mirror {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  color: var(--text-1);
}
/* The input keeps the caret and the selection; the mirror behind it supplies the glyphs. */
.composer-field textarea.ant-input {
  position: relative;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: var(--text-1);
}
/* The glyphs above are transparent so the mirror can draw them — and a placeholder inherits that
   too, with no mirror behind it to draw it instead. Give it back its own colour (antd's placeholder
   grey, which it carries as `color`), or an empty composer is a blank card with no prompt in it. */
.composer-field textarea.ant-input::placeholder {
  -webkit-text-fill-color: currentColor;
}
.composer-field textarea.ant-input::selection {
  background: rgba(22, 119, 255, 0.25);
  -webkit-text-fill-color: var(--text-1);
}
/* antd 6 gives `variant="borderless"` inputs their own brand-coloured `:focus-visible` outline
   (antd 5 set `outline: none` there). Inside the composer that paints a second blue ring around
   the textarea, nested inside the box's own `:focus-within` border — one focus affordance, drawn
   twice. The box border stays; this one goes. */
.composer-field textarea.ant-input:focus-visible {
  outline: none;
}
/* Zero net layout width: the padding shaping the pill is cancelled by an equal negative margin,
   so the background bleeds outward while the glyphs stay exactly where the textarea puts them.
   Any residual width here compounds — every chip pushes the rest of the line further off. */
.composer-chip {
  border-radius: 6px;
  padding: 1px 5px;
  margin: 0 -5px;
  white-space: nowrap;
}
.composer-chip--list,
.composer-chip--task {
  background: color-mix(in srgb, var(--brand) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--brand) 38%, transparent);
  color: var(--brand);
}
.composer-chip--mention {
  background: color-mix(in srgb, var(--text-1) 6%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--text-1) 16%, transparent);
  color: var(--text-2);
}
/* The shell draft is red mono; its metrics differ, so the mirror steps aside entirely rather
   than painting chips at the wrong places. */
.composer-box-shell .composer-mirror {
  display: none;
}
.composer-box-shell .composer-field textarea.ant-input {
  -webkit-text-fill-color: var(--error);
}

/* `resize: none` because the composer has its own top drag handle (native corner grip would
   fight autoSize). Padding is NOT set here: it lives in the shared `.composer-field` block, where
   the mirror behind the textarea takes the same value. */
.composer-box textarea.ant-input {
  resize: none;
}
/* `!cmd` shell mode: the draft runs raw on the runner instead of going to the agent, so the
   composer takes on the same red mono treatment as the queued bubble it becomes (and as the
   CLI's own `!` input) — the mode is visible while typing, not only after sending. Both
   selectors because antd may hand `className` to the textarea itself or to a wrapper; the
   `.composer-box` prefix keeps this above antd's own `.ant-input` colour. */
.composer-box textarea.composer-shell,
.composer-box .composer-shell textarea {
  color: var(--error);
  caret-color: var(--error);
  font-family: var(--font-mono, ui-monospace, monospace);
}
/* Top-edge grip to drag the composer taller/shorter; double-click resets to auto-grow.
   Sits over the box's top border so it reads as an affordance without stealing text room.
   Only rendered once the box has hit its auto-grow cap (see composerCapped), so the pill
   only shows on hover to stay out of the way. */
.composer-resize-handle {
  position: absolute;
  top: -3px;
  left: 12px;
  right: 12px;
  height: 8px;
  cursor: ns-resize;
  z-index: 5;
}
.composer-resize-handle::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 28px;
  height: 3px;
  transform: translate(-50%, -50%);
  border-radius: 2px;
  background: var(--border-strong, var(--border));
  opacity: 0;
  transition: opacity 0.15s ease;
}
.composer-box:hover .composer-resize-handle::before,
.composer-resize-handle:hover::before {
  opacity: 1;
}

/* `/` command & skill autocomplete — floats just above the composer box */
.composer-slash-menu {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(100% + 6px);
  max-height: 260px;
  overflow-y: auto;
  padding: 4px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
  z-index: 20;
}
.composer-slash-item {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 6px;
  cursor: pointer;
}
.composer-slash-item.is-active {
  background: var(--bg-hover);
}
.composer-slash-name {
  flex: none;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
  color: var(--text-1);
}
.composer-slash-type {
  flex: none;
  font-size: 11px;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.composer-slash-desc {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--text-3);
}
/* The card's foot: `+`, workspace (a draft's only), mode — then, right-aligned, the model
   control, the usage gauges and Send. One line, always: on a phone the gauges drop their
   numbers and the model's name gives way before anything else does (see the 600px block).
   The side padding lines the `+` up with the text: its glyph's left arm is 9.57px into the 32px
   button ((32 - 16) / 2 to the icon, then 1.57 of PlusOutlined's own margin), so 1px of border
   + 13.43 + 9.57 = 24, the text's edge. Send mirrors it on the right. */
.composer-toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  padding: 4px 13.43px 7px;
}
/* One quiet text size for the toolbar's words. AntD's borderless Selects otherwise render
   their value at 14px / colorText — a size and a shade heavier than the model's effort and the
   usage percents beside them — so pull the selected value down to match. The disabled
   (non-editable) shade is left to AntD so a read-only control still reads as read-only. */
.composer-toolbar .ant-select-content-has-value,
.composer-toolbar .ant-select-placeholder {
  font-size: 13px;
}
.composer-toolbar .ant-select:not(.ant-select-disabled) .ant-select-content-has-value {
  color: var(--text-2);
}
/* The model control: "Opus 5.5 Max" — the model in the text colour, the effort after it in the
   secondary one, one button. Its menu (`.composer-model-menu`) holds provider, model, effort and
   speed. */
.composer-toolbar .composer-model-pill {
  min-width: 0;
  padding-left: 0;
}
.composer-model-chip {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  padding: 3px 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  font: inherit;
  font-size: 13px;
  line-height: 20px;
  white-space: nowrap;
  cursor: pointer;
}
.composer-model-chip.ant-dropdown-open {
  background: var(--bg-hover);
}
.composer-model-chip:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
.composer-model-chip:disabled {
  cursor: not-allowed;
}
.composer-model-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-1);
  font-weight: 600;
}
.composer-model-effort {
  flex: none;
  color: var(--text-2);
}
.composer-model-chip:disabled .composer-model-name,
.composer-model-chip:disabled .composer-model-effort {
  color: var(--text-3);
}
.composer-model-menu.ant-dropdown-menu {
  min-width: 200px;
}
/* A task run on smart selection's pick (model routing §9): a ✦ and a light blue ground, no wider
   than before — why it is this model opens at the top of the menu. */
.composer-model-chip.is-smart {
  background: var(--brand-tint);
}
.composer-model-chip.is-smart.ant-dropdown-open {
  background: var(--brand-tint-hover);
}
.composer-model-chip.is-smart .composer-model-name {
  color: var(--brand-strong);
}
.composer-model-spark {
  align-self: center;
  color: var(--brand);
  font-size: 12px;
}
.composer-route-note {
  max-width: 320px;
  white-space: normal;
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.6;
}
.composer-route-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-1);
  font-size: 13px;
  font-weight: 650;
}
.composer-route-reason {
  margin-top: 6px;
}
.composer-route-open {
  color: var(--brand-strong);
  font-weight: 600;
}
/* Lightweight, borderless controls (Claude-style): text-only label, with a faint
   rounded background surfacing only on hover. The pill category is named via Tooltip. */
.composer-pill {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding-left: 6px;
  border-radius: 6px;
  transition: background 0.15s;
}
.composer-pill:hover {
  background: var(--bg-hover);
}
/* Pushes the model control, the gauges and Send to the right edge, leaving `+` and Mode on the
   left. */
.composer-pill-spacer {
  flex: 1 1 auto;
}
/* Compact plan-usage indicator at the right end of the pill row. The bar retains
   Orbit's percent-consumed semantics for every provider. */
.composer-usage {
  gap: 6px;
  padding-right: 6px;
  cursor: default;
}
.composer-usage-bar {
  width: 26px;
  height: 4px;
  border-radius: 2px;
  background: var(--border-subtle);
  overflow: hidden;
  flex: none;
}
.composer-usage-fill {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--brand);
}
.composer-usage.full .composer-usage-fill {
  background: var(--warning-solid);
}
.composer-usage-pct {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--text-2);
}
/* Context gauge: a donut (not the plan bar) so the session-local context metric reads as a
   different kind of thing from the account-level plan usage. Brand blue until it fills,
   then ramps amber ≥75% / red ≥90%. */
.context-ring {
  flex: none;
  display: block;
}
.context-ring-track {
  stroke: var(--border-subtle);
}
.context-ring-fill {
  stroke: var(--brand);
  transition: stroke-dashoffset 0.3s ease, stroke 0.2s ease;
}
.context-ring-warn .context-ring-fill {
  stroke: var(--warning-solid);
}
.context-ring-danger .context-ring-fill {
  stroke: var(--error-solid);
}
/* Phone composer: bigger round ends for a thumb, the gauges as shapes only, and one rule for
   what gives way when the toolbar runs out of room. This block must live AFTER the base
   .composer-toolbar rules: media queries add no specificity, so a later same-specificity rule
   would otherwise override these. */
@media (max-width: 600px) {
  /* Bigger round ends for a thumb: 36px circles instead of the pointer's 32. */
  .composer-box .composer-attach-btn.ant-btn,
  .composer-box .composer-send.ant-btn {
    width: 36px;
    min-width: 36px;
    height: 36px;
  }
  /* The bigger circle puts the glyph 2px further into it, so 2px less padding keeps the `+`'s left
     arm on the text's line: 1 + 11.43 + (36 - 16) / 2 + 1.57 = 24. */
  .composer-toolbar {
    gap: 2px;
    padding: 2px 11.43px 5px;
  }
  .composer-toolbar .composer-pill:not(.composer-model-pill) {
    padding-left: 3px;
  }
  /* A phone's toolbar holds the gauges as shapes only: the ring and the bar still say how full
     they are, and the number is one tap away in their popovers (and read out by their labels).
     Desktop has the room and keeps it. */
  .composer-toolbar .composer-usage-pct {
    display: none;
  }
  .composer-toolbar .composer-usage {
    padding-right: 3px;
  }
  /* Everything keeps its natural width but the names: the model's name, a pool's account and a
     draft's workspace give way (with an ellipsis) — the effort, the mode, the gauges and Send
     never do. */
  .composer-toolbar > .composer-pill,
  .composer-toolbar > .composer-usage,
  .composer-toolbar > .ant-btn {
    flex: none;
  }
  .composer-toolbar > .composer-model-pill,
  .composer-toolbar > .composer-account,
  .composer-toolbar > .composer-pill-workspace {
    min-width: 0;
    flex-shrink: 1;
  }
  .composer-pill-workspace .ant-select {
    min-width: 0;
  }
  /* ── The `+` menu ─────────────────────────────────────────────────────────────────────────
     One menu, two clients — and the phone is the one that can be held next to the iOS app, so
     here it takes the native menu's box: 250 wide, 42.4px rows, 17px type, a 26px corner, and a
     rule between the two groups inset 24 from either edge. Every number is measured off the
     phone screenshot in docs/mocks/composer-attach-menu-phone.html, and pinned by
     WorkspaceView.composerMenu.test.tsx so it cannot drift back to antd's defaults.
     Desktop keeps antd's density on purpose: that menu is a pointer menu at the foot of a pane,
     and a 250px card there would be the wrong size for the surface it opens on. */
  .composer-attach-menu.ant-dropdown-menu {
    /* 250 is where it rests, and it is a floor rather than a width because one row's label is
       longer than the others: "Shell (session unavailable)" needs the whole 250 before it fits,
       and a card that wraps THAT into two lines stops looking like the native menu it is
       copying. So the card grows to fit its widest row, up to what the phone can show. */
    min-width: 250px;
    width: max-content;
    max-width: calc(100vw - 44px);
    padding: 10px 0;
    border-radius: 26px;
    box-shadow:
      0 18px 44px rgba(0, 0, 0, 0.17),
      0 2px 8px rgba(0, 0, 0, 0.06);
  }
  .composer-attach-menu .ant-dropdown-menu-item {
    display: flex;
    align-items: center;
    height: 42.4px;
    padding: 0 0 0 31px;
    border-radius: 0;
    font-size: 17px;
    /* antd leaves this to the row it draws; a native menu row is one line, always. */
    white-space: nowrap;
  }
  /* The glyph box and the gap after it: 31 + 19 + 16 lands the word 66 from the card's edge,
     which is where the native menu has it. */
  .composer-attach-menu .ant-dropdown-menu-item .ant-dropdown-menu-item-icon {
    min-width: 19px;
    font-size: 19px;
  }
  /* Glyphs are drawn in the native menu's secondary tone — but only on a row that can be used,
     so an unavailable one keeps antd's dimmed colour instead of reading as enabled. */
  .composer-attach-menu .ant-dropdown-menu-item:not(.ant-dropdown-menu-item-disabled)
    .ant-dropdown-menu-item-icon {
    color: #8a8a8e;
  }
  .composer-attach-menu .ant-dropdown-menu-item .ant-dropdown-menu-item-icon + span {
    margin-inline-start: 16px;
  }
  /* The rule between the two groups: 9.5 + 1 + 9.5 = the 20pt band the native menu leaves, and
     the line itself drawn as the background antd already uses so no border has to be undone. */
  .composer-attach-menu .ant-dropdown-menu-item-divider {
    height: 1px;
    margin: 9.5px 24px;
    background-color: #eaeaea;
  }
}
/* Popover body: one gauge per subscription window (reuses .runner-util for the bar). */
.cu-pop {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 280px;
  max-width: 320px;
}
/* With a reset credit the body changes with every state of it. One width keeps the popover from
   jumping as the status line comes and goes; the cap keeps it on a narrow phone screen. */
.cu-pop.cu-pop-reset {
  width: min(320px, calc(100vw - 48px));
}
/* Focus lands on the popover body when a press opens it; the controls inside carry the rings. */
.cu-pop:focus {
  outline: none;
}
/* In the popover the gauge spans the full card — drop the runner slot-meter's
   200px cap it inherits from .runner-util, and run a touch taller than the
   inline composer bar to suit this expanded view. */
.cu-pop .runner-util {
  max-width: none;
  height: 6px;
}
.cu-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  margin-bottom: 6px;
}
.cu-label {
  font-size: 13px;
  color: var(--text-3);
}
.cu-row > .cu-label {
  margin-bottom: 6px;
  font-weight: 600;
}
.cu-pct {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--text-1);
}
.cu-reset {
  margin-top: 6px;
  font-size: 12px;
  color: var(--text-4);
}
/* Whose quota the windows below are, ruled off from them. Account names are often emails: the name
   gives way with an ellipsis, the label never does. */
.cu-account {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-subtle);
}
.cu-account .cu-head {
  margin-bottom: 0;
}
.cu-account-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-1);
}
/* The pill is a button now — it opens a popover that can hold an action — so it sheds the UA button
   chrome and keeps the look the span had, with a ring for keyboard focus only. */
button.composer-usage {
  padding-block: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  line-height: inherit;
  cursor: pointer;
}
button.composer-usage:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
/* A Codex reset is under way: a small pulse on the pill, so it still says so with the popover closed. */
.composer-usage-resetting {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
  animation: cu-rc-pulse 1.2s ease-in-out infinite;
}
@keyframes cu-rc-pulse {
  50% {
    opacity: 0.35;
  }
}
@media (prefers-reduced-motion: reduce) {
  .composer-usage-resetting {
    animation: none;
  }
}
/* Codex earned reset credit, under the usage windows (docs/codex-rate-limit-reset-contract.md). The
   status line is a live region that stays mounted while empty, so it spaces itself only when it
   has something to say. */
.cu-rc {
  padding-top: 14px;
  border-top: 1px solid var(--border-subtle);
}
.cu-rc > * + * {
  margin-top: 10px;
}
.cu-rc > .cu-rc-live:empty {
  margin-top: 0;
}
.cu-rc-card {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 8px;
  background: var(--brand-tint);
}
.cu-rc-icon {
  flex: none;
  margin-top: 2px;
  font-size: 22px;
  color: var(--brand);
}
.cu-rc-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.cu-rc-title {
  font-size: 13px;
  font-weight: 500;
  color: var(--brand);
}
.cu-rc-count {
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--text-1);
}
.cu-rc-meta {
  font-size: 12px;
  color: var(--text-3);
}
.cu-rc-meta.cu-rc-stale {
  color: var(--warning);
}
.cu-rc-live:focus {
  outline: none;
}
.cu-rc-status {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-2);
}
.cu-rc-status-icon {
  flex: none;
  font-size: 14px;
  line-height: 18px;
}
.cu-rc-status--progress .cu-rc-status-icon {
  color: var(--brand);
}
.cu-rc-status--success .cu-rc-status-icon {
  color: var(--success-solid);
}
.cu-rc-status--info .cu-rc-status-icon {
  color: var(--text-3);
}
.cu-rc-status--warning .cu-rc-status-icon {
  color: var(--warning-solid);
}
.cu-rc-status--error .cu-rc-status-icon {
  color: var(--error-solid);
}
.cu-rc-status-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.cu-rc-reason {
  font-size: 12px;
  color: var(--text-3);
}
.cu-rc-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.cu-rc-confirm-text {
  margin: 0 0 14px;
  color: var(--text-2);
}
.cu-rc-confirm-usage {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 14px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  color: var(--text-2);
}
.cu-rc-confirm-value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--text-1);
}
.cu-rc-confirm-note {
  margin: 12px 0 0;
  font-size: 12px;
  color: var(--text-3);
}

/* Staged attachments — a row of thumbnail chips at the top of the composer card, above the text
   they go out with. Each chip reuses the .composer-pill shape (rounded, bordered) sized to a small
   thumbnail. Inset like the text (`.composer-field`), so the first thumbnail and the text share
   their left edge. */
.composer-attachments {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 23px 0;
}
.composer-attach {
  position: relative;
  padding-left: 0;
  overflow: hidden;
  width: 48px;
  height: 48px;
}
/* Ant Design's Image wraps the <img> in a .ant-image div; make it fill the chip
   so the thumbnail (and its click-to-zoom hover mask) covers the full 48x48. */
.composer-attach .ant-image {
  width: 48px;
  height: 48px;
  display: block;
}
.composer-attach-thumb {
  width: 48px;
  height: 48px;
  object-fit: cover;
  border-radius: inherit;
  display: block;
  cursor: zoom-in;
}
.composer-attach .ant-image-cover {
  border-radius: inherit;
}
.composer-attach-eye {
  font-size: 14px;
}
/* Dim + center a spinner over a thumbnail still uploading. */
.composer-attach-spin {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bg-raised);
  font-size: 16px;
  background: rgba(0, 0, 0, 0.35);
}
.composer-attach-remove {
  position: absolute;
  top: 1px;
  right: 1px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.55);
  color: var(--bg-raised);
  font-size: 9px;
  cursor: pointer;
}
.composer-attach-remove:hover {
  background: rgba(0, 0, 0, 0.8);
}
/* A non-image upload staged in the composer: a horizontal chip (icon + name + size) with a
   remove button, instead of the image thumbnail. */
.composer-file {
  gap: 6px;
  padding: 4px 6px 4px 8px;
  max-width: 220px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-sunken);
  font-size: 12px;
  color: var(--text-1);
}
.composer-file-icon {
  flex: none;
  color: var(--text-3);
  font-size: 13px;
}
.composer-file-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.composer-file-size {
  flex: none;
  color: var(--text-3);
}
.composer-file-remove {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--text-3);
  font-size: 9px;
  cursor: pointer;
}
.composer-file-remove:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}

/* ---- Interactive session chat (Route B) ---- */
.chat-note {
  color: var(--text-3);
  font-size: 13px;
  padding: 10px 4px;
}
/* What is above the loaded window: a page in flight, or the way back to the first message. Sticky
   inside the scroller — it has to stay reachable wherever the reader is, and the top of the content
   is not a place they can stop: arriving there pulls in the next page, which lands anchored and
   leaves them a page below it. Zero-height so it floats over the transcript rather than indenting
   it, and transparent apart from the pill itself. */
.chat-older-top {
  position: sticky;
  top: 10px;
  z-index: 4;
  height: 0;
  text-align: center;
  pointer-events: none;
}
.chat-older-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-raised);
  color: var(--text-2);
  font-size: 13px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  pointer-events: auto;
}
button.chat-jump-start {
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
button.chat-jump-start:hover {
  background: var(--bg-sunken);
  color: var(--text-1);
}
/* Transcript placeholder while an unvisited session's tail page is in flight. Geometry tracks
   .chat-user / .chat-assistant so the skeleton occupies the same columns the real messages will,
   and the whole block pulses as one — per-line staggering reads as content arriving, which is
   exactly the wrong promise while a single request is outstanding. */
.chat-skeleton {
  padding: 4px 0;
  animation: chat-skeleton-pulse 1.6s ease-in-out infinite;
}
.chat-skeleton-user {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
  padding: 8px 12px;
}
.chat-skeleton-assistant {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 8px 0 20px;
  padding: 0 12px;
}
.chat-skeleton-line {
  display: block;
  height: 12px;
  border-radius: 6px;
  background: var(--fill-muted);
}
@keyframes chat-skeleton-pulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .chat-skeleton {
    animation: none;
  }
}
.chat-msg {
  max-width: 80%;
  padding: 8px 12px;
  border-radius: 10px;
  margin: 8px 0;
  font-size: 14px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}
.chat-user {
  background: var(--brand-tint);
  margin-left: auto;
  /* Hug the text — .chat-msg's max-width:80% is a wrap cap, not a fixed width, so a
     plain block would stretch the bubble background across 80% and trail blank space
     after a short message. fit-content shrinks to the text; margin-left:auto right-aligns. */
  width: fit-content;
}
/* Wraps the user bubble + a meta row (copy · relative time) beneath it as one right-aligned
   column. The meta row sits IN FLOW (not absolute) so it reserves its own height — an earlier
   absolute version overlapped whatever message followed. The time is always shown; the copy
   button only fades in on hover (its slot is reserved, so revealing it shifts nothing). */
.chat-user-wrap {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  width: fit-content;
  max-width: 80%;
  margin: 8px 0 8px auto;
}
.chat-user-wrap > .chat-user {
  margin: 0;
  max-width: 100%;
}
/* Links in a user message (Markdown links, plus bare URLs remark-gfm autolinks); underline + brand
   colour so they read as clickable against the tinted bubble. break-word already lets a long link
   wrap. Wins over `.md a` for the underline — that rule only sets a colour. */
.chat-user a {
  color: var(--brand);
  text-decoration: underline;
}
/* The whole meta row (copy + time) is hidden until hover — the time is not shown at rest,
   per request. It still reserves height (occupies flow), so revealing it never overlaps the
   next message and never shifts layout. */
.chat-user-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 3px;
  height: 18px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.12s ease;
}
.chat-user-wrap:hover .chat-user-meta,
.chat-user-meta:focus-within {
  opacity: 1;
  pointer-events: auto;
}
.chat-time {
  font-size: 12px;
  line-height: 1;
  color: var(--text-3);
}
/* A message the engine never received. Always visible (unlike the hover-only meta row):
   the whole point is that nobody has to hover to find out their message did not land. */
.chat-undelivered {
  margin-top: 3px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--error-solid);
}
/* Send it again without retyping it. A link, not a button: the message is already gone, and
   the weight of a real button next to a failure reads as the fix rather than as an offer. */
.chat-undelivered-retry {
  margin-left: 8px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: var(--brand);
  cursor: pointer;
}
.chat-undelivered-retry:hover {
  text-decoration: underline;
}
/* How far a mid-turn message (a steer) got into the turn it joined. Muted and in the bubble's
   own column: it is the only report that message gets — the running turn's reply answers
   something else — but it is a progress note, not a problem, so it never competes with the
   failure mark above, which owns the error colour. */
.chat-steer-state {
  margin-top: 3px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--text-3);
}
.chat-copy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--text-3);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  transition: color 0.12s ease, background 0.12s ease;
}
.chat-copy:hover {
  color: var(--text-1);
  background: var(--bg-hover);
}
.chat-status-card {
  width: min(560px, 100%);
  margin: 10px 0;
  border: 1px solid var(--border);
  border-left: 3px solid var(--brand);
  border-radius: 8px;
  background: var(--bg-raised);
  overflow: hidden;
}
.chat-status-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-1);
  font-size: 13.5px;
  font-weight: 650;
}
.chat-status-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: var(--brand);
  color: #fff;
  font-size: 12px;
}
.chat-status-grid {
  display: grid;
  gap: 0;
  padding: 6px 12px 10px;
}
.chat-status-row {
  display: grid;
  grid-template-columns: minmax(92px, max-content) minmax(0, 1fr);
  gap: 14px;
  padding: 4px 0;
  font-size: 13.5px;
  line-height: 1.45;
}
.chat-status-label {
  color: var(--text-2);
}
.chat-status-value {
  min-width: 0;
  color: var(--text-1);
  overflow-wrap: anywhere;
}
/* Fenced code block in assistant markdown — a hover copy button in the top-right corner so a
   whole generated file (e.g. an HTML report) can be lifted out without the surrounding prose.
   The block is the hover area and the button sits inside it, so the pointer never leaves it. */
.md-codeblock {
  position: relative;
}
.md-copy {
  position: absolute;
  top: 6px;
  right: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: var(--bg-raised);
  box-shadow: 0 0 0 1px var(--border-subtle);
  color: var(--text-2);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.12s ease, color 0.12s ease, background 0.12s ease;
}
.md-codeblock:hover .md-copy,
.md-copy:focus-visible {
  opacity: 1;
  pointer-events: auto;
}
.md-copy:hover {
  color: var(--text-1);
  background: var(--bg-hover);
}
/* Images sent with a user turn — a wrapping row of thumbnails above the bubble's text
   (shared by the live user bubble and the queued bubble). */
.chat-images {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chat-images:not(:last-child) {
  margin-bottom: 6px;
}
.chat-image {
  max-width: 220px;
  max-height: 220px;
  border-radius: 8px;
  object-fit: contain;
  display: block;
}
/* A picture a tool returned is meant to be READ, not merely noticed: at the thumbnail size above,
   the 1180×768 screenshots this session takes render 220×143 — small enough that the only way to
   see one is to click it. Give a result's own images a readable width instead, and cap the height
   so a tall capture (a full page, a phone screenshot) can't own the viewport; the click-to-zoom
   pager is still there for detail. Images the *user* sent keep the 220px chip size: those hang off
   a bubble as attachments, and are not what the turn is about. */
.chat-result .chat-image {
  max-width: min(100%, 760px);
  max-height: 520px;
}
/* …and let the card end where the picture does. A tool card is full-width, so a 760px image inside
   one trails half a row of blank card on a wide window — the picture reads as a stamp in a corner
   rather than as the content. Matched through `>` so only the card's OWN result counts: unscoped,
   `:has` would also match a sub-workspace card any of whose nested calls returned an image, and
   shrink that whole transcript to fit it. max-width keeps the usual full-width behaviour as the
   ceiling, so a result that also carries wide text is no narrower than it is today. */
.chat-tool-card:has(> .chat-tool-detail > .chat-result > .chat-images) {
  width: fit-content;
  max-width: 100%;
}
/* AntD wraps each <Image> in a .ant-image; round it so the hover mask is clipped to the
   image's corners, and hint clickability with a zoom cursor. */
.chat-images .ant-image {
  border-radius: 8px;
  overflow: hidden;
  cursor: zoom-in;
}
/* The custom preview mask (eye icon + "预览") shown on hover. */
.chat-image-mask {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
}
/* A transcript thumbnail that opens the session-wide left/right preview pager. Mirrors the
   AntD .ant-image thumbnail (rounded, zoom cursor) and paints the mask as a hover overlay. */
.chat-image-btn {
  position: relative;
  display: inline-flex;
  padding: 0;
  border: 0;
  background: none;
  border-radius: 8px;
  overflow: hidden;
  cursor: zoom-in;
  line-height: 0;
}
.chat-image-btn .chat-image-mask {
  position: absolute;
  inset: 0;
  justify-content: center;
  color: #fff;
  background: rgba(0, 0, 0, 0.35);
  opacity: 0;
  transition: opacity 0.15s ease;
}
.chat-image-btn:hover .chat-image-mask,
.chat-image-btn:focus-visible .chat-image-mask {
  opacity: 1;
}
/* Placeholder box while a durable attachment blob is being fetched (post-reload). */
.chat-image-loading {
  width: 120px;
  height: 90px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.06);
}
/* A result image whose bytes the server dropped from the preview (see MAX_IMAGE_PAYLOAD): the card
   opens on the image block, so until the untrimmed payload lands there is a picture-shaped hole
   where the picture is going. Reserve that slot — the cap .chat-result .chat-image itself lands
   in, so the swap barely moves the transcript — and spin, so an open card never reads as a broken
   one. The spinner is the only content: this box is a shape, not a chip. */
.chat-result-image-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  width: min(100%, 760px);
  height: 520px;
  border-radius: 8px;
  background: var(--fill-inset);
  color: var(--text-3);
}
.md .ant-image {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 10px 0;
  border-radius: 8px;
  overflow: hidden;
  cursor: zoom-in;
}
.md-image {
  display: block;
  max-width: min(100%, 760px);
  max-height: 70vh;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-raised);
  object-fit: contain;
}
.md-image-loading {
  width: min(100%, 520px);
  height: 260px;
  background: rgba(0, 0, 0, 0.06);
}
.md-image-unavailable {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 5px 9px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-raised);
  color: var(--text-2);
  font-size: 12px;
}
.md-image-unavailable code {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* What delivery appended to a person's message, named on one line under their words instead of
   dumped into them (ControlPlaneNote). Muted and small: it is provenance, not content — the eye
   should skip it unless the reply mentions something the message did not, and then it opens to
   exactly what the model read. */
.chat-injected {
  margin-top: 6px;
  padding-top: 5px;
  border-top: 1px dashed var(--border-subtle);
  color: var(--text-3);
  font-size: 11.5px;
}
.chat-injected-head {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
/* Drop the focus ring on mouse click; keep it for keyboard navigation. */
.chat-injected-head:focus {
  outline: none;
}
.chat-injected-head:focus-visible {
  border-radius: 4px;
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
.chat-injected-body {
  margin: 4px 0 0;
  color: var(--text-2);
  white-space: pre-wrap;
  word-break: break-word;
}
/* The background-jobs block opened as rows (BackgroundJobsNote): the wake card's own row language
   (.bgwake-job*), one step quieter, because this sits inside someone's bubble rather than standing
   as a card of its own. */
.bgjobs {
  margin-top: 6px;
}
.bgjobs-group {
  margin-bottom: 4px;
  color: var(--text-2);
  font-weight: 600;
}
.bgjobs-list {
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
}
.bgjobs-job {
  padding: 6px 8px;
  border-radius: 8px;
  /* Translucent: the bubble this sits in is already tinted, and an opaque panel lands as a hole. */
  background: var(--fill-inset);
}
.bgjobs-job + .bgjobs-job {
  margin-top: 4px;
}
.bgjobs-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.bgjobs-mark {
  flex: none;
}
.bgjobs-mark.is-ok {
  color: var(--success-solid);
}
.bgjobs-mark.is-failed {
  color: var(--error-solid);
}
.bgjobs-mark.is-running {
  color: var(--text-3);
}
/* The command is the row. Two lines of it, because a job's command can be a whole heredoc and the
   fold below holds the rest. */
.bgjobs-name {
  display: -webkit-box;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: var(--text-1);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  overflow-wrap: anywhere;
}
.bgjobs-outcome {
  flex: none;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
}
/* The ids line up under the command, not under its icon. */
.bgjobs-meta {
  margin-top: 2px;
  padding-left: 20px;
  color: var(--text-3);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  overflow-wrap: anywhere;
}
.bgjobs-raw summary {
  color: var(--text-3);
  cursor: pointer;
}
.bgjobs-raw pre {
  max-height: 320px;
  margin: 4px 0 0;
  padding: 8px;
  overflow: auto;
  border-radius: 6px;
  background: var(--fill-inset);
  color: var(--text-2);
  white-space: pre-wrap;
  word-break: break-word;
}

/* The `#`-referenced tasks opened as cards (ReferencedTaskNote): the background-jobs row language
   (.bgjobs-*), since the two sit one above the other in the same fold whenever a note carries both.
   The title is the link, so the task is one click from the message that referenced it. */
.reftask {
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
}
.reftask-task {
  padding: 6px 8px;
  border-radius: 8px;
  /* Translucent: the bubble this sits in is already tinted, and an opaque panel lands as a hole. */
  background: var(--fill-inset);
}
.reftask-task + .reftask-task {
  margin-top: 4px;
}
.reftask-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.reftask-head .status-pill {
  flex: none;
}
/* What the status line said after the status: the kind of task it is, not its lifecycle. */
.reftask-suffix {
  flex: none;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-inset);
  color: var(--text-2);
}
/* The title is the row, and the row is the link. Two lines of it — a task title runs long and the
   id is under it. Named twice so it wins over `.chat-user a`, which underlines links in a person's
   own message: this one is a whole row rather than a link mid-sentence, and the `#`-pill in the
   same bubble (.md-reference) drops the underline for the same reason. */
.reftask .reftask-title {
  display: -webkit-box;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: var(--brand);
  text-decoration: none;
  overflow-wrap: anywhere;
}
.reftask .reftask-title:hover {
  text-decoration: underline;
}
.reftask-outcome {
  flex: none;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
}
.reftask-meta {
  margin-top: 2px;
  color: var(--text-3);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  overflow-wrap: anywhere;
}

/* A `#`-reference in a message, styled to read as the same object the composer chipped — the
   user typed a pill and should recognise it in their own bubble. Inline, not a block chip: it
   sits mid-sentence and must not disturb the line box. */
.md-reference {
  padding: 1px 5px;
  margin: 0 -1px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--brand) 10%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--brand) 30%, transparent);
  color: var(--brand);
  text-decoration: none;
}
.md-reference:hover {
  background: color-mix(in srgb, var(--brand) 18%, transparent);
}

/* ── An Orbit link in a message, drawn as a card ──────────────────────────────────────────────
   A link that names an object of this deployment (a pasted page URL, or an agent's own
   `[名字](orbit-task:…)` on a line of its own) is drawn as the object rather than the address: the
   type's tile and name, the title as the link, then one or two lines of live status. One skeleton,
   four contents — components/OrbitLinkCard.tsx is what fills it in. */
.orbit-link-card {
  margin: 6px 0;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-raised);
  color: var(--text-1);
}
/* Embedded in a user bubble rather than raised on top of it: tighter corners, and the bubble's own
   tint as the border, so the card reads as part of the message it was written in. */
.chat-user .orbit-link-card {
  border-radius: 8px;
  border-color: color-mix(in srgb, var(--brand) 20%, transparent);
}
.olc-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.olc-head > :not(.olc-kind) {
  margin-left: auto;
}
/* The type's name keeps its width and the state beside it gives way: a failed session's state is its
   error, which can run to a sentence, and a pill held at its full length pushed the card out of its
   bubble. */
.olc-kind {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-2);
}
.olc-tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--brand) 12%, transparent);
  color: var(--brand);
  font-size: 12px;
}
.olc-state {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  padding: 1px 7px;
  border: 1px solid;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
.olc-state.is-live {
  border-color: var(--brand-border);
  background: var(--brand-tint);
  color: var(--brand);
}
.olc-state.is-attention {
  border-color: var(--warning-border);
  background: var(--warning-bg);
  color: var(--warning);
}
.olc-state.is-done {
  border-color: var(--success-border);
  background: var(--success-bg);
  color: var(--success);
}
.olc-state.is-failed {
  border-color: var(--error-border);
  background: var(--error-bg);
  color: var(--error);
}
.olc-state.is-idle {
  border-color: var(--border);
  background: var(--bg-subtle);
  color: var(--text-2);
}
.olc-title {
  margin-top: 4px;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
}
/* Named through the card so it wins over `.chat-user a`, which underlines every link in a bubble:
   the title is the row's link, not a word in a sentence. */
.orbit-link-card .olc-title a {
  color: var(--brand);
  text-decoration: none;
}
.orbit-link-card .olc-title a:hover {
  text-decoration: underline;
}
.olc-line {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 3px;
  font-size: 13px;
  color: var(--text-2);
}
.olc-line-text {
  overflow-wrap: anywhere;
}
.olc-line-glyph {
  flex: none;
  color: var(--text-3);
}
.olc-line.is-warning,
.olc-line.is-warning .olc-line-glyph {
  color: var(--warning);
}
.olc-badge {
  flex: none;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-size: 11px;
}
.olc-meter {
  display: flex;
  gap: 2px;
  height: 6px;
  margin-top: 6px;
  border-radius: 4px;
  background: var(--fill-muted);
  overflow: hidden;
}
.olc-meter-seg {
  height: 6px;
}
.olc-meter-seg.is-done {
  background: var(--success);
}
.olc-meter-seg.is-ready {
  background: var(--warning-solid);
}
.olc-meter-seg.is-failed {
  background: var(--error);
}
.olc-foot {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--border-subtle);
  font-size: 12.5px;
  color: var(--text-2);
}
/* One line, like the native card's: a failed coordinator's word is its error. */
.olc-foot-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.olc-foot-time {
  flex: none;
}
.olc-foot-arrow {
  margin-left: auto;
  color: var(--text-3);
}
/* The address the card replaced, under the two states that have nothing else to show. */
.olc-path {
  margin-top: 6px;
  color: var(--text-3);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11.5px;
  overflow-wrap: anywhere;
}
/* Still reading: two bars where the title and the status line will be. */
.olc-skeleton {
  display: grid;
  gap: 5px;
  margin-top: 6px;
}
.olc-skeleton span {
  display: block;
  height: 8px;
  border-radius: 4px;
  background: var(--fill-inset);
}
.olc-skeleton span:last-child {
  width: 55%;
}
/* Nothing to show: a grey tile and a title that says so rather than a card that looks half-drawn. */
.orbit-link-card.is-unavailable .olc-tile {
  background: var(--fill-inset);
  color: var(--text-3);
}
.orbit-link-card.is-unavailable .olc-title {
  color: var(--text-2);
}
/* A non-image attachment the user sent: a downloadable chip (paperclip + filename) that
   fetches the blob on click. */
.chat-files {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chat-files:not(:last-child) {
  margin-bottom: 6px;
}
.chat-file {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 240px;
  padding: 5px 10px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-raised);
  color: var(--text-1);
  font-size: 12px;
  cursor: pointer;
}
.chat-file:hover {
  background: var(--bg-hover);
}
.chat-file.is-error {
  border-color: var(--error-border);
  color: var(--error);
}
.chat-file.is-error:hover {
  background: var(--error-bg);
}
.chat-file-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Sticky "your prompt" bar: sits flush under the header (outside the scroll area, so no
   jitter) and surfaces the in-view turn's question once a long answer pushes it off the
   top. Click to jump back to the original bubble. */
.chat-sticky-question {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 12px;
  border: none;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--bg-sunken);
  text-align: left;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-1);
}
.chat-sticky-question:hover {
  background: var(--bg-hover);
}
/* Tail-first: the question for the content in view is still loading from an older page —
   show the bar muted and non-interactive until it resolves. */
.chat-sticky-loading {
  cursor: default;
  color: var(--text-3);
}
.chat-sticky-loading:hover {
  background: var(--bg-sunken);
}
.chat-sticky-label {
  flex: none;
  font-size: 12px;
  color: var(--text-3);
}
.chat-sticky-text {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The pending-decision strip. Flush under the header and OUTSIDE the transcript scroller, because
   it says what is true now rather than what happened: the transcript's vertical flow is for
   events, and a thing recomputed every turn sitting in it read as a message nobody sent. Collapsed
   it is one line of counts — it blocks no turn, so it must not look like the approval card, which
   does. */
.decision-strip {
  flex: none;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--bg-sunken);
}
.decision-strip-line {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 12px;
  border: none;
  background: none;
  text-align: left;
  cursor: pointer;
  font-size: 13px;
  /* Set, so the strip keeps its height whichever script the question it names is written in. */
  line-height: 20px;
  color: var(--text-1);
}
.decision-strip-line:hover {
  background: var(--bg-hover);
}
/* The one mark of attention the collapsed line carries, and only when something is being asked of
   the reader. */
.decision-strip-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent, #3b82f6);
}
.decision-strip-count {
  font-variant-numeric: tabular-nums;
}
.decision-strip-quiet,
.decision-strip-sep {
  flex: none;
  white-space: nowrap;
  color: var(--text-3);
}
/* The question the line goes to, in its own words: cut short rather than wrapped, because the strip
   is one line and the age and position after it must stay readable. */
.decision-strip-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.decision-strip-caret {
  flex: none;
  margin-left: auto;
  color: var(--text-3);
}
.decision-strip-unread {
  padding: 7px 12px;
  font-size: 12px;
  color: var(--text-2);
}
/* Unfolded, the WAITING ON YOU rows scroll inside the strip rather than pushing the conversation
   down the screen: the pinned area has a ceiling and the transcript keeps its own space. */
.decision-strip-body {
  max-height: 46vh;
  overflow-y: auto;
  border-top: 1px solid var(--border-subtle);
}
.decision-rail-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 7px 12px;
  font-size: 12px;
}
.decision-rail-label {
  font-weight: 600;
  color: var(--text-1);
}
.decision-rail-count {
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}
/* Not greyed: every row that reaches this group is an instruction the reader can act on. */
.decision-rail-mine .decision-rail-label {
  color: var(--text-1);
}
.decision-rail-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.decision-rail-row {
  border-top: 1px solid var(--border-subtle);
}
/* Layout only. Nothing here says "pressable": a row is only text, so it does not advertise a press
   that would do nothing. */
.decision-rail-summary {
  display: flex;
  align-items: baseline;
  gap: 10px;
  width: 100%;
  padding: 6px 12px;
  border: none;
  background: none;
  text-align: left;
  font-size: 13px;
  color: var(--text-1);
}
.decision-rail-task {
  min-width: 0;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.decision-rail-criterion,
.decision-rail-rev,
.decision-rail-age {
  flex: none;
  font-size: 12px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}
.decision-rail-inert {
  cursor: default;
}
/* Why there is nothing to press. Set as text, indented under the row it is about. */
.decision-rail-why {
  padding: 0 12px 8px;
  font-size: 12px;
  line-height: 1.5;
}
/* A PENDING session before its first event: instead of a lonely top-left note in a
   blank pane, fill the transcript area with a calm, centered "waiting to run" state. */
.chat-queued-state {
  min-height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 24px;
  text-align: center;
}
.chat-queued-dots {
  display: flex;
  gap: 6px;
}
.chat-queued-dots span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--brand);
  animation: chat-queued-bounce 1.4s ease-in-out infinite;
}
.chat-queued-dots span:nth-child(2) {
  animation-delay: 0.16s;
}
.chat-queued-dots span:nth-child(3) {
  animation-delay: 0.32s;
}
@keyframes chat-queued-bounce {
  0%,
  80%,
  100% {
    opacity: 0.25;
    transform: translateY(0);
  }
  40% {
    opacity: 1;
    transform: translateY(-3px);
  }
}
.chat-queued-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-1);
}
.chat-queued-desc {
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-3);
  max-width: 320px;
}

/* An existing conversation can return to PENDING while it waits to reacquire a turn
   slot. Keep its transcript visible and append this compact status instead of replacing
   the history with the full-height first-run state above. */
.chat-slot-wait {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  margin: 10px 4px 2px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-sunken);
  text-align: center;
}
.chat-slot-wait span:first-child {
  color: var(--text-1);
  font-weight: 600;
}

/* How long the wait above has been going. Rides inside the title so it shares that line, at
   normal weight because .chat-slot-wait bolds its first child. Tabular figures so the ticking
   second does not shift the title beside it once a second. */
.chat-wait-elapsed {
  margin-left: 8px;
  padding: 1px 6px;
  border-radius: 5px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

/* A message queued behind the running turn: a dimmed user bubble with a withdraw
   action, shown until the runner picks it up (then it renders as a normal user turn). */
.chat-queued {
  background: var(--brand-tint);
  border: 1px dashed var(--brand-border);
  opacity: 0.9;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.chat-queued-meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  font-size: 12px;
}
.chat-queued-tag {
  color: var(--text-3);
}

.chat-queued-tag-failed {
  color: var(--danger, #c53b3b);
  border-color: color-mix(in srgb, var(--danger, #c53b3b) 35%, transparent);
  background: color-mix(in srgb, var(--danger, #c53b3b) 8%, transparent);
}
/* Why it did not land — said in place, between the state and the way out of it, rather than
   left in a tooltip nobody hovers. Ellipsised on a narrow pane; the row's title still carries
   the server's full wording. */
.chat-queued-why {
  color: var(--text-3);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A queued `!cmd`: shown verbatim as the shell command it will run, so it reads like
   the Bash card its output eventually lands in rather than a chat message. Red picks up
   the CLI's own `!`-input colouring, and reads as "this bypasses the agent" — it's the
   theme's error token only because that's where the palette keeps its red; both the light
   and dark values are already contrast-checked. */
.chat-queued-cmd {
  color: var(--error);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 13px;
  white-space: pre-wrap;
  word-break: break-word;
}
/* Assistant turns are long-form Markdown — render them as a document (no bubble,
   spanning the full session width) rather than a chat pill; only short
   user/streaming-raw turns keep a bubble. max-width:none overrides .chat-msg's
   80% cap (equal specificity, but later, so this wins). */
.chat-assistant {
  background: transparent;
  max-width: none;
  padding: 0 12px;
  border-radius: 0;
}
.chat-streaming::after {
  content: '▋';
  margin-left: 1px;
  color: var(--text-3);
  animation: chat-caret-blink 1s steps(1) infinite;
}
/* Streaming assistant bubble renders markdown, so attach the caret inline after the
   last rendered block instead of after the bubble (which would drop it to a new line). */
.chat-streaming-md .md > :last-child::after {
  content: '▋';
  margin-left: 1px;
  color: var(--text-3);
  animation: chat-caret-blink 1s steps(1) infinite;
}
@keyframes chat-caret-blink {
  50% {
    opacity: 0;
  }
}
.chat-tool {
  font-size: 12.5px;
  color: var(--text-2);
  margin: 4px 0;
}
.chat-tool code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--text-3);
}
.chat-tool-result {
  font-size: 12.5px;
  color: var(--text-3);
  margin: 2px 0 6px;
  white-space: pre-wrap;
  word-break: break-word;
}
.chat-turn-divider {
  margin: 12px 0;
}
.chat-error {
  color: var(--error);
  font-size: 13px;
  line-height: 1.5;
  margin: 6px 0;
  /* Mark in its own column so a wrapped sentence lines up under itself rather than under the
     glyph, and so a logged URL breaks instead of stretching the row. */
  display: flex;
  gap: 6px;
  align-items: baseline;
  overflow-wrap: anywhere;
}
.chat-error-card {
  margin: 6px 0;
  border: 0;
  border-left: 3px solid var(--error);
  background: transparent;
}
.chat-error-card-head {
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  overflow-wrap: anywhere;
}
.chat-error-card .chat-error-card-icon {
  color: var(--error);
  flex: none;
  background: var(--error-bg);
}
.chat-error-card .chat-error-card-status {
  color: var(--error);
  font-size: 12px;
}
.chat-error-card-detail {
  margin: 0 10px 0 58px;
  padding: 0 0 2px;
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.chat-error-card-path {
  margin: 0 0 2px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--text-3);
}
.chat-error-card-reason {
  color: var(--text-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.chat-error-card-disclosure {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin: 3px 0 0 -2px;
  padding: 0;
  border: 0;
  color: var(--text-2);
  background: transparent;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.chat-error-card-disclosure:hover {
  color: var(--text-1);
}
.chat-error-card-log {
  max-height: 280px;
  margin: 4px 10px 7px 58px;
  padding: 7px 8px;
  border-radius: 6px;
  background: var(--bg-sunken);
  color: var(--text-2);
  font: 12px/1.45 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  white-space: pre-wrap;
  overflow: auto;
}
.chat-error-mark {
  flex: none;
}
/* A parsed engine log line (data-level set) is the engine talking to its own log, not the turn
   failing: the level keeps its colour on the mark, while the sentence — often a paragraph of
   advice with a link — reads as secondary text instead of a wall of red. */
.chat-error[data-level] .chat-error-text {
  color: var(--text-2);
}
.chat-error[data-level='WARN'] .chat-error-mark {
  color: var(--warning);
}
.chat-error[data-level='INFO'] .chat-error-mark,
.chat-error[data-level='DEBUG'] .chat-error-mark,
.chat-error[data-level='TRACE'] .chat-error-mark {
  color: var(--text-2);
}
.chat-error-text a {
  color: inherit;
  text-decoration: underline;
}
/* How many identical repeats of this line folded into it. Rides at the end of the line, dimmer
   than the message: it is a fact about the log, not part of what the engine said. */
.chat-error-repeat,
.chat-diagnostic-repeat {
  margin-left: 6px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  opacity: 0.7;
}

/* A heads-up from the runner about a turn that otherwise succeeded (e.g. edits left in the
   machine's shared checkout). Amber and quiet — read it, don't panic. */
.chat-notice {
  color: var(--warning);
  font-size: 13px;
  line-height: 1.5;
  margin: 6px 0;
}
.chat-diagnostic {
  display: flex;
  gap: 6px;
  align-items: baseline;
  overflow-wrap: anywhere;
}
.chat-diagnostic-mark {
  flex: none;
}
.chat-diagnostic-label {
  flex: none;
  color: var(--text-3);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.chat-diagnostic-text {
  min-width: 0;
}
.chat-notice.chat-diagnostic .chat-diagnostic-text {
  color: var(--text-2);
}
.chat-error.chat-diagnostic .chat-diagnostic-text a,
.chat-notice.chat-diagnostic .chat-diagnostic-text a {
  color: inherit;
  text-decoration: underline;
}

/* Sign-in failure: a remedy card, not an error line. Sits at message width so it reads as
   part of the conversation rather than as chrome. */
.chat-authfix {
  margin: 8px 0;
  padding: 12px 14px;
  border: 1px solid var(--warning-border);
  border-radius: 10px;
  background: var(--warning-bg);
  font-size: 13px;
}
.chat-authfix-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.chat-authfix-icon {
  color: var(--warning);
}
.chat-authfix-title {
  font-weight: 600;
  color: var(--text-1);
}
.chat-authfix-msg {
  margin: 6px 0 0;
  color: var(--text-3);
  font-size: 12px;
  word-break: break-word;
}
.chat-authfix-desc {
  margin: 8px 0 0;
  color: var(--text-2);
}
.chat-authfix-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
/* Browser-driven runner sign-in, inside the sign-in card. */
/* No panel of its own: the card is already the container, and buttons are self-delimiting —
   boxing them only drew a second frame inside the first. Quoted content still gets one
   (.chat-authfix-last, .rsi-usercode): that is material to read, not an action to take. */
.rsi {
  margin-top: 10px;
}
.rsi-row {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-1);
  font-size: 13px;
}
.rsi-hint {
  margin-top: 6px;
  color: var(--text-3);
  font-size: 12px;
}
.rsi-warn {
  margin-bottom: 8px;
  color: var(--warning);
  font-size: 12px;
}
.rsi-open {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 12px;
  border-radius: 7px;
  background: var(--brand);
  color: #fff;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
}
.rsi-open:hover {
  background: var(--brand-strong);
  color: #fff;
}
/* The device flow's one-time code: the user retypes it into another window, so it is set big,
   monospaced and selectable rather than styled as body text. */
.rsi-usercode {
  margin: 6px 0 10px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg-subtle);
  color: var(--text-1);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 2px;
  text-align: center;
  user-select: all;
}
.rsi-form {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
.rsi-input {
  flex: 1;
  min-width: 0;
  padding: 5px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-base);
  color: var(--text-1);
  font-size: 13px;
  font-family: inherit;
}
.rsi-input:focus {
  outline: none;
  border-color: var(--brand-border);
}
.rsi-btn {
  flex: none;
  padding: 5px 14px;
  border: 1px solid var(--brand-border);
  border-radius: 6px;
  background: var(--brand);
  color: #fff;
  font-size: 13px;
  cursor: pointer;
}
.rsi-btn:disabled {
  opacity: 0.5;
  cursor: default;
}
/* The two ways back in, side by side. They wrap rather than shrink: both labels name what they
   do, and a card in a narrow column shouldn't turn either into an ellipsis. */
.rsi-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
/* The alternative route: same weight of decision, less weight of ink — it costs the user a key
   they may not have yet, so it doesn't compete with the sign-in for the first click. Raised, not
   transparent: once the surrounding panel went away it sat straight on the card's warm tint,
   which read as a disabled control rather than the sibling of the retry button below it. */
.rsi-btn-alt {
  flex: none;
  padding: 5px 14px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
  color: var(--text-1);
  font-size: 13px;
  cursor: pointer;
}
.rsi-btn-alt:hover {
  border-color: var(--brand-border);
  color: var(--brand);
}
.rsi-link {
  margin-top: 8px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-3);
  font-size: 12px;
  text-decoration: underline;
  cursor: pointer;
}
.rsi-link:hover {
  color: var(--text-1);
}
/* Beside the button rather than under it, where the row already spaces it. */
.rsi-actions .rsi-link {
  margin-top: 0;
}
.rsi-done {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--success);
  font-size: 13px;
}

/* Takes a rejected configured key to the page that holds it. The runner-login shape has its own
   pair of buttons (.rsi-actions); this shape has only the one route. */
.chat-authfix-go {
  margin-top: 10px;
  padding: 5px 14px;
  border: 1px solid var(--brand-border);
  border-radius: 6px;
  background: var(--brand);
  color: #fff;
  font-size: 13px;
  cursor: pointer;
}
.chat-authfix-go:hover {
  background: var(--brand-strong);
}
/* The message the retry would re-send, quoted. Clamped: it can be a whole pasted prompt, and
   this is a label for the button under it, not a second copy of the conversation. Panelled like
   the sign-in box above it — on the card's warm background a quote rule alone left it reading as
   more of the card's own prose, when it is the one thing here the user didn't write just now.
   Sunk into that warm background rather than filled over it: this card is always warning-tinted,
   and an opaque fill on a tint is a bright hole that outranks the button it introduces. */
.chat-authfix-last {
  /* Shown whole: three clamped lines cut the message off mid-sentence, and a quote you can't
     read to the end doesn't answer the question it is here for — "is this what gets re-sent?".
     A tall ceiling with its own scroll keeps a pasted essay from swallowing the card, without
     hiding the end of anything of ordinary length. */
  max-height: 13em;
  overflow-y: auto;
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}
.chat-authfix-retry {
  margin-top: 10px;
  padding: 5px 12px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
  color: var(--text-1);
  font-size: 12.5px;
  cursor: pointer;
}
.chat-authfix-retry:hover {
  border-color: var(--brand-border);
  color: var(--brand);
}

/* Provider quota exhausted. Not an error — a pause — and the card's weight follows one
   question: does the reader still have to do something? While a retry is armed the answer is
   no, so this sits neutral, a status line rather than an alarm; a card that stays orange for
   five hours over a situation already handled is just wrong. It escalates to the sign-in
   card's warning tint only when the ball is back in their court (no reset time, retries
   spent, or auto-retry switched off). Same skeleton as .chat-authfix throughout. */
.chat-quota {
  margin: 8px 0;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-raised);
  font-size: 13px;
}
.chat-quota[data-needs-you='true'] {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.chat-quota-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.chat-quota-icon {
  color: var(--text-3);
  flex: none;
}
.chat-quota[data-needs-you='true'] .chat-quota-icon {
  color: var(--warning);
}
.chat-quota-title {
  font-weight: 600;
  color: var(--text-1);
}
.chat-quota-msg {
  margin: 6px 0 0;
  color: var(--text-2);
  font-size: 12px;
}
/* The provider's error verbatim (transient-API-error variant only). Monospace and clipped to a
   few lines: it is a machine string worth copying exactly, but a JSON body must not push the
   countdown and the retry button below the fold. Bordered as well as filled — the fill alone is
   a couple of percent, which in light mode left this as unexplained floating monospace. */
.chat-quota-err {
  max-height: 6em;
  overflow-y: auto;
  margin: 8px 0 0;
  padding: 7px 9px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: var(--fill-inset);
  /* --text-2, not the --text-3 a machine string would otherwise get: sinking the panel darkened
     what is behind this text, and leaving it one step paler than the body copy on a darker
     ground would have taken it from 3:1 to 2.7:1 in light mode. */
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11.5px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}
/* Absolute time first, countdown second: the absolute one is what the user plans around ("I'll
   be back after lunch"), the relative one is what they feel. Tabular figures because it ticks
   — a digit changing width twitches the line every second in the corner of the eye. */
.chat-quota-when {
  margin: 7px 0 0;
  color: var(--text-1);
  font-size: 13px;
}
/* Quieter than the absolute time beside it, but only one step: at --text-3 the countdown was the
   palest thing on the card (3:1 on white) while being what most readers actually look for. */
.chat-quota-in {
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
}
/* What happens next, and the one switch that stops it. Boxed because it is the only thing in
   the card that is a control rather than prose. */
.chat-quota-auto {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 11px;
  padding: 9px 11px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--fill-inset);
}
.chat-quota-auto-txt {
  flex: 1;
  min-width: 0;
}
.chat-quota-auto-l {
  color: var(--text-1);
  font-size: 12.5px;
  font-weight: 550;
}
.chat-quota-auto-d {
  color: var(--text-3);
  font-size: 11.5px;
  margin-top: 1px;
}
.sw {
  flex: none;
  width: 40px;
  height: 21px;
  padding: 0;
  border: 0;
  border-radius: 11px;
  background: var(--fill-muted);
  position: relative;
  cursor: pointer;
}
.sw[data-on='true'] {
  background: var(--brand);
}
.sw::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
}
.sw[data-on='true']::after {
  left: 21px;
}
/* The message the retry would re-send, quoted — same panel and same reason as
   .chat-authfix-last: by now it has scrolled away, and on a first-turn limit it was never in
   the transcript at all. One fill for both of this card's tints: --fill-inset darkens whatever
   is under it, so the neutral card and the escalated one both get a recess instead of the
   escalated one getting a bright hole. */
.chat-quota-last {
  max-height: 13em;
  overflow-y: auto;
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}
.chat-quota-lastl {
  margin: 10px 0 -4px;
  color: var(--text-3);
  font-size: 11.5px;
}
.chat-quota-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}
.chat-quota-retry {
  padding: 5px 12px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
  color: var(--text-1);
  font-size: 12.5px;
  cursor: pointer;
}
/* :not() so the escalated card's lighter fill doesn't swallow the primary button — the
   specificity war .rsi-btn-alt lost once already. */
.chat-quota[data-needs-you='true'] .chat-quota-retry:not([data-primary='true']) {
  background: var(--bg-base);
}
.chat-quota-retry:hover {
  border-color: var(--brand-border);
  color: var(--brand);
}
.chat-quota-retry[data-primary='true'] {
  border-color: var(--brand-border);
  background: var(--brand);
  color: #fff;
}
.chat-quota-retry[data-primary='true']:hover {
  background: var(--brand-strong);
  color: #fff;
}
/* A Retry already in flight (docs/session-request-reply-contract.md §2.1, §8 criterion 19): the
   button stays where it was and stops offering, so a double tap cannot read as two attempts.
   Placed after the variants above so it wins their hovers at equal specificity. */
.chat-authfix-retry:disabled,
.chat-quota-retry:disabled {
  opacity: 0.6;
  cursor: default;
}
.chat-authfix-retry:disabled:hover,
.chat-quota-retry:disabled:hover {
  border-color: var(--border);
  background: var(--bg-raised);
  color: var(--text-1);
}
.chat-quota-note {
  color: var(--text-3);
  font-size: 11.5px;
}
/* Firing: the card becomes its own progress indicator rather than being replaced by one, so
   whoever comes back to a resumed session can still read what happened here. */
.chat-quota-run {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 11px;
  color: var(--brand);
  font-size: 12.5px;
}
.chat-quota-run .spin {
  width: 13px;
  height: 13px;
  border: 2px solid var(--brand-border);
  border-top-color: var(--brand);
  border-radius: 50%;
  animation: chat-quota-spin 0.8s linear infinite;
}
@keyframes chat-quota-spin {
  to {
    transform: rotate(360deg);
  }
}

/* ── rich transcript: Markdown + per-tool cards + sub-agent nesting ───────── */
.md {
  /* Markdown appears inside vertical scrollers (the transcript, task panel and document view).
     `overflow-y: auto` also makes their horizontal overflow scrollable, so one path-like inline
     code span otherwise gives the whole mobile page a desktop-sized scroll width. `anywhere`
     contributes an emergency break to min-content sizing while leaving ordinary prose alone;
     fenced code opts out below and keeps its own horizontal scroller. */
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 14px;
  line-height: 1.6;
  /* Markdown is rendered to real HTML; reset the pre-wrap inherited from
     .chat-msg (meant for raw user/streaming text) so the structural newlines
     mdast-util-to-hast injects between blocks/list-items don't render as blank
     lines and inflate the spacing. */
  white-space: normal;
}
.md > *:first-child {
  margin-top: 0;
}
.md > *:last-child {
  margin-bottom: 0;
}
.md p {
  margin: 6px 0;
}
/* An HTML block — a tag on a line of its own, like a pasted <background-jobs> — is shown as its
   source text (MD has no rehype-raw), in an element of its own (remarkHtmlBlocks) so it keeps the
   line breaks and indentation the reset above would run together. Spaced like a paragraph; a
   single class, so the first/last-child margin resets still win. */
.md-html {
  margin: 6px 0;
  white-space: pre-wrap;
}
.md ul,
.md ol {
  margin: 6px 0;
  padding-left: 22px;
}
.md li {
  margin: 2px 0;
}
.md h1,
.md h2,
.md h3,
.md h4 {
  margin: 12px 0 6px;
  line-height: 1.3;
}
.md h1 {
  font-size: 1.3em;
}
.md h2 {
  font-size: 1.18em;
}
.md h3 {
  font-size: 1.05em;
}
.md code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.88em;
  background: var(--bg-sunken);
  border: 1px solid var(--border);
  padding: 1px 5px;
  border-radius: 4px;
}
.md pre {
  max-width: 100%;
  margin: 8px 0;
  padding: 10px 12px;
  background: var(--bg-sunken);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  overflow-x: auto;
  overflow-wrap: normal;
  word-break: normal;
}
.md pre code {
  background: none;
  border: none;
  padding: 0;
  font-size: 12.5px;
}
.md table {
  border-collapse: separate;
  border-spacing: 0;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
  margin: 8px 0;
  font-size: 13px;
}
.md th,
.md td {
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 4px 8px;
}
.md th:last-child,
.md td:last-child {
  border-right: none;
}
.md tr:last-child td {
  border-bottom: none;
}
.md th {
  background: var(--fill-muted);
  font-weight: 600;
  text-align: left;
}
.md blockquote {
  margin: 8px 0;
  padding-left: 12px;
  border-left: 3px solid var(--border);
  color: var(--text-2);
}
.md a {
  color: var(--brand);
}

/* thinking */
.chat-think {
  margin: 6px 0;
  border-left: 2px solid var(--border);
  padding-left: 10px;
}
.chat-think-head {
  font-size: 12.5px;
  color: var(--text-3);
  cursor: pointer;
  user-select: none;
}
.chat-think-body {
  color: var(--text-2);
  margin-top: 4px;
}
.chat-think-body .md {
  font-size: 13px;
  font-style: italic;
}
/* Only ever drawn inside the viewport below, so it carries that spacing itself rather than
   through a descendant rule. */
.chat-think-stream {
  color: var(--text-3);
  font-style: italic;
  font-size: 13px;
  margin: 4px 0 0;
  white-space: pre-wrap;
  word-break: break-word;
}
/* Reasoning as it streams, held to about ten lines that scroll themselves. Unbounded, it pushed
   the answer — and the tool calls on the way to it — clean out of the viewport: DeepSeek writes
   23k characters of reasoning per turn at the median, 122k at p90. Bounding it also shrinks what
   the fold at the end costs: the block gives back ~130px instead of a page. */
.chat-think-live {
  margin: 6px 0;
  border-left: 2px solid var(--border);
  padding-left: 10px;
}
.chat-think-live-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: var(--text-3);
}
.chat-think-port {
  max-height: 11em;
  overflow-y: auto;
  /* The transcript is itself a scroller pinned to the tail; a wheel that reaches the end of this
     one must not chain up into it and fight that pin. */
  overscroll-behavior: contain;
  padding-right: 8px;
}
.chat-think-meta {
  color: var(--text-4);
  font-variant-numeric: tabular-nums;
}

/* tool cards — folded one-line rows that expand on click */
.chat-tool-card {
  --tone: #d6d9de;
  --tone-bg: var(--bg-hover);
  margin: 6px 0;
  border: none;
  border-left: 3px solid var(--tone);
  overflow: hidden;
  background: transparent;
}
/* folded rows read as a flowing, rail-marked list; once expanded the card
   regains a full border + surface so its detail body stays visually grouped. */
.chat-tool-card.is-open {
  border: 1px solid var(--border);
  border-left: 3px solid var(--tone);
  border-radius: 8px;
  background: var(--bg-raised);
}
/* per-tool colour family: drives the icon chip + the card's left rail */
.chat-tone-read {
  --tone: #2563eb;
  --tone-bg: #e8f0fe;
}
.chat-tone-exec {
  --tone: #0d9488;
  --tone-bg: #e2f6f3;
}
.chat-tone-write {
  --tone: #d97706;
  --tone-bg: #fdf0dd;
}
.chat-tone-agent {
  --tone: #7c3aed;
  --tone-bg: #f1ebfd;
}
.chat-tool-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  font-size: 12.5px;
  cursor: pointer;
  user-select: none;
}
.chat-tool-row:hover {
  background: var(--bg-sunken);
}
.chat-tool-row.no-detail {
  cursor: default;
}
.chat-tool-row.no-detail:hover {
  background: none;
}
.chat-tool-caret {
  flex: none;
  width: 1em;
  color: var(--text-4);
  font-size: 10px;
}
.chat-tool-icon {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: var(--tone-bg);
  color: var(--tone);
  font-size: 13px;
}
.chat-tool-name {
  flex: none;
  font-weight: 600;
  color: var(--text-1);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
/* session_create result → a clickable card that links to the spawned child session.
   Tone (--tone/--tone-bg) comes from the chat-tone-agent class on the card. */
.chat-session-card {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 6px 0;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--tone);
  background: var(--bg-raised);
}
.chat-session-card.is-clickable {
  cursor: pointer;
}
.chat-session-card.is-clickable:hover {
  background: var(--bg-hover);
  border-color: var(--tone);
}
.chat-session-card-icon {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 6px;
  background: var(--tone-bg);
  color: var(--tone);
  font-size: 14px;
}
.chat-session-card-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.chat-session-card-title {
  font-weight: 600;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.chat-session-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11.5px;
  color: var(--text-4);
}
.chat-session-card-workspace {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color: var(--text-3);
}
.chat-session-card-provider {
  text-transform: capitalize;
}
.chat-session-card-status {
  text-transform: uppercase;
  letter-spacing: 0.03em;
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--tone-bg);
  color: var(--tone);
}
.chat-session-card-open {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--tone);
}
.chat-tool-summary {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-2);
  font-size: 12.5px;
}
.chat-tool-summary.mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
}
/* path summary: bold leaf filename + dimmed parent dir */
.chat-path-file {
  font-weight: 600;
  color: var(--text-1);
}
.chat-path-dir {
  margin-left: 6px;
  font-weight: 400;
  color: var(--text-4);
}
/* trailing metadata badge (line range, edit count) */
.chat-tool-meta {
  flex: none;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  color: var(--text-3);
  background: var(--fill-muted);
  border-radius: 5px;
  padding: 0 6px;
}
.chat-tool-status {
  flex: none;
  font-size: 13px;
}
.chat-tool-status.ok {
  color: var(--success);
}
.chat-tool-status.err {
  color: var(--error);
}
.chat-tool-status.running {
  color: var(--brand);
}
.chat-tool-status.pending {
  color: var(--dot-idle);
}
.chat-tool-task .chat-tool-row {
  background: #faf8ff;
}
.chat-tool-task .chat-tool-row:hover {
  background: #f4eefe;
}
.chat-tool-group .chat-tool-row {
  min-height: 32px;
}
.chat-tool-group:not(.is-open) .chat-tool-row {
  background: transparent;
}
.chat-tool-group:not(.is-open) .chat-tool-row:hover {
  background: var(--bg-sunken);
}
.chat-tool-group-lead {
  color: var(--text-3);
}
.chat-tool-group-lead.is-failed {
  color: var(--error);
}
.chat-tool-group-lead .mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
}
/* The breakdown is what a settled group's folded row is really for, so give it room for the
   usual two-or-three kinds — but never much past half the row, or a narrow window would let it
   squeeze the counts (which have no fixed width of their own) out of the line entirely. */
.chat-tool-group-breakdown {
  max-width: min(420px, 55%);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-tool-group-detail {
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-raised);
  padding: 4px 8px 8px;
}
.chat-tool-group-detail .chat-tool-card {
  margin: 4px 0;
}
.chat-tool-detail {
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-raised);
}
.chat-tool-detail > .chat-result:first-child {
  border-top: none;
}
.chat-tool-body {
  padding: 8px 10px;
}
.chat-tool-prompt {
  font-size: 13px;
  color: var(--text-2);
}
/* key/value table for unknown & MCP tool inputs (vs a raw JSON blob) */
.chat-kv {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12.5px;
}
.kv-row {
  display: flex;
  gap: 8px;
  align-items: baseline;
}
.kv-key {
  flex: none;
  min-width: 92px;
  color: var(--text-3);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
}
.kv-val {
  color: var(--text-1);
  white-space: pre-wrap;
  word-break: break-word;
}
.kv-row .chat-pre-wrap {
  flex: 1 1 auto;
  min-width: 0;
}

/* AskUserQuestion: one card per question (header · prompt · options) */
.chat-questions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.chat-q {
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--bg-raised);
}
.chat-q-header {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 4px;
}
.chat-q-text {
  font-size: 13px;
  color: var(--text-1);
  margin-bottom: 6px;
  /* The question is one plain-text string the agent wrote, line breaks and all, and both renderers
     (`QuestionForm`, and `Questions` in the transcript) put it here unchanged — so this is the only
     place that decides whether they survive. `word-break` because an id or a URL with no break
     opportunity in it would otherwise widen the card past its column. */
  white-space: pre-wrap;
  word-break: break-word;
}
.chat-q-opts {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.chat-q-opt {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px 8px;
  border-radius: 6px;
  background: var(--bg-sunken);
}
.chat-q-opt-label {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-1);
}
.chat-q-opt-desc {
  font-size: 12px;
  color: var(--text-2);
}
/* Historical variant (in the transcript): highlight the option(s) the user
   picked. inset box-shadow (not border) so the outline adds no layout shift. */
.chat-q-opt.is-picked:not(.chat-q-opt-btn) {
  background: var(--brand-tint);
  box-shadow: inset 0 0 0 1px var(--brand-border);
}
.chat-q-opt.is-picked:not(.chat-q-opt-btn) .chat-q-opt-label::before {
  content: '✓ ';
  color: var(--brand);
}
.chat-q-multi {
  margin-top: 6px;
  font-size: 11px;
  color: var(--text-3);
}
/* Interactive variant (in the approval card): options are clickable buttons. */
.chat-q-opt-btn {
  width: 100%;
  text-align: left;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: border-color 0.1s, background 0.1s;
}
.chat-q-opt-btn:hover {
  border-color: var(--brand-border);
  background: var(--brand-tint);
}
.chat-q-opt-btn.is-picked {
  border-color: var(--brand);
  background: var(--brand-tint);
}
.chat-q-opt-btn.is-picked .chat-q-opt-label::before {
  content: '✓ ';
  color: var(--brand);
}
/* ── The evidence-decision card ───────────────────────────────────────────────────────────
   The completion decision (`EvidenceDecisionCard.tsx`) is a judgment about a row the server
   publishes in full, not a form, so it is laid out as the reader decides — what is claimed, what
   is admitted missing, what was checked for them — with the actions stacked underneath instead of
   hidden behind a pick-then-Submit. */
.decision-ask-body {
  padding-bottom: 12px;
}
.decision-ask-chip {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--text-3);
  margin: 8px 0 4px;
}
/* The claim is the card's lead: it is the sentence somebody is standing behind, and everything
   below it is evidence about that sentence. */
.decision-ask-claim {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.45;
  color: var(--text-1);
  white-space: pre-wrap;
}
.decision-ask-quiet {
  font-weight: 400;
  color: var(--text-3);
}
.decision-ask-meta {
  margin-top: 4px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11.5px;
  color: var(--text-3);
  word-break: break-all;
}
/* The sentence being judged, first on the card: the criterion's own text, in the frame the gaps
   have and without their amber — what the answer is measured against is not a warning. */
.decision-ask-standard {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--bg-raised);
}
.decision-ask-standard-head {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--text-3);
}
.decision-ask-standard-text {
  margin-top: 2px;
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-1);
  overflow-wrap: anywhere;
}
/* The submitter's account at the foot of the card. It is quoted material rather than the card's
   lead now, so it does not keep the lead's size and weight. */
.decision-ask-account {
  margin-top: 10px;
}
.decision-ask-account .decision-ask-claim {
  margin-top: 4px;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.55;
  color: var(--text-2);
}
/* What the submitter says they did NOT establish. Amber because it is the reason to press the
   other button, and never folded for the same reason. */
.decision-ask-gaps {
  margin-top: 10px;
  border: 1px solid var(--warning-border);
  border-radius: 8px;
  background: var(--warning-bg);
  padding: 8px 10px;
}
.decision-ask-gaps-head {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--warning);
}
.decision-ask-gaps-list,
.decision-ask-gaps-rest {
  margin: 4px 0 0;
  padding-left: 18px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-1);
}
.decision-ask-gaps-list li + li,
.decision-ask-gaps-rest li + li {
  margin-top: 4px;
}
.decision-ask-checks {
  margin-top: 8px;
}
/* A disclosure has to read as one without reading as an action: text-sized, text-coloured, and
   carrying nothing but the caret to say it opens. Same shape the decision rail's tally has. */
.decision-ask-toggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  border: none;
  background: none;
  cursor: pointer;
  font: inherit;
  font-size: 12.5px;
  color: var(--text-2);
  text-align: left;
}
.decision-ask-toggle:hover:not(:disabled) {
  text-decoration: underline;
}
.decision-ask-caret {
  color: var(--text-3);
  font-size: 11px;
}
.decision-ask-check-list {
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
  font-size: 12.5px;
  line-height: 1.5;
}
.decision-ask-check-list li {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  color: var(--text-2);
}
.decision-ask-check-list li.is-held .decision-ask-check-mark {
  color: var(--success);
}
.decision-ask-check-list li.is-broken .decision-ask-check-mark {
  color: var(--warning);
}
.decision-ask-check-detail {
  flex-basis: 100%;
  color: var(--text-3);
  white-space: pre-wrap;
}
/* The actions stack: a verdict is a full-width choice, not one of three things on a toolbar.
   Written against `.card-actions` too, because that class sets `align-items: center` further down
   this file and the later rule would otherwise decide the layout of a card it knows nothing about. */
.card-actions.decision-ask-actions {
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  margin-top: 12px;
}
/* What an answer given from the card leaves where its actions were. */
.decision-ask-picked {
  margin-top: 12px;
  font-size: 12.5px;
  color: var(--text-2);
}
/* Its head carries the provenance mark the criteria card carries, and a version it can no longer
   answer says why above the actions it has disabled. */
.evidence-decision .approval-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
.evidence-decision-heading {
  min-width: 0;
}
.evidence-decision-stale {
  margin: 12px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-2);
}
.evidence-decision-error {
  margin-top: 12px;
}
/* A decision recorded from the conversation, kept where it was made (`EvidenceDecisionReceipt`):
   the card's frame at rest, without the brand tone of a question that is waiting for somebody.
   Two classes, because `.approval-card` is written further down and would win at one. */
.approval-card.evidence-decision-receipt {
  border-color: var(--border);
  background: var(--bg-raised);
}
.evidence-decision-receipt .approval-head {
  background: var(--bg-raised);
  border-bottom-color: var(--border-subtle);
}
.evidence-decision-receipt-mark {
  color: var(--success-solid);
}
/* ── The owner-confirmation card ──────────────────────────────────────────────────────────
   `OwnerConfirmationCard.tsx`: an OWNER_CONFIRMED task's run has ended its turn, and its owner is
   asked to confirm it done or send it back. The evidence card's frame, with the two facts a person
   decides from — what settles the task, and what the run reported — each in a box of its own. */
.owner-confirmation-lead {
  margin-top: 8px;
}
.owner-confirmation-box {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--bg-raised);
}
.owner-confirmation-key {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--text-3);
}
.owner-confirmation-value {
  margin-top: 2px;
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-1);
  overflow-wrap: anywhere;
  /* The text keeps its paragraphs and list items on lines of their own (`markdownToPlainLines`). */
  white-space: pre-wrap;
}
/* What counts as done, folded to one row that opens in place: the key, how many items, a caret. */
.owner-confirmation-fold {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 0;
  border: none;
  background: none;
  cursor: pointer;
  font: inherit;
  text-align: left;
}
.owner-confirmation-count {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-2);
}
.owner-confirmation-fold .anticon {
  font-size: 10px;
  color: var(--text-3);
}
/* If you confirm: Orbit's own facts about what the press sets off, right above Confirm done. White
   and edged in the neutral border, with a symbol per row and no author, where the two boxes above
   it quote somebody. */
.owner-confirmation-if {
  margin-top: 10px;
  padding: 8px 12px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-base);
}
.owner-confirmation-if-row {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}
.owner-confirmation-if-symbol {
  flex: none;
  width: 14px;
  padding-top: 2px;
  font-size: 12px;
  color: var(--text-3);
}
.owner-confirmation-if-row.is-start .owner-confirmation-if-symbol {
  color: var(--brand);
}
.owner-confirmation-if-text {
  flex: 1;
  min-width: 0;
}
.owner-confirmation-if-lead {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.5;
  color: var(--text-1);
}
.owner-confirmation-if-added {
  font-weight: 500;
  color: var(--success-solid);
}
.owner-confirmation-if-detail {
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The line under the buttons on both cards whose second answer is a composer handoff: where the
   next message goes, and what pressing does not do. One rule, two cards — the sentence is the
   promise, and a promise that drifts between two cards saying the same thing is two promises. */
.owner-confirmation-hint,
.decision-ask-hint {
  margin-top: 8px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-3);
}
/* What the line under the title says: whose call this is, with the task's address kept quieter
   beside it. It replaced `<id> · OWNER_CONFIRMED`, which spent the card's second line on an
   enum and a 21-character id. */
.owner-confirmation-yours {
  margin-top: 4px;
  font-size: 12.5px;
  color: var(--text-2);
}
.owner-confirmation-id {
  margin-left: 6px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11.5px;
  color: var(--text-3);
  word-break: break-all;
}
/* The task panel's pointer to that card while a run is waiting on it: a way there, not a button. */
.tdp-owner-confirmation-pointer {
  display: inline-flex;
  align-items: center;
  font-size: 13px;
  color: var(--warning-solid);
  white-space: nowrap;
}
/* …and while its report is still with its reviewer: nobody is asking the owner yet, so not amber. */
.tdp-owner-confirmation-pointer.is-under-review {
  color: var(--text-2);
}
/* The review bar (`OwnerConfirmationReview.tsx`): the reviewer's box, between what the agent said and
   If you confirm. Drawn like the agent's own box — somebody's words, under their name — with Orbit's
   first line in it. */
.owner-confirmation-review {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--bg-raised);
}
.owner-confirmation-review-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
/* The reviewer's name gives way, never the label or the time beside it. */
.owner-confirmation-review-who {
  display: flex;
  flex: 1;
  min-width: 0;
  white-space: nowrap;
}
.owner-confirmation-review-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 11px;
  color: var(--text-3);
}
.owner-confirmation-review-who .owner-confirmation-key {
  flex: none;
  white-space: pre;
}
.owner-confirmation-review-sha {
  flex: none;
  margin-left: auto;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  color: var(--text-3);
}
.owner-confirmation-review-sha.is-struck {
  text-decoration: line-through;
}
.owner-confirmation-review-status {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
}
.owner-confirmation-review-status .anticon {
  font-size: 14px;
  color: var(--text-3);
}
.owner-confirmation-review-status.is-warn {
  color: var(--warning);
}
.owner-confirmation-review-note {
  margin-top: 4px;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--text-2);
}
/* Orbit's first line: one line, the whole of it in the lines below. */
.owner-confirmation-review-headline {
  margin-top: 6px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.45;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.owner-confirmation-review-headline.is-warn {
  color: var(--warning);
}
.owner-confirmation-review-row {
  display: grid;
  grid-template-columns: 84px 1fr;
  column-gap: 8px;
  margin-top: 5px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-1);
  cursor: pointer;
}
.owner-confirmation-review-row-label {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}
.owner-confirmation-review-row.is-checked .owner-confirmation-review-row-label {
  color: var(--success);
}
.owner-confirmation-review-row.is-not-checked .owner-confirmation-review-row-label,
.owner-confirmation-review-row.is-problem .owner-confirmation-review-row-label {
  color: var(--warning);
}
/* Two lines at most at rest; a press opens the row to each of its lines. */
.owner-confirmation-review-row-text {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
}
.owner-confirmation-review-items {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-wrap: anywhere;
}
.owner-confirmation-review-items li + li {
  margin-top: 4px;
}
.owner-confirmation-review-why {
  font-size: 12px;
  color: var(--text-2);
}
.owner-confirmation-review-ref {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11.5px;
  color: var(--text-3);
  overflow-wrap: anywhere;
}
.owner-confirmation-review-quote {
  margin-top: 7px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-1);
  overflow-wrap: anywhere;
}
.owner-confirmation-review-old {
  margin-top: 6px;
}
.owner-confirmation-review-old .anticon,
.owner-confirmation-review-evidence .anticon {
  font-size: 10px;
  color: var(--text-3);
}
.owner-confirmation-review-reopen {
  margin-top: 8px;
}
/* The answer blocks for the reviewer's questions: the question card's own rows. */
.owner-confirmation-review-answers {
  margin-top: 4px;
}
.owner-confirmation-review-question + .owner-confirmation-review-question {
  margin-top: 10px;
}
.owner-confirmation-review-question-text {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-1);
}
.owner-confirmation-review-evidence {
  margin-top: 2px;
}
/* Under a receipt: the review came in after the decision, and what the owner answered. */
.owner-confirmation-before-review {
  margin-top: 2px;
  font-size: 12px;
  color: var(--text-3);
}
.owner-confirmation-answers {
  margin-top: 10px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-1);
}
.owner-confirmation-answers-head {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-2);
}
.owner-confirmation-answer + .owner-confirmation-answer {
  margin-top: 4px;
}
/* ── The settlement confirmation card ─────────────────────────────────────────────────────
   `AcceptanceConfirmationCard.tsx`: whether the stated criteria, together, are what "done" means.
   The approval card's own tone rather than the warning one — it is a question about meaning, like
   the question and plan cards, not a ruler getting looser — with the provenance mark in its head
   like the other two cards Orbit draws into a conversation. */
/* The receipt wears the same head as the card it replaces, so it takes the same row: the heading,
   and the provenance mark pushed to the trailing edge by its own `margin-left: auto`. */
.settlement-card .approval-head,
.settlement-receipt .approval-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
.settlement-card-heading {
  min-width: 0;
}
.settlement-card-body {
  padding-top: 10px;
  padding-bottom: 10px;
}
.settlement-card-meta {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}
.settlement-card-stale {
  margin: 10px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-2);
}
/* The criteria are open on the card, not behind a toggle: the reader is agreeing to THESE, and a
   folded list is an invitation to sign what was never opened. Each is clamped to two lines so a set
   of any size still reads as one card; `is-open` takes the clamp off. */
.settlement-card-criteria {
  margin: 10px 0 0;
  padding-left: 22px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-1);
}
/* The clamp is on the text and not on the row: `-webkit-box` on the `li` itself would take its
   ordinal with it, and the ordinal is how a reader names which condition they mean. */
.settlement-card-criterion {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.settlement-card-criteria.is-open .settlement-card-criterion {
  -webkit-line-clamp: unset;
  overflow: visible;
}
.settlement-card-criteria li + li {
  margin-top: 4px;
}
/* A reading control, not an action: it sits with the text it unfolds rather than in the action row,
   which is why it is not a `.card-action`. */
.settlement-card-read {
  margin-top: 6px;
  padding: 0;
  border: none;
  background: none;
  font-size: 12.5px;
  color: var(--brand);
  cursor: pointer;
}
.settlement-card-read:hover {
  text-decoration: underline;
}
.settlement-card-explains {
  margin: 10px 0 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-2);
}
.settlement-card-error {
  margin-top: 10px;
}
/* The record of a confirmation (`AcceptanceConfirmationReceipt`): what was signed, by whom, and at
   which version. Denser than the card it stands in for, because nothing on it is pressable — it is
   the same brand tone and the same head, so a reader who watched the card give way to it reads one
   object being written down rather than two. */
.settlement-receipt-body {
  padding-top: 10px;
  padding-bottom: 10px;
}
.settlement-receipt-line {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-1);
}
.settlement-receipt-stamp {
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--text-3);
}
/* The settings a start left the project running with, under the receipt's line and the "Project
   started" card's title (`RunSettingsSummary`): one quiet line, with what the owner changed from the
   coordinator's suggestion set in bold where it stands. */
.settlement-receipt-settings {
  margin: 2px 0 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-2);
  overflow-wrap: anywhere;
}
.run-settings-changed {
  font-weight: 600;
  color: var(--text-1);
  text-decoration: underline dotted;
  text-underline-offset: 3px;
}

/* ── Start this project? ─────────────────────────────────────────────────────────────────
   `StartProjectCard.tsx`: the settlement card's shell, with three sections under it — the
   criteria, the plan, and How it runs, drawn with the integration settings card's own rows
   (`.project-integration-setting`) in a raised panel. Mock: start-mock/board2-start-web.html. */
.start-card-section {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 14px 0 6px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-3);
}
.start-card-section + .settlement-card-criteria {
  margin-top: 4px;
}
.start-card-section-aside {
  margin-left: auto;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  color: var(--brand);
}
.start-card-plan {
  font-size: 13px;
  line-height: 1.65;
  color: var(--text-1);
}
.start-card-link {
  margin-left: 6px;
  padding: 0;
  border: none;
  background: none;
  font: inherit;
  color: var(--brand);
  text-decoration: none;
  cursor: pointer;
}
.start-card-plan > .start-card-link:first-child {
  margin-left: 0;
}
.start-card-link:hover {
  text-decoration: underline;
}
.start-card-warn {
  margin-top: 2px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--warning);
}
.start-card-settings {
  padding: 0 12px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 8px;
  background: var(--bg-raised);
}
/* The two lines, one under the other; the class makes these rules outrank antd's own
   `.ant-radio-group` / `.ant-radio-wrapper` ones, which would otherwise win on order. How it runs
   (`.project-run-settings`) draws the same two. */
.start-card-settings .start-card-lines,
.project-run-settings .project-run-lines {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.start-card-settings .start-card-lines .ant-radio-wrapper,
.project-run-settings .project-run-lines .ant-radio-wrapper {
  align-items: flex-start;
  margin-inline-end: 0;
}
.start-card-settings .start-card-lines .ant-radio,
.project-run-settings .project-run-lines .ant-radio {
  align-self: flex-start;
  margin-top: 3px;
}
.start-card-branch,
.start-card-mono,
.start-card-mono input {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
}
.start-card-branch {
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--bg-subtle);
  overflow-wrap: anywhere;
}
.start-card-inline {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-1);
}
.start-card-settings .start-card-count,
.project-run-settings .start-card-count {
  width: 72px;
}
/* The merge check row when Automatic would merge the branch into main with nothing run on the
   combined tree: its label in the warning colour, and the sentence saying why under the box. */
.project-integration-setting.is-warn .project-integration-setting-label {
  color: var(--warning);
}
.start-card-note {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-3);
}
.start-card-checked {
  display: flex;
  gap: 7px;
  margin: 12px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-2);
}
.start-card-tick {
  flex: none;
  font-weight: 700;
  color: var(--success);
}
/* 443px and the like: the settings rows go to one column at the integration card's own 640px
   breakpoint, and the lines keep their names and lose their descriptions. */
@media (max-width: 640px) {
  .start-card-option-hint {
    display: none;
  }
}

/* ── Confirm the new criteria? ───────────────────────────────────────────────────────────
   `CriteriaChangeCard.tsx`: only what changed, one row each — a mark, which criterion and what
   happened to it, and its words (a stricter check's old one quieter under the new).
   Mock: start-mock/board4-criteria-change.html. */
.criteria-change-list {
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-raised);
}
.criteria-change-list li {
  display: grid;
  grid-template-columns: 22px 100px minmax(0, 1fr);
  gap: 8px;
  padding: 8px 10px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-1);
}
.criteria-change-list li + li {
  border-top: 1px solid var(--border-subtle);
}
.criteria-change-mark {
  font-weight: 700;
  text-align: center;
  border-radius: 4px;
}
.criteria-change-kind {
  padding-top: 1px;
  font-size: 12px;
  font-weight: 600;
}
.criteria-change-text {
  min-width: 0;
  overflow-wrap: anywhere;
}
.criteria-change-was {
  display: block;
  font-size: 12px;
  color: var(--text-3);
}
.criteria-change-list .is-new .criteria-change-mark {
  color: var(--success);
  background: var(--success-bg);
}
.criteria-change-list .is-new .criteria-change-kind {
  color: var(--success);
}
.criteria-change-list .is-stricter .criteria-change-mark,
.criteria-change-list .is-revised .criteria-change-mark {
  color: var(--brand);
  background: var(--brand-tint);
}
.criteria-change-list .is-stricter .criteria-change-kind,
.criteria-change-list .is-revised .criteria-change-kind {
  color: var(--brand);
}
.criteria-change-rest {
  margin-top: 8px;
  font-size: 12.5px;
  color: var(--text-3);
}
.criteria-change-rest .settlement-card-read {
  margin-top: 0;
}
@media (max-width: 640px) {
  .criteria-change-list li {
    grid-template-columns: 22px minmax(0, 1fr);
  }
  .criteria-change-text {
    grid-column: 2;
  }
}
/* Two short answers stay side by side on a phone: the stacked action sheet below 600px exists for
   the approval card's third, long label, and these cards have none. */
@media (max-width: 600px) {
  .start-card .card-actions,
  .criteria-change-card .card-actions {
    flex-direction: row;
    align-items: center;
  }
  .start-card .card-action,
  .criteria-change-card .card-action {
    width: auto;
  }
}

/* ── Why is this project not done ────────────────────────────────────────────────────────
   `ProjectSettlementCard.tsx`: the projection, rendered in the coordinator conversation. Not a
   question and not a verdict — the same approval tone as the card it is the other end of (brand
   tint, no green, no tick), because `project.status` is derived by the server and this only says
   what it is waiting on. One block per clause that does not hold, and the criteria that trip it
   are a grid so the fact column lines up down the block, which is the column being checked. */
.project-settlement .approval-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
.project-settlement-heading {
  min-width: 0;
}
.project-settlement-body {
  padding-top: 10px;
  padding-bottom: 10px;
}
.project-settlement-meta {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}
/* The rule, then the count of clauses that do not hold: the whole card is one sentence held up
   against one project, so the sentence is stated before the blocks rather than assumed. */
.project-settlement-rule {
  margin: 10px 0 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-2);
}
.project-settlement-block {
  margin: 12px 0 0;
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--bg-raised);
  border: 1px solid var(--brand-border);
}
.project-settlement-block-title {
  display: flex;
  gap: 8px;
  align-items: baseline;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
/* The count is the clause's own number: how many criteria trip it, or a mark for the two clauses
   that are about the project rather than about any criterion. */
.project-settlement-block-count {
  flex: none;
  min-width: 18px;
  padding: 1px 6px;
  border-radius: 20px;
  background: var(--text-1);
  color: var(--bg-raised);
  font-size: 11px;
  font-weight: 700;
  text-align: center;
}
.project-settlement-rows {
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}
.project-settlement-rows li {
  display: flex;
  gap: 8px;
  align-items: baseline;
  padding: 4px 0;
  border-top: 1px solid var(--border-subtle);
  font-size: 12.5px;
}
.project-settlement-rows li:first-child {
  border-top: none;
}
/* One mark per row and it is the ordinal, as on the criteria card: the reader names a criterion by
   its number, and a tick or a cross here would be the verdict badge 0229 deleted. */
.project-settlement-no {
  flex: none;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--text-1);
  color: var(--bg-raised);
  font-size: 10px;
  font-weight: 600;
  line-height: 17px;
  text-align: center;
}
.project-settlement-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--text-1);
}
/* The fact column: `Settled · No receipt` and its two siblings. Never red — UNKNOWN is the absence
   of evidence, not a finding that the work is absent. */
.project-settlement-facts {
  flex: none;
  font-size: 11px;
  color: var(--text-2);
  white-space: nowrap;
}
.project-settlement-read {
  margin-top: 6px;
  padding: 0;
  border: none;
  background: none;
  font-size: 12.5px;
  color: var(--brand);
  cursor: pointer;
}
.project-settlement-read:hover {
  text-decoration: underline;
}
.project-settlement-conflicts {
  margin: 6px 0 0;
  padding-left: 18px;
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--text-3);
}
.project-settlement-why {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-2);
}
.project-settlement-clears {
  margin: 6px 0 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-1);
}
.project-settlement-tally {
  margin: 12px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}
/* The settled state, which is read back from the projection rather than remembered: it says the
   derivation stopped withholding, and it does not become a green card because of it. */
.project-settlement-settled {
  margin: 10px 0 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-1);
}
.project-settlement-settled-provenance {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-3);
}
/* The action row is a wrapping flex row: the hint under it carries `flex-basis: 100%`, which is a
   no-op unless the row is flex — it was meant to sit under the buttons and instead ran on beside
   them (`.approval-actions` alone is not a flex container; `.card-actions` is). */
.project-settlement-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.project-settlement-error {
  margin-top: 10px;
}
.project-settlement-hint {
  flex-basis: 100%;
  margin: 2px 0 0;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-3);
}

/* Free-text answer field: lets the user type their own answer to a question. */
.chat-q-custom {
  margin-top: 4px;
  width: 100%;
  box-sizing: border-box;
  padding: 5px 8px;
  font: inherit;
  font-size: 12.5px;
  color: var(--text-1);
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
  outline: none;
  transition: border-color 0.1s, background 0.1s;
}
.chat-q-custom:focus {
  border-color: var(--brand);
  background: var(--brand-tint);
}
.chat-q-custom::placeholder {
  color: var(--text-4);
}

/* monospace blocks (commands, json, results) */
.chat-pre-wrap.muted .chat-pre {
  color: var(--text-2);
  font-size: 12px;
}
.chat-pre-wrap.cmd .chat-pre {
  background: var(--bg-sunken);
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  padding: 8px 10px;
}
.chat-cmd-prompt {
  color: var(--brand);
  font-weight: 600;
  user-select: none;
}
.chat-pre {
  margin: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12.5px;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--text-1);
}
.chat-more {
  margin-top: 4px;
  background: none;
  border: none;
  color: var(--brand);
  font-size: 12px;
  cursor: pointer;
  padding: 0;
}

/* edit diff — line-level, with context + collapsed unchanged runs */
.chat-diff {
  margin: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12.5px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  overflow: hidden;
}
.diff-line {
  display: flex;
  align-items: flex-start;
  white-space: pre-wrap;
  word-break: break-word;
}
.diff-ln {
  flex: none;
  width: 34px;
  padding: 0 6px;
  text-align: right;
  color: var(--text-4);
  background: var(--bg-subtle);
  font-size: 11px;
  user-select: none;
}
.diff-sign {
  flex: none;
  width: 16px;
  text-align: center;
  color: var(--text-3);
  user-select: none;
}
.diff-text {
  flex: 1 1 auto;
  min-width: 0;
  padding-right: 8px;
}
.diff-del {
  background: var(--error-bg);
}
.diff-del .diff-sign,
.diff-del .diff-text {
  color: var(--error);
}
.diff-add {
  background: var(--success-bg);
}
.diff-add .diff-sign,
.diff-add .diff-text {
  color: var(--success);
}
.diff-ctx .diff-text {
  color: var(--text-2);
}
.diff-gap {
  background: var(--bg-subtle);
}
.diff-gutter {
  flex: none;
  width: 84px;
  background: var(--bg-subtle);
}
.diff-gap .diff-text {
  color: var(--text-4);
  font-style: italic;
  padding-left: 8px;
}

/* todos */
.chat-todos {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 13px;
}
.todo {
  display: flex;
  gap: 8px;
}
.todo-mark {
  width: 14px;
  color: var(--text-3);
}
.todo-completed {
  color: var(--text-3);
  text-decoration: line-through;
}
.todo-in_progress .todo-mark {
  color: var(--brand);
}

/* sub-agent (Task) transcript — nested under the spawning call */
.chat-subagent {
  margin: 6px 0;
  padding: 2px 0 2px 12px;
  border-left: 2px solid var(--border);
}

/* tool result */
.chat-result {
  border-top: 1px dashed var(--border-subtle);
  padding: 6px 10px;
  background: var(--bg-subtle);
}
.chat-result.is-error {
  background: var(--error-bg);
}
.chat-result-label {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-4);
  margin-bottom: 3px;
}
.chat-result.is-error .chat-result-label {
  color: var(--error-border);
}
.chat-result-empty {
  font-size: 12.5px;
  color: var(--error);
}

/* Tool-permission approval card (plan-mode ExitPlanMode + any gated tool). */
.approval-card {
  border: 1px solid var(--brand);
  border-radius: 10px;
  background: var(--brand-tint);
  margin: 10px 0;
  overflow: hidden;
}
.approval-head {
  padding: 10px 14px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-1);
  background: var(--brand-tint);
  border-bottom: 1px solid var(--brand-border);
}
.approval-body {
  padding: 4px 14px;
  max-height: 360px;
  overflow: auto;
  font-size: 13.5px;
  color: var(--text-1);
}
/* The question form and a plan grow with their content instead of scrolling inside the
   card — every line stays fully visible and the transcript scrolls naturally. A long plan
   shouldn't be crushed into a 360px scroll box. (A raw tool-input JSON dump keeps the cap
   below; it's a debug blob, not something read top to bottom.) */
.approval-body.is-questions,
.approval-body.is-plan {
  max-height: none;
  overflow: visible;
}
/* ── DAG change card ──────────────────────────────────────────────────────────────────────
   The consequence first and largest: a batch reading "remove 4 edges" is unremarkable until
   you know it releases 40 tasks, and those start on the next sweep. */
.dag-approval {
  padding: 4px 0 8px;
}
.dag-approval-note {
  margin: 0 0 10px;
  color: var(--text-1);
}
.dag-approval-impact {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 10px;
}
.dag-impact {
  padding: 3px 9px;
  border-radius: 6px;
  background: var(--bg-raised);
  color: var(--text-2);
  font-size: 12.5px;
}
.dag-impact--run {
  background: color-mix(in srgb, var(--success, #52c41a) 14%, transparent);
  color: var(--success, #389e0d);
  font-weight: 600;
}
.dag-impact--block {
  background: color-mix(in srgb, var(--warning, #faad14) 16%, transparent);
  color: var(--warning-fg, #ad6800);
  font-weight: 600;
}
/* The batch's shape. Nodes read as the same objects the counts above describe, and edges are the
   quietest thing on the card — the structure should be legible from the arrangement, not from the
   lines being loud. */
.batch-graph {
  margin: 2px 0 8px;
}
.batch-graph-edge {
  fill: none;
  stroke: color-mix(in srgb, var(--text-3) 55%, transparent);
  stroke-width: 1.2;
}
.batch-graph-node rect {
  fill: color-mix(in srgb, var(--brand) 12%, var(--bg-raised));
  stroke: color-mix(in srgb, var(--brand) 34%, transparent);
  stroke-width: 1;
}
.batch-graph-node text {
  fill: var(--text-1);
  font-size: 11px;
}
/* Waiting on something that is not drawn: dashed, so it never reads as a task ready to start. */
.batch-graph-node.is-outside rect {
  stroke-dasharray: 3 2;
  fill: var(--bg-raised);
}

.dag-approval-caption {
  margin: 0 0 3px;
  color: var(--text-3);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
/* Under a new project's criteria on its create card: approving the create does not confirm them. */
.create-criteria-note {
  margin: 2px 0 0;
  color: var(--text-3);
  font-size: 12px;
}
.dag-approval-ops,
.dag-approval-changes {
  list-style: none;
  margin: 0 0 10px;
  padding: 0;
  font-size: 12.5px;
}
.dag-op {
  display: flex;
  align-items: baseline;
  gap: 7px;
  padding: 2px 0;
}
.dag-op-verb {
  width: 10px;
  font-weight: 700;
  color: var(--text-3);
}
.dag-op--add .dag-op-verb {
  color: var(--brand);
}
.dag-op.is-noop {
  opacity: 0.55;
}
.dag-op-noop {
  color: var(--text-3);
  font-size: 11.5px;
}
.dag-approval-changes li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 2px 0;
  border-top: 1px solid var(--border-subtle);
}
.dag-change-move {
  color: var(--text-3);
  white-space: nowrap;
}
.dag-approval-foot {
  margin: 0;
  color: var(--text-3);
  font-size: 11.5px;
}
/* The single create's own two rows: the name, which the batch card puts in its tree and this card
   has no tree for, and the fold over the description — the field written for the agent that will
   execute the task, and the only one long enough to push the buttons off a phone's screen. */
.create-title {
  margin: 4px 0 2px;
  color: var(--text-1);
  font-weight: 600;
}
.create-fold {
  margin: 2px 0 0;
  font-size: 12.5px;
  color: var(--text-2);
}
.create-fold > summary {
  padding: 3px 0;
  color: var(--text-3);
  cursor: pointer;
}
.dag-approval-criteria {
  margin: 0;
  color: var(--text-2);
  line-height: 1.6;
  white-space: pre-wrap;
}
.approval-input {
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12.5px;
  margin: 8px 0;
}
/* ---- Card actions: one size, wherever a card asks the reader for something ----
   The approval card settled these numbers over three rounds of beta — default control size, not a
   50pt slab; the 44pt target is spent on option rows, where a mis-tap costs more. The decision
   rail renders through the same component (`CardAction.tsx`) so there is one set of them. */
.card-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.approval-actions {
  padding: 10px 14px;
  border-top: 1px solid var(--brand-border);
}
/* The line a card carries once its turn is over and its actions are all disabled. Muted and
   above the dead row, so it reads as the reason they are dead rather than as another ask. */
.approval-stale {
  margin: 0;
  padding: 8px 14px 0;
  font-size: 12px;
  color: var(--text-2);
}
.card-action {
  padding: 6px 16px;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
  border: 1px solid transparent;
}
.card-action--primary {
  background: var(--brand);
  color: var(--bg-raised);
}
.card-action--primary:hover:not(:disabled) {
  background: var(--brand-strong);
}
.card-action--secondary {
  background: var(--bg-raised);
  color: var(--text-2);
  border-color: var(--border);
}
.card-action--secondary:hover:not(:disabled) {
  background: var(--bg-hover);
}
.card-action--outline {
  background: var(--bg-raised);
  color: var(--brand);
  border-color: var(--brand-border);
}
.card-action--outline:hover:not(:disabled) {
  background: var(--brand-tint);
}
.card-action--accent {
  background: var(--brand-tint);
  color: var(--brand-strong);
  border-color: var(--brand-border);
}
.card-action--accent:hover:not(:disabled) {
  background: var(--brand-border);
}
.approval-rule {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--brand-border);
  color: var(--brand-strong);
  white-space: nowrap;
}
/* An action that cannot succeed is disabled rather than lit-and-refused, and it says so at a
   glance — in both cards, because there is one button. */
.card-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
/* And the primary tone loses its FILL while it is disabled, rather than only being dimmed. A solid
   brand slab at half strength is still the most pressable-looking thing on a card, so a Confirm
   the door would refuse went on inviting the press it was built to refuse. Outline instead of
   fill, so the two states differ in shape and not only in strength. Enabled is untouched. */
.card-action--primary:disabled {
  background: var(--bg-raised);
  color: var(--text-3);
  border-color: var(--border);
}
.approval-kbd {
  margin-left: 8px;
  font-size: 11px;
  opacity: 0.75;
}
/* ── The criteria-decision card ────────────────────────────────────────────────────────────────
   The approval card's shape, in the warning tone, because what it asks about is a ruler getting
   LOOSER — the one change in this product that cannot be undone by doing more work. Written after
   `.approval-*` so these land on top of them, and the actions row is selected with both classes
   because `.card-actions` further up sets its own alignment. */
.criteria-decision {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
/* A card that is no longer a question — answered at another end, displaced, or stranded by a moved
   seal — is dimmed as one object: the account owner's call on 2026-09-11, the same 0.72 iOS dims
   those three states by. The heading, the reason and the disabled actions still say why; this is
   the at-a-glance half. An unread card stays bright, because a read that has not come back is not
   an answer. Both classes, so no later single-class rule can undo it. */
.criteria-decision.is-stale {
  opacity: 0.72;
}
.criteria-decision .approval-head {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--warning-bg);
  border-bottom-color: var(--warning-border);
}
.criteria-decision-heading {
  min-width: 0;
}
/* The receipt a card answered in this window leaves in its place (`CriteriaDecisionReceipt`): the
   question's head, then one line saying what was recorded and where the proposing session was told. */
.criteria-decision-receipt {
  margin: 0;
  padding: 8px 14px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-1);
  background: var(--bg-raised);
}
.criteria-decision-verdict {
  color: var(--success);
  font-weight: 600;
}
/* The mark. Boxed and set apart from the heading it follows, because its whole job is to be
   distinguishable at a glance from anything an agent could have typed into the conversation. */
.criteria-provenance {
  flex: none;
  margin-left: auto;
  padding: 2px 7px;
  border: 1px solid var(--warning-border);
  border-radius: 4px;
  background: var(--bg-raised);
  color: var(--warning);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.criteria-decision .approval-body {
  background: var(--bg-raised);
  padding: 10px 14px 4px;
}
.criteria-decision-kv {
  display: flex;
  gap: 8px;
  font-size: 12.5px;
  color: var(--text-2);
  line-height: 1.7;
}
.criteria-decision-k {
  flex: none;
  width: 96px;
  color: var(--text-3);
}
.criteria-decision-v {
  flex: 1;
  min-width: 0;
}
.criteria-decision-proposed {
  margin: 8px 0 0;
  padding-left: 20px;
  font-size: 13px;
  line-height: 1.7;
}
.criteria-decision-method,
.criteria-decision-new {
  margin-left: 8px;
  font-size: 11.5px;
  color: var(--text-3);
}
.criteria-decision-new {
  color: var(--warning);
}
/* ── The diff ──────────────────────────────────────────────────────────────────────────────────
   One row per criterion the proposal MOVES, and a rewrite is ONE paragraph: the sentence as it
   would stand, with what it drops struck through in place. Laid out as two — the words proposed
   and then the words on record — three rewrites of long Chinese criteria came to 483px inside a
   360px scroll box, and the clause that actually moved was still something a reader had to find
   by comparing them. */
.criteria-decision-entry {
  margin-bottom: 6px;
}
.criteria-decision-entry .criteria-decision-method {
  display: block;
  margin-left: 0;
  margin-top: 2px;
}
/* The badge stays INLINE, on the tail of the words it is about. Given a line of its own it costs
   a row per change, and three of those are what push the fold back off the bottom of the 360px
   box this card is read in — which is the thing being fixed. */
.criteria-decision-entry .criteria-decision-new {
  margin-left: 6px;
  white-space: nowrap;
}
/* ── A rewrite, inline ─────────────────────────────────────────────────────────────────────────
   The words the proposal drops and the words it adds, marked IN PLACE inside the sentence they
   moved in, so one line carries both versions. Laid out one after the other they were two
   paragraphs of ninety-character Chinese per rewrite, and three of those overflowed the box.

   Colour is never the only carrier: the dropped run is struck through and the added one
   underlined, both of which survive a monochrome screen and colour-blind vision. `text-decoration`
   is restated because a UA gives `<ins>` its underline and `<del>` its line-through by default and
   an app stylesheet is not entitled to assume it. */
.criteria-decision-cut {
  text-decoration: line-through;
  text-decoration-color: var(--error);
  text-decoration-thickness: 1.5px;
  color: var(--text-3);
}
.criteria-decision-add {
  text-decoration: underline;
  text-decoration-color: var(--success);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 2px;
  color: var(--text-1);
  background: var(--success-bg);
}
/* The one place on the card that says what those two marks mean — riding on the summary's line,
   because a line of its own is a line this card does not have. */
.criteria-decision-legend {
  margin-left: 10px;
  font-size: 11.5px;
  color: var(--text-3);
}
/* The criteria this proposal leaves alone: a count, and their words behind a native disclosure.
   Folded rather than hidden, because "three reworded" and "the whole set replaced with three" are
   the same three rows until the reader is told how many did not move — which is also why the
   summary above the list counts them a second time, where nothing has to be scrolled to. */
.criteria-decision-unchanged {
  margin: 10px 0 0;
  font-size: 12.5px;
  color: var(--text-2);
}
.criteria-decision-unchanged > summary {
  cursor: pointer;
  color: var(--text-3);
}
.criteria-decision-proposed--quiet {
  font-size: 12.5px;
  color: var(--text-3);
}
.criteria-decision-hold,
.criteria-decision-gone {
  margin: 10px 0 0;
  font-size: 12.5px;
  color: var(--text-2);
  line-height: 1.65;
}
.criteria-decision .approval-stale {
  background: var(--bg-raised);
}
.criteria-decision-error {
  margin: 8px 14px 0;
}
.card-actions.criteria-decision-actions {
  background: var(--bg-raised);
  border-top-color: var(--warning-border);
}
/* The question a project's coordinator put to its owner (`CoordinatorQuestionCard`, mock 5). The
   same card chrome as the proposal above it, because they are the same kind of thing: something the
   platform is asking the person for. The mark is in the brand colour rather than the warning one —
   nothing is wrong, somebody is being asked. */
.criteria-provenance.prov-brand {
  border-color: var(--brand);
  color: var(--brand);
}
/* The heading and the mark share the head, with the mark pushed to the far end by its own
   `margin-left: auto` — so the two never read as one run of words. */
.coordinator-question-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.coordinator-question-heading {
  min-width: 0;
  font-weight: 600;
}
.coordinator-question .approval-body {
  background: var(--bg-raised);
  padding: 10px 14px 4px;
  /* This card is read and answered top to bottom. Keep its body in the page flow so a
     long question cannot turn the card itself into a nested scroll region. */
  max-height: none;
  overflow: visible;
}
.coordinator-question-text {
  margin: 2px 0 8px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-1);
}
/* An option is the answer, so it is the tap target: a whole row, 44pt-ish, and the chosen one is
   outlined rather than merely ticked. */
.coordinator-question-option {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  margin: 6px 0;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  font-size: 13.5px;
  cursor: pointer;
}
.coordinator-question-option.is-chosen {
  border-color: var(--brand);
  box-shadow: 0 0 0 2px var(--brand-tint);
}
.coordinator-question-option input {
  flex: none;
  margin-top: 3px;
  accent-color: var(--brand);
}
.coordinator-question-option-text {
  min-width: 0;
}
.coordinator-question-option-why {
  display: block;
  margin-top: 2px;
  font-size: 12.5px;
  color: var(--text-2);
}
.coordinator-question-recommended {
  margin-left: 6px;
  padding: 0 5px;
  border: 1px solid var(--success-border);
  border-radius: 4px;
  background: var(--success-bg);
  color: var(--success);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
.coordinator-question-free {
  margin: 6px 0;
}
/* What it holds up, and what happens if nobody answers. */
.coordinator-question-meta {
  margin: 8px 0 2px;
  font-size: 12.5px;
  color: var(--text-2);
}
.coordinator-question-error {
  margin: 8px 14px 0;
}
.card-actions.coordinator-question-actions {
  background: var(--bg-raised);
}
.coordinator-question-asked {
  margin-left: auto;
  font-size: 11.5px;
  color: var(--text-3);
}
/* The receipt left in the card's place once it is answered. */
.coordinator-question-receipt {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  margin: 0;
  padding: 10px 14px;
  font-size: 13px;
  line-height: 1.6;
  background: var(--bg-raised);
}
.coordinator-question-verdict {
  color: var(--success);
  font-weight: 600;
}
.coordinator-question-foot {
  color: var(--text-2);
  font-size: 12px;
}
/* The binding, said and never shown: the press carries the proposal's one-time key. */
.criteria-decision-bound {
  margin-left: auto;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
  color: var(--text-3);
}
/* On a phone the three buttons can't share one row: the long "auto-allow future …"
   label shrinks to a 5-6 line block and drags the others into tall boxes. Stack them
   full-width instead (the standard phone action-sheet layout). */
@media (max-width: 600px) {
  .card-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .card-action {
    width: 100%;
    padding: 10px 14px; /* ~40px comfortable tap target on touch */
  }
  /* No hardware Enter/⌘ key on touch — the hints are noise and force extra wrapping. */
  .approval-kbd {
    display: none;
  }
}

/* ---- Task detail panel (slide-in beside the task list) ---- */
.task-row.clickable {
  cursor: pointer;
}
/* Multi-select (checkbox) rows get a left accent bar — distinct from the focused row's
   tinted background, so "selected for a batch" reads differently from "open in the panel". */
.task-row.checked {
  box-shadow: inset 3px 0 0 var(--brand);
}
.task-row.selected {
  background: var(--brand-tint);
}
.task-row.selected:hover {
  background: var(--brand-border);
}

.task-detail-panel {
  position: relative;
  flex: none;
  width: clamp(460px, 52vw, 780px);
  height: var(--app-vh);
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--border-subtle);
  background: var(--bg-raised);
  box-shadow: -4px 0 16px rgba(31, 35, 41, 0.04);
  animation: tdp-slide-in 0.22s cubic-bezier(0.4, 0, 0.2, 1);
}
/* Drag handle on the panel's left edge — a 1px line (over the border) with a wider hit area. */
.tdp-resizer {
  position: absolute;
  left: 0;
  top: 0;
  width: 1px;
  height: 100%;
  cursor: col-resize;
  z-index: 2;
}
.tdp-resizer::before {
  content: '';
  position: absolute;
  inset: 0 -5px;
}
.tdp-resizer:hover,
.tdp-resizer.resizing {
  background: var(--brand);
}
@keyframes tdp-slide-in {
  from {
    transform: translateX(24px);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}
.tdp-head {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 18px 12px 14px 20px;
  border-bottom: 1px solid var(--border-subtle);
  flex: none;
}
.tdp-head-main {
  flex: 1;
  min-width: 0;
}
.tdp-head-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: none;
}
/* Phone: four presses beside the title do not fit. The title is the flex remainder (flex:1;
   min-width:0), so it was squeezed to one CJK character per line while the actions kept their
   width. Below 600px the actions take a row of their own — each growing into the space, and
   wrapping when a label is long — while the panel's own window buttons (🗑 ⋯ ✕) stay up beside the
   title, at 40px: the touch target the composer's buttons take at this width. */
@media (max-width: 600px) {
  .tdp-head {
    flex-wrap: wrap;
    row-gap: 12px;
  }
  .tdp-head > .ant-btn-icon-only {
    /* Ordered ahead of the actions, which come after them in the markup: with wrap, order is what
       decides which line each lands on, and these have to stay on the title's. */
    order: 1;
    width: 40px;
    height: 40px;
  }
  .tdp-head-actions {
    order: 2;
    flex: 1 1 100%;
    flex-wrap: wrap;
    gap: 8px;
  }
  .tdp-head-actions > * {
    flex: 1 1 0;
  }
  .tdp-head-actions > .ant-btn {
    height: 40px;
  }
  /* Run now sits in a span — the Tooltip needs it to still fire while the button is disabled —
     and the running-session case in a Link. Stretch what is inside those two as well. */
  .tdp-head-actions > a > .ant-btn,
  .tdp-head-actions > span > .ant-btn {
    flex: 1;
    height: 40px;
  }
}
.tdp-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-1);
  line-height: 1.4;
  word-break: break-word;
}
.tdp-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
  font-size: 12px;
  color: var(--text-2);
}
.tdp-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.tdp-meta-item.muted {
  color: var(--text-3);
}
.tdp-badge {
  font-size: 12px;
  line-height: 18px;
  padding: 0 8px;
  border-radius: 9px;
  border: 1px solid transparent;
}
.tdp-badge.tone-blue {
  background: var(--brand-tint);
  color: var(--brand);
  border-color: var(--brand-border);
}
.tdp-badge.tone-green {
  background: var(--success-bg);
  color: var(--success-solid);
  border-color: var(--success-border);
}
.tdp-badge.tone-muted {
  background: var(--bg-hover);
  color: var(--text-3);
  border-color: var(--bg-hover-strong);
}
.tdp-badge.tone-red {
  background: var(--error-bg);
  color: var(--error-solid);
  border-color: var(--error-border);
}
.tdp-badge.tone-amber {
  background: var(--warning-bg);
  color: var(--warning);
  border-color: var(--warning-border);
}
/* The project a task is filed under, above its title in the detail panel. */
.tdp-project-line {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 4px;
  font-size: 12.5px;
  color: var(--text-3);
  min-width: 0;
}
.tdp-project-line a {
  color: var(--text-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdp-project-line a:hover {
  color: var(--brand);
}
.tdp-project-line .tdp-badge {
  flex: none;
}
/* Under the project line when that project was cancelled: its tasks do not start. */
.tdp-project-note {
  margin: -2px 0 6px;
  font-size: 12.5px;
  color: var(--text-3);
}
/* How this row is judged, under its title. One pill either way: the judgment method on a row that
   has its own work, and the plain statement that a gate row has none. */
.tdp-judgment {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: fit-content;
  margin-top: 10px;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: 11px;
  background: var(--bg-hover);
  color: var(--text-2);
  font-size: 12px;
  line-height: 20px;
}
.tdp-judgment.is-judged .anticon {
  color: var(--success-solid);
}
.tdp-judgment.is-gate {
  background: var(--warning-bg);
  border-color: var(--warning-border);
  color: var(--warning);
}

/* The check that settles this row, directly under the row itself. */
.tdp-verifier {
  margin: 12px 20px 4px;
  padding: 10px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  background: var(--bg-subtle);
}
.tdp-verifier-head {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-3);
}
.tdp-verifier-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
}
.tdp-verifier-title {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  color: var(--text-1);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdp-verifier-empty {
  margin-top: 6px;
  font-size: 13px;
  color: var(--text-2);
}

.tdp-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.tdp-loading,
.tdp-empty {
  padding: 48px;
  text-align: center;
  color: var(--text-3);
  font-size: 13px;
}
.tdp-section {
  padding: 16px 20px;
  border-bottom: 1px solid var(--bg-hover);
}
.tdp-section:last-child {
  border-bottom: none;
}
.tdp-section-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-3);
  margin-bottom: 10px;
}
.tdp-input-hint {
  margin: -4px 0 10px;
  font-size: 12px;
}
.tdp-input-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
}
.tdp-input {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 8px;
  border: 1px solid var(--bg-hover);
  border-radius: 6px;
}
.tdp-input-thumb {
  width: 40px;
  height: 40px;
  flex: none;
  object-fit: cover;
  border-radius: 4px;
  background: var(--bg-hover);
}
.tdp-input-thumb-empty {
  /* Holds the row's height while the bytes are still being fetched, so a list of mocks does
     not reflow line by line as each thumbnail resolves. */
  display: block;
}
.tdp-input-icon {
  width: 40px;
  flex: none;
  font-size: 20px;
  color: var(--text-3);
  text-align: center;
}
.tdp-input-meta {
  flex: 1;
  min-width: 0;
  font-size: 13px;
}
.tdp-input-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdp-field {
  display: flex;
  gap: 10px;
  margin-bottom: 8px;
  font-size: 13px;
}
.tdp-field:last-child {
  margin-bottom: 0;
}
.tdp-field-label {
  width: 76px;
  flex: none;
  color: var(--text-3);
}
.tdp-field-value {
  flex: 1;
  min-width: 0;
  color: var(--text-1);
  word-break: break-word;
}
/* 「创建来源」会话链接，跳转到创建此任务的 session */
.tdp-field-link {
  color: var(--brand);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdp-field-link:hover {
  text-decoration: underline;
}
/* 内联可编辑的「负责 Agent」下拉，外观对齐其它文本字段 */
.tdp-assignee-select {
  flex: 1;
  min-width: 0;
  margin: -3px 0;
}
.tdp-assignee-select.ant-select .ant-select-content {
  padding: 0;
  font-size: 13px;
}
.tdp-assignee-select.ant-select .ant-select-content-has-value {
  color: var(--text-1);
}
.tdp-assignee-select.ant-select .ant-select-placeholder {
  color: var(--text-3);
}
.tdp-assignee-select.ant-select:hover .ant-select-content {
  background: var(--bg-hover);
  border-radius: 4px;
}
/* The Suggested tier (model routing §9): its picker with the coordinator's reason under it, and in
   the picker each tier's dot, its model and effort, and the work it is for. */
.tdp-field-stack {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.tdp-field-note {
  margin-top: 1px;
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--text-3);
}
.tdp-hint-value {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.tdp-hint-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}
.tdp-hint-dot.is-s {
  background: var(--success-solid);
}
.tdp-hint-dot.is-m {
  background: var(--brand);
}
.tdp-hint-dot.is-l {
  background: var(--warning-solid);
}
.tdp-hint-dot.is-xl {
  background: var(--error);
}
.tdp-hint-option {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  max-width: 340px;
  white-space: normal;
}
.tdp-hint-option .tdp-hint-dot {
  margin-top: 6px;
}
.tdp-hint-option-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.tdp-hint-option.is-none .tdp-hint-option-name {
  font-weight: 400;
  color: var(--text-3);
}
.tdp-hint-option-detail {
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--text-2);
}
/* 「Start at」editor: the label keeps the shared 76px gutter, everything the control needs —
   input, its two actions, and the line under them — stacks in the remaining column. */
.tdp-schedule {
  align-items: flex-start;
}
.tdp-schedule-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.tdp-schedule-actions {
  display: flex;
  gap: 8px;
}
.tdp-schedule-hint,
.tdp-schedule-error {
  font-size: 12px;
  line-height: 1.5;
}
.tdp-schedule-error {
  color: var(--error);
}

/* Wrapper around the description's Markdown render — no pre-wrap here, the `.md`
   child is real HTML. Description markdown inherits the 13px panel size rather
   than .md's 14px, same as .tdp-comment-text. */
.tdp-prose {
  color: var(--text-2);
  word-break: break-word;
}
.tdp-prose .md {
  font-size: 13px;
}
/* The acceptance block: a sub-label per field with its value under it, rather than the
   76px label gutter the one-line Details rows use — acceptance criteria is prose, and
   an acceptance command is a whole command line. */
.tdp-acceptance-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
}
.tdp-acceptance-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-3);
}
.tdp-acceptance-criteria-input,
.tdp-acceptance-command-input {
  font-size: 13px;
}
.tdp-acceptance-pair {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-2);
}
.tdp-acceptance-pair-label {
  color: var(--text-3);
}
.tdp-acceptance-command {
  /* A command is one long line and the panel is narrow: break it rather than let it
     scroll the section sideways. */
  word-break: break-all;
  background: var(--bg-hover);
  border-radius: 4px;
  padding: 1px 5px;
}
.tdp-acceptance-exit-input {
  width: 64px;
}
.tdp-acceptance-empty,
.tdp-acceptance-hint,
.tdp-acceptance-error {
  display: block;
  font-size: 12px;
  line-height: 1.5;
  margin-top: 4px;
}
.tdp-acceptance-error {
  color: var(--error);
}
.tdp-acceptance-actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
.tdp-muted {
  color: var(--text-3);
  font-size: 13px;
}

.tdp-dependency-row {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 2px 0;
}
.tdp-dependency-trigger {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-1);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.tdp-dependency-trigger:hover {
  background: var(--bg-hover);
  color: var(--brand);
}
.tdp-dependency-trigger:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
.tdp-dependency-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Multi-level task dependencies. The inline canvas is deliberately a viewer: relationship
   edits stay in the explicit controls below it, while direct edges expose a guarded remove
   action on their source node. */
.tdp-dependency-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.tdp-dependency-head .tdp-section-title {
  margin-bottom: 0;
}
.tdp-dependency-summary {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-3);
  font-size: 11.5px;
}
.tdp-dependency-view.ant-segmented {
  flex: none;
  font-size: 12px;
}
.tdp-dependency-notice {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  margin-bottom: 10px;
  border: 1px solid var(--brand-border);
  border-radius: 6px;
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-size: 12px;
}
.tdp-dependency-notice.is-failed {
  border-color: var(--error-border);
  background: var(--error-bg);
  color: var(--error);
}
.tdp-dependency-graph-loading,
.tdp-dependency-graph-error {
  display: flex;
  min-height: 120px;
  align-items: center;
  justify-content: center;
  color: var(--text-3);
  font-size: 12px;
}
.tdp-dependency-graph-error {
  min-height: auto;
  padding: 8px 10px;
  border: 1px solid var(--warning-border);
  border-radius: 6px;
  background: var(--warning-bg);
  color: var(--warning);
}
.tdp-dependency-truncated {
  margin-top: 7px;
  color: var(--warning);
  font-size: 11.5px;
}

.tdg-canvas,
.tdg-full-canvas {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--bg-sunken);
}
.tdg-canvas {
  height: clamp(300px, 46vh, 420px);
}
.tdg-full-canvas {
  /* Use the same small viewport unit as the app shell. On iOS, 100vh includes the browser chrome
     and makes the bottom of the graph look available even though Safari is sitting over it. */
  height: calc(var(--app-vh) - 150px);
  min-height: 420px;
}
.tdg-canvas .react-flow,
.tdg-full-canvas .react-flow {
  background: transparent;
}
.tdg-canvas.is-vertical .react-flow__pane {
  touch-action: pan-y;
}
.tdg-canvas .react-flow__controls,
.tdg-full-canvas .react-flow__controls {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 7px;
  box-shadow: 0 2px 8px rgba(31, 35, 41, 0.08);
}
.tdg-canvas .react-flow__controls-button,
.tdg-full-canvas .react-flow__controls-button {
  width: 28px;
  height: 28px;
  border-color: var(--border-subtle);
  background: var(--bg-raised);
  color: var(--text-2);
  fill: currentColor;
}
.tdg-canvas .react-flow__controls-button:hover,
.tdg-full-canvas .react-flow__controls-button:hover {
  background: var(--bg-hover);
  color: var(--brand);
}
.tdg-maximize {
  position: absolute;
  z-index: 5;
  top: 8px;
  right: 8px;
  display: inline-flex;
  width: 30px;
  height: 30px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg-raised);
  color: var(--text-2);
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(31, 35, 41, 0.06);
}
.tdg-maximize:hover,
.tdg-maximize:focus-visible {
  border-color: var(--brand-border);
  color: var(--brand);
}
.tdg-maximize:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
.tdg-direction {
  position: absolute;
  z-index: 4;
  right: 8px;
  bottom: 8px;
  padding: 3px 7px;
  border: 1px solid var(--border-subtle);
  border-radius: 5px;
  background: color-mix(in srgb, var(--bg-raised) 92%, transparent);
  color: var(--text-3);
  font-size: 10.5px;
  pointer-events: none;
}
.tdg-visible-count {
  padding: 3px 7px;
  border: 1px solid var(--border-subtle);
  border-radius: 5px;
  background: color-mix(in srgb, var(--bg-raised) 94%, transparent);
  color: var(--text-3);
  font-size: 10.5px;
  box-shadow: 0 1px 4px rgba(31, 35, 41, 0.05);
}
.tdg-pan-hint {
  padding: 4px 9px;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: color-mix(in srgb, var(--bg-raised) 94%, transparent);
  color: var(--text-3);
  font-size: 10.5px;
  pointer-events: none;
  box-shadow: 0 1px 4px rgba(31, 35, 41, 0.05);
}
.tdg-node {
  position: relative;
  width: 204px;
  height: 76px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg-raised);
  box-shadow: 0 2px 7px rgba(31, 35, 41, 0.08);
  transition: border-color 0.12s, box-shadow 0.12s;
}
.tdg-node:hover,
.tdg-node:focus-within {
  border-color: var(--brand-border);
  box-shadow: 0 3px 10px rgba(31, 35, 41, 0.12);
}
.tdg-node.is-focus {
  border: 2px solid var(--brand);
  box-shadow: 0 0 0 2px var(--brand-tint), 0 3px 10px rgba(31, 35, 41, 0.1);
}
.tdg-node.state-failed:not(.is-focus) {
  border-color: var(--error-border);
}
.tdg-node-main {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 7px;
  padding: 9px 32px 9px 11px;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: var(--text-1);
  text-align: left;
  cursor: pointer;
}
.tdg-node-main:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
.tdg-node-title-row {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: 6px;
}
.tdg-node-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  color: var(--text-1);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdg-current-tag {
  flex: none;
  padding: 1px 5px;
  border-radius: 5px;
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-size: 9.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.tdg-node .status-pill {
  height: 20px;
  padding: 0 7px 0 6px;
  font-size: 10.5px;
}
.tdg-node .status-pill .status-dot {
  width: 7px;
  height: 7px;
}
.tdg-node-remove {
  position: absolute;
  z-index: 2;
  top: 7px;
  right: 7px;
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--text-4);
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.12s, color 0.12s, background 0.12s;
}
.tdg-node:hover .tdg-node-remove,
.tdg-node:focus-within .tdg-node-remove {
  opacity: 1;
}
@media (hover: none) {
  .tdg-node-remove {
    opacity: 1;
  }
}
.tdg-node-remove:hover,
.tdg-node-remove:focus-visible {
  background: var(--error-bg);
  color: var(--error);
}
.tdg-node-remove:disabled {
  cursor: wait;
  opacity: 0.5;
}
.tdg-node .react-flow__handle {
  width: 7px;
  height: 7px;
  border: 1px solid var(--bg-raised);
  background: var(--text-4);
  pointer-events: none;
}
.tdg-aggregate-node {
  position: relative;
  width: 204px;
  height: 76px;
  border: 1px dashed var(--brand-border);
  border-radius: 9px;
  background: color-mix(in srgb, var(--brand-tint) 38%, var(--bg-raised));
  box-shadow: 0 2px 7px rgba(31, 35, 41, 0.04);
}
.tdg-aggregate-main {
  display: flex;
  width: 100%;
  height: 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: var(--brand-strong);
  cursor: pointer;
}
.tdg-aggregate-main:hover,
.tdg-aggregate-main:focus-visible {
  background: color-mix(in srgb, var(--brand-tint) 65%, transparent);
}
.tdg-aggregate-main:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
.tdg-aggregate-main:disabled {
  cursor: wait;
  opacity: 0.65;
}
.tdg-aggregate-count {
  font-size: 13px;
  font-weight: 650;
}
.tdg-aggregate-action {
  color: var(--text-3);
  font-size: 10.5px;
}
.tdg-aggregate-node .react-flow__handle {
  width: 7px;
  height: 7px;
  border: 1px solid var(--bg-raised);
  background: var(--brand-border);
  pointer-events: none;
}

/* A fold: one mark standing for a run of tasks, or for one stage of a motif the project repeats.
   Dashed and tinted like `.tdg-aggregate-node`, which is the task graph's collapsed branch — the
   vocabulary is deliberately shared, so "dashed means there is more behind this" is learned once. */
.pdg-fold {
  position: relative;
  width: 196px;
  height: 80px;
  border: 1px dashed var(--brand-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--brand-tint) 30%, var(--bg-raised));
}
/* Finished work, folded by this side rather than the server's. Green rather than the fold's usual
   brand tint, and quiet: it is the one fold whose contents nobody is waiting on. */
.pdg-fold.is-settled {
  border-color: var(--success-border);
  background: color-mix(in srgb, var(--success-bg) 40%, var(--bg-raised));
}
.pdg-fold.is-settled .pdg-fold-title {
  color: var(--text-2);
}
.pdg-fold.state-failed {
  border-color: var(--error-border);
  background: color-mix(in srgb, var(--error-bg) 45%, var(--bg-raised));
}
.pdg-fold.is-open {
  border-style: solid;
}
.pdg-fold-main {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  gap: 7px;
  padding: 10px 12px;
  border: 0;
  border-radius: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.pdg-fold-main:disabled {
  cursor: default;
}
.pdg-fold-main:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
.pdg-fold-title-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
}
.pdg-fold-title {
  overflow: hidden;
  flex: 1;
  min-width: 0;
  color: var(--text-1);
  font-size: 12.5px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pdg-fold-count {
  flex: none;
  padding: 1px 6px;
  border-radius: 5px;
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-size: 11px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}
.pdg-fold-bar {
  display: flex;
  overflow: hidden;
  height: 6px;
  border-radius: 3px;
  background: var(--bg-sunken);
}
.pdg-fold-seg.is-done {
  background: var(--success);
}
.pdg-fold-seg.is-active {
  background: var(--brand);
}
/* A floor, not a fair share: 24 failures in 6,118 tasks is 0.4% of the bar, and the whole reason
   to look at a folded batch is to see that they are there. */
.pdg-fold-seg.is-failed {
  min-width: 5px;
  background: var(--error-solid);
}
.pdg-fold-seg.is-cancelled {
  background: var(--text-4);
  opacity: 0.6;
}
.pdg-fold-seg.is-open {
  background: var(--text-4);
  opacity: 0.3;
}
.pdg-fold-legend {
  overflow: hidden;
  color: var(--text-3);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pdg-fold-legend .is-failed {
  color: var(--error-solid);
  font-weight: 650;
}
.pdg-fold .react-flow__handle {
  width: 7px;
  height: 7px;
  border: 1px solid var(--bg-raised);
  background: var(--brand-border);
  pointer-events: none;
}
.pdg-fold-samples {
  display: flex;
  min-width: 220px;
  max-width: 380px;
  flex-direction: column;
  gap: 6px;
}
.pdg-fold-samples-head {
  color: var(--text-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}
.pdg-fold-sample {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 4px 6px;
  border-radius: 6px;
  color: var(--text-1);
}
.pdg-fold-sample:hover {
  background: var(--bg-sunken);
}
.pdg-fold-sample-title {
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A parent task folded into the frame its subtasks sit in — see ProjectDependencyGraph.tsx for
   why parent/child is a box here and never an edge. */
.pdg-group {
  width: 100%;
  height: 100%;
  border: 1px dashed var(--border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--bg-raised) 55%, transparent);
}
.pdg-group.state-failed {
  border-color: var(--error-border);
}
.pdg-group-header {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  padding: 8px 14px 0;
  color: var(--text-1);
}
.pdg-group-title {
  overflow: hidden;
  flex: 1;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pdg-group-header:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}
.pdg-group .react-flow__handle {
  width: 7px;
  height: 7px;
  border: 1px solid var(--bg-raised);
  background: var(--text-4);
  pointer-events: none;
}
/* One task on the project graph.
   Deliberately not `.tdg-node` — see TaskNode in ProjectDependencyGraph.tsx for why a canvas that
   draws a whole plan cannot afford the chrome a canvas that draws a handful of nodes can. */
.pdg-task {
  position: relative;
  display: flex;
  overflow: hidden;
  width: 168px;
  height: 64px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-raised);
  transition: border-color 0.12s, box-shadow 0.12s;
}
/* The status rail. A second channel that is not hue — under deuteranopia the ready/done pair is
   near the discrimination floor, and the meta line's word is the third. */
.pdg-task::before {
  content: '';
  flex: none;
  width: 3px;
  background: var(--dot-idle);
}
.pdg-task-main {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding: 7px 9px;
  border: 0;
  background: transparent;
  color: var(--text-1);
  text-align: left;
  cursor: pointer;
}
.pdg-task-main:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: -2px;
}
.pdg-task-title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  /* Task titles here carry identifiers — `dispatch_authorization`, branch names — and a word
     longer than the card is the whole line if it is not allowed to break. */
  overflow-wrap: anywhere;
  color: var(--text-1);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.32;
}
.pdg-task-meta {
  color: var(--text-3);
  font-size: 10px;
  line-height: 1;
}
.pdg-task:hover,
.pdg-task:focus-within {
  border-color: var(--brand-border);
}
/* Settled work is background: it is the answer to "how far has this got", which the shape of the
   plan already gives, and it is never the answer to "what should I do". */
.pdg-task.is-complete {
  border-color: var(--border-subtle);
  background: var(--bg-subtle);
}
.pdg-task.is-complete::before {
  background: var(--success-border);
}
.pdg-task.is-complete .pdg-task-title {
  color: var(--text-3);
  font-weight: 500;
}
/* The one thing on this canvas worth acting on today. */
.pdg-task.is-ready {
  border-color: var(--brand-border);
  box-shadow: 0 0 0 3px var(--brand-tint);
}
.pdg-task.is-ready::before {
  background: var(--brand);
}
.pdg-task.is-ready .pdg-task-meta {
  color: var(--brand-strong);
  font-weight: 600;
}
.pdg-task.is-active::before {
  background: var(--brand);
}
.pdg-task.is-active .pdg-task-meta {
  color: var(--brand-strong);
  font-weight: 600;
}
.pdg-task.is-queued::before {
  background: var(--brand-border);
}
.pdg-task.is-failed {
  border-color: var(--error-border);
}
.pdg-task.is-failed::before {
  background: var(--error-solid);
}
.pdg-task.is-failed .pdg-task-meta {
  color: var(--error);
  font-weight: 600;
}
.pdg-task .react-flow__handle {
  width: 6px;
  height: 6px;
  border: 1px solid var(--bg-raised);
  background: var(--text-4);
  pointer-events: none;
}

/* The section heading and its one-time-learn legend, at a size a reader can actually read — it
   used to be 10.5px pinned into the corner of the canvas forever. */
.pdg-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 10px;
}
.pdg-section-title.ant-typography {
  flex: none;
  white-space: nowrap;
}
.pdg-legend {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  color: var(--text-3);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Everything not on a path through the mark under the pointer. */
.pdg-canvas .react-flow__node.is-faded,
.tdg-full-canvas .react-flow__node.is-faded {
  opacity: 0.34;
  transition: opacity 0.12s;
}

.tdg-error {
  display: flex;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 24px;
  color: var(--error);
  font-size: 12px;
  text-align: center;
}
.ant-modal.tdg-modal {
  max-width: none;
  top: 24px;
  padding-bottom: 0;
}
.tdg-modal .ant-modal-body {
  padding-top: 4px;
}
.tdg-modal .react-flow__minimap {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
}

/* A portrait phone is the graph's opposite aspect ratio. Give the modal back the 96px that used
   to disappear into two outer and two inner 24px gutters, then let its top-to-bottom layout use
   the long axis. The container is the viewport; only a compact safe-area inset remains around the
   canvas. This applies to both project and single-task dependency graphs. */
@media (max-width: 640px) {
  .ant-modal.tdg-modal {
    top: 0;
    width: 100% !important;
    height: var(--app-vh);
    max-width: none;
    margin: 0;
  }
  .tdg-modal .ant-modal-container {
    display: flex;
    height: 100%;
    min-height: 0;
    flex-direction: column;
    padding:
      max(12px, env(safe-area-inset-top, 0px))
      max(12px, env(safe-area-inset-right, 0px))
      max(12px, env(safe-area-inset-bottom, 0px))
      max(12px, env(safe-area-inset-left, 0px));
    border-radius: 0;
  }
  .tdg-modal .ant-modal-header {
    flex: none;
    margin-bottom: 10px;
  }
  .tdg-modal .ant-modal-title {
    padding-inline-end: 40px;
  }
  .tdg-modal .ant-modal-close {
    top: max(12px, env(safe-area-inset-top, 0px));
    inset-inline-end: max(12px, env(safe-area-inset-right, 0px));
  }
  .tdg-modal .ant-modal-body {
    display: flex;
    flex: 1;
    min-height: 0;
    padding-top: 0;
  }
  .tdg-full-canvas {
    flex: 1;
    width: 100%;
    height: auto;
    min-height: 0;
  }
  .tdg-modal .react-flow__minimap {
    width: 120px;
    height: 90px;
  }
}

.tdg-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.tdg-list-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 4px;
  border-radius: 7px;
}
.tdg-list-row:hover {
  background: var(--bg-hover);
}
.tdg-list-row.is-focus {
  background: var(--brand-tint);
  box-shadow: inset 2px 0 0 var(--brand);
}
.tdg-list-open {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: 9px;
  padding: 6px 7px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-1);
  text-align: left;
  cursor: pointer;
}
.tdg-list-open:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
.tdg-list-open .status-pill {
  flex: none;
}
.tdg-list-copy {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}
.tdg-list-title-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
}
.tdg-list-title,
.tdg-list-relation {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdg-list-title {
  flex: 1;
  min-width: 0;
  font-size: 12.5px;
}
.tdg-list-relation {
  color: var(--text-3);
  font-size: 10.5px;
}
.tdg-list-remove {
  display: inline-flex;
  width: 28px;
  height: 28px;
  flex: none;
  align-items: center;
  justify-content: center;
  margin-right: 4px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--text-4);
  cursor: pointer;
}
.tdg-list-remove:hover,
.tdg-list-remove:focus-visible {
  background: var(--error-bg);
  color: var(--error);
}

@media (prefers-reduced-motion: reduce) {
  .pdg-task,
  .pdg-canvas .react-flow__node.is-faded,
  .tdg-full-canvas .react-flow__node.is-faded,
  .tdg-node,
  .tdg-node-remove {
    transition: none;
  }
  .tdg-canvas .react-flow__edge.animated path,
  .tdg-full-canvas .react-flow__edge.animated path {
    animation: none;
  }
}

.tdp-session {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  color: var(--text-1);
  font-size: 13px;
}
.tdp-session:hover {
  background: var(--bg-hover);
}
.tdp-session.is-failed {
  background: var(--error-bg);
}
.tdp-session.is-failed:hover {
  background: var(--error-bg);
}
.tdp-session-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.tdp-session-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdp-session-sub {
  font-size: 11px;
  color: var(--text-3);
  margin-top: 1px;
}
/* A run's routing (model routing §9): the tier smart selection put it on — amber when a failed run
   moved it up — or, where the Agent has not turned it on, the purple line saying what it would
   have picked. Either opens the Why under the row. */
.tdp-route-tag {
  display: inline-flex;
  align-items: center;
  margin-left: 6px;
  padding: 0 5px;
  border: 0;
  border-radius: 4px;
  background: var(--brand-tint);
  color: var(--brand-strong);
  font: inherit;
  font-size: 10.5px;
  font-weight: 650;
  line-height: 16px;
  vertical-align: 1px;
  cursor: pointer;
}
.tdp-route-tag.is-up {
  background: var(--warning-bg);
  color: var(--warning);
}
.tdp-route-would {
  align-self: flex-start;
  margin-top: 2px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--route-shadow);
  font: inherit;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
}
.tdp-route-would:hover {
  text-decoration: underline;
}
.tdp-route-why {
  margin: 6px 0 2px 26px;
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 9px;
  background: var(--brand-tint);
}
.tdp-route-why-title {
  margin-bottom: 5px;
  font-size: 12.5px;
  font-weight: 650;
  color: var(--text-1);
}
.tdp-route-why ul {
  margin: 0;
  padding-left: 16px;
  font-size: 12px;
  line-height: 1.65;
  color: var(--text-2);
}
.tdp-route-why-foot {
  margin-top: 5px;
  font-size: 11px;
  color: var(--text-3);
}
.tdp-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--scrollbar-hover);
  flex: none;
}
.tdp-dot.RUNNING {
  background: var(--brand);
}
.tdp-dot.COMPLETED,
.tdp-dot.SUCCEEDED {
  background: var(--success-solid);
}
.tdp-dot.FAILED {
  background: var(--error);
}
.tdp-dot.AWAITING_INPUT {
  background: var(--warning-solid);
}

.tdp-comment {
  display: flex;
  gap: 10px;
  margin-bottom: 14px;
}
.tdp-comment:last-child {
  margin-bottom: 0;
}
.tdp-comment-body {
  flex: 1;
  min-width: 0;
}
.tdp-comment-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 3px;
}
.tdp-comment-author {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.tdp-comment-time {
  font-size: 11px;
  color: var(--text-3);
}
.tdp-comment-text {
  font-size: 13px;
  color: var(--text-2);
  line-height: 1.6;
  word-break: break-word;
}
/* §13.8: what happened to this comment's @-mentions. Quiet by default — a mention on its way is
   not news — and only the two states that need somebody take a colour. */
.tdp-mention-deliveries {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
}
.tdp-mention-delivery {
  font-size: 11px;
  color: var(--text-3);
}
.tdp-mention-delivery-blocked {
  color: var(--warning, #d48806);
}
.tdp-mention-delivery-dead {
  color: var(--danger, #cf1322);
}
.tdp-mention-delivery-untracked {
  font-style: italic;
}
.tdp-mention-delivery a {
  color: inherit;
  text-decoration: underline dotted;
}
/* Comment markdown inherits the 13px bubble size rather than .md's 14px. */
.tdp-comment-text.md {
  font-size: 13px;
}

.tdp-compose {
  flex: none;
  display: flex;
  gap: 8px;
  align-items: flex-end;
  padding: 12px 16px;
  border-top: 1px solid var(--border-subtle);
}
.tdp-compose .ant-input {
  flex: 1;
}

/* Task comment @-mentions: highlighted chip in rendered comments + composer menu. */
.tdp-mention {
  color: var(--brand);
  background: var(--brand-tint);
  border-radius: 4px;
  padding: 0 2px;
  font-weight: 600;
}
.tdp-compose {
  position: relative;
}
.tdp-mention-menu {
  position: absolute;
  left: 16px;
  right: 16px;
  bottom: calc(100% - 6px);
  max-height: 220px;
  overflow-y: auto;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
  padding: 4px;
  z-index: 20;
}
.tdp-mention-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
}
.tdp-mention-item.active,
.tdp-mention-item:hover {
  background: var(--bg-hover);
}
.tdp-mention-name {
  font-size: 13px;
  color: var(--text-1);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tdp-mention-norunner {
  font-size: 11px;
  color: var(--text-4);
  flex: none;
}

/* ============================================================================
   NARROW VIEWPORTS (phones / split panes)
   The desktop layout is a row of fixed-width columns — nav · session list ·
   conversation (and, on the task list, a detail panel). Below ~960px that stops
   fitting (nav 340 + list 264 leaves a usable conversation no room), so the nav
   collapses into an off-canvas drawer and each master/detail pair stacks to one
   full-width screen at a time. Keep the query in sync with MOBILE_QUERY in
   lib/useMediaQuery.ts.
   ========================================================================== */
@media (max-width: 960px) {
  /* The off-canvas drawer lives at the viewport's left edge; without this any
     stray sideways overflow would still surface a horizontal scrollbar. */
  body {
    overflow-x: hidden;
  }

  /* Let the browser own vertical scrolling but hand horizontal gestures to our
     swipe-to-reveal handler, so the two don't fight. */
  .session-row {
    touch-action: pan-y;
  }

  /* Fixed top bar carrying the drawer toggle. */
  .app-topbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 48px;
    z-index: 40;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 8px;
    background: var(--bg-raised);
    border-bottom: 1px solid var(--border-subtle);
  }
  .app-nav-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-1);
    font-size: 18px;
    cursor: pointer;
  }
  .app-nav-toggle:hover {
    background: var(--bg-hover);
  }
  .app-topbar-name {
    font-size: 16px;
    font-weight: 600;
    color: var(--text-1);
  }

  /* Nav → off-canvas drawer. position:fixed drops it out of flow, so the content
     region fills the full width and the page stops overflowing sideways. */
  .app-nav {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    z-index: 60;
    width: min(320px, 84vw) !important;
    height: var(--app-vh);
    transform: translateX(-100%);
    transition: transform 0.25s ease;
  }
  .app-nav.open {
    transform: translateX(0);
    /* A closed drawer sits exactly one drawer-width off-screen, so a persistent
       shadow would still spill into the viewport as a grey strip. */
    box-shadow: 2px 0 16px rgba(0, 0, 0, 0.18);
  }
  .tp-resizer {
    display: none;
  }
  .app-nav-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 55;
    background: rgba(0, 0, 0, 0.4);
  }

  /* Content clears the fixed top bar. */
  .app-main {
    padding-top: 48px;
  }
  .app-view--doc {
    padding: 16px;
  }

  /* Agent console: stack the two panes, showing one at a time, each full width. */
  .workspace-split {
    --pane-gutter: 14px;
  }
  .session-col {
    width: 100% !important;
    padding-top: 12px;
  }
  .workspace-view {
    padding-top: 12px;
  }
  .session-resizer {
    display: none;
  }
  .workspace-split.show-conversation .session-col {
    display: none;
  }
  .workspace-split:not(.show-conversation) .workspace-view {
    display: none;
  }
  /* When a conversation is open, its in-pane header (← · title · ⋯) already carries the
     back nav, identity, live state, and actions — so the global "Orbit" bar stacked above
     it is pure redundancy. Drop it and reclaim its 48px band (the ← returns to the session
     list, where the ☰ menu still lives, so global nav stays one tap away). */
  .app-shell:has(.workspace-split.show-conversation) .app-topbar {
    display: none;
  }
  .app-shell:has(.workspace-split.show-conversation) .app-main {
    padding-top: 0;
  }
  /* As the sole top bar the header sits a touch tighter than the roomy desktop version. */
  .workspace-split.show-conversation .workspace-header {
    padding-bottom: 10px;
  }
  /* In-pane back button: leaves the open conversation for the session list. */
  .workspace-back-mobile {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    flex: none;
    margin-right: 4px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-2);
    font-size: 16px;
    cursor: pointer;
  }
  .workspace-back-mobile:hover {
    background: var(--bg-hover);
    color: var(--text-1);
  }

  /* Session list <-> conversation: push and pop, instead of the bare display flip above.
     There is nothing in the DOM to tween between those two states, so what animates is the
     pair of full-viewport snapshots the View Transition API takes; lib/paneTransition.ts
     starts it and puts the direction on <html> for the duration. Snapshots are also why the
     vanishing top bar behaves: the outgoing image still carries its 48px band and the
     incoming one never had it, so each screen travels as the thing the reader was looking at.
     Reduced motion never gets here — paneTransition.ts declines to start a transition, which
     leaves the instant swap. */
  @keyframes pane-enter-from-right {
    from {
      transform: translateX(100%);
    }
  }
  @keyframes pane-exit-to-left {
    to {
      transform: translateX(-25%);
      filter: brightness(0.82);
    }
  }
  @keyframes pane-enter-from-left {
    from {
      transform: translateX(-25%);
      filter: brightness(0.82);
    }
  }
  @keyframes pane-exit-to-right {
    to {
      transform: translateX(100%);
    }
  }
  /* The UA cross-fades the two snapshots and blends them additively; these are opaque screens
     sliding over one another, so both of those defaults have to go. */
  html[data-pane-nav]::view-transition-old(root),
  html[data-pane-nav]::view-transition-new(root) {
    animation-duration: 260ms;
    animation-timing-function: cubic-bezier(0.32, 0.72, 0, 1);
    animation-fill-mode: both;
    mix-blend-mode: normal;
  }
  html[data-pane-nav='push']::view-transition-old(root) {
    animation-name: pane-exit-to-left;
  }
  html[data-pane-nav='push']::view-transition-new(root) {
    animation-name: pane-enter-from-right;
    box-shadow: -10px 0 28px rgba(0, 0, 0, 0.12);
  }
  /* Going back, the conversation is the screen that moves, so it has to stay on top — the list
     underneath merely eases out of the parallax offset it was pushed to. */
  html[data-pane-nav='pop']::view-transition-old(root) {
    z-index: 2;
    animation-name: pane-exit-to-right;
    box-shadow: -10px 0 28px rgba(0, 0, 0, 0.12);
  }
  html[data-pane-nav='pop']::view-transition-new(root) {
    z-index: 1;
    animation-name: pane-enter-from-left;
  }

  /* Task detail: full-screen overlay instead of a side column. */
  .task-detail-panel {
    position: fixed;
    inset: 0;
    width: 100% !important;
    height: var(--app-vh);
    z-index: 60;
    border-left: none;
  }
  /* No drag-to-resize on a full-screen panel. */
  .tdp-resizer {
    display: none;
  }

  /* iOS Safari force-zooms the whole page when a focused input has font-size < 16px
     (and never zooms back out). Lift every focusable input to 16px on mobile so the
     keyboard opens without the jarring zoom; desktop keeps the compact 13–14px sizes.
     Not touching the viewport meta — pinch-to-zoom stays enabled for accessibility. */
  .ant-input,
  .ant-input-affix-wrapper input,
  textarea.ant-input,
  .skills-search,
  .share-dialog-url-input {
    font-size: 16px;
  }
  /* AntD Select focuses this hidden search input on tap — a <16px font here is what
     still zooms the page when the composer's Mode / Model / Effort dropdowns open.
     AntD sizes it from the Select's own font token through a rule that outranks a plain
     selector, so !important is required to actually lift it. The input is invisible on a
     non-search Select, so this only affects the zoom trigger, not layout. */
  .ant-select-input {
    font-size: 16px !important;
  }
}

/* ── Worktree diff drawer: resizable width, folder-grouped list, file nav, split view ──────── */
.wt-diff-body {
  position: relative;
}
/* A thin grab strip on the drawer's left edge to drag its width (see startResize). */
.wt-diff-resizer {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 6px;
  cursor: col-resize;
  z-index: 5;
}
.wt-diff-resizer:hover,
.wt-diff-resizer.resizing {
  background: var(--brand);
  opacity: 0.3;
}
/* Re-assert the diff body as the scroll container (it shares .chat-diff, which sets
   overflow:hidden, defined later in the file) so the sticky hunk headers below have a scroller. */
.wt-diff-view {
  overflow: auto;
}
.wt-diff-view .diff-gap {
  position: sticky;
  top: 0;
  z-index: 1;
}
/* Folder-grouped file list */
.wt-diff-files {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.wt-tree-dir {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.wt-diff-group-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  border: 0;
  background: transparent;
  border-radius: 5px;
  padding: 3px 6px;
  margin: 0 -6px;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11.5px;
  color: var(--text-3);
}
.wt-diff-group-head:hover {
  background: var(--bg-hover);
}
.wt-diff-group-caret {
  flex: none;
  width: 10px;
  color: var(--text-4);
}
.wt-diff-group-dir {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wt-diff-group-meta {
  flex: none;
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
}
.wt-diff-group-meta .add {
  color: var(--success-solid);
}
.wt-diff-group-meta .del {
  color: var(--error-solid);
}
.wt-diff-group-n {
  color: var(--text-4);
}
/* Pane head: prev/next file nav + Unified/Split toggle */
.wt-diff-nav {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}
.wt-diff-nav button {
  border: 0;
  background: transparent;
  cursor: pointer;
  color: var(--text-3);
  width: 22px;
  height: 22px;
  border-radius: 5px;
  font-size: 15px;
  line-height: 1;
}
.wt-diff-nav button:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-1);
}
.wt-diff-nav button:disabled {
  opacity: 0.3;
  cursor: default;
}
.wt-diff-nav-pos {
  min-width: 40px;
  text-align: center;
  font-size: 11px;
  color: var(--text-4);
  font-variant-numeric: tabular-nums;
}
/* "Show N more lines" expander under a capped diff */
.wt-diff-more {
  display: block;
  width: 100%;
  border: 0;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-subtle);
  color: var(--text-2);
  padding: 8px;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
}
.wt-diff-more:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}
/* Split (side-by-side) diff: two columns sharing the existing .diff-add/.diff-del coloring */
.wt-diff-split .diff-split-row {
  display: flex;
  align-items: stretch;
}
.wt-diff-split .diff-split-cell {
  flex: 1 1 50%;
  min-width: 0;
  display: flex;
  align-items: flex-start;
  white-space: pre-wrap;
  word-break: break-word;
}
.wt-diff-split .diff-split-cell:first-child {
  border-right: 1px solid var(--border-subtle);
}
.wt-diff-split .diff-split-empty {
  background: var(--bg-subtle);
}
.wt-diff-split .diff-split-cell .diff-text {
  padding: 0 8px;
}
/* The drawer shows real file line numbers, which reach 4-5 digits in large files. The base
   .diff-ln gutter is a fixed 34px and inherits white-space: pre-wrap, so a wide number wrapped
   onto a second line — splitting it (e.g. "1649" → "164"/"9") and inflating that row's height.
   Fit up to 5 digits (1ch = the monospace digit width; border-box includes the 12px padding),
   never wrap, and use min-width so every row's gutter stays uniform (code columns line up) while
   still growing for 6+ digit files. Scoped to the drawer; the transcript gutter is unchanged. */
.wt-diff-view .diff-ln {
  width: auto;
  min-width: calc(5ch + 12px);
  white-space: nowrap;
}
.wt-diff-split .diff-split-hunk {
  display: flex;
}
/* With syntax highlighting on, the add/del background + sign carry the change; the line text
   itself stays normal code color so the hljs token colors read cleanly (GitHub-style) rather than
   being flattened to green/red. Scoped to the drawer so transcript inline diffs keep their tint. */
.wt-diff-view .diff-add .diff-text,
.wt-diff-view .diff-del .diff-text {
  color: var(--text-1);
}
/* Maximize / Restore toggle in the drawer header (sits in AntD's `extra` slot, left of ✕). */
.wt-diff-max-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid var(--border-subtle);
  background: transparent;
  color: var(--text-2);
  border-radius: 6px;
  padding: 3px 10px;
  font-size: 12px;
  cursor: pointer;
}
.wt-diff-max-btn:hover {
  background: var(--bg-hover);
  color: var(--text-1);
}

/* ── Public read-only pages (/s/<token>, PublicShell) ───────────────────────────
   Standalone (no app shell): a branded header bar — the breadcrumb that is the link's scope,
   then the page's status, the Live mark, Read-only and the page's actions — a centered
   scrolling body reusing the global .chat-* bubble styles, and a small footer. */
.share-page {
  display: flex;
  flex-direction: column;
  height: var(--app-vh);
  background: var(--bg-base);
  color: var(--text-1);
}
.share-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 20px;
  border-bottom: 1px solid var(--border);
  flex: none;
}
.share-brand {
  font-weight: 700;
  font-size: 16px;
  letter-spacing: 0.2px;
  color: var(--text-1);
  flex: none;
}
.share-crumbs {
  min-width: 0;
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-2);
  white-space: nowrap;
  overflow: hidden;
}
.share-crumb {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-2);
  text-decoration: none;
}
.share-crumb.is-here {
  color: var(--text-1);
  font-weight: 600;
}
.share-crumb-sep {
  flex: none;
  color: var(--text-4);
}
.share-right {
  flex: none;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  color: var(--text-3);
}
.share-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: default;
}
.share-live i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--success-solid);
  box-shadow: 0 0 0 3px var(--success-bg);
}
.share-download {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg-sunken);
  color: var(--text-1);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s;
}
.share-download:hover:not(:disabled) {
  background: var(--bg-hover-strong);
}
.share-download:disabled {
  opacity: 0.5;
  cursor: default;
}
.share-download-icon {
  flex: none;
}
.share-download-spin {
  flex: none;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  border: 2px solid var(--border);
  border-top-color: var(--text-1);
  animation: runner-spin 0.7s linear infinite;
}
.share-badge {
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--bg-sunken);
  border: 1px solid var(--border);
  color: var(--text-2);
  font-size: 11px;
}
.share-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.share-inner {
  max-width: 760px;
  margin: 0 auto;
  padding: 20px 20px 48px;
}
.share-footer {
  flex: none;
  padding: 10px 20px;
  border-top: 1px solid var(--border);
  text-align: center;
  font-size: 12px;
  color: var(--text-3);
}
/* Phone: the header runs out of room, so tighten it and collapse the download
   button to a square icon — the title keeps the space instead of the action. Read-only
   goes too: the footer says it. */
@media (max-width: 600px) {
  .share-header {
    gap: 10px;
    padding: 10px 14px;
  }
  .share-right {
    gap: 8px;
  }
  .share-right .share-badge {
    display: none;
  }
  .share-download {
    width: 40px;
    height: 40px;
    padding: 0;
    justify-content: center;
  }
  .share-download-label {
    display: none;
  }
}
.share-state {
  margin: auto;
  text-align: center;
  color: var(--text-3);
  padding: 40px;
}

/* ── Public project page (SharedProjectPage) ────────────────────────────────────
   docs/mocks/share-links/04: the app project page's own blocks and CSS at its own reading width,
   with what only its owner reads taken out. What is here is only what the public page adds. */
.share-inner.is-wide {
  max-width: 1040px;
}
.share-project-meta::before {
  content: '·';
  margin-right: 9px;
  color: var(--text-4);
}
/* A phone keeps the status, the count and the last activity on one line (mock 07): when it started
   is the one fact the header can give up there. */
@media (max-width: 640px) {
  .share-project-meta.is-started {
    display: none;
  }
}
/* Work overview on a row of its own: the Coordinator card beside it on the app page is the owner's. */
.share-project-overview {
  margin-bottom: 20px;
}
.share-project-coordinator {
  display: inline-block;
  margin-top: 10px;
  font-size: 13px;
}
.share-project-tasks {
  margin-bottom: 24px;
}
/* A task's title opens its public page, and reads as the title it is on the app's row. */
.share-project-task {
  color: inherit;
}
.share-project-task:hover {
  color: var(--brand);
  text-decoration: underline;
}
.pdg-footnote {
  margin-top: 8px;
  color: var(--text-3);
  font-size: 12px;
}

/* ── Public task page (SharedTaskPage) ──────────────────────────────────────────
   docs/mocks/share-links/05, left half: the task's header, then one card per block in the app task
   panel's order — Dependencies, Description, Acceptance, (Inputs), Runs, (Comments). */
.share-task {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
}
.share-task-head {
  margin-bottom: 4px;
}
.share-task-title {
  margin: 0 0 8px;
  font-size: 21px;
  font-weight: 650;
  line-height: 1.3;
  letter-spacing: -0.01em;
  color: var(--text-1);
  word-break: break-word;
}
.share-task-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 13px;
  color: var(--text-2);
}
.share-task-judged {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-raised);
  font-size: 12px;
  color: var(--text-2);
}
.share-task-superseded {
  margin-top: 8px;
  font-size: 13px;
  color: var(--text-2);
}
.share-card {
  background: var(--bg-raised);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 14px 16px;
  min-width: 0;
}
.share-card-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 0 0 10px;
}
.share-card-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--text-1);
}
.share-card-hint {
  font-size: 12.5px;
  color: var(--text-3);
}
.share-card-note {
  margin-top: 6px;
  font-size: 12.5px;
  color: var(--text-3);
}
.share-muted {
  color: var(--text-3);
  font-size: 13px;
}
.share-dep {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  font-size: 13px;
  border-top: 1px solid var(--border-subtle);
}
.share-dep:first-child {
  border-top: 0;
}
.share-dep-relation {
  flex: none;
  width: 78px;
  font-size: 12px;
  color: var(--text-3);
}
.share-dep-title {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.share-dep.is-elsewhere .share-dep-title {
  color: var(--text-3);
}
.share-prose {
  min-width: 0;
}
/* A long description, folded to its first lines until "Show more"; the fade only where it cuts. */
.share-prose.is-folded {
  position: relative;
  max-height: 150px;
  overflow: hidden;
}
.share-prose.is-fading::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 48px;
  background: linear-gradient(rgba(255, 255, 255, 0), var(--bg-raised));
}
.share-more {
  margin-top: 6px;
  padding: 0;
  border: 0;
  background: none;
  font-size: 12.5px;
  color: var(--brand);
  cursor: pointer;
}
.share-acceptance-pair {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}
.share-acceptance-command {
  font: 12px ui-monospace, SFMono-Regular, Menlo, 'DejaVu Sans Mono', monospace;
  background: var(--fill-inset);
  padding: 1px 5px;
  border-radius: 4px;
  word-break: break-all;
}
.share-inputs,
.share-runs {
  display: grid;
  gap: 6px;
}
.share-input {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: none;
  color: var(--text-1);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}
.share-input-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.share-run {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  font-size: 13px;
}
.share-run-when {
  min-width: 0;
  color: var(--text-1);
}
.share-run-open {
  margin-left: auto;
  flex: none;
  color: var(--brand);
  text-decoration: none;
}
.share-run-open.share-muted {
  color: var(--text-3);
}
.share-comment {
  border-top: 1px solid var(--border-subtle);
  padding: 10px 0 2px;
}
.share-comment:first-of-type {
  border-top: 0;
  padding-top: 2px;
}
.share-comment-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
  font-size: 12.5px;
}
.share-comment-avatar {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-size: 11px;
  font-weight: 700;
}
.share-comment-author {
  font-weight: 600;
  color: var(--text-1);
}
.share-state-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-1);
  margin-bottom: 6px;
}
.share-state-desc {
  font-size: 13px;
}

/* ── Share dialog (ShareModal) ─────────────────────────────────────────────────
   docs/mocks/share-links/03-share-dialog: Access, the link, Includes with counts, the Live line,
   Expires, and a foot with the views and the two buttons. */
.share-dialog-state {
  padding: 28px 0;
  text-align: center;
  color: var(--text-3);
}
.share-access {
  display: flex;
  align-items: center;
  gap: 10px;
}
.share-access-icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--fill-muted);
  color: var(--text-2);
  font-size: 15px;
}
.share-access-icon.is-public {
  background: var(--success-bg);
  color: var(--success);
}
.share-access-main {
  min-width: 0;
}
.share-access-select {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: -6px;
  padding: 2px 6px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-1);
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.share-access-select:hover {
  background: var(--fill-muted);
}
.share-access-caret {
  color: var(--text-3);
  font-size: 10px;
}
.share-access-detail {
  margin-top: 1px;
  color: var(--text-3);
  font-size: 12.5px;
  line-height: 1.5;
}
.share-access-menu .ant-dropdown-menu-item {
  align-items: flex-start;
  padding-top: 8px;
  padding-bottom: 8px;
}
.share-access-menu .ant-dropdown-menu-item .ant-dropdown-menu-item-icon {
  margin-top: 3px;
}
.share-access-option {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  max-width: 300px;
}
.share-access-option-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}
.share-access-option-title {
  font-weight: 500;
}
.share-access-option-detail {
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.5;
  white-space: normal;
}
.share-access-option-check {
  margin-top: 4px;
  color: var(--brand);
}
.share-dialog-url {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
.share-dialog-url-input {
  flex: 1;
  min-width: 0;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-sunken);
  color: var(--text-1);
  font-size: 12.5px;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
}
.share-dialog-label {
  margin: 16px 0 4px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
}
.share-layer {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 7px 0;
}
.share-layer + .share-layer {
  border-top: 1px solid var(--border-subtle);
}
.share-layer-check {
  align-items: flex-start;
  min-width: 0;
}
.share-layer-check .ant-checkbox {
  align-self: flex-start;
  margin-top: 2px;
}
.share-layer-name {
  display: block;
  color: var(--text-1);
  font-size: 13.5px;
  font-weight: 500;
}
.share-layer-detail {
  display: block;
  margin-top: 1px;
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.5;
}
/* A layer's risk, said in amber once the layer is on (Conversations: command output, file contents). */
.share-layer-detail.is-warn {
  color: var(--warning);
}
.share-layer-count {
  flex: none;
  margin-top: 2px;
  color: var(--text-3);
  font-size: 12px;
  white-space: nowrap;
}
/* A layer that sits under another (a project's Comments & files and Conversations, under Task
   pages): indented beneath it, and greyed out while that one is off. */
.share-layer.is-nested {
  padding-left: 26px;
}
.share-layer.is-idle .share-layer-name,
.share-layer.is-idle .share-layer-detail,
.share-layer.is-idle .share-layer-count {
  color: var(--text-4);
}
.share-dialog-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  font-size: 13px;
}
.share-dialog-row:first-of-type {
  margin-top: 8px;
}
.share-dialog-key {
  flex: none;
  width: 64px;
  color: var(--text-2);
}
.share-dialog-live {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-2);
}
.share-dialog-live i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--success-solid);
  box-shadow: 0 0 0 3px var(--success-bg);
}
.share-dialog-expiry {
  min-width: 96px;
}
.share-dialog-hint {
  color: var(--text-3);
  font-size: 12px;
}
.share-dialog-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-subtle);
}
.share-dialog-stat {
  flex: 1;
  min-width: 0;
  color: var(--text-3);
  font-size: 12px;
}
.share-dialog-muted {
  color: var(--text-4);
}

/* ============================================================================
   Provider onboarding — logo gallery + guided add flow (ProvidersPage).
   ========================================================================== */
.prov-page-head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 6px 12px;
}
.prov-page-sub {
  flex-basis: 100%;
  color: var(--text-3);
  font-size: 12px;
}
.provider-gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
@media (max-width: 640px) {
  .provider-gallery {
    grid-template-columns: 1fr;
  }
}

.provider-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  text-align: left;
  color: inherit;
  text-decoration: none;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 12px;
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s, transform 0.15s;
}
.provider-card:hover {
  border-color: var(--brand-border);
  box-shadow: 0 4px 14px rgba(51, 112, 255, 0.1);
  transform: translateY(-1px);
}
.provider-card.custom {
  border-style: dashed;
  background: var(--bg-subtle);
}
.provider-card .pc-name {
  font-weight: 600;
  font-size: 14px;
  color: var(--text-1);
}
.provider-card .pc-sub {
  margin-top: 1px;
  font-size: 12px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* A vendor the user has already connected. The card still connects another key, so it keeps the
   normal surface and marks itself at the edges: a tinted border and a check. */
.provider-card.connected {
  border-color: var(--success-border);
}
.provider-card.connected .pc-sub {
  color: var(--success);
  font-weight: 500;
}
/* The provider name in the keys table: when the endpoint column is hidden on narrow
   screens the name gets the leftover width, so a long custom label ellipsizes instead
   of stretching the table past the viewport. */
.prov-cell-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}
/* A long custom base URL is the one cell that can't ellipsize (a truncated URL reads as a
   different one), so it wraps at any character instead of setting the column's width. */
.prov-endpoint {
  font-size: 12px;
  color: var(--text-3);
  overflow-wrap: anywhere;
}
/* The enabled state's mobile stand-in, inside the provider cell: same signal as the tag,
   in the width of a punctuation mark. */
.prov-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-4);
}
.prov-dot.on {
  background: var(--success-solid);
}
@media (max-width: 640px) {
  /* With the endpoint and models columns hidden, the remaining cells only need half the
     gutter — and that padding is what still pushed the table a few pixels past a phone.
     Mirrors AntD's own selectors so this outranks their default cell padding. */
  .provider-keys .ant-table-thead > tr > th.ant-table-cell,
  .provider-keys .ant-table-tbody > tr > td.ant-table-cell {
    padding-inline: 10px;
  }
}

.provider-card .pc-logo {
  position: relative;
  flex: none;
  display: grid;
}
.provider-card .pc-check {
  position: absolute;
  right: -4px;
  bottom: -4px;
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  border: 2px solid var(--bg-raised);
  background: var(--success-solid);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.provider-tile {
  flex: none;
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.provider-back {
  display: inline-block;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}
.provider-back:hover {
  color: var(--brand);
}

.provider-idbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-subtle);
}

.provider-adv {
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.provider-adv-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 13px;
  cursor: pointer;
  user-select: none;
  background: var(--bg-subtle);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.provider-adv-head:hover {
  background: var(--bg-hover);
}
.provider-adv-head .pa-chev {
  color: var(--text-3);
  transition: transform 0.18s;
}
.provider-adv-head.open .pa-chev {
  transform: rotate(90deg);
}
.provider-adv-badge {
  margin-left: auto;
  padding: 2px 8px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  color: var(--success);
  background: var(--success-bg);
}
.provider-adv-body {
  padding: 14px;
  border-top: 1px solid var(--border-subtle);
}

.provider-empty {
  margin-top: 12px;
  padding: 28px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 14px;
}
.provider-empty h3 {
  margin: 0 0 4px;
  font-size: 18px;
  font-weight: 600;
  color: var(--text-1);
}
.provider-empty p {
  margin: 0 0 20px;
  font-size: 14px;
  color: var(--text-3);
}

/* The gallery below an existing list. */
.provider-more {
  margin-top: 28px;
}
.provider-more h3 {
  margin: 0 0 12px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-2);
}

/* A vendor whose CLI is already signed in on one of the user's machines — the cheaper route,
   pointed at in the brand colour so it reads as a hint rather than a status. */
.provider-card .pc-sub.pc-local {
  color: var(--brand);
  font-weight: 500;
}

/* ============================================================================
   Providers → "On your runners": the engine CLIs signed in on each machine.
   A different kind of identity from the API keys below (one machine, one
   subscription, nothing pasted), hence its own section rather than more rows.
   ========================================================================== */
.re-sec {
  margin-top: 22px;
}
.re-sec-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 10px;
}
.re-sec-head h3 {
  flex: none;
  margin: 0;
  font-size: 14px;
  font-weight: 650;
  color: var(--text-1);
}
.re-sec-sub {
  order: 1;
  flex-basis: 100%;
  font-size: 12px;
  color: var(--text-3);
}
.re-sec-count {
  margin-left: auto;
  font-size: 11.5px;
  color: var(--text-4);
  white-space: nowrap;
}

.re-card {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-raised);
  overflow: hidden;
  /* Its rows fit the card, not the viewport: the sidebar beside the page is user-resizable, so one
     window width is many card widths. */
  container: re-card / inline-size;
}
.re-card + .re-card {
  margin-top: 10px;
}
/* An offline runner's rows describe its last check-in, not its present state. Server-side account
   actions remain available in More; operations that need the machine are disabled in its menu. */
.re-card.offline {
  background: var(--bg-subtle);
}
.re-card.offline .re-row > :not(.re-id),
.re-card.offline .re-id > :not(.re-id-main),
.re-card.offline .re-id-main > :not(.re-name):not(.re-name-input),
.re-card.offline .re-name > * {
  opacity: 0.62;
}
.re-card.offline .re-row > .re-act:has(.re-more) {
  opacity: 1;
}
.re-head {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 14px;
  background: var(--bg-subtle);
  border-bottom: 1px solid var(--border-subtle);
}
/* A collapsed card is a header on its own — the border below it would be a line under nothing. */
.re-card.collapsed .re-head {
  border-bottom: 0;
}
.re-card.offline .re-head {
  background: var(--fill-muted);
}
/* Everything that isn't the Manage link folds the card; it's the whole left half of the header,
   so the hit target matches what reads as "this runner". */
.re-toggle {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.re-chev {
  flex: none;
  width: 10px;
  color: var(--text-3);
  font-size: 10px;
  transition: transform 0.15s;
}
.re-chev.open {
  transform: rotate(90deg);
}
.re-summary {
  font-size: 11.5px;
  color: var(--text-3);
  border-left: 1px solid var(--border);
  padding-left: 9px;
  white-space: nowrap;
}
.re-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--dot-idle);
}
.re-dot.on {
  background: var(--success-solid);
}
.re-runner {
  font-size: 13px;
  font-weight: 650;
  color: var(--text-1);
}
.re-runner-meta {
  font-size: 11.5px;
  color: var(--text-3);
}
.re-head-sp {
  flex: 1;
}
.re-manage {
  font-size: 12px;
  color: var(--brand);
  white-space: nowrap;
}

/* The runner header's spare width belongs to its toggle, with Manage kept independent. */
.re-runner-card .re-head {
  gap: 0;
  padding: 0;
}
.re-runner-card .re-toggle {
  flex: 1;
  align-self: stretch;
  gap: 10px;
  min-height: 64px;
  padding: 10px 12px;
  border-radius: 11px 0 0 11px;
}
.re-runner-card .re-toggle:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: -3px;
}
.re-runner-card .re-chev {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--text-2);
  transition: color 0.15s, transform 0.15s;
}
.re-runner-card .re-chev.open,
.re-runner-card .re-toggle:hover .re-chev {
  color: var(--brand);
}
.re-runner-copy {
  display: flex;
  flex: 1;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px 9px;
  min-width: 0;
}
.re-runner-copy .re-runner,
.re-runner-copy .re-runner-meta {
  overflow-wrap: anywhere;
}
.re-runner-card .re-manage {
  display: flex;
  align-items: center;
  min-height: 44px;
  margin: 0 14px 0 8px;
}
.re-runner-card .re-manage:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 3px;
  border-radius: 4px;
}
.re-runner-card .re-head > .ant-tag {
  margin: 0 4px;
}
@container re-card (max-width: 600px) {
  .re-runner-card .re-head {
    flex-wrap: wrap;
  }
  .re-runner-card .re-toggle {
    flex-basis: 100%;
    gap: 8px;
    padding: 10px 8px;
    border-radius: 11px;
  }
  .re-runner-copy,
  .re-runner-copy > span {
    display: block;
  }
  .re-runner-copy .re-runner-meta {
    margin-top: 3px;
  }
  .re-runner-card .re-summary {
    border-left: 0;
    padding: 3px 0 0;
  }
  .re-runner-card .re-manage {
    margin-left: auto;
    margin-right: 12px;
  }
  .re-runner-card .re-head > .ant-tag {
    margin-left: 75px;
  }
}

.re-row {
  display: grid;
  /* The last column is sized for two small buttons side by side: `+ Account` beside `Re-sign in` on
     a one-account Codex row, `Re-sign in` beside `Remove` on an added account's. At 110px the pair
     ran left over the quota's percentage.
     On a narrow card the quota's bar gives way before the name does. The name keeps 137px, what it
     had at 110px on a 617px card (a 961px window beside the default sidebar): an engine's name on
     one line, DEFAULT clear of the status beside it. The bar pays for the wider buttons instead. */
  grid-template-columns: minmax(137px, 1fr) 108px minmax(128px, 190px) 172px;
  align-items: center;
  gap: 14px;
  padding: 11px 14px;
}
.re-row + .re-row {
  border-top: 1px solid var(--border-subtle);
}
/* The row a "Not signed in" link came here for. Tinted for as long as the URL names it, the way a
   linked-to line stays lit — so the answer to "which one?" survives a scroll or a second look. */
.re-row.focused {
  background: var(--brand-tint);
  box-shadow: inset 3px 0 0 var(--brand);
}
/* A card too narrow for those floors (617px, 615 inside its border: the sidebar dragged wider, or a
   scrollbar that takes up room) takes each row on two lines rather than cut its buttons off at the
   card's edge: name and status, then quota and actions. The phone layout below is its own. */
@media (min-width: 701px) {
  @container re-card (max-width: 614px) {
    .re-row {
      grid-template-columns: minmax(0, 1fr) 172px;
    }
    /* The status over the actions, both against the card's right edge. */
    .re-row > :nth-child(2) {
      justify-self: end;
    }
    /* Under the name it belongs to, clear of the tile and of an account's rail. */
    .re-quota {
      margin-left: 38px;
    }
  }
}
@media (max-width: 700px) {
  /* Status and action stay together on the second line; the quota gauge is the one part
     that can wait for a wider window. */
  .re-row {
    grid-template-columns: minmax(0, 1fr) 108px;
  }
  .re-quota {
    display: none;
  }
}
/* A runner's engines and their accounts (RunnerEngines). Each row's quota is every window of its
   login with when it resets, under a status that says whether the login can run now — the account
   pools' login rows, which share these classes and keep the layout above. The status is sized for
   the longest thing it says, "Spent · resets Mon 19:00"; the last column holds the widest pair of
   actions, Add account beside More on a one-account row. On a narrow card the quota's bar gives way before the
   name does: the name keeps 137px, an engine's name on one line clear of the status beside it. */
.re-runner-card .re-row {
  grid-template-columns: minmax(137px, 1fr) 168px minmax(128px, 190px) 160px;
  /* Against the top: the quota stacks a window per line, and the name, status and actions stay level
     with the first of them. */
  align-items: start;
}
/* A group's head has no status or quota of its own — its accounts do — so its line runs the width
   of the row, and its one action sits level with the name it belongs to. */
@media (min-width: 701px) {
  .re-runner-card .re-row.re-grp {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
  }
  /* Too narrow for those floors (665px, 663 inside the border), as above: name and status, then
     quota and actions. */
  @container re-card (max-width: 662px) {
    .re-runner-card .re-row {
      grid-template-columns: minmax(0, 1fr) max-content;
    }
    .re-runner-card .re-row > :nth-child(2) {
      justify-self: end;
    }
    .re-runner-card .re-quota {
      margin-left: 38px;
    }
  }
}
@media (max-width: 700px) {
  /* Keep the name and its actions together. Status and quota get their own lines so Add account
     and Sign in can both remain visible without squeezing the account's state. Reserve room for
     the engine name and let the action column shrink so its buttons can wrap on a small phone. */
  .re-runner-card .re-row {
    grid-template-columns: minmax(112px, 1fr) minmax(0, max-content);
    gap: 8px 10px;
  }
  .re-runner-card .re-row > .re-act {
    grid-row: 1;
    grid-column: 2;
  }
  .re-runner-card .re-row > .re-status,
  .re-runner-card .re-row > .ant-tag {
    grid-row: 2;
    grid-column: 1 / -1;
    margin-left: 38px;
    justify-self: start;
  }
  .re-runner-card .re-quota {
    display: block;
    grid-row: 3;
    grid-column: 1 / -1;
    margin-left: 38px;
  }
  .re-runner-card .re-acct .re-name {
    overflow-wrap: anywhere;
  }
}
.re-id {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.re-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.re-meta {
  margin-top: 1px;
  font-size: 11.5px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* "updated 6h ago", after the version. Dimmer than the version it follows: routine upkeep is a
   footnote until it stops happening, at which point it is the loudest thing in the row. */
.re-upd {
  color: var(--text-4);
}
.re-upd.warn {
  color: var(--warning);
  font-weight: 500;
}
.re-quota-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 11px;
  color: var(--text-3);
}
.re-quota-head b {
  color: var(--text-2);
  font-weight: 600;
}
.re-quota .runner-util {
  margin-top: 5px;
  max-width: none;
}
.re-quota-none {
  font-size: 11px;
  color: var(--text-4);
}
/* One window under another, each with when it resets — the account pools' login rows. */
.re-window + .re-window {
  margin-top: 8px;
}
.re-reset {
  margin-top: 3px;
  font-size: 11px;
  color: var(--text-3);
  white-space: nowrap;
}
/* A reading older than the runner's reads: the numbers above are as of then, not now. A fact in the
   resets' grey, not a warning — a runner reads an engine no workspace defaults to only while one of
   its sessions runs, so an idle Codex login's reading is often this old with nothing wrong. */
.re-stale {
  margin-top: 8px;
  font-size: 11px;
  color: var(--text-3);
}
.re-status {
  min-width: 0;
}
.re-status .ant-tag {
  max-width: 100%;
  margin-inline-end: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: middle;
}
.re-act {
  display: flex;
  justify-content: flex-end;
  /* An account's row holds two actions — off this machine, and sign in — and a group head one;
     one child is a no-op. */
  gap: 8px;
}
.re-runner-card .re-act {
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 30px;
}
.re-action.ant-btn {
  height: 30px;
  padding: 0 10px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  line-height: 28px;
  gap: 6px;
}
.re-action.ant-btn-default:not(:disabled) {
  color: var(--text-2);
  border-color: var(--border);
  background: var(--bg-raised);
  box-shadow: 0 1px 1px rgba(31, 35, 41, .025);
}
.re-action .anticon {
  font-size: 13px;
}
.re-action.re-add-account,
.re-action.re-install {
  min-width: 112px;
}
.re-action.re-add-account:not(:disabled) {
  color: var(--brand);
  border-color: color-mix(in srgb, var(--brand) 15%, var(--bg-raised));
  background: color-mix(in srgb, var(--brand) 5.5%, var(--bg-raised));
}
.re-action.re-add-account:not(:disabled):hover {
  background: var(--brand-tint);
  border-color: var(--brand-border);
}
.re-action.re-more {
  width: 30px;
  min-width: 30px;
  padding: 0;
  color: var(--text-3);
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}
.re-action.re-more:hover,
.re-action.re-more.ant-dropdown-open {
  color: var(--text-2);
  background: var(--fill-muted);
}
.re-action.re-more .anticon {
  font-size: 17px;
}
.re-menu-anchor {
  display: inline-flex;
}
.re-account-menu .ant-dropdown-menu {
  min-width: 176px;
  padding: 5px;
  border: 1px solid var(--border-subtle);
  border-radius: 9px;
  box-shadow: 0 8px 28px rgba(31, 35, 41, .11), 0 2px 5px rgba(31, 35, 41, .04);
}
.re-account-menu .ant-dropdown-menu .ant-dropdown-menu-item {
  min-height: 33px;
  padding: 5px 9px;
  font-size: 12px;
  gap: 8px;
  border-radius: 5px;
}
.re-account-menu .ant-dropdown-menu .ant-dropdown-menu-item-icon {
  color: var(--text-3);
  font-size: 13px;
}
.re-account-menu .ant-dropdown-menu .ant-dropdown-menu-item-danger .ant-dropdown-menu-item-icon {
  color: inherit;
}
/* Codex with more than one account: the engine's row heads a group, and each account is a row
   under it. The head keeps what the engine owns — binary, version, updates — and says how many. */
.re-grp .re-meta b {
  color: var(--text-2);
  font-weight: 600;
}
/* An account row hangs off the engine above it: indented past the engine's tile, with a rail drawn
   up into the row before it and on down to where the next account's rail begins, so the tree reads
   as one line instead of a dash beside each name. The rail is positioned against the row rather
   than the name cell, so the spine reaches the row's bottom edge whatever the row's content does —
   the gap it has to cross is the next row's own rail reaching up 14px above its top. */
.re-acct {
  position: relative;
}
.re-acct .re-id {
  padding-left: 38px;
}
.re-rail {
  position: absolute;
  left: 27px;
  top: -14px;
  bottom: 0;
  width: 12px;
  border-left: 1px solid var(--border);
}
/* The elbow into this row: it starts 28px below the rail's top and turns right, so its horizontal
   lands 22px into the row — level with where the rail's own bottom used to sit. The turn is a
   quarter circle, and a spine passing straight through it (every row but the last) leaves its
   corner showing as the branch it is. */
.re-rail::after {
  content: '';
  position: absolute;
  left: 0;
  top: 28px;
  width: 12px;
  height: 7px;
  border-left: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  border-bottom-left-radius: 7px;
}
/* The last account under an engine is where the tree ends: the spine stops where its own elbow
   begins, so the turn is the last thing drawn. Carrying it to the elbow's end instead would leave
   a 5px tail hanging under the curve — the straight border doesn't know the corner curved away. */
.re-acct-end .re-rail {
  bottom: auto;
  height: 28px;
}
/* A mark beside a name: NEXT, where the next session starts — on a pool, or among a runner's accounts. */
.re-chip {
  display: inline-block;
  margin-left: 6px;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-muted);
  color: var(--text-3);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 16px;
  vertical-align: 1px;
}
/* The name being renamed: the session title's underlined input (.workspace-name-input), at the
   name's own size, its width set from the unseen twin below so the underline hugs the text. */
.re-name-input {
  display: block;
  box-sizing: content-box;
  max-width: 100%;
  min-width: 3ch;
  margin: 0;
  padding: 0;
  border: none;
  border-bottom: 1px solid var(--brand);
  background: transparent;
  outline: none;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.re-name-mirror {
  position: absolute;
  left: -9999px;
  top: 0;
  visibility: hidden;
  white-space: pre;
  font-size: 13px;
  font-weight: 600;
}
/* Two slots, one account: said under the second slot's row, in the second slot's own words, with
   the way out beside it. Indented past the rail so it reads as that row's and not the card's. */
.re-dup {
  grid-column: 1 / -1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  margin-top: 7px;
  padding-left: 38px;
  font-size: 11.5px;
  color: var(--text-3);
}
.re-dup b {
  color: var(--text-2);
  font-weight: 600;
}
/* "+ Account": the new account's name, above the sign-in that adds it. */
.re-add {
  display: flex;
  align-items: center;
  gap: 10px;
  /* The sign-in below starts flush in a panel (.re-panel .rsi), so the gap between them is this row's. */
  margin-bottom: 10px;
}
.re-add-label {
  flex: none;
  width: 118px;
  font-size: 12.5px;
  color: var(--text-2);
}

/* An install or a sign-in in flight, opened under the row it belongs to. */
.re-panel {
  grid-column: 1 / -1;
  margin-top: 4px;
  padding: 12px 13px;
  border-radius: 10px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-subtle);
}
.re-panel.bad {
  background: var(--error-bg);
  border-color: var(--error-border);
}
/* Drift, not breakage: an engine nobody has updated in a week still works today. Amber says
   "this needs a person eventually", which is the truth — red would say "this is down". */
.re-panel.warn {
  background: var(--warning-bg);
  border-color: var(--warning-border);
}
.re-panel-row {
  font-size: 12.5px;
  color: var(--text-2);
  white-space: pre-wrap;
}
.re-panel.bad .re-panel-row {
  color: var(--error);
  font-weight: 500;
}
.re-panel.warn .re-panel-row {
  color: var(--warning);
  font-weight: 500;
}
.re-panel-hint {
  margin-top: 7px;
  font-size: 11.5px;
  color: var(--text-3);
}
.re-cmd {
  display: inline-block;
  margin-top: 4px;
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
  color: var(--text-2);
  user-select: all;
}
.re-link {
  border: 0;
  background: none;
  padding: 0;
  color: var(--brand);
  font-size: 11.5px;
  cursor: pointer;
  white-space: nowrap;
}
.re-link:disabled {
  color: var(--text-4);
  cursor: default;
}
/* The relay card spaces itself off the message above it in a transcript; in a panel of its
   own that margin is doubled padding. */
.re-panel .rsi {
  margin-top: 0;
}

.re-unreported {
  padding: 14px;
  font-size: 12.5px;
  color: var(--text-3);
}

.re-empty {
  padding: 26px;
  text-align: center;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-raised);
}
.re-empty-logos {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin-bottom: 14px;
}
.re-empty h4 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-1);
}
.re-empty p {
  margin: 0 0 16px;
  font-size: 13px;
  color: var(--text-3);
}

/* ============================================================================
   Providers → "Account pools": several Claude subscriptions under one name. The
   runner cards' skeleton (fold, head, three-column rows), with a status column
   wide enough for "Unavailable · usage unreadable" (185px measured — the widest
   a member's tag gets; "Unavailable · key refused" is 151px and "Spent · resets
   Mon 14:05" less) and a little wider, so a font that rounds a pixel or two
   differently does not bring the ellipsis back. A fixed track rather than
   max-content so the columns of every row in a card line up; what it costs is
   the name column, and at a 900px card that is 36px of 386 against a name that
   needs 149 — nothing — while at the narrowest desktop card (617px, the default
   sidebar at a 961px window) the name is truncated already, as it was at 160px.
   ========================================================================== */
.pool-sec .re-card + .re-card {
  margin-top: 10px;
}
.pool-row {
  grid-template-columns: minmax(0, 1fr) 196px 140px 110px;
}
.pool-status {
  min-width: 0;
}
.pool-status .ant-tag {
  max-width: 100%;
  margin-inline-end: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: middle;
}
/* The NEXT chip goes under a name it has no room beside, rather than eat into it. */
.pool-row .re-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  row-gap: 2px;
  min-width: 0;
}
.pool-member-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pool-row .re-chip {
  flex: none;
}
/* Most accounts have nothing to press; on a phone their empty action cell would still take a line. */
.pool-row .re-act:empty {
  display: none;
}
/* The pool's page takes accounts out, so its rows carry up to two actions: Re-add key and the
   remove mark (88 + 8 + 24px measured). */
.pool-detail .pool-row {
  grid-template-columns: minmax(0, 1fr) 196px 130px 124px;
}
/* The head's gauge: the account the next session runs on, never an average of them. */
.pool-gauge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  font-size: 11.5px;
  color: var(--text-3);
  white-space: nowrap;
}
.pool-gauge-name {
  color: var(--text-2);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pool-gauge .runner-util {
  flex: none;
  width: 80px;
  margin-top: 0;
}
.pool-gauge-pct {
  font-variant-numeric: tabular-nums;
  color: var(--text-2);
}
/* Its tightest window at 90% or more: orange with its bar, as the composer's quota turns. */
.pool-gauge-pct.near-limit {
  color: var(--warning);
  font-weight: 600;
}
.pool-gauge.spent {
  color: var(--warning);
  font-weight: 500;
}
/* A pool none of whose accounts can run says why, in red: unlike a spent one, no reset brings it
   back, and every door that takes a provider refuses it. */
.pool-gauge.none {
  color: var(--error);
  font-weight: 500;
}
/* Why the pool would no longer admit an account, in the words joining it is refused with: a line of
   the row's own under the account's name, since those words run past the status column. */
.pool-why {
  grid-column: 1 / -1;
  margin-top: -8px;
  padding-left: 38px;
  font-size: 11.5px;
  color: var(--error);
}
.pool-note {
  padding: 10px 14px;
  font-size: 12px;
  color: var(--text-3);
  border-bottom: 1px solid var(--border-subtle);
}
.pool-note b {
  color: var(--text-2);
  font-weight: 600;
}
@media (max-width: 700px) {
  /* Folded to one line: the name gives way first, then the next account's name — its gauge stays. */
  .pool-card .re-head {
    gap: 8px;
  }
  .pool-card .re-toggle {
    flex: 1 1 auto;
  }
  .pool-card .re-runner {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .pool-card .re-head-sp,
  .pool-gauge-name,
  .pool-gauge-none,
  .pool-wide {
    display: none;
  }
  .pool-gauge .runner-util {
    width: 40px;
  }
  /* Whole, whatever it says — the next account's bar, a reset, or why nothing can run. Left to
     shrink, it gave way beside a long name instead and ran into the Manage arrow (390px). */
  .pool-gauge {
    flex: none;
  }
  .pool-row,
  .pool-detail .pool-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }
  /* The actions take a line of their own here; why an account is out stays under its name, above them. */
  .pool-row .re-act {
    order: 1;
  }
}
/* At the top of the keys list while there is something to pool and no pool yet. */
.pool-hint {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 12px;
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--brand-tint);
  font-size: 12.5px;
  color: var(--text-2);
}
.pool-hint > span {
  flex: 1;
  min-width: 0;
}
.pool-hint b {
  color: var(--text-1);
  font-weight: 600;
}
/* Add account / Create a pool: every key, with the server's verdict on it. */
.pool-name {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  font-size: 12.5px;
  color: var(--text-2);
}
.pool-pick-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.pool-pick {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 8px;
  border-radius: 8px;
  cursor: pointer;
}
.pool-pick:hover {
  background: var(--bg-hover);
}
.pool-pick.off {
  cursor: default;
}
.pool-pick.off:hover {
  background: none;
}
.pool-pick.off .provider-tile {
  opacity: 0.5;
}
.pool-pick-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.pool-pick-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-1);
}
.pool-pick.off .pool-pick-name {
  color: var(--text-3);
}
.pool-pick-why {
  font-size: 11.5px;
  color: var(--text-3);
}
.pool-pick-why.refused {
  color: var(--error);
}
.pool-page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin: 10px 0 16px;
}
.pool-danger {
  margin-top: 16px;
}

/* ============================================================================
   Shared pools: several people's OpenAI API keys under one name (lib/sharedPools.ts).
   The account pool's card with a key to a row, plus its people and its rules.
   ========================================================================== */
/* A person is a circle with their initial, in their colour in the pool. */
.pool-av {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #fff;
  font-weight: 600;
  line-height: 1;
}
.pool-you {
  flex: none;
  margin-left: 6px;
  font-size: 12px;
  font-weight: 400;
  color: var(--text-3);
}
/* The head: the engine's mark before the name, SHARED after it, the people at the right. */
.pool-card .re-toggle .provider-tile {
  flex: none;
  margin-right: 2px;
}
.re-chip.pool-shared-chip {
  flex: none;
  margin-left: 0;
  background: var(--brand-tint);
  color: var(--brand);
}
.pool-people {
  display: inline-flex;
  align-items: center;
  flex: none;
  margin-right: 6px;
}
.pool-people .pool-av {
  box-shadow: 0 0 0 2px var(--bg-raised, #fff);
}
.pool-people .pool-av + .pool-av {
  margin-left: -5px;
}
.pool-people-more {
  margin-left: 4px;
  font-size: 11px;
  color: var(--text-3);
}
/* The section head carries the way to make another pool. */
.pool-sec-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.pool-sec-head h3 {
  white-space: nowrap;
}
.pool-sec-head .pool-new {
  margin-left: auto;
  align-self: center;
  flex: none;
}
/* A key's status says more than an account's ("At cap · resets Oct 1"), so on a desktop its row takes
   the room the money's bar can spare. The phone's own two-column row below is narrower than this. */
@media (min-width: 701px) {
  .pool-card .re-row.pool-row-key,
  .pool-detail .re-row.pool-row-key {
    grid-template-columns: minmax(137px, 1fr) 178px minmax(128px, 190px) 172px;
  }
}
/* Whose key it is and all anyone sees of it: `Wikova · sk-…AB12`. */
.pool-key-mask {
  margin-top: 1px;
  font-size: 12px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── the pool's page: its title, its people and its rules ─────────────────────── */
.pool-page-title {
  display: flex;
  align-items: center;
  gap: 10px;
}
.pool-page-title .page-title {
  margin-bottom: 0;
}
.pool-sub-sec {
  margin-top: 16px;
}
.pool-card .re-head .pool-head-count {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-3);
  margin-left: 6px;
}
.pool-head-note {
  font-size: 11.5px;
  color: var(--text-3);
  white-space: nowrap;
}
.pool-person {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(160px, 240px) 28px;
  align-items: center;
  gap: 14px;
  padding: 10px 14px;
}
.pool-person + .pool-person {
  border-top: 1px solid var(--border-subtle);
}
.pool-person-id {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.pool-person-name {
  display: flex;
  align-items: center;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--text-1);
}
.pool-person-name > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pool-person-name .re-chip {
  flex: none;
}
.pool-person-meta {
  font-size: 12px;
  color: var(--text-3);
}
.pool-share {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
}
.pool-share .runner-util {
  flex: 1;
  margin-top: 0;
}
.pool-share-pct {
  width: 32px;
  text-align: right;
}
.pool-person-more {
  color: var(--text-3);
  text-align: center;
}
.pool-rule {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 12px 14px;
}
.pool-rule + .pool-rule {
  border-top: 1px solid var(--border-subtle);
}
.pool-rule-t {
  font-size: 13.5px;
  color: var(--text-1);
}
.pool-rule-h {
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-3);
}
.pool-danger-row {
  display: flex;
  gap: 8px;
  align-items: center;
}
.pool-danger-note {
  font-size: 12px;
  color: var(--text-3);
}

/* ── A Codex pool by who reads it: its owner, or somebody they added (docs/mocks/account-pool-access) ── */
/* The subtitle: who can use it first, a shade darker. */
.pool-sub {
  font-size: 12px;
  color: var(--text-3);
}
.pool-sub b {
  color: var(--text-2);
  font-weight: 500;
}
/* Whose sessions an account runs, after its fingerprint: a ChatGPT account its owner's alone, a key
   everybody's. */
.pool-runs-for {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--text-2);
  white-space: nowrap;
}
.pool-runs-for.all {
  color: var(--success);
}
.pool-runs-for .anticon {
  font-size: 11px;
}
/* The owner's ChatGPT accounts, as somebody they added sees them: one locked line. */
.pool-card .re-row.pool-row-locked {
  grid-template-columns: minmax(0, 1fr);
  background: var(--bg-subtle);
}
.pool-row-locked .re-name {
  color: var(--text-2);
}
.pool-lock-tile {
  display: grid;
  flex: none;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px dashed var(--border);
  border-radius: 7px;
  background: var(--fill-muted);
  color: var(--text-3);
  font-size: 13px;
}
/* Who can use it: the switch with what it means beside it, then each person, the one rule, and why the
   owner's ChatGPT accounts are never anybody else's. */
.who-card .re-head {
  gap: 10px;
}
.who-mode {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border-subtle);
}
.who-mode:last-child {
  border-bottom: 0;
}
.who-mode-h {
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-3);
}
.who-card .pool-rule {
  border-top: 1px solid var(--border-subtle);
}
.pool-runs {
  color: var(--text-3);
}
.pool-runs.all {
  color: var(--text-2);
}
.who-foot {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 10px 14px;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-subtle);
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}
.who-foot .anticon {
  flex: none;
  margin-top: 4px;
  font-size: 12px;
}
.who-foot b {
  color: var(--text-2);
  font-weight: 600;
}
/* Shared with people, and no API key yet: none of them can start a session, and what fixes it. */
.who-warn {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px 14px;
  border-top: 1px solid var(--warning-border);
  background: var(--warning-bg);
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-2);
}
.who-warn > .anticon {
  flex: none;
  font-size: 15px;
  color: var(--warning-solid);
}
.who-warn b {
  color: var(--text-1);
  font-weight: 600;
}
.who-warn .ant-btn {
  flex: none;
  margin-left: auto;
}
.pool-share-emails {
  width: 100%;
}
/* "Add account": each kind a card that is its own radio, what it runs said on it. */
.add-kinds {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}
.add-kinds .ant-radio-wrapper.add-kind {
  display: flex;
  align-items: flex-start;
  margin-inline-end: 0;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-raised);
}
.add-kinds .ant-radio-wrapper.add-kind.ant-radio-wrapper-checked {
  border-color: var(--brand);
  background: var(--brand-tint);
}
.add-kinds .add-kind .ant-radio {
  align-self: flex-start;
  margin-top: 3px;
}
.add-kinds .add-kind .ant-radio-label {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding-inline: 12px 0;
}
.add-kind-t {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-1);
}
.add-kind-s {
  display: block;
  margin-top: 2px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-2);
}
.add-kind-s b {
  color: var(--text-1);
  font-weight: 600;
}
.add-kind-key {
  display: grid;
  flex: none;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  background: linear-gradient(135deg, #6b7280, #4b5563);
  color: #fff;
  font-size: 13px;
}

/* ── "Add a key" / "Replace key" ─────────────────────────────────────────────── */
.pa-lead {
  font-size: 13px;
  color: var(--text-2);
  line-height: 1.6;
  margin: 2px 0 12px;
}
.pa-facts {
  margin: 0 0 14px;
  padding: 10px 12px 10px 30px;
  border-radius: 8px;
  background: var(--bg-sunken);
  font-size: 12.5px;
  line-height: 1.65;
  color: var(--text-2);
}
.pa-facts li + li {
  margin-top: 4px;
}
.pa-facts b {
  color: var(--text-1);
  font-weight: 600;
}
/* Kept on purpose: whoever puts a key in is told it can't be resold and is theirs to answer for. */
.pa-risk {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin: 0 0 4px;
  padding: 8px 10px;
  border: 1px solid var(--warning-border, #f5d6a3);
  border-radius: 8px;
  background: var(--warning-tint, #fff8ec);
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--text-2);
}
.pa-risk .anticon {
  margin-top: 3px;
  color: var(--warning);
}
.pa-done {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 4px 0 8px;
}
.pa-done-t {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
}
.pa-done-s {
  font-size: 12.5px;
  color: var(--text-3);
  line-height: 1.6;
}
.pa-done .anticon {
  font-size: 22px;
  color: var(--success, #16a34a);
  margin-top: 2px;
}
.pa-dup .anticon {
  color: var(--warning);
}
.pa-acct {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 10px 0 2px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
}
.pa-acct-t {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-1);
}
.pa-acct-s {
  font-size: 12px;
  color: var(--text-3);
}

/* ── A Codex pool of one's own: its ChatGPT account, and "Sign in with ChatGPT" ───────────── */
/* The account's row: its status says little ("Available", "Signed out"), its quota says more — two
   windows, each with when it resets — and its actions are "Sign in again" beside the sign-out mark. */
@media (min-width: 701px) {
  .pool-card .re-row.pool-row-login,
  .pool-detail .re-row.pool-row-login {
    grid-template-columns: minmax(137px, 1fr) 150px minmax(128px, 180px) 136px;
    align-items: start;
  }
}
.pool-login-window + .pool-login-window {
  margin-top: 8px;
}
/* The sign-out mark rests grey and turns red only under the pointer: red on a row that is fine read
   as something wrong with it. Weightier than antd's resting colour, lighter than its :hover and
   :active, which keep the danger button's own red. */
.pool-row .pool-signout.ant-btn {
  color: var(--text-3);
}
.pool-login-reset {
  margin-top: 3px;
  font-size: 11px;
  color: var(--text-3);
  white-space: nowrap;
}
/* The one-time code, as the page it is typed into prints it: large, spaced, and copied in one press. */
.cx-open {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin: 2px 0 14px;
}
.cx-url {
  font-size: 12px;
  color: var(--text-3);
  word-break: break-all;
}
.cx-hint {
  font-size: 13px;
  color: var(--text-2);
  line-height: 1.6;
}
.cx-code {
  margin: 8px 0 12px;
  padding: 14px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-sunken);
  text-align: center;
}
.cx-code .cx-code-text {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--text-1);
}
/* The copy mark beside it stays a control's size, not the code's. */
.cx-code .ant-typography-copy {
  margin-inline-start: 10px;
  font-size: 16px;
  vertical-align: 4px;
}
.cx-wait {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-1);
}
.cx-expiry {
  margin-top: 6px;
  font-size: 12px;
  color: var(--text-3);
}
@media (max-width: 700px) {
  /* The quota is what an account's row is about: a line of its own under the name, bars and resets
     kept — as a runner's accounts have it on Providers. */
  .pool-row .re-quota.pool-login-quota {
    display: block;
    grid-column: 1 / -1;
    margin-left: 38px;
  }
  .pool-row.pool-row-login .re-act {
    grid-column: 1 / -1;
    margin-top: -4px;
  }
  .cx-code .cx-code-text {
    font-size: 22px;
  }
}

/* ── New pool ─────────────────────────────────────────────────────────────────── */
.np-field {
  display: block;
  margin: 0 0 14px;
}
.np-field-l {
  display: block;
  margin: 0 0 6px;
  font-size: 13px;
  color: var(--text-2);
}
.np-field-h {
  margin-top: 6px;
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-3);
}
.np-field-h.np-field-err {
  color: var(--error);
}
.np-engine .ant-segmented-item-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.np-people {
  width: 100%;
  margin-top: 10px;
}
.np-can-add {
  margin-top: 8px;
}

@media (max-width: 700px) {
  /* The name outranks the chip and the people on a phone's head line: the pool's own page carries
     SHARED, and the Members card who is in it. */
  .pool-people,
  .pool-card .re-toggle .pool-shared-chip {
    display: none;
  }
  /* A key's actions sit at the right edge of a line of their own. */
  .pool-row.pool-row-key .re-act {
    grid-column: 1 / -1;
    margin-top: -4px;
  }
  /* The money is what a key's row is about, so it keeps a line of its own under the name; the bar
     waits for a wider window, as a personal pool's does. */
  .pool-row .re-quota.pool-key-money {
    display: block;
    grid-column: 1 / -1;
    margin-left: 38px;
  }
  .pool-row .re-quota.pool-key-money .runner-util {
    display: none;
  }
  .pool-person {
    grid-template-columns: minmax(0, 1fr) 28px;
    row-gap: 6px;
  }
  .pool-person > :nth-child(2) {
    grid-column: 1;
    grid-row: 2;
    padding-left: 38px;
  }
  .pool-person > :nth-child(3) {
    grid-column: 2;
    grid-row: 1;
  }
  /* The members' note drops under their title. */
  .pool-sub-sec .re-head {
    flex-wrap: wrap;
    row-gap: 2px;
  }
  .pool-sub-sec .pool-head-note {
    display: block;
    order: 5;
    width: 100%;
  }
  .pool-rule {
    gap: 14px;
  }
}

/* The connect page (/providers/new/:slug, /providers/:id): a narrow, numbered walkthrough. */
.provider-form {
  max-width: 680px;
  margin: 0 auto;
}
.provider-step {
  margin-top: 22px;
}
.provider-step .ps-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
.provider-step .ps-num {
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-2);
  background: var(--fill-muted);
}
.provider-step .ps-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
}
.provider-step .ps-link {
  margin-left: auto;
  font-size: 12px;
  font-weight: 500;
}
.provider-step .ps-hint {
  margin-top: 4px;
  font-size: 12px;
  color: var(--text-3);
}

.provider-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--border-subtle);
}

/* Model rows are a small table, and their placeholders vanish once filled — so the columns are
   labelled. Widths track the inputs underneath. */
.pf-models-head {
  display: flex;
  gap: 8px;
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-3);
}
.pf-models-head span:nth-child(1),
.pf-models-head span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.pf-models-head span:nth-child(3) {
  flex: none;
  width: 140px;
}
.pf-models-head span:nth-child(4) {
  flex: none;
  width: 32px;
}

/* The list Orbit maintains: one line and a way in, not a spreadsheet to review. */
.pf-models-sum {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-size: 13px;
  color: var(--text-2);
}
.pf-models-sum .pf-sum-list {
  flex: 1;
  min-width: 0;
}
.pf-models-sum a {
  flex: none;
  font-size: 12px;
  font-weight: 500;
}

/* ── ⌘K session search palette ──────────────────────────────────────────────
   A command palette, so it sits high on the screen (Modal `top`) and owns its own
   chrome: no antd title bar, no footer buttons, body padding stripped. The three
   regions — input, results, hint bar — mirror the session list's own vocabulary so a
   result row reads the same as the row it will navigate to. */
.ssearch-modal .ant-modal-container {
  padding: 0;
  overflow: hidden;
  border-radius: 12px;
}
.ssearch-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  height: 52px;
  border-bottom: 1px solid var(--border-subtle);
}
.ssearch-head-icon {
  color: var(--text-3);
  font-size: 16px;
}
.ssearch-input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-size: 16px;
  color: var(--text-1);
}
.ssearch-input::placeholder {
  color: var(--text-4);
}
/* Capped so a long result set scrolls inside the palette instead of running off-screen. */
.ssearch-list {
  max-height: min(52vh, 440px);
  overflow-y: auto;
}
.ssearch-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 16px;
  cursor: pointer;
}
/* One highlight, driven by the keyboard cursor — hover sets that cursor rather than painting a
   second, competing highlight, so mouse and keyboard can never disagree about the Enter target.
   Brand tint rather than --bg-hover: in dark the modal surface IS --bg-hover (AntD's
   colorBgElevated is pinned to the same #343437), so a hover-grey cursor was invisible there. */
.ssearch-row.active {
  background: var(--brand-tint);
}
.ssearch-body {
  flex: 1;
  min-width: 0;
}
.ssearch-title-line {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ssearch-title {
  font-size: 14px;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* "Completed" / "Trash": this hit is real but isn't in the Open list the sidebar is showing. */
.ssearch-badge {
  flex: none;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-muted);
  color: var(--text-3);
  font-size: 11px;
  line-height: 17px;
}
.ssearch-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 2px;
  color: var(--text-3);
  font-size: 12px;
}
.ssearch-meta > span + span::before {
  content: '·';
  margin-right: 6px;
}
.ssearch-workspace {
  color: var(--text-2);
}
.ssearch-snippet {
  margin-top: 3px;
  color: var(--text-2);
  font-size: 12px;
  line-height: 17px;
  /* The server already caps the window; this keeps a wide match to one line in the row. */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ssearch-snippet mark {
  padding: 0 1px;
  border-radius: 2px;
  background: var(--brand-tint-hover);
  color: var(--brand-strong);
}
.ssearch-empty {
  padding: 28px 16px;
  color: var(--text-3);
  font-size: 13px;
  text-align: center;
}
.ssearch-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-subtle);
  color: var(--text-3);
  font-size: 12px;
}
.ssearch-hint-warn {
  color: var(--warning);
}
.ssearch-keys {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: none;
  color: var(--text-4);
}
.ssearch-keys kbd {
  padding: 1px 5px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--bg-raised);
  font-family: inherit;
  font-size: 11px;
}

/* ---- New Session provider hero (the compose pane's middle area) ----
   Collapsed to one identity: a big brand mark on the first line, the name on the second.
   Deliberately unframed — a card border at this size reads heavy, and the mark is the anchor.
   "Clickable" is carried by the chevron plus the hover states below. */
.np-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 8px 16px;
}
.np-title {
  font-size: 17px;
  font-weight: 600;
  color: var(--text-1);
  letter-spacing: -0.01em;
}
.np-sub {
  margin-top: 5px;
  font-size: 12.5px;
  color: var(--text-3);
}
/* The ordinary empty state follows the mobile hierarchy: provider first, then the instruction,
   then the model that this draft will actually send with. */
.np-empty-copy {
  margin-top: 20px;
  font-size: 17px;
  color: var(--text-3);
}
.np-current-model {
  margin-top: 5px;
  font-size: 14px;
  color: var(--text-4);
}
.np-card {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin-top: 18px;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  font: inherit;
}
.np-card:disabled {
  cursor: default;
}
/* Drop the focus ring on mouse click; keep it for keyboard navigation — and put it on the name
   pill, since a rect around the 56px mark reads as the card frame this hero deliberately avoids. */
.np-card:focus {
  outline: none;
}
.np-card:focus-visible .np-name {
  outline: 2px solid var(--brand);
  outline-offset: 1px;
}
.np-mark {
  transition: transform 0.16s;
}
.np-card:not(:disabled):hover .np-mark {
  transform: translateY(-2px);
}
.np-name {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 10px;
  font-size: 16px;
  font-weight: 650;
  color: var(--text-1);
  transition: background 0.15s, color 0.15s;
}
.np-card:not(:disabled):hover .np-name {
  background: var(--bg-hover);
}
.np-card.open .np-name {
  background: var(--brand-tint);
  color: var(--brand-strong);
}
.np-chev {
  font-size: 11px;
  font-weight: 400;
  color: var(--text-3);
}
.np-card.open .np-chev {
  color: var(--brand-strong);
}
/* One line for the two things a switch changes: which model, and whose money. */
.np-summary {
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-3);
}
.np-summary b {
  color: var(--text-2);
  font-weight: 600;
}
.np-summary .np-dot {
  color: var(--text-4);
}
.np-summary a {
  color: var(--brand);
  text-decoration: none;
}
.np-summary a:hover {
  color: var(--brand-strong);
}
.np-note {
  margin-top: 9px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid var(--brand-border);
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-size: 11.5px;
}

/* the open list */
.np-pop .ant-popover-container {
  padding: 6px;
}
.np-list {
  width: 244px;
}
.np-row {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 9px;
  padding: 7px 8px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--text-2);
  font: inherit;
  font-size: 12.5px;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}
.np-row:hover {
  background: var(--bg-hover);
}
/* An engine the runner has but isn't signed into: the identity reads as unavailable, while the
   reason doubles as the link to the Providers page that fixes it. */
.np-unavailable .np-mark,
.np-unavailable .np-row-name {
  opacity: 0.5;
}
/* Beats .np-row-model's grey below, wherever the two land in the cascade. */
.np-row-model.np-fix {
  color: var(--brand);
}
/* The same row in the composer model menu's Provider submenu, where the row is one string rather
   than three elements: dim it as unavailable, but leave it pickable — choosing it opens the sign-in it
   names, so greying it out would take away the only thing it is there to offer. */
.ant-dropdown-menu-item.composer-provider-fix .scope-menu-row {
  color: var(--text-3);
}
/* A Codex account under Codex in that submenu: indented under its engine, its own quota on the right
   where the other rows say their value, orange once a window is nearly spent. Names are often emails,
   so the name gives way before the quota does. */
.ant-dropdown-menu-item.composer-account-row .scope-menu-row {
  padding-left: 14px;
}
.composer-account-row-name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.composer-account-row .scope-menu-value-text {
  max-width: none;
}
.composer-account-row.near-limit .scope-menu-value {
  color: var(--warning);
}
.np-row.on {
  background: var(--brand-tint);
  color: var(--text-1);
  font-weight: 600;
}
.np-row-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.np-label-detail {
  margin-left: 6px;
  font-size: 10px;
  font-weight: 400;
  color: var(--text-3);
}
.prov-runtime {
  margin-top: 3px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--text-3);
}
/* Each row previews the model it would switch to, so the consequence is visible before the click. */
.np-row-model {
  margin-left: auto;
  padding-left: 8px;
  font-size: 11px;
  font-weight: 400;
  color: var(--text-4);
  white-space: nowrap;
}
.np-sep {
  height: 1px;
  margin: 5px 4px;
  background: var(--border-subtle);
}
.np-connect {
  color: var(--brand);
}
.np-plus {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border: 1px dashed var(--border);
  border-radius: 5px;
  background: var(--fill-muted);
  color: var(--text-3);
  font-size: 12px;
}
/* An account pool: its vendor's mark, with how many accounts it holds in the corner. */
.np-mark-wrap {
  position: relative;
  flex: none;
  display: inline-flex;
}
.np-pool-badge {
  position: absolute;
  top: -4px;
  right: -5px;
  min-width: 1.6em;
  padding: 0 0.35em;
  border-radius: 999px;
  border: 1.5px solid var(--bg-raised);
  background: var(--text-1);
  color: var(--bg-raised);
  font-weight: 700;
  line-height: 1.45;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
/* "Pin a specific account": the accounts a pool runs on, one click further away than the pool. */
.np-pin-toggle {
  color: var(--text-3);
}
.np-pin-chev {
  display: inline-block;
  width: 20px;
  text-align: center;
  font-size: 10px;
  transition: transform 0.15s;
}
.np-pin-chev.open {
  transform: rotate(90deg);
}
.np-pinned {
  padding-left: 14px;
}
/* An engine's own accounts on this runner, under its row: which one this session spends. The tick
   takes the mark's column, so the account names line up with the engine's. */
.np-account-tick {
  flex: none;
  width: 20px;
  text-align: center;
  font-size: 11px;
  color: var(--brand);
}
.np-account.picked {
  color: var(--text-1);
}
.np-account .np-row-model.near-limit {
  color: var(--warning);
}
/* Account names are often emails, so the list makes room for one beside its quota. */
.np-list.with-accounts {
  width: 280px;
}
.np-list.with-details {
  width: 360px;
  max-width: calc(100vw - 32px);
}
/* The composer's account pill: which of a pool's accounts this session is spending. */
.composer-account {
  padding-right: 6px;
  font-size: 12px;
  color: var(--text-2);
  cursor: default;
}
.composer-account-name {
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Project identity stays visually quiet; the command centre and then the goal beneath it own the
   live numbers, actions and purpose. This avoids both the old repeated status tags and the large
   blank rectangle created when a 90px title block shared a row with a 250px coordinator card. */
.project-detail-identity {
  margin: 14px 0;
}
.project-detail-identity .page-title {
  max-width: 920px;
  margin: 0;
  font-size: clamp(26px, 3vw, 34px);
  font-weight: 650;
  line-height: 1.18;
  letter-spacing: -0.025em;
}
.project-detail-meta {
  display: flex;
  /* Wraps because this row now carries the status presses beside the tag and the count: on a
     phone the three of them plus Delete are wider than the screen, and a row that cannot wrap
     pushes the last one out of reach rather than under the others. */
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  margin-top: 10px;
  color: var(--text-2);
  font-size: 13px;
}
.project-detail-meta .ant-tag {
  margin-inline-end: 0;
}

/* The integration line, directly under the title metadata (contract §7.2 V3, mock 2 ①). Its
   settings are the project's How it runs block (`.project-run-settings`), not a disclosure here. */
.project-integration {
  margin-top: 10px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
}
/* On the project page the card under the line keeps its distance from it (mock board3 ④). */
[data-project-block='integration-line'] > .project-integration {
  margin-bottom: 14px;
}
.project-integration-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 7px 10px;
  font-size: 12.5px;
  color: var(--text-2);
}
.project-integration-facts {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}
.project-integration-facts b {
  color: var(--text-1);
  font-weight: 600;
}
/* The current landings under the line (§2.7a): one compact block per task, in the task page's words. */
.project-land-task {
  border-top: 1px solid var(--border-subtle);
  padding: 8px 10px;
}
.project-land-task-title {
  display: inline-block;
  margin-bottom: 4px;
  font-weight: 600;
  font-size: 12.5px;
  color: var(--text-1);
}
.project-land-task-title:hover {
  color: var(--brand);
}
/* A task's newest landing attempt: the task's status and the landing's apart, the reason, the facts. */
.land-task-status {
  font-size: 12.5px;
  color: var(--text-2);
}
.land-task-status-head {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.land-task-task-state {
  color: var(--text-1);
  font-weight: 600;
}
.land-task-generation,
.land-task-step {
  color: var(--text-3);
}
.land-task-reason {
  margin-top: 5px;
  color: var(--text-1);
}
.land-task-receipt {
  margin-top: 5px;
  color: var(--text-3);
}
.land-task-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 6px 0 0;
}
.land-task-facts > div {
  display: flex;
  gap: 5px;
  min-width: 0;
}
.land-task-facts dt {
  color: var(--text-3);
}
.land-task-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
}
/* A project nobody has started: one sentence beside the mark, wrapping under itself on a phone. */
.project-integration-undecided {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}
.project-integration-undecided > svg {
  margin-top: 3px;
}
.project-integration-undecided b {
  color: var(--text-1);
  font-weight: 600;
}
.project-integration-branch {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-1);
  font-weight: 600;
}
.project-integration-setting {
  display: grid;
  grid-template-columns: 132px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  padding: 12px 0 0;
  font-size: 13px;
}
@media (max-width: 640px) {
  .project-integration-setting {
    grid-template-columns: minmax(0, 1fr);
    gap: 6px;
  }
}
.project-integration-setting-label {
  color: var(--text-2);
  padding-top: 4px;
}
.project-integration-setting-hint {
  margin-top: 4px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-3);
}
.project-integration-setting-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
}

/* What the account owner is shown before claiming a project's goal is met: one row per stated
   criterion, each carrying BOTH facts the server can offer — whether the work filed under it
   settled, and whether any receipt proves that work landed. Inside a modal, so the list scrolls
   rather than pushing the confirm button off a laptop screen. */
.project-status-evidence {
  margin: 12px 0;
  padding: 10px 12px;
  background: var(--bg-subtle);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
}
.project-status-evidence-tally {
  margin: 0 0 2px;
  font-size: 13px;
  color: var(--text-2);
}
.project-status-evidence ul {
  max-height: 220px;
  margin: 8px 0 0;
  padding: 0;
  overflow-y: auto;
  list-style: none;
}
.project-status-evidence li {
  display: flex;
  gap: 8px;
  align-items: baseline;
  padding: 3px 0;
  font-size: 13px;
}
.project-status-evidence-no {
  flex: none;
  min-width: 16px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}
.project-status-evidence-text {
  flex: 1 1 auto;
  min-width: 0;
}
.project-status-evidence-facts {
  flex: none;
  color: var(--text-3);
  white-space: nowrap;
}
.project-status-evidence-note {
  margin: 10px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}

/* A project's stable purpose follows the live work account. Long Markdown stays complete here, so
   links, lists and code are always readable without a disclosure control or a second copy. */
.project-goal-card {
  margin-bottom: 14px;
  padding: 15px 18px 16px;
  background: var(--bg-raised);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
}
.project-goal-head,
.project-goal-heading {
  display: flex;
  align-items: center;
}
.project-goal-head {
  min-height: 24px;
}
.project-goal-heading {
  min-width: 0;
  gap: 9px;
}
.project-goal-heading .ant-typography {
  margin: 0;
}
.project-goal-icon {
  color: var(--brand);
  font-size: 18px;
}
.project-goal-content {
  margin-top: 8px;
  color: var(--text-1);
}
.project-goal-empty.ant-typography {
  margin: 8px 0 0;
}
@media (max-width: 560px) {
  .project-goal-card {
    padding: 14px;
  }
}

/* Blockers (mock 6): each open blocker's kind, the work it is about, what it asks for and its
   files, with the press that resolves it. Drawn only while something is open. A section of the
   work zone rather than a card: it stands directly above the run queue and wears that section's
   heading, so what is standing in the way and what can be started read as one block. */
.project-blockers {
  margin-bottom: 24px;
}
.project-blockers-heading.ant-typography {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.project-blockers-heading-label {
  flex: none;
  white-space: nowrap;
}
.project-blockers-summary.ant-typography {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-blockers-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.project-blockers-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px 12px;
  align-items: start;
  padding: 10px 0;
  border-top: 1px solid var(--border-subtle);
}
.project-blockers-headline {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-1);
}
.project-blockers-headline .ant-tag {
  margin-inline-end: 0;
  font-weight: 400;
}
.project-blockers-subject {
  margin-top: 2px;
  font-size: 12.5px;
  color: var(--text-2);
}
.project-blockers-subject a {
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--border);
  text-underline-offset: 2px;
}
.project-blockers-question {
  margin-top: 7px;
  font-size: 13px;
  line-height: 1.5;
  font-weight: 600;
  color: var(--text-1);
}
.project-blockers-next {
  margin-top: 2px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-3);
}
.project-blockers-next span {
  margin-right: 5px;
  color: var(--text-2);
  font-weight: 600;
}
.project-blockers-paths {
  margin-top: 6px;
  font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace;
  font-size: 11.5px;
  color: var(--text-3);
  overflow-wrap: anywhere;
}
.project-blockers-files {
  margin-top: 3px;
}
.project-blockers-files > summary {
  cursor: pointer;
  list-style-position: inside;
}
.project-blockers-files ul {
  margin: 5px 0 0;
  padding-left: 18px;
  color: var(--text-3);
}
.project-blockers-files code,
.project-blockers-dialog-evidence code {
  font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace;
  font-size: 11px;
  overflow-wrap: anywhere;
}
.project-blockers-evidence {
  margin-top: 7px;
  color: var(--text-2);
  font-size: 12px;
}
.project-blockers-evidence > summary {
  cursor: pointer;
  color: var(--text-2);
}
.project-blockers-evidence p {
  margin: 5px 0 0;
  padding-left: 18px;
  line-height: 1.55;
  white-space: pre-wrap;
}
.project-blockers-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}
.project-blockers-age {
  font-size: 11.5px;
  color: var(--text-3);
  white-space: nowrap;
}
.project-blockers-resolved {
  padding: 8px 0 0;
  border-top: 1px solid var(--border-subtle);
  font-size: 12.5px;
  color: var(--text-3);
}
.project-blockers-resolved > summary {
  cursor: pointer;
}
.project-blockers-resolved ul {
  margin: 6px 0 2px;
  padding-left: 16px;
}
.project-blockers-dialog-subject {
  margin-bottom: 10px;
  font-size: 12.5px;
  color: var(--text-2);
}
.project-blockers-dialog-question {
  margin: 0 0 12px;
  padding: 10px 12px;
  border-left: 3px solid var(--brand);
  background: var(--bg-sunken);
  color: var(--text-1);
  font-size: 13px;
  line-height: 1.55;
}
.project-blockers-dialog-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--text-3);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.project-blockers-dialog-evidence {
  margin: 0 0 12px;
  padding: 9px 11px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.55;
}
.project-blockers-dialog-evidence p {
  margin: 0;
  white-space: pre-wrap;
}
.project-blockers-dialog-evidence ul {
  margin: 0;
  padding-left: 17px;
}
.project-blockers-dialog-label {
  display: block;
  margin-bottom: 4px;
  font-size: 12.5px;
  font-weight: 600;
}
.project-blockers-dialog-foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
.project-blockers-dialog-note {
  margin-inline-end: auto;
  font-size: 11.5px;
  color: var(--text-3);
}
@media (max-width: 560px) {
  .project-blockers-row {
    grid-template-columns: minmax(0, 1fr);
  }
  .project-blockers-side {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

/* Work account and human control are one command centre: a flexible evidence card and a stable
   352px action rail. Both stretch to one row, so the overview absorbs the coordinator's height
   instead of leaving dead canvas under the title. Below 920px each gets the full reading width. */
.project-command-center {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 352px;
  gap: 14px;
  align-items: stretch;
  margin-bottom: 20px;
}
.project-command-center > * {
  min-width: 0;
}
.project-ready-heading.ant-typography {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.project-ready-heading-label {
  flex: none;
  white-space: nowrap;
}
.project-ready-summary.ant-typography {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-ready-row {
  grid-template-columns: minmax(260px, 1fr) minmax(120px, auto) auto;
}
@media (max-width: 640px) {
  .project-ready-row {
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: 12px !important;
    row-gap: 4px !important;
  }
  .project-ready-impact {
    grid-column: 1;
  }
  .project-ready-action {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
}
/* The Work overview's live landing line (ProjectPanoramaHeader): the card's one moving part, shown
   only while the platform is landing work — which is exactly the minutes its counts stand still and
   the page reads as stopped. Full width above the cells, with the same hairline under it that
   separates the cells from each other.

   The ring uses brand blue while a fresh read reports a running job. Queued jobs and unavailable
   updates remain grey and still. The state words carry the meaning without colour or motion,
   including under `prefers-reduced-motion` below. */
.project-landing {
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border-subtle);
  font-size: 13.5px;
}
.project-landing-heading {
  display: flex;
  align-items: center;
  gap: 8px;
}
.project-landing-meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 8px;
  font-size: 12px;
  color: var(--text-3);
}
.project-landing-ring {
  display: inline-flex;
  flex: none;
  color: var(--text-3);
}
.project-landing-running .project-landing-ring {
  color: var(--brand);
  animation: project-landing-spin 1.6s linear infinite;
}
.project-landing-word {
  flex: none;
  font-weight: 600;
  color: var(--text-2);
}
.project-landing-running .project-landing-word {
  color: var(--brand);
}
/* The task has its own line so the phase and elapsed clock stay readable on a phone. */
.project-landing-what {
  margin-top: 8px;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
  color: var(--text-1);
}
.project-landing-state,
.project-landing-clock {
  flex: none;
  font-size: 12.5px;
  color: var(--text-2);
}
/* Tabular figures so the count does not shuffle the words beside it as the digits change. */
.project-landing-clock {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.project-landing-running .project-landing-clock {
  color: var(--brand);
}
.project-landing-state {
  margin-left: auto;
}
.project-manual-task {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
  margin-top: 10px;
  color: var(--text-2);
}
.project-manual-open {
  display: inline-block;
  margin-top: 10px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--bg-hover-strong);
  font-weight: 600;
}
@keyframes project-landing-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .project-landing-running .project-landing-ring {
    animation: none;
  }
}
.project-work-overview > header {
  flex-wrap: wrap;
}
.project-overview-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
@media (max-width: 640px) {
  .project-overview-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 920px) {
  .project-command-center {
    grid-template-columns: minmax(0, 1fr);
  }
}
/* The rail holds the coordinator beside the overview. How it runs follows this row at full width,
   so a tall settings card cannot leave a dead strip beside the overview. */
.project-command-rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}
.project-command-rail > .project-command-coordinator {
  flex: 1 1 auto;
}

/* How it runs (mock board3 ④): the settings follow the command centre at full width. The two
   groups keep execution and integration scannable without shrinking the command input into the
   former 352px rail. */
.project-run-settings {
  margin-bottom: 20px;
}
.project-run-settings .project-open-items-hint {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  margin-left: auto;
  padding: 2px 10px;
  border-radius: 999px;
  background: var(--brand-tint);
  color: var(--brand-strong);
  font-size: 11.5px;
  font-weight: 650;
}
.project-run-settings-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 14px 0 18px;
  padding: 11px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 9px;
  background: var(--brand-tint);
  font-size: 13px;
}
.project-run-settings-summary-dot {
  flex: none;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--brand);
}
.project-run-settings-summary > div {
  display: grid;
  gap: 2px;
}
.project-run-settings-summary strong {
  color: var(--text-1);
  font-weight: 650;
}
.project-run-settings-summary span:not(.project-run-settings-summary-dot) {
  color: var(--text-2);
}
.project-run-settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 28px;
}
.project-run-settings-group {
  min-width: 0;
}
.project-run-settings-group-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.project-run-settings-group-head::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border-subtle);
}
.project-run-settings-grid .project-integration-setting {
  grid-template-columns: 132px minmax(0, 1fr);
  gap: 12px;
}
.project-run-settings-grid .project-integration-setting-label {
  padding-top: 4px;
}
.project-run-settings-grid .project-run-lines .ant-radio-wrapper-disabled {
  color: var(--text-1);
  cursor: default;
}
.project-run-settings-grid .project-run-lines .ant-radio-wrapper-disabled .ant-radio-disabled + span {
  color: var(--text-1);
}
.project-run-settings-grid .project-run-lines .ant-radio-disabled.ant-radio-checked .ant-radio-inner {
  border-color: var(--brand);
  background: var(--brand);
}
.project-run-settings-grid .project-run-lines .ant-radio-disabled.ant-radio-checked .ant-radio-inner::after {
  background-color: #fff;
}
.project-run-settings-grid .start-card-mono,
.project-run-settings-grid .start-card-mono input {
  width: 100%;
}
.project-run-settings-grid .project-integration-setting.is-warn .ant-input {
  width: 100%;
}
.project-run-settings .project-integration-setting-actions {
  padding-top: 16px;
  border-top: 1px solid var(--border-subtle);
}
.project-run-settings-loading {
  padding: 16px 0 8px;
  text-align: center;
}
.project-run-settings-error {
  margin-top: 10px;
}
@media (max-width: 920px) {
  .project-run-settings-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 4px;
  }
}
@media (max-width: 640px) {
  .project-run-settings .project-open-items-head {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }
  .project-run-settings .project-open-items-hint {
    margin-left: 0;
  }
  .project-run-settings-grid .project-integration-setting {
    grid-template-columns: minmax(0, 1fr);
    gap: 6px;
  }
  .project-run-settings-grid .project-integration-setting-label {
    padding-top: 0;
  }
}

/* A task row has flexible copy followed by a fixed count and, sometimes, a disclosure. AntD's
   List.Meta can visually paint an unbroken identifier outside its computed flex width: its inner
   content uses width:0 but has no emergency wrap point. That overflow belongs to the document
   scroller, so one source-symbol list such as `NewProjectDraft|EMPTY_NEW_PROJECT_DRAFT|...` can
   make the whole project page desktop-wide on a phone. The owned wrapper supplies a real
   shrink-to-fit boundary and the two text spans add wrap opportunities without truncating the
   title or changing the criteria excerpt. */
.project-task-row-layout {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  min-width: 0;
}
.project-task-row-copy,
.project-task-row-meta,
.project-task-row-meta .ant-list-item-meta-content {
  min-width: 0;
}
.project-task-row-copy {
  flex: 1;
}
.project-task-row-title,
.project-task-row-description {
  overflow-wrap: anywhere;
}
.project-task-row-count,
.project-task-row-disclosure {
  flex: none;
}
.project-task-row-count {
  white-space: nowrap;
}
.project-task-children {
  min-width: 0;
  margin-block-start: 8px;
  margin-inline-start: 32px;
}
/* A row opens its task over the page (ProjectTaskRow) and is tinted the way a Tasks page row is —
   the same two tokens for "under the pointer" and "open in the panel". The inline padding gives
   the tint room at the row's edges; the negative margin keeps the words where they were. Scoped
   under .ant-list to outrank AntD's own item padding without !important. */
.ant-list .project-task-row.is-openable {
  cursor: pointer;
  padding-inline: 12px;
  margin-inline: -12px;
}
.project-task-row.is-openable:hover {
  background: var(--bg-hover);
}
.project-task-row.is-open {
  background: var(--brand-tint);
}
.project-task-row.is-open:hover {
  background: var(--brand-border);
}
/* The title is a link for ⌘/middle-click and the keyboard; to the eye it is the row's title. */
.project-task-row-link,
.project-task-row-link:hover {
  color: inherit;
}
/* A task open over its project's page (ProjectTaskPanel) — the Tasks page's panel, lying over the
   page instead of beside it. The page is a whole document (graph, cards, the task list) and
   narrowing it would re-flow all of it, carrying the row that was pressed out of view; the Tasks
   page narrows its table instead, which suits a table. At ≤960px both are the same full-screen page
   (the panel's own rule). */
@media (min-width: 961px) {
  .project-task-panel > .task-detail-panel {
    position: fixed;
    top: 0;
    right: 0;
    z-index: 40;
    box-shadow: -12px 0 32px rgba(31, 35, 41, 0.1);
  }
}
/* Preserve the reading order but stop fixed metadata from squeezing the identity down to a few
   characters: the full title/excerpt gets the first band, then count + disclosure share the next. */
@media (max-width: 640px) {
  .project-task-row-layout {
    align-items: flex-start;
    flex-wrap: wrap;
    column-gap: 12px;
    row-gap: 8px;
  }
  .project-task-row-copy {
    flex: 1 0 100%;
  }
  .project-task-children {
    margin-inline-start: 16px;
  }
}

/* The acceptance section: the criteria this project states, as one full-width card between the
   goal and the task list. It used to be the narrow half of a 1.32 : 1 pair with the blocking
   ranking, which had the widths backwards — the ranking is horizontal bars that need room, and
   criteria are whole sentences that were being wrapped to four lines each.

   The card's body padding is 0 and every block below sets its own, so a row spans the full width
   instead of floating inside a 24px gutter. Migration 0229 removed the project acceptance
   judgment, so a row no longer carries a verdict and the head no longer carries a meter. */
.acceptance-card {
  margin-bottom: 24px;
}
.acceptance-standing {
  padding: 12px 24px;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.6;
}
.acceptance-block {
  padding: 12px 24px;
}
.acceptance-criteria {
  margin: 0;
  padding: 0;
  list-style: none;
}
.acceptance-row {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 9px 24px;
  border-top: 1px solid var(--border-subtle);
}
/* A failed criterion is the one row a reader is scanning 53 of them for. Tint plus an edge accent
   plus the badge: three signals, only one of which is a hue. */
.acceptance-row.is-fail {
  background: var(--error-bg);
}
.acceptance-row.is-fail::before {
  content: '';
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  width: 2px;
  background: var(--error-solid);
}
/* The row's ONE mark: the number IS the state. SHAPE BEFORE HUE — met is a filled disc, unmet is
   a 2px ring around nothing, and a criterion the read did not answer for is a dashed ring; the
   three stay apart in greyscale and for a reader who cannot separate the hues, so colour is the
   second signal here and never the only one. The unmet ring is drawn in near-black deliberately:
   against a white row it carries MORE weight than the filled disc, which puts the emphasis on the
   rows that still want somebody.

   Until 2026-09-06 the state was a separate 10px dot beside the number. On a phone the number is
   a 36px disc, so that put two circles in the gutter with the meaningless one 3.6x the size of
   the one carrying the meaning, and the dot was read as a bullet. One mark, drawn three ways.

   22px on the desktop rather than the phone's 36px: desktop rows are denser and a 36px disc would
   become the page's subject instead of the criterion beside it. */
.acceptance-row-no {
  flex: none;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  margin-top: 1px;
  border-radius: 50%;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.acceptance-row-no.is-met {
  border: 1px solid var(--success);
  background: var(--success);
  /* Knocked out of the fill, which is what makes it reversed in BOTH themes: white on the light
     theme's #1a7f37, and the dark theme's own page colour on its lighter green — where white
     would sit at 2.3 : 1. */
  color: var(--bg-base);
}
.acceptance-row-no.is-unmet {
  border: 2px solid var(--text-1);
  background: transparent;
  color: var(--text-1);
}
/* No answer, drawn as no answer. The read did not report on this criterion, so the ring is dashed
   and grey: a solid ring would say "not met", which is a claim nobody made. */
.acceptance-row-no.is-unanswered {
  border: 1px dashed var(--border);
  background: transparent;
  color: var(--text-3);
  font-weight: 400;
}
.acceptance-row-text {
  flex: 1;
  min-width: 0;
  line-height: 1.66;
}
/* What the read says about a criterion's work, under the criterion itself. A SENTENCE, still not
   a pill and not a rail: 0229 deleted a per-row verdict and a head meter, and this is a different
   kind of thing — computed from task rows, written by nobody — so it must not arrive dressed as
   the score that was removed. It sits at the standing line's size rather than the row text's: it
   answers the criterion, it does not compete with it. At 12px in the third grey it was the right
   sentence set as a footnote, and nobody read it. */
.acceptance-work {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
  margin-top: 4px;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.55;
}
/* The one hue in the row, and it lands on three words rather than behind the whole line.
   UNMET IS NOT RED. A project stated this morning has met none of its criteria and has failed
   nothing; fifty-three red rows would tell its owner the project was broken. It is given weight
   instead — full text colour at 600 — which also clears AA at 13px, where --warning (3.7 : 1)
   does not. */
.acceptance-work-state.is-met {
  color: var(--success);
}
.acceptance-work-state.is-unmet {
  color: var(--text-1);
  font-weight: 600;
}
/* Printed only beside work that HAS met its criterion, where both values appear: the ordinary
   one recedes, and the one with no receipt behind it comes up to full text colour, because a
   criterion reported met by work nothing puts on the default branch is the exact false green
   this card exists to keep visible. */
.acceptance-landing {
  color: var(--text-2);
}
.acceptance-landing.is-flagged {
  color: var(--text-1);
}
.acceptance-landing::before {
  content: '· ';
  color: var(--text-3);
}
/* "not on main yet", the tail of a criterion met on the project branch: warn text, so the one
   thing a reader skimming a green row must not miss is the one thing that is not receded. */
.acceptance-landing-warn {
  color: var(--warning-text, var(--warning-solid));
}
.acceptance-unmet {
  margin-top: 5px;
  font-size: 12px;
  line-height: 1.55;
}
.acceptance-unmet-reason + .acceptance-unmet-reason {
  margin-top: 6px;
}
.acceptance-unmet-clause {
  color: var(--text-2);
}
/* One task holding a reason open, and what would settle it. Indented under its reason so a
   criterion with two reasons reads as two groups rather than one run of names. */
.acceptance-held-up {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
  margin-top: 3px;
  padding-inline-start: 10px;
  border-inline-start: 2px solid var(--border-subtle);
  color: var(--text-3);
}
.acceptance-held-up-title {
  color: var(--brand-strong);
}
.acceptance-held-up-title:hover {
  color: var(--brand-strong);
  text-decoration: underline;
}
/* What that task needs, as a sentence, and readable as one: inheriting the container's --text-3
   put it at 3.0 : 1 on white — the same contrast the state line was pulled out of. A raw code
   this build does not recognise keeps the receded chip, because it is a value and not prose. */
.acceptance-held-up-action {
  color: var(--text-2);
}
.acceptance-held-up-action .ant-typography code {
  margin-inline: 0;
  font-size: 11px;
}
/* "How it's checked" — the method the OWNER wrote beside the criterion, folded away because it
   is what a reader needs when they are about to go and check one, not while they are reading down
   the list. Styled as the quiet twisty it is rather than as a button: nothing about it should
   compete with the state sentence above it. */
.acceptance-method {
  margin-top: 5px;
  font-size: 12px;
  line-height: 1.55;
}
.acceptance-method-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  /* A 10px triangle beside 12px text is a 15px-high target that reads as decoration. The row is
     given a real height and the label is underlined, so it is visibly something to press before
     anybody has hovered it — still the quiet twisty, no longer a hairline. */
  min-height: 24px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-2);
  font: inherit;
  text-decoration: underline;
  text-decoration-color: var(--border);
  text-underline-offset: 2px;
  cursor: pointer;
}
.acceptance-method-toggle:hover {
  color: var(--text-1);
  text-decoration-color: currentColor;
}
.acceptance-method-marker {
  color: var(--text-3);
  font-size: 12px;
  text-decoration: none;
}
.acceptance-method-body {
  margin-top: 4px;
  padding-inline-start: 10px;
  border-inline-start: 2px solid var(--border-subtle);
  color: var(--text-2);
}
.acceptance-more-meta.ant-typography {
  margin-inline-start: 10px;
  font-size: 12px;
}
.acceptance-note {
  padding: 10px 24px 12px;
  border-top: 1px solid var(--border-subtle);
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.6;
}
.acceptance-note-compact {
  display: none;
}
/* On a phone Acceptance becomes a compact, inspectable summary rather than a long table. Four
   complete rows establish the shape of the criteria and the list disclosure names everything
   that is not initially on screen. Complete means complete: a row draws the whole criterion and
   the sentence uses the whole card width, because clamping it to three lines behind a per-row
   chevron cost 88px of every line (a 36px number, a rail sized for a verdict 0229 deleted) to
   show a condition cut mid-clause. Keep this breakpoint identical to ACCEPTANCE_PHONE_QUERY in
   ProjectAcceptanceCard.tsx. */
@media (max-width: 560px) {
  .acceptance-card.ant-card {
    overflow: hidden;
    border-radius: 12px;
    box-shadow: 0 2px 10px rgba(31, 35, 41, 0.06);
  }
  :root[data-theme='dark'] .acceptance-card.ant-card {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.24);
  }
  /* The meter belongs to the whole reading, so on a phone it spans the head instead of sitting
     under only the right-aligned number. The Card head is the positioned containing block. */
  .acceptance-card.has-meter .ant-card-head {
    position: relative;
    min-height: 92px;
    padding-bottom: 26px;
  }
  .acceptance-card .ant-card-head {
    padding-inline: 16px;
  }
  .acceptance-card .ant-card-head-wrapper {
    min-height: 56px;
  }
  .acceptance-card .ant-card-head-title {
    font-size: 18px;
  }
  .acceptance-standing {
    margin: 12px 16px 8px;
    padding: 13px 14px;
    border: 1px solid var(--border-subtle);
    border-radius: 8px;
    background: var(--bg-subtle);
    font-size: 13px;
    line-height: 1.5;
  }
  .acceptance-row {
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr);
    align-items: start;
    column-gap: 12px;
    row-gap: 4px;
    padding: 12px 16px;
  }
  .acceptance-row:first-child {
    border-top: 0;
  }
  /* The 36px disc this gutter has drawn since c5343b96 keeps its size and gains the meaning: same
     three states as the desktop, scaled. It no longer shares the column with anything — the 54px
     that held a dot beside it is gone with the dot. */
  .acceptance-row-no {
    grid-column: 1;
    width: 36px;
    height: 36px;
    margin-top: 0;
    font-size: 14px;
  }
  .acceptance-row-text {
    grid-column: 2;
    padding-top: 1px;
    font-size: 14.5px;
    line-height: 1.55;
    overflow-wrap: anywhere;
  }
  .acceptance-more {
    padding: 10px 16px 8px;
    text-align: center;
  }
  .acceptance-more-button.ant-btn {
    min-height: 44px;
    border-color: var(--border-subtle);
    border-radius: 8px;
    background: var(--bg-subtle);
    color: var(--text-1);
    font-weight: 600;
  }
  .acceptance-more-button.ant-btn:hover {
    border-color: var(--border);
    background: var(--bg-hover);
    color: var(--text-1);
  }
  .acceptance-more-icon {
    margin-inline-start: 8px;
    font-size: 11px;
    transition: transform 160ms ease;
  }
  .acceptance-more-icon.is-expanded {
    transform: rotate(180deg);
  }
  .acceptance-more-meta.ant-typography {
    display: block;
    margin: 6px 0 0;
    font-size: 11.5px;
  }
  /* The landing half wraps on a 393px screen whatever it is given, and the separator that joins
     it to the state sentence on a desktop then hangs alone at the head of the new line. Narrow,
     it takes a line of its own and drops the dot: the two facts are still adjacent, and nothing
     is left dangling. */
  .acceptance-landing {
    flex-basis: 100%;
  }
  .acceptance-landing::before {
    content: none;
  }
  .acceptance-method-toggle {
    min-height: 32px;
  }
  .acceptance-note {
    padding: 9px 16px 11px;
    text-align: center;
  }
  .acceptance-note-wide {
    display: none;
  }
  .acceptance-note-compact {
    display: inline;
  }
}

@media (max-width: 560px) and (prefers-reduced-motion: reduce) {
  .acceptance-more-icon {
    transition: none;
  }
}

/* Projects has one heading row and one filter row. Lifecycle history is an action beside the
   heading; the segmented control below always narrows the CURRENT scope, so Open never pretends
   to be a sibling of Running or Ready. */
.projects-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.projects-title-row .page-title {
  flex: 1;
  min-width: 0;
}
.projects-title-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}
.projects-scope-action {
  color: var(--text-2);
}
.projects-new-button {
  flex: none;
}
.projects-toolbar {
  display: grid;
  gap: 12px;
  margin: 16px 0 6px;
}
.projects-toolbar-search {
  width: 100%;
}
.projects-toolbar-scope {
  display: flex;
  align-items: center;
  gap: 12px;
}
.projects-toolbar-scope-label {
  flex: none;
  min-width: 88px;
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-2);
}
.projects-toolbar-filter {
  width: min(100%, 360px);
}
.projects-toolbar-filter .ant-segmented-item {
  flex: 1;
}

/* Projects list rows. Every row is exactly two lines tall — one title, one goal — because the
   goal is truncated by the box rather than by a character count: how many rendered lines 180
   characters occupy depends on how much of them is CJK (a full-width glyph is twice a Latin one),
   which is what had these rows jumping between 150px and 220px. Sizes track
   projects-redesign.html: 11px of row padding (set inline, where it beats AntD's own
   token-generated rule), a 14px/600 title and a 12.5px goal in --text-3.

   Laid out here rather than through List.Item.Meta: that component's title and description carry
   their own margins, which a fixed row height cannot inherit, and its internal element names have
   already been renamed under us once (antd 5 → 6). */
.project-row-link {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  color: inherit;
}
/* min-width:0 the whole way down is what lets `text-overflow` fire at all: a flex item's floor is
   its content's intrinsic width, so without this the row grows instead of the text ellipsing. */
.project-row-main {
  flex: 1;
  min-width: 0;
}
.project-row-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin-bottom: 3px;
}
/* The title is the only thing that gives up width; the status tag beside it keeps its own. */
.project-row-head > * {
  flex: none;
}
.project-row-title {
  flex: 0 1 auto;
  min-width: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-1);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.project-row-goal {
  font-size: 12.5px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* The two right-hand columns, both fixed-width so the bars and the dates line up down the page —
   a meter that starts at a different x on every row cannot be compared to the one above it.
   Sizes track projects-redesign.html. */
.project-row-meter {
  width: 196px;
  flex: none;
}
/* 6px of bar, then 6px of air, then the figures. The bar's own segments (2px surface gaps, a 3px
   floor under a non-zero bucket, 4px rounded at the two outer ends only) are BucketMeter's, shared
   with the project page's header — see ProjectPanoramaHeader. */
.project-row-buckets {
  display: flex;
  gap: 11px;
  margin-top: 6px;
  font-size: 11.5px;
  color: var(--text-3);
  /* Tabular figures so 1,204 under 118 stays a column of digits rather than a ragged edge. */
  font-variant-numeric: tabular-nums;
}
.project-row-buckets > span {
  display: flex;
  align-items: center;
  gap: 3.5px;
}
/* The figure is the channel that survives when the colour does not, so it reads darker and heavier
   than the row's other secondary text — never as quiet as the label beside it. */
.project-row-buckets b {
  font-weight: 600;
  color: var(--text-2);
}
.project-row-when {
  width: 78px;
  flex: none;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.project-row-activity {
  display: block;
  font-size: 12px;
  color: var(--text-2);
}
/* Scale, not status: one step quieter than the time above it, which is the number that orders the
   page. */
.project-row-count {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--text-4);
  white-space: nowrap;
}

/* The row's badge: "Needs you · Critical · 3d · 2 blockers", "Running · no activity 3d", or
   "12/12 settled · still open". Sized from
   projects-redesign.html — 11px/600 in a 5px pill. It keeps its own width through the
   `.project-row-head > *` rule above, which is what stops the badge from being the thing that
   ellipses when a long title runs out of room.

   Both tones are the theme's own tokens, so they follow the palette into dark mode instead of
   carrying a hex apiece: amber for a row that is wrong, brand for one that is merely unfinished. */
.project-row-chip {
  font-size: 11px;
  font-weight: 600;
  line-height: 18px;
  padding: 0 7px;
  border-radius: 5px;
  white-space: nowrap;
  letter-spacing: 0.2px;
}
.project-row-chip-warning {
  background: var(--warning-bg);
  border: 1px solid var(--warning-border);
  color: var(--warning);
}
.project-row-chip-brand {
  background: var(--brand-tint);
  border: 1px solid var(--brand-border);
  color: var(--brand-strong);
}

/* Where this project's finished work lands, beside the chip that says what to do about the project
   (contract §7.1 V1/V2, mock 1 ④): `⎇ project/bg-jobs` for a project branch, `main` for a project
   that merges straight into it.

   Neutral on purpose. The chip to its left is the signal — an amber row wants somebody — and this
   one is a fact about the project that never changes and never asks. Drawn in the mock's own
   tokens so it follows the palette into dark mode, and sized to the chip beside it so the two read
   as one line of metadata rather than two competing badges. */
.project-row-line {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 18px;
  padding: 0 7px;
  border-radius: 5px;
  background: var(--fill-muted);
  color: var(--text-1);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  letter-spacing: 0.2px;
}
/* The branch mark is the glyph's shape, not its colour: it says "branch" and the name says which. */
.project-row-line svg {
  color: var(--text-3);
}

/* ---- Projects list on a phone ----
   The row above is `text | 196px meter | 78px dates`, and none of it wraps. On a 393px phone the
   row is 341px wide, so those two fixed columns and their 16px gaps take 306px — and the title,
   the one item in the line that can shrink, is computed at 0px. Not truncated: ZERO, not one
   character drawn, while the badges beside it (which are `flex: none`) overflow the box and paint
   on top of the meter. What a reader could still see on that row was the goal underneath.

   So the row folds into two bands: the text takes a line of its own, the meter and the dates share
   the next one. Everything here is a narrow-screen override — the desktop rules above are
   untouched, and this block is the only place that knows a phone exists.

   640px, not the app's existing 960px: 960 is where three columns stop fitting, this is where
   306px of fixed columns stops fitting. A portrait tablet at 768px still has a 736px row and reads
   the original layout fine, so it is deliberately left out. Kept identical to
   PROJECTS_PHONE_QUERY, which decides the same question for the two things CSS cannot do here. */
@media (max-width: 640px) {
  .projects-title-actions {
    gap: 2px;
  }
  .projects-scope-action {
    padding-inline: 8px;
  }
  .projects-new-button {
    width: 40px;
    height: 40px;
    padding: 0;
  }
  /* The plain label establishes the parent scope; the only selectable row stays below it and
     uses three equal, phone-sized targets. */
  .projects-toolbar-scope {
    display: block;
  }
  .projects-toolbar-scope-label {
    min-width: 0;
    margin-bottom: 8px;
  }
  .projects-toolbar-filter {
    width: 100%;
  }

  /* The header's small print explains what the section is ordered by. Worth a line on a desktop,
     three lines above the rows here. */
  .project-section-note {
    display: none;
  }

  .project-row-link {
    flex-wrap: wrap;
    /* Narrower than the gap between two rows: these are two bands of one row, and if the split
       reads as wide as a row boundary the list stops having rows. */
    row-gap: 9px;
  }
  .project-row-main {
    flex: 1 0 100%;
  }
  /* Belt and braces. The title gives up width before anything else does, so with the full line to
     itself the badges no longer overflow — but the box that overflowed onto the meter is this one,
     and it should not be able to do that again. */
  .project-row-head {
    overflow: hidden;
  }
  .project-row-meter {
    width: auto;
    flex: 1 1 auto;
    min-width: 0;
  }
}

/* ── Watches (docs/watch-contract.md): the Following page, watch cards, the session and task
   relations, and the transcript card for a turn a watch queued. A watch is not a process, so none of
   this borrows the Background processes tray's look (contract §9.2). */
