  color: var(--warning);
}

/* Carries its own vertical margin rather than living off its neighbour's: two wakes in a row —
   one watch firing twice, or two watches at once — have no message bubble between them to lend
   theirs, and used to touch. 8px is what .chat-msg uses, and adjacent margins collapse, so a wake
   next to a message keeps the spacing it already had. */
.watch-wake-wrap {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
}
.watch-wake {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: var(--brand-tint);
  color: var(--text-1);
}
.watch-wake.is-expired,
.watch-wake.is-revoked,
.watch-wake.is-unresolvable {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.watch-wake-title {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brand);
  font-weight: 600;
}
.watch-wake.is-expired .watch-wake-title,
.watch-wake.is-revoked .watch-wake-title,
.watch-wake.is-unresolvable .watch-wake-title {
  color: var(--warning);
}
.watch-wake-why {
  margin: 3px 0 6px;
}
.watch-wake-changed {
  margin: 0 0 6px;
  padding: 0;
  font-size: 12px;
  list-style: none;
}
.watch-wake-meta {
  color: var(--text-2);
  font-size: 12px;
}
.watch-wake-undelivered {
  margin-top: 4px;
  color: var(--warning);
  font-size: 12px;
}
.watch-wake-links {
  margin-top: 6px;
  font-size: 12px;
}
.watch-wake-raw {
  margin-top: 6px;
  font-size: 12px;
}
.watch-wake-raw summary {
  color: var(--text-2);
  cursor: pointer;
}
.watch-wake-raw pre {
  max-height: 320px;
  margin: 6px 0 0;
  padding: 8px;
  overflow: auto;
  border-radius: 6px;
  background: var(--fill-inset);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
}
/* A wake still waiting behind the running turn (WorkspaceView's queued tail): dashed like a queued
   message, with the queue's status line at its foot. What withdrawing it costs takes a line of its
   own under the state and the action, rather than the one-line ellipsis a delivery failure gets. */
.watch-wake.is-queued {
  border-style: dashed;
}
.watch-wake-queued {
  margin-top: 6px;
}
.watch-wake-queued .chat-queued-meta {
  flex-wrap: wrap;
  justify-content: flex-start;
  row-gap: 2px;
}
.watch-wake-queued .chat-queued-why {
  order: 1;
  flex-basis: 100%;
  white-space: normal;
}
/* The turn the control plane opened for a background job's news, or for a wakeup coming due
   (BackgroundWakeCard): one event line in the agent's stream, in the grammar `⊘ interrupted`
   (.chat-note) already uses, rather than a card on the reader's side of the conversation — which is
   where their own messages sit, in their tint, so a run of wakes read as somebody cutting in. A
   job that failed or was killed takes the error tone and keeps its tail out of the fold. */
.bgwake {
  margin: 6px 0;
  font-size: 13px;
  color: var(--text-3);
}
.bgwake-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  padding: 3px 4px;
  border-radius: 6px;
  list-style: none;
  cursor: pointer;
}
.bgwake-row::-webkit-details-marker {
  display: none;
}
.bgwake-row:hover {
  background: var(--bg-sunken);
}
.bgwake-mark {
  flex: none;
  align-self: center;
  display: inline-flex;
  color: var(--success-solid);
}
.bgwake.is-failed .bgwake-mark {
  color: var(--error-solid);
}
.bgwake-mark.is-pending {
  color: var(--text-3);
}
.bgwake-title {
  flex: none;
}
.bgwake.is-failed .bgwake-title {
  color: var(--error);
}
/* The one line gives way here: the title, how it came out and when stay whole, and all of the name
   is in the fold. */
.bgwake-name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--text-2);
}
.bgwake-name.is-command {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12px;
}
/* A phone leaves the name a few letters beside the title, so there it takes a line of its own,
   lined up under the title. */
@media (max-width: 600px) {
  .bgwake-row {
    flex-wrap: wrap;
  }
  .bgwake-name {
    order: 1;
    flex-basis: 100%;
    padding-left: 20px;
  }
}
.bgwake-status {
  flex: none;
  padding: 0 6px;
  border-radius: 5px;
  background: var(--fill-muted);
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11px;
}
.bgwake-time {
  flex: none;
  font-size: 12px;
}
.bgwake-details-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: none;
  margin-left: auto;
  font-size: 12px;
}
.bgwake-caret {
  flex: none;
  align-self: center;
  color: var(--text-4);
  font-size: 10px;
  transition: transform 0.15s;
}
.bgwake-fold[open] > .bgwake-row .bgwake-caret {
  transform: rotate(90deg);
}
/* What the line carried, opened: hung under its title, off a rule, like a tool card's detail. */
.bgwake-body {
  margin: 2px 0 6px 22px;
  padding: 6px 10px;
  border-left: 2px solid var(--border-subtle);
  font-size: 12px;
}
.bgwake-jobs,
.bgwake-wakeups {
  margin: 0 0 6px;
  padding: 0;
  list-style: none;
}
.bgwake-job + .bgwake-job,
.bgwake-wakeup + .bgwake-wakeup {
  margin-top: 8px;
}
.bgwake-job-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
  color: var(--text-2);
}
.bgwake-job-mark {
  flex: none;
}
.bgwake-job-mark.is-ok {
  color: var(--success-solid);
}
.bgwake-job-mark.is-failed {
  color: var(--error-solid);
}
.bgwake-job-mark.is-running {
  color: var(--text-3);
}
.bgwake-job-name {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
}
.bgwake-job-exit {
  flex: none;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--fill-inset);
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11px;
}
.bgwake-job-cmd,
.bgwake-job-meta {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11px;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}
.bgwake-job-cmd {
  margin-top: 2px;
  color: var(--text-2);
}
.bgwake-job-meta {
  margin-top: 2px;
  color: var(--text-3);
}
.bgwake-wakeup-reason {
  margin-bottom: 2px;
  color: var(--text-2);
}
.bgwake-wakeup .chat-pre-wrap {
  margin-top: 6px;
}
.bgwake-meta {
  color: var(--text-3);
}
.bgwake-raw {
  margin-top: 4px;
}
.bgwake-raw summary {
  color: var(--text-2);
  cursor: pointer;
}
.bgwake-raw pre {
  max-height: 320px;
  margin: 6px 0 0;
  padding: 8px;
  overflow: auto;
  border-radius: 6px;
  background: var(--fill-inset);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
}
/* Whatever else the same note carried, folded in with the rest of what the line carried. */
.bgwake-body > .chat-injected {
  margin-top: 8px;
}
.bgwake-tail {
  margin: 6px 0 6px 22px;
  padding: 10px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: var(--bg-sunken);
}
.bgwake-tail-name {
  margin-bottom: 2px;
  color: var(--text-2);
  font-size: 12px;
}
.bgwake-output > summary {
  list-style: none;
  cursor: pointer;
}
.bgwake-output > summary::-webkit-details-marker {
  display: none;
}
.bgwake-output-label {
  display: block;
  margin-bottom: 6px;
  font-size: 12px;
  color: var(--text-3);
}
/* Clamp visual lines: one long JSON line must be as compact as multiline output. */
.bgwake-output-preview {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-height: 1.6;
  max-height: 4.8em;
  overflow: hidden;
}
.bgwake-output-action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  color: var(--brand);
  font-size: 12px;
}
.bgwake-output-collapse,
.bgwake-output[open] .bgwake-output-preview,
.bgwake-output[open] .bgwake-output-expand {
  display: none;
}
.bgwake-output[open] .bgwake-output-collapse {
  display: inline;
}
.bgwake-output[open] .bgwake-output-action .anticon {
  transform: rotate(180deg);
}
.bgwake-output-full {
  margin-top: 6px;
  line-height: 1.6;
}
.bgwake-undelivered {
  margin: 2px 0 0 22px;
  color: var(--warning);
  font-size: 12px;
}
/* A wake written into the running turn: delivery progress in the same quiet tone as a steer. */
.bgwake-steer {
  margin: 2px 0 0 22px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--text-3);
}
/* Still waiting behind the running turn (WorkspaceView's queued tail): dashed like a queued
   message, with the queue's own status line under it. */
.bgwake.is-queued .bgwake-row {
  border: 1px dashed var(--border);
}
.bgwake-queued {
  margin: 4px 0 0 22px;
}
.bgwake-queued .chat-queued-meta {
  flex-wrap: wrap;
  justify-content: flex-start;
  row-gap: 2px;
}
/* An exception item's delivery to the coordinator (components/OpenItemDeliveryCard.tsx): the same
   card shape as a watch's wake — right-aligned, control-plane-owned — with the item's own fields
   drawn instead of the paragraph they were rendered into. Amber rather than brand: an exception
   item is something nobody's work is waiting behind, and every one of them is somebody's to decide. */
.oic-wrap {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
}
.oic {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--warning-border);
  border-radius: 12px;
  background: var(--warning-bg);
  color: var(--text-1);
}
.oic-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--warning);
  font-weight: 600;
}
.oic-mark {
  flex: none;
}
.oic-kind {
  margin-left: auto;
  flex: none;
  padding: 0 8px;
  border: 1px solid var(--warning-border);
  border-radius: 9px;
  background: var(--bg-raised);
  color: var(--text-2);
  font-size: 11px;
  font-weight: 500;
  line-height: 18px;
}
.oic-title {
  margin: 4px 0 2px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.oic-where {
  color: var(--text-2);
  font-size: 12px;
}
.oic-where a {
  color: var(--brand);
  text-decoration: none;
}
.oic-why {
  margin-top: 8px;
}
.oic-files {
  margin: 6px 0 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--bg-raised);
  list-style: none;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12px;
}
.oic-files li {
  overflow-wrap: anywhere;
}
.oic-more {
  margin-top: 6px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--brand);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.oic-facts {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--bg-raised);
  font-size: 12px;
}
.oic-facts.is-landed {
  color: var(--success);
}
.oic-facts.is-unknown {
  color: var(--text-2);
}
.oic-facts-mark {
  flex: none;
}
.oic-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  font-size: 12px;
}
.oic-actions-label {
  color: var(--text-2);
}
.oic-chip {
  padding: 1px 8px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg-raised);
  color: var(--text-1);
  font-size: 12px;
}
.oic-links {
  display: flex;
  gap: 12px;
  margin-top: 6px;
  font-size: 12px;
}
.oic-links a {
  color: var(--brand);
  text-decoration: none;
}
.oic-meta {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-hover-strong);
  color: var(--text-3);
  font-size: 11px;
}
.oic-undelivered {
  margin-top: 4px;
  color: var(--warning);
  font-size: 12px;
}
.oic-raw {
  margin-top: 6px;
  font-size: 12px;
}
.oic-raw summary {
  color: var(--text-2);
  cursor: pointer;
}
.oic-raw pre {
  max-height: 320px;
  margin: 6px 0 0;
  padding: 8px;
  overflow: auto;
  border-radius: 6px;
  background: var(--fill-inset);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
}
/* A delivery still waiting behind the running turn (WorkspaceView's queued tail): dashed like a
   queued message, with the queue's status line at its foot, so taking the turn changes nothing
   about how the delivery reads. Same shape the two wakes take while they wait. */
.oic.is-queued {
  border-style: dashed;
}
.oic-queued {
  margin-top: 6px;
}
.oic-queued .chat-queued-meta {
  flex-wrap: wrap;
  justify-content: flex-start;
  row-gap: 2px;
}
.oic-queued .chat-queued-why {
  order: 1;
  flex-basis: 100%;
  white-space: normal;
}
/* The turn that starts a task's run (components/TaskStartCard.tsx): the same card shape as the two
   above — right-aligned, control-plane-owned — drawing the task the brief was built from instead of
   the brief. Brand-toned like a wake, but a shade lighter than the owner's own bubble so the two
   never read as the same thing. */
.tsc-wrap {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
}
.tsc {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--brand-tint) 50%, var(--bg-raised));
  color: var(--text-1);
}
.tsc-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brand);
  font-weight: 600;
}
.tsc-mark {
  flex: none;
}
.tsc-auto {
  margin-left: auto;
  flex: none;
  padding: 0 8px;
  border: 1px solid var(--brand-border);
  border-radius: 9px;
  background: var(--bg-raised);
  color: var(--text-2);
  font-size: 11px;
  font-weight: 500;
  line-height: 18px;
}
.tsc-title {
  margin: 4px 0 2px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.tsc-where {
  color: var(--text-2);
  font-size: 12px;
}
.tsc-where a,
.tsc-links a {
  color: var(--brand);
  text-decoration: none;
}
.tsc-desc {
  margin-top: 6px;
}
/* Folded to three lines until Show details: the description is what identifies the work, and its
   start is usually the whole of what a reader needs from it. */
.tsc-desc.is-folded {
  position: relative;
  max-height: 4.6em;
  overflow: hidden;
}
.tsc-desc.is-folded::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1.4em;
  background: linear-gradient(transparent, color-mix(in srgb, var(--brand-tint) 50%, var(--bg-raised)));
}
.tsc-section {
  margin-top: 10px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
}
.tsc-body {
  margin-top: 2px;
}
/* Set like the Markdown beside it (`.md`), so plain criteria do not read as a different size. */
.tsc-plain {
  font-size: 14px;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.tsc-judged {
  margin-top: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--bg-raised);
  font-size: 12px;
}
.tsc-judged-line {
  font-weight: 500;
}
.tsc-judged-how {
  margin-top: 2px;
  color: var(--text-2);
}
.tsc-command {
  margin: 6px 0 0;
  color: var(--text-2);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-all;
}
.tsc-command.is-one-line {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.tsc-command.is-clamped {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
.tsc-more {
  padding: 0;
  border: 0;
  background: none;
  color: var(--brand);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.tsc-judged .tsc-more {
  margin-top: 4px;
}
.tsc-links {
  display: flex;
  gap: 12px;
  margin-top: 8px;
  font-size: 12px;
}
.tsc-links a {
  margin-left: auto;
}
.tsc-meta {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-hover-strong);
  color: var(--text-3);
  font-size: 11px;
}
.tsc-undelivered {
  margin-top: 4px;
  color: var(--warning);
  font-size: 12px;
}
.tsc-raw {
  margin-top: 6px;
  font-size: 12px;
}
.tsc-raw summary {
  color: var(--text-2);
  cursor: pointer;
}
.tsc-raw pre {
  max-height: 320px;
  margin: 6px 0 0;
  padding: 8px;
  overflow: auto;
  border-radius: 6px;
  background: var(--fill-inset);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
}

/* Another Orbit session's message (components/SessionMessageCard.tsx): on the side every turn this
   conversation is handed sits, but a raised card rather than the owner's own tinted bubble — the
   words are another agent's, and the head says whose. */
.smc-wrap {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
}
.smc {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: var(--bg-raised);
  color: var(--text-1);
}
.smc-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  color: var(--text-2);
  font-size: 12px;
}
.smc-mark {
  flex: none;
  color: var(--brand);
}
.smc-from {
  color: var(--brand);
  font-weight: 600;
  text-decoration: none;
  overflow-wrap: anywhere;
}
.smc-agent {
  flex: none;
  padding: 0 8px;
  border: 1px solid var(--brand-border);
  border-radius: 9px;
  color: var(--text-2);
  font-size: 11px;
  line-height: 18px;
}
.smc-body {
  margin-top: 6px;
}
.smc-more {
  padding: 0;
  border: 0;
  background: none;
  color: var(--brand);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.smc-meta {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-hover-strong);
  color: var(--text-3);
  font-size: 11px;
}
.smc-meta a {
  color: var(--brand);
  text-decoration: none;
}
.smc-undelivered {
  margin-top: 4px;
  color: var(--warning);
  font-size: 12px;
}
/* Still waiting to be delivered (WorkspaceView's queued tail): dashed like a queued message, with the
   queue's status line at its foot — the same shape the delivery and project-start cards take. */
.smc.is-queued {
  border-style: dashed;
}
.smc-queued {
  margin-top: 6px;
}
.smc-queued .chat-queued-meta {
  flex-wrap: wrap;
  justify-content: flex-start;
  row-gap: 2px;
}
.smc-queued .chat-queued-why {
  order: 1;
  flex-basis: 100%;
  white-space: normal;
}
/* A message that asks for a reply (session requests): what it asks, by when, and where it stands —
   read live, so the state word moves while the card does not. */
.smc-request {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  margin-top: 6px;
  color: var(--text-2);
  font-size: 12px;
}
.smc-request-asks {
  font-weight: 600;
}
.smc-request-state {
  padding: 0 8px;
  border: 1px solid var(--bg-hover-strong);
  border-radius: 9px;
  line-height: 18px;
  font-size: 11px;
}
.smc-request-state-open {
  border-color: var(--brand-border);
  color: var(--brand);
}
.smc-request-state-replied {
  border-color: var(--success);
  color: var(--success);
}
.smc-request-state-no_reply,
.smc-request-state-recipient_ended,
.smc-request-state-expired,
.smc-request-state-undelivered {
  color: var(--warning);
}

/* The outcomes of this session's own requests, handed back (SessionReplyCard.tsx): the platform's
   turn, so the agent's side of the transcript, in the brand tone. */
.src-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 8px 0;
}
.src {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: var(--bg-raised);
  color: var(--text-1);
}
.src-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  color: var(--text-2);
  font-size: 12px;
}
.src-mark {
  flex: none;
  color: var(--brand);
}
.src-from {
  color: var(--brand);
  font-weight: 600;
  text-decoration: none;
  overflow-wrap: anywhere;
}
.src-outcome {
  flex: none;
  padding: 0 8px;
  border: 1px solid var(--bg-hover-strong);
  border-radius: 9px;
  font-size: 11px;
  line-height: 18px;
  color: var(--warning);
}
.src-outcome-replied {
  border-color: var(--success);
  color: var(--success);
}
.src-asked,
.src-chose,
.src-note {
  margin-top: 6px;
  color: var(--text-2);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.src-label {
  color: var(--text-3);
  font-size: 11px;
}
.src-body,
.src-excerpt {
  margin-top: 6px;
}
.src-excerpt {
  padding-left: 8px;
  border-left: 2px solid var(--bg-hover-strong);
  color: var(--text-2);
}
.src-meta {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-hover-strong);
  color: var(--text-3);
  font-size: 11px;
}
.src-meta a {
  color: var(--brand);
  text-decoration: none;
}

/* The message telling a coordinator its project was started (ProjectStartedCard.tsx): the exception
   item's card, in the brand tone — nothing here failed — with the tasks that wait on the coordinator
   as a raised list of links. */
.psc-wrap {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
}
.psc {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: var(--brand-tint);
  color: var(--text-1);
}
.psc.is-queued {
  border-style: dashed;
}
.psc-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brand);
  font-weight: 600;
}
.psc-mark {
  flex: none;
}
.psc-kind {
  margin-left: auto;
  flex: none;
  padding: 0 8px;
  border: 1px solid var(--brand-border);
  border-radius: 9px;
  background: var(--bg-raised);
  color: var(--text-2);
  font-size: 11px;
  font-weight: 500;
  line-height: 18px;
}
.psc-title {
  margin: 4px 0 2px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.psc-settings {
  margin: 0 0 2px;
  font-size: 12.5px;
  color: var(--text-2);
  overflow-wrap: anywhere;
}
.psc-lead {
  margin-top: 6px;
  font-size: 13px;
}
.psc-tasks {
  margin: 6px 0 0;
  padding: 2px 10px;
  border-radius: 8px;
  background: var(--bg-raised);
  list-style: none;
  font-size: 13px;
}
.psc-tasks li {
  padding: 4px 0;
  border-bottom: 1px solid var(--bg-hover-strong);
  overflow-wrap: anywhere;
}
.psc-tasks li:last-child {
  border-bottom: 0;
}
.psc-tasks a,
.psc-unlisted a {
  color: var(--brand);
  text-decoration: none;
}
.psc-more {
  margin-top: 6px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--brand);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.psc-unlisted {
  margin-top: 4px;
  font-size: 12px;
}
.psc-meta {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--bg-hover-strong);
  color: var(--text-3);
  font-size: 11px;
}
.psc-undelivered {
  margin-top: 4px;
  color: var(--warning);
  font-size: 12px;
}
.psc-raw {
  margin-top: 6px;
  font-size: 12px;
}
.psc-raw summary {
  color: var(--text-2);
  cursor: pointer;
}
.psc-raw pre {
  max-height: 320px;
  margin: 6px 0 0;
  padding: 8px;
  overflow: auto;
  border-radius: 6px;
  background: var(--fill-inset);
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
}
.psc-queued {
  margin-top: 6px;
}
.psc-queued .chat-queued-meta {
  flex-wrap: wrap;
  justify-content: flex-start;
  row-gap: 2px;
}
.psc-queued .chat-queued-why {
  order: 1;
  flex-basis: 100%;
  white-space: normal;
}
/* A confirmation review's two turns (`ConfirmationReviewTurnCards.tsx`): the request a reviewer is
   handed, and the reviewer's return handed to the run. Orbit's turns, drawn as the started card is. */
.crc-wrap {
  display: flex;
  justify-content: flex-end;
  margin: 8px 0;
}
.crc {
  width: min(560px, 88%);
  padding: 10px 12px;
  border: 1px solid var(--brand-border);
  border-radius: 12px;
  background: var(--brand-tint);
  color: var(--text-1);
}
.crc.is-returned {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.crc.is-queued {
  border-style: dashed;
}
.crc-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brand);
  font-weight: 600;
}
.crc.is-returned .crc-head {
  color: var(--warning);
}
.crc-when {
  margin-left: auto;
  color: var(--text-3);
  font-size: 11px;
  font-weight: 400;
}
.crc-title,
.crc-who {
  margin: 4px 0 2px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.crc-title a,
.crc-who a {
  color: var(--brand);
  text-decoration: none;
}
.crc-meta {
  font-size: 12.5px;
  color: var(--text-2);
}
.crc-actions {
  margin-top: 8px;
}
.crc-quote {
  margin-top: 4px;
  font-size: 13px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.crc-problems {
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
  font-size: 13px;
}
.crc-problems li {
  display: grid;
  grid-template-columns: 64px 1fr;
  column-gap: 8px;
  margin-top: 3px;
  overflow-wrap: anywhere;
}
.crc-problem-label {
  color: var(--warning);
  font-size: 12px;
  line-height: 1.6;
}
.crc-undelivered {
  margin-top: 4px;
  color: var(--warning);
  font-size: 12px;
}
.crc-queued {
  margin-top: 6px;
}
.watch-editor {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.watch-editor-label {
  margin-bottom: 6px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
}
.watch-editor-options {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.watch-editor-option {
  display: block;
  color: var(--text-1);
}
.watch-editor-hint {
  display: block;
  color: var(--text-3);
  font-size: 12px;
}
.watch-editor-aggregation {
  margin-bottom: 8px;
}
.watch-editor-fixed {
  color: var(--text-1);
}
.watch-editor-session {
  width: 100%;
  margin-top: 8px;
}
@media (max-width: 600px) {
  .watch-facts {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }
  .watch-facts dd {
    margin-bottom: 6px;
  }
  .watch-card-head {
    flex-wrap: wrap;
  }
}

/* ── Open items (mock 2 ②) ─────────────────────────────────────────────────────────────────
   Everything this project still owes somebody, in the two groups that say who is expected to act.
   The dot carries the group as colour and the sub-head carries it as a word, so the two groups are
   told apart without reading colour at all — the palette does not separate under CVD. */
.project-open-items {
  margin-bottom: 14px;
  padding: 14px 18px 12px;
  background: var(--bg-raised);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
}
.project-open-items-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 4px;
}
.project-open-items-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-1);
}
.project-open-items-hint {
  font-size: 12.5px;
  color: var(--text-3);
}
.project-open-items-group {
  margin: 10px 2px 0;
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--text-3);
}
.project-open-items-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.project-open-item-row {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) 210px auto;
  gap: 12px;
  align-items: center;
  padding: 10px 2px;
  border-top: 1px solid var(--border-subtle);
}
.project-open-items-group + .project-open-items-list .project-open-item-row:first-child {
  border-top: 0;
}
.project-open-item-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--warning-solid);
}
.project-open-item-row.is-coordinator .project-open-item-dot {
  background: var(--brand);
}
.project-open-item-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-1);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-open-item-line {
  font-size: 12.5px;
  color: var(--text-3);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-open-item-who {
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--text-2);
}
.project-open-item-age {
  display: block;
  font-size: 11.5px;
  color: var(--text-3);
}
/* A phone has no 210px to give the who column beside the item: who has it and for how long go under
   what it is, the press stays beside both, and the item's own words wrap rather than cut to "Start …". */
@media (max-width: 640px) {
  .project-open-item-row {
    grid-template-columns: 10px minmax(0, 1fr) auto;
    row-gap: 2px;
  }
  .project-open-item-dot {
    grid-row: 1;
  }
  .project-open-item-main {
    grid-column: 2;
  }
  .project-open-item-who {
    grid-column: 2;
    grid-row: 2;
  }
  .project-open-item-press {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
  .project-open-item-age {
    display: inline;
    margin-inline-start: 6px;
  }
  .project-open-item-title,
  .project-open-item-line {
    white-space: normal;
  }
}
.project-open-item-press {
  text-align: right;
}
.project-open-item-action,
.project-open-item-action:hover {
  text-decoration: none;
}
.project-open-item-action {
  display: inline-block;
  padding: 2px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-raised);
  font-size: 12.5px;
  color: var(--text-1);
  white-space: nowrap;
}
.project-open-item-action:hover {
  border-color: var(--brand);
  color: var(--brand-strong);
}
.project-open-item-action.is-primary {
  border-color: var(--brand);
  background: var(--brand);
  color: #fff;
}
.project-open-item-action.is-primary:hover {
  background: var(--brand-strong);
  border-color: var(--brand-strong);
  color: #fff;
}
/* A press drawn as a button rather than a link — Review on the request to start — in the same box. */
button.project-open-item-action {
  font-family: inherit;
  line-height: inherit;
  cursor: pointer;
}
button.project-open-item-action:disabled {
  opacity: 0.6;
  cursor: default;
}
/* The owner's own "Start…" while no coordinator has asked: the row's title is the press, and the
   dot is quiet, because nobody is waiting on it (mock board3 ②). */
.project-open-item-row.is-own-start .project-open-item-dot {
  background: var(--text-4);
}
.project-open-item-start {
  display: block;
  max-width: 100%;
  padding: 0;
  border: none;
  background: none;
  font-family: inherit;
  text-align: start;
  color: var(--brand);
  cursor: pointer;
}
.project-open-item-start:hover {
  text-decoration: underline;
}
/* The action row's third weight (mock 7, 方案 B): the doors that only look and only stop read as text
   links instead of boxes as heavy as the press the card is asking for — no border, no fill,
   underlined, and quiet until they are hovered. Scoped to the action row so these four properties
   stand against the link chrome antd sets for the presses drawn in this weight, which comes in at
   the same weight as a bare class of this file's; the row's own box is untouched, because it is the
   way IN and not a door being demoted. */
.project-open-item-actions .project-open-item-quiet {
  height: auto;
  padding: 0 2px;
  color: var(--text-2);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.project-open-item-actions .project-open-item-quiet.is-danger {
  color: var(--error);
}
.project-open-item-actions a.project-open-item-quiet:hover,
.project-open-item-actions button.project-open-item-quiet:hover {
  color: var(--text-1);
}
.project-open-item-actions .project-open-item-quiet.is-danger:hover {
  color: var(--error);
}

/* ── The exception cards (mocks 5 and 6 ①) ─────────────────────────────────────────────────
   One card for a conflict, a failed combined-tree check, a task that failed, an item a clock made
   the owner's, and a pause. Amber chrome for what the owner has to act on and neutral for what the
   coordinator is handling — the same two the rows above use, so a card and its row agree. */
.approval-card.project-open-item-card {
  margin: 10px 0;
}
.project-open-item-card.is-coordinator {
  border-color: var(--border);
  background: var(--bg-raised);
}
.project-open-item-card.is-coordinator .approval-head {
  background: var(--bg-subtle);
  border-bottom-color: var(--border-subtle);
}
.project-open-item-card.is-owner {
  border-color: var(--warning-border);
  background: var(--warning-bg);
}
.project-open-item-card.is-owner .approval-head {
  background: var(--warning-bg);
  border-bottom-color: var(--warning-border);
}
.project-open-item-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.project-open-item-heading {
  min-width: 0;
}
/* An item whose handling by the coordinator has ended (§4.7 H5): the same card, quieter — nothing on
   it is waiting for anybody. */
.project-open-item-card.is-settled {
  border-color: var(--border-subtle);
  background: var(--bg-raised);
}
.project-open-item-card.is-settled .approval-head {
  background: var(--bg-subtle);
  border-bottom-color: var(--border-subtle);
  color: var(--text-2);
}
/* Where the coordinator's handling stands (§4.7): blue while its rerun runs — the colour the project
   list's "Coordinator · handling" chip uses — green once it was handled, grey once a new item took
   its place. */
.project-open-item-state {
  flex: none;
  padding: 0 6px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  line-height: 18px;
  color: var(--text-2);
}
.project-open-item-state.is-handling {
  border-color: var(--brand-border);
  background: var(--brand-tint);
  color: var(--brand);
}
.project-open-item-state.is-handled {
  border-color: var(--success-border);
  background: var(--success-bg);
  color: var(--success);
}
.project-open-item-state.is-superseded {
  color: var(--text-3);
}
.project-open-item-line.is-handling .project-open-item-state {
  display: inline-block;
  margin-right: 2px;
  line-height: 16px;
}
.project-open-item-handling {
  margin-top: 6px;
}
/* The provenance mark in its third colour: nothing is wrong and nobody is being asked to decide —
   Orbit is reporting a fact. Same box, so the three marks read as one family. */
.criteria-provenance.prov-neutral {
  border-color: var(--border);
  color: var(--text-3);
}
.project-open-item-card .approval-body.project-open-item-body {
  background: var(--bg-raised);
  padding: 10px 14px;
}
.project-open-item-detail {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-2);
}
/* The card's fact block (mock 5): the rows under the heading, and the tail of what a failed check
   printed under the Check row. The label and value cells are the merge confirmation card's own two
   classes, so a row reads the same on both cards; the two treatments below are the ones that card
   wears as `promotion-mono` / `promotion-bad`. */
.project-open-item-fact + .project-open-item-fact {
  margin-top: 2px;
}
.project-open-item-mono {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11.5px;
}
.project-open-item-bad {
  color: var(--error);
  font-weight: 600;
}
.project-open-item-log {
  margin: 4px 0 2px;
  padding: 8px 10px;
  background: var(--fill-inset);
  border-radius: 6px;
  overflow: hidden;
}
.project-open-item-log .chat-pre {
  font-size: 11.5px;
  line-height: 1.55;
}
.project-open-item-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}
.project-open-item-actions:empty {
  display: none;
}
.project-open-item-error {
  flex-basis: 100%;
}
.project-open-item-reason-label {
  display: block;
  margin-bottom: 4px;
  font-size: 12.5px;
  font-weight: 600;
}
.project-open-item-foot {
  padding: 8px 14px;
  border-top: 1px solid var(--border-subtle);
  font-size: 12px;
  color: var(--text-2);
}

/* ── The coordinator card's two progress rows (mock 2 ③) ───────────────────────────────────
   Whether Orbit's last word reached the conversation, and how much of today's own initiative it
   has left. Laid out like the identity rows above them so the card reads as one column. */
.project-coordinator-progress {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-top: 7px;
  font-size: 12.5px;
  color: var(--text-2);
}
.project-coordinator-progress.is-stacked {
  display: block;
}
.project-coordinator-progress-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}
.project-coordinator-progress-label {
  font-size: 11.5px;
  color: var(--text-3);
}
.project-coordinator-progress-value .is-carried {
  color: var(--success);
}
.project-coordinator-progress-value .is-returned,
.project-coordinator-progress-value .is-paused {
  color: var(--warning);
  font-weight: 600;
}
.project-coordinator-meter {
  height: 6px;
  margin-top: 4px;
  border-radius: 4px;
  background: var(--fill-muted);
  overflow: hidden;
}
.project-coordinator-meter i {
  display: block;
  height: 6px;
  border-radius: 4px;
  background: var(--brand);
}
.project-coordinator-meter i.is-paused {
  background: var(--warning-solid);
}

/* ── The merge-into-main confirmation card (`ProjectPromotionCard`, mock 4) ────────────────────
   The criteria card's chrome, because it is the same kind of object: something Orbit filed that
   the account owner — and only they — answers. What differs is the body, which is a short table
   rather than a paragraph: the reader is weighing four facts, and four labelled rows is how they
   can be weighed without reading a sentence twice. */
.approval-card.project-promotion {
  margin: 10px 0;
}
.project-promotion-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
/* The receipt is not a question: green, and with the neutral mark the other receipts carry. */
.project-promotion.is-merged {
  border-color: var(--success-border);
  background: var(--success-bg);
}
.project-promotion.is-merged .approval-head {
  background: var(--success-bg);
  border-bottom-color: var(--success-border);
  color: var(--success);
  font-weight: 600;
}
.project-promotion .approval-body.project-promotion-body {
  background: var(--bg-raised);
  padding: 10px 14px 6px;
}
.project-promotion-row + .project-promotion-row {
  margin-top: 2px;
}
.project-promotion-body .criteria-decision-k {
  width: 84px;
}
.promotion-mono {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11.5px;
}
.promotion-ok {
  color: var(--success);
  font-weight: 600;
}
.promotion-bad {
  color: var(--error);
  font-weight: 600;
}
/* Something is happening on a runner right now and this card is watching it: the one place the
   card moves on its own, so it is the one place a spinner belongs. */
.promotion-spin {
  display: inline-block;
  width: 11px;
  height: 11px;
  margin-right: 6px;
  border: 2px solid var(--brand-border);
  border-top-color: var(--brand);
  border-radius: 50%;
  vertical-align: -1px;
  animation: promotion-spin 0.9s linear infinite;
}
@keyframes promotion-spin {
  to { transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce) {
  .promotion-spin { animation: none; }
}
.card-actions.project-promotion-actions {
  background: var(--bg-raised);
  border-top-color: var(--warning-border);
}
.project-promotion.is-merged .card-actions.project-promotion-actions {
  border-top-color: var(--success-border);
}
.project-promotion-link {
  font-size: 12.5px;
}
/* Pushed to the far end of the action row: how long this has been asked is context, not a press. */
.project-promotion-asked {
  margin-left: auto;
  font-size: 11.5px;
  color: var(--text-3);
}
.project-promotion-error {
  margin: 0 14px 10px;
}
/* B5's row: the blockers this merge would decide along with it, as a short list under the sentence
   that says so — the same shape the Tasks row would take, and never a second blockers card. */
.promotion-warn {
  color: var(--warning);
  font-weight: 600;
}
.project-promotion-blockers {
  margin: 2px 0 0;
  padding-left: 18px;
}
/* The tasks this merge would bring in, by name, under the count that says how many there are: what
   the owner is actually deciding about, and the list the blockers row below it belongs to. */
.project-promotion-tasks {
  margin: 2px 0 0;
  padding-left: 18px;
}

/* ── Orbit Wiki ────────────────────────────────────────────────────────────────────────────────
   The pages under /wiki: the home, a topic, the entry drawer and Review (design §12.1, mocks 01–04).

   THIS IS THE MOCKS' OWN SHEET, PORTED. `docs/mocks/wiki/wiki-desktop.css` says of itself that
   everything it defines beyond the mock frame is "the pieces the Wiki adds, prefixed wk-", linked
   after the shipped index.css so every colour resolves through the real tokens — which makes those
   rules the design of these surfaces rather than a picture of them. They are reproduced here with
   the mock frame (`.frame`, `.m-*`, `.doc-col` and the sheet's fixed widths) dropped, since the app
   already provides the last of those with `.app-view--doc`.

   What the Wiki reuses rather than restates: `.project-open-items` is every card, `.tdp-*` is the
   drawer's frame and the badges, `.orbit-link-card` is a source, `.approval-card`/`.card-action` are
   Review's cards and buttons, `.chat-diff`/`.diff-*` is the amendment's diff, and `.tp-count.needs-you`
   is the sidebar's amber number. */

/* ── the page and its chrome ─────────────────────────────────────────────────────────────────── */
.wk-page { max-width: 1040px; margin: 0 auto; }
.wk-body { margin-top: 0; }
.wk-title-row { display: flex; align-items: center; gap: 12px; }
.wk-title-row .page-title { flex: none; }
.wk-select { position: relative; display: inline-flex; align-items: center; gap: 7px; height: 30px;
             padding: 0 26px 0 10px; border: 1px solid var(--border); border-radius: 6px;
             background: var(--bg-raised); font-size: 13px; color: var(--text-1); white-space: nowrap; }
.wk-select select { appearance: none; border: 0; background: transparent; font: inherit; color: inherit;
                    padding: 0; margin: 0; outline: none; cursor: pointer; max-width: 220px; }
.wk-select .ic.caret { position: absolute; right: 9px; font-size: 11px; color: var(--text-3); pointer-events: none; }
.wk-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.wk-search { display: flex; align-items: center; gap: 8px; height: 32px; margin: 16px 0 0; padding: 0 8px 0 11px;
             border: 1px solid var(--border); border-radius: 6px; background: var(--bg-raised); font-size: 14px; color: var(--text-4); }
.wk-search .ic { color: var(--text-4); font-size: 14px; }
.wk-search .grow { flex: 1; }
/* The line is the ⌘K palette's way in: a button the width of the line, drawn as the line itself. */
.wk-search-open { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; height: 100%; padding: 0; border: 0;
                  background: transparent; font: inherit; color: inherit; text-align: left; cursor: text; }
.wk-kbd { padding: 0 5px; border: 1px solid var(--border); border-radius: 4px; background: var(--bg-subtle); color: var(--text-3);
          font: 11px/17px -apple-system, "Segoe UI", sans-serif; white-space: nowrap; }
.wk-status-row { margin-top: 14px; }
.wk-status-row .wk-sep { color: var(--text-4); }
.wk-status-row .wk-warn-text, .wk-status-row .wk-warn-text b { color: var(--warning); }
.wk-status-review { display: inline-flex; align-items: center; gap: 8px; }
/* The maintenance part of the status row (criterion 5, mocks 11 ② and 12 ④): amber while the run waits and red
   when it broke, as the session list's dots are; Set up and View run are links. */
.wk-maint { display: inline-flex; align-items: center; white-space: nowrap; }
.wk-maint--muted { color: var(--text-3); }
.wk-maint--warn, .wk-status-row .wk-maint--warn b { color: var(--warning); }
.wk-maint--error, .wk-status-row .wk-maint--error b { color: var(--error); }
.wk-maint-ok { margin-left: 6px; color: var(--success); font-weight: 600; }
.wk-maint-dot { display: inline-block; width: 7px; height: 7px; margin-right: 6px; border-radius: 50%; flex: none; vertical-align: 1px; }
.wk-maint--warn .wk-maint-dot { background: var(--warning-solid); }
.wk-maint--error .wk-maint-dot { background: var(--error-solid); }
.wk-maint-spin { display: inline-block; width: 11px; height: 11px; margin-right: 6px; border-radius: 50%; flex: none;
                 border: 1.6px solid var(--brand-border); border-top-color: var(--brand); animation: runner-spin 0.9s linear infinite; }
.wk-maint-link { color: var(--brand); text-decoration: none; white-space: nowrap; }
.wk-maint-link:hover { text-decoration: underline; }
@media (prefers-reduced-motion: reduce) { .wk-maint-spin { animation: none; } }
.wk-crumb { font-size: 13px; color: var(--text-3); display: flex; align-items: center; gap: 6px; }
.wk-crumb a { color: var(--brand); text-decoration: none; }
.wk-crumb .ic { font-size: 10px; color: var(--text-4); }
.wk-mono { font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: 11.5px; }
.wk-sep { color: var(--text-4); }

/* ── the two columns, and the card ───────────────────────────────────────────────────────────── */
.wk-cols { display: grid; grid-template-columns: minmax(0, 1fr) 288px; gap: 24px; align-items: start; margin-top: 16px; }
.wk-col { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.wk-card { margin: 0; }
.wk-card .project-open-items-head { align-items: center; }
.wk-card-trailing { margin-left: auto; font-size: 12.5px; color: var(--brand); white-space: nowrap; }
.wk-card-trailing a { color: inherit; text-decoration: none; }
.wk-pin { color: var(--text-3); font-size: 13px; }
.wk-empty { padding: 6px 2px 2px; font-size: 13px; color: var(--text-3); }
.wk-body > .wk-card + .wk-card { margin-top: 16px; }

/* ── trust, anchor and op marks: one vocabulary on every surface ─────────────────────────────── */
.tdp-badge.tone-owner { background: var(--invert-surface); color: var(--invert-text); border-color: var(--invert-surface); font-weight: 500; }
.tdp-badge .ic { font-size: 11px; }
.wk-anchor { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; white-space: nowrap; }
.wk-anchor.ok { color: var(--success); }
.wk-anchor.ok .wk-mono { color: var(--success); }
.wk-anchor.changed { color: var(--warning); font-weight: 600; }
.wk-anchor.missing { color: var(--error); font-weight: 600; }
.wk-anchor.muted { color: var(--text-3); }
.wk-anchor .ic { font-size: 12px; }
.wk-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; flex: none; }
.wk-dot.owner { background: var(--invert-surface); }
.wk-dot.confirmed { background: var(--brand); }
.wk-dot.proposed { background: var(--dot-idle); }
.wk-dot.amber { background: var(--warning-solid); }
.wk-kind { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border-radius: 6px;
           background: var(--fill-muted); color: var(--text-2); font-size: 13px; flex: none; }
.wk-op { display: inline-block; min-width: 56px; text-align: center; box-sizing: border-box; padding: 0 6px; border-radius: 4px;
         font: 700 10.5px/18px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace;
         letter-spacing: .04em; white-space: nowrap; flex: none; }
.wk-op.add { background: var(--success-bg); color: var(--success); }
.wk-op.amend { background: var(--brand-tint); color: var(--brand-strong); }
.wk-op.retire { background: var(--fill-muted); color: var(--text-2); }

/* ── entry rows: the project list row, plus the Wiki's three trailing facts ───────────────────── */
.wk-row { display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 10px 2px;
          border-top: 1px solid var(--border-subtle); }
.wk-row:first-child { border-top: 0; }
.wk-row-main { min-width: 0; }
.wk-row-t { display: flex; align-items: center; gap: 7px; min-width: 0; font-size: 14px; font-weight: 600; color: var(--text-1); }
.wk-row-t > span.tt { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.wk-row-t a, .wk-dec .t a, .wk-tl-t a { color: inherit; text-decoration: none; }
.wk-row-t a:hover, .wk-dec .t a:hover, .wk-tl-t a:hover { text-decoration: underline; }
.wk-row-d { margin-top: 1px; font-size: 12.5px; color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-row-d code, .wk-row-t code { font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: 11.5px; }
.wk-new { width: 6px; height: 6px; border-radius: 50%; background: var(--brand); flex: none; }

/* ── the topic page ──────────────────────────────────────────────────────────────────────────── */
.wk-topic-page { margin-top: 4px; }
.t-title { margin: 8px 0 0; font-size: 34px; font-weight: 650; line-height: 1.18; letter-spacing: -.025em; color: var(--text-1); }
.t-meta { display: flex; align-items: center; gap: 9px; margin-top: 10px; font-size: 13px; color: var(--text-2); }
.t-meta .chg { display: inline-flex; align-items: center; gap: 6px; }
.wk-sec { margin-top: 22px; }
.wk-sec-h { display: flex; align-items: center; gap: 9px; padding: 0 2px 8px; border-bottom: 1px solid var(--border-subtle); }
.wk-sec-h h3 { margin: 0; font-size: 12.5px; font-weight: 650; letter-spacing: .3px; color: var(--text-1); }
.wk-sec-h .n { font-size: 11.5px; font-weight: 600; color: var(--text-2); background: var(--fill-muted); border-radius: 999px; padding: 1px 7px; }
.wk-sec-h .note { font-size: 11.5px; color: var(--text-3); }
.wk-sec-h .col { font-size: 11px; color: var(--text-3); letter-spacing: .02em; }
.wk-sec-h .cols { margin-left: auto; margin-right: 10px; display: grid; grid-template-columns: 92px 118px 128px; column-gap: 12px; }
.wk-sec-h .cols span:last-child { text-align: right; }
.wk-erow { display: grid; grid-template-columns: 22px minmax(0, 1fr) 92px 118px 128px; gap: 0 12px; align-items: center;
           padding: 10px 12px 10px 2px; border-bottom: 1px solid var(--border-subtle); }
.wk-erow > .main { min-width: 0; }
.wk-erow .used { text-align: right; font-size: 12px; color: var(--text-2); white-space: nowrap; }
.wk-erow .used b { font-weight: 600; color: var(--text-1); }
.wk-erow.changed { background: color-mix(in srgb, var(--warning-bg) 55%, transparent); }
.wk-erow .warnline { margin-top: 3px; font-size: 12px; color: var(--warning); display: flex; align-items: center; gap: 6px; }
.wk-erow .warnline code { font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: 11.5px; }
.wk-erow.sup .wk-row-t .tt { text-decoration: line-through; color: var(--text-3); font-weight: 500; }
.wk-erow.sup .wk-kind { opacity: .6; }
.wk-erow.sup .supby { font-size: 12.5px; color: var(--text-3); margin-top: 1px; }
.wk-erow.sup .supby a { color: var(--brand); text-decoration: none; }
.wk-erow.is-selected { background: var(--brand-tint); }
.wk-more { display: block; width: 100%; text-align: left; padding: 8px 2px 0; border: 0; background: transparent;
           font: inherit; font-size: 12.5px; color: var(--brand); cursor: pointer; }

/* ── the home page's lists: the decision log, the change feed, the usage bars ──────────────────── */
.wk-dec { display: grid; grid-template-columns: 86px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 9px 2px;
          border-top: 1px solid var(--border-subtle); }
.wk-dec:first-child { border-top: 0; }
.wk-dec .d { font: 12px/1.4 ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-3); }
.wk-dec .t { font-size: 13.5px; font-weight: 600; color: var(--text-1); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-dec .s { margin-top: 2px; font-size: 12.5px; color: var(--text-3); display: flex; align-items: center; gap: 6px; min-width: 0; }
.wk-dec .s .x { text-decoration: line-through; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.wk-review-sub { margin: -2px 0 8px; }
.wk-rv-row { display: flex; align-items: flex-start; gap: 8px; padding: 7px 0; border-top: 1px solid var(--border-subtle); font-size: 13px; line-height: 18px; }
.wk-rv-row.first { border-top: 0; }
.wk-rv-row .t { flex: 1; min-width: 0; color: var(--text-1); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.wk-rv-row .a { flex: none; color: var(--text-3); font-size: 12px; }
.wk-rv-foot { display: flex; align-items: center; gap: 10px; margin-top: 10px; }
.wk-rv-foot .hint { font-size: 12px; color: var(--text-3); }
.wk-card .tp-count.needs-you { font-size: 12px; }
.wk-tl { list-style: none; margin: 4px 0 0; padding: 0; }
.wk-tl li { position: relative; display: grid; grid-template-columns: 12px minmax(0, 1fr); gap: 8px; padding: 6px 0; }
.wk-tl li::before { content: ""; position: absolute; left: 3px; top: 20px; bottom: -8px; width: 1px; background: var(--border); }
.wk-tl li:last-child::before { display: none; }
.wk-tl .wk-dot { margin-top: 6px; }
.wk-tl-h { display: flex; align-items: baseline; gap: 6px; font-size: 12.5px; color: var(--text-2); }
.wk-tl-h b { color: var(--text-1); font-weight: 600; }
.wk-tl-h .when { margin-left: auto; color: var(--text-3); font-size: 12px; white-space: nowrap; }
.wk-tl-t { font-size: 13px; line-height: 1.45; color: var(--brand); }
.wk-tl-n { font-size: 12px; color: var(--text-3); }
.wk-tl .retired .wk-tl-t { color: var(--text-2); text-decoration: line-through; }
.wk-tl .retired .wk-tl-t a { color: inherit; }
.wk-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 2px; margin-top: 8px; background: var(--border-subtle); border-radius: 8px; overflow: hidden; }
.wk-stats > div { background: var(--bg-raised); padding: 8px 10px 9px; }
.wk-stats .n { font-size: 26px; font-weight: 650; line-height: 1.2; color: var(--text-1); }
.wk-stats .l { font-size: 12px; line-height: 1.35; color: var(--text-3); }
.wk-bars { margin-top: 12px; }
.wk-bars .h { margin: 0 0 2px; font-size: 11.5px; font-weight: 650; letter-spacing: .03em; text-transform: uppercase; color: var(--text-3); }
.wk-bar { padding: 5px 0 4px; }
.wk-bar .t { font-size: 12.5px; color: var(--text-1); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-bar .t a { color: inherit; text-decoration: none; }
.wk-bar .b { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
.wk-bar .b i { display: block; height: 6px; border-radius: 0 4px 4px 0; background: var(--brand); }
.wk-bar .b .v { font-size: 12px; color: var(--text-2); }

/* ── the entry drawer ────────────────────────────────────────────────────────────────────────── */
.wk-with-drawer { position: relative; display: flex; align-items: stretch; min-height: 100%; }
.wk-drawer-bg { flex: 1; min-width: 0; }
.wk-with-drawer .wk-scrim { position: fixed; inset: 0; z-index: 4; border: 0; padding: 0;
                            background: rgba(15, 23, 42, .16); cursor: pointer; }
.wk-drawer { position: fixed; top: 0; right: 0; bottom: 0; z-index: 5; width: 560px; max-width: 100%;
             display: flex; flex-direction: column; overflow-y: auto; background: var(--bg-raised);
             border-left: 1px solid var(--border-subtle); box-shadow: -10px 0 28px rgba(15, 23, 42, .14);
             animation: tdp-slide-in .22s cubic-bezier(.4, 0, .2, 1); }
.wk-drawer .tdp-head { position: relative; }
.wk-dkind { display: flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 600; color: var(--text-2); }
.wk-dkind .dim { font-weight: 400; color: var(--text-3); }
.wk-drawer .tdp-title { margin-top: 8px; font-size: 18px; line-height: 1.35; }
.wk-drawer .tdp-meta { margin-top: 10px; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.wk-drawer .tdp-section { padding: 14px 20px 16px; }
.wk-drawer .tdp-section-title { display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
.wk-drawer .tdp-section-title .c { font-weight: 400; }
.wk-dkv { display: grid; grid-template-columns: 68px minmax(0, 1fr); gap: 7px 12px; font-size: 13.5px; line-height: 1.6; }
.wk-dkv > .k { color: var(--text-3); font-size: 12.5px; padding-top: 1px; }
.wk-dkv > .v { color: var(--text-1); min-width: 0; }
.wk-dkv code { font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: 12px;
               background: var(--fill-muted); border-radius: 4px; padding: 0 4px; }
.wk-dsrc { display: flex; flex-direction: column; gap: 8px; }
.wk-dsrc .orbit-link-card { margin: 0; }
.wk-src-card { border: 1px solid var(--border); border-radius: 10px; padding: 8px 10px; }
.wk-src-card .orbit-link-card { border: 0; padding: 0; }
.wk-commit { border: 1px solid var(--border); border-radius: 10px; padding: 8px 10px; }
.wk-commit .h { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--text-1); }
.wk-commit .h .ic { color: var(--brand); font-size: 14px; }
.wk-commit .h .sha { font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: 12px; color: var(--brand); }
.wk-commit .h .ref { color: var(--text-3); overflow-wrap: anywhere; }
.olc-quote { margin-top: 7px; padding: 6px 8px; border-radius: 6px; background: var(--fill-inset); font-size: 12.5px; line-height: 1.5; color: var(--text-1); }
.olc-quote .wk-quote-text { overflow-wrap: anywhere; }
.olc-quote .who { display: flex; align-items: center; gap: 6px; margin-top: 3px; font-size: 11.5px; color: var(--text-3); }
.olc-quote .who .ver { margin-left: auto; color: var(--success); font-weight: 600; white-space: nowrap; }
.olc-quote .who .unverified { margin-left: auto; color: var(--text-3); white-space: nowrap; }
.wk-anchors { border: 1px solid var(--border-subtle); border-radius: 8px; overflow: hidden; }
.wk-anc { display: flex; align-items: center; gap: 10px; padding: 7px 10px; font-size: 12.5px; }
.wk-anc + .wk-anc { border-top: 1px solid var(--border-subtle); }
.wk-anc .p { flex: 1; min-width: 0; font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace;
             font-size: 12px; color: var(--text-1); overflow-wrap: anywhere; }
.wk-anc .ic.aim { color: var(--text-3); font-size: 13px; }
.wk-anc-note { margin-top: 8px; font-size: 12px; color: var(--text-3); line-height: 1.5; }
.wk-used-h { font-size: 13px; color: var(--text-2); margin-bottom: 4px; }
.wk-used-h b { color: var(--text-1); font-weight: 600; }
.wk-drawer .tdp-session { padding: 7px 8px; margin: 0 -8px; cursor: pointer; }
.wk-drawer .tdp-session .tdp-badge { font-size: 11.5px; }
.wk-hist { list-style: none; margin: 0; padding: 0; }
.wk-hist li { position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 10px; padding: 0 0 12px; }
.wk-hist li::before { content: ""; position: absolute; left: 14px; top: 22px; bottom: 0; width: 1px; background: var(--border); }
.wk-hist li:last-child { padding-bottom: 0; }
.wk-hist li:last-child::before { display: none; }
.wk-hist .rev { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 20px; border-radius: 10px;
                background: var(--fill-muted); color: var(--text-2); font: 600 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace; }
.wk-hist li.cur .rev { background: var(--brand-tint); color: var(--brand-strong); }
.wk-hist .h { font-size: 13px; color: var(--text-1); line-height: 20px; }
.wk-hist .m { font-size: 12px; color: var(--text-3); margin-top: 1px; }
.wk-modal-note { margin: 0 0 10px; font-size: 12.5px; line-height: 1.55; color: var(--text-3); }
.wk-note-dim { font-size: 12.5px; color: var(--text-3); }
.wk-form { display: grid; grid-template-columns: 108px minmax(0, 1fr); gap: 10px 12px; align-items: start; }
.wk-form .k { font-size: 12.5px; color: var(--text-3); padding-top: 6px; }
.wk-form .wk-modal-note { grid-column: 1 / -1; }

/* ── Review ──────────────────────────────────────────────────────────────────────────────────── */
.rv-page { max-width: 1040px; margin: 0 auto; }
.rv-head { display: flex; align-items: flex-end; gap: 16px; margin-top: 8px; }
.rv-head .page-title { font-size: 20px; }
.rv-sub { margin-top: 4px; font-size: 13px; color: var(--text-2); }
.wk-seg { display: inline-flex; gap: 2px; margin-left: auto; padding: 2px; border-radius: 6px; background: var(--fill-muted); }
.wk-seg button { padding: 3px 12px; border: 0; border-radius: 4px; background: transparent; font-size: 13px; line-height: 20px;
                 color: var(--text-2); white-space: nowrap; cursor: pointer; }
.wk-seg button.on { background: var(--bg-raised); color: var(--text-1); font-weight: 500; box-shadow: 0 1px 2px rgba(0, 0, 0, .08); }
.wk-seg button b { margin-left: 5px; font-weight: 600; color: var(--text-3); }
/* The phone's card pager (mock 09): one proposal card at a time, with the position between two plain
   buttons. It is drawn only on a phone — a desktop shows the queue as a list. */
.wk-pager { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.wk-pager .pos { flex: 1; text-align: center; font-size: 13px; color: var(--text-2); font-variant-numeric: tabular-nums; }
.rv-cols { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 20px; align-items: start; margin-top: 16px; }
.rv-list { display: flex; flex-direction: column; gap: 16px; min-width: 0; }
.wk-prop.approval-card { margin: 0; }
.wk-prop .approval-head { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 500; color: var(--text-2);
                          border-radius: 10px 10px 0 0; }
.wk-prop .approval-head .by { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-prop .approval-head a { color: var(--brand); text-decoration: none; font-weight: 600; }
.wk-prop .approval-head .kind { color: var(--text-1); font-weight: 600; }
.wk-prop .approval-head .age { margin-left: auto; color: var(--text-3); font-weight: 400; white-space: nowrap; }
.wk-prop .approval-body { background: var(--bg-raised); padding: 12px 16px; max-height: none; overflow: visible; }
.wk-prop .approval-actions { background: var(--bg-raised); border-radius: 0 0 10px 10px; }
.wk-prop-t { font-size: 16px; font-weight: 650; line-height: 1.4; color: var(--text-1); }
.wk-prop-t .q { color: var(--text-3); font-weight: 500; }
.wk-pkv { display: grid; grid-template-columns: 92px minmax(0, 1fr); gap: 5px 12px; margin-top: 10px; font-size: 13.5px; line-height: 1.6; }
.wk-pkv > .k { color: var(--text-3); font-size: 12.5px; padding-top: 1px; }
.wk-pkv > .v { color: var(--text-1); min-width: 0; }
.wk-pkv > .wk-diff-cell { grid-column: 1 / -1; }
.wk-pkv code { font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: 12px;
               background: var(--fill-muted); border-radius: 4px; padding: 0 4px; }
.wk-pkv .olc-quote { margin-top: 0; }
.wk-pkv .wk-anchors { margin-top: 1px; }
.wk-prop .chat-diff { margin-top: 10px; }
.wk-prop .chat-diff .diff-hunk { padding: 3px 10px; background: var(--bg-subtle); color: var(--text-3); font-size: 12px;
                                 border-bottom: 1px solid var(--border-subtle); }
.wk-none { color: var(--text-2); }
.wk-none .dim { color: var(--text-3); }
.wk-prop .card-actions .grow { flex: 1; }
.wk-prop .card-actions .note { font-size: 12px; color: var(--text-3); }
.wk-prop .card-action .ic { font-size: 11px; margin-left: 4px; vertical-align: -1px; }
.wk-warn { display: flex; gap: 8px; align-items: flex-start; margin: 0 0 10px; padding: 8px 10px; border: 1px solid var(--warning-border);
           border-radius: 8px; background: var(--warning-bg); font-size: 13px; line-height: 1.5; color: var(--text-1); }
.wk-warn .ic { color: var(--warning); font-size: 15px; margin-top: 2px; }
.wk-warn b { color: var(--warning); }
.wk-warn a { color: var(--brand); margin-left: 4px; white-space: nowrap; }
.aa-row { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 8px; padding: 8px 0; border-top: 1px solid var(--border-subtle); font-size: 13px; }
.aa-row.first { border-top: 0; }
.aa-row .ic { color: var(--success); font-size: 14px; margin-top: 3px; }
.aa-row b { font-weight: 600; color: var(--text-1); }
.aa-row .d { color: var(--text-3); font-size: 12.5px; }
.aa-ask { margin-top: 6px; padding: 8px 10px; border-radius: 8px; background: var(--fill-inset); font-size: 12.5px; line-height: 1.55; color: var(--text-2); }
.aa-ask b { color: var(--text-1); font-weight: 600; }

/* ── review modes (criterion 8, mocks 17–20): Wiki settings, the marks' bar, one run, a challenge ──
   The settings page is the app's Settings page for one space — one centred column of cards, a sentence
   on the left and its control on the right. The marks' bar and a run's drawer are the entry drawer's
   own frame; a challenge card is a Review card with its answers swapped. */
.wk-settings { max-width: 600px; margin: 0 auto; }
.wk-settings .page-title { margin-top: 8px; }
.wk-settings-sub { margin: -4px 0 16px; font-size: 13px; color: var(--text-3); overflow-wrap: anywhere; }
.wk-settings-card { margin-bottom: 16px; }
.wk-settings-hint { font-size: 12.5px; font-weight: 400; color: var(--text-3); }
.wk-settings-lead { margin-bottom: 8px; font-size: 13px; color: var(--text-2); }
.wk-modes.ant-radio-group { display: flex; flex-direction: column; gap: 4px; width: 100%; }
.wk-mode { padding: 9px 12px 10px; border-radius: 8px; }
.wk-mode.on { background: var(--brand-tint); }
.wk-mode-t { font-weight: 600; color: var(--text-1); }
.wk-mode-tag { margin-left: 6px; font-size: 11.5px; color: var(--text-3); }
.wk-mode-d { margin: 2px 0 0 24px; font-size: 12.5px; line-height: 1.5; color: var(--text-3); }
.wk-spot { display: flex; align-items: center; gap: 16px; margin: 10px 0 0 24px; padding: 9px 12px; border-radius: 8px;
           border: 1px solid var(--border-subtle); background: var(--bg-raised); }
.wk-spot > div { flex: 1; min-width: 0; }
.wk-spot.off { opacity: .55; }
.wk-spot-t { font-size: 13.5px; color: var(--text-1); }
.wk-spot-d { margin-top: 2px; font-size: 12px; line-height: 1.5; color: var(--text-3); }
.wk-floors { margin-top: 12px; }
.wk-maint-off { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 12px; align-items: center; }
.wk-maint-t { font-size: 14px; color: var(--text-1); }
.wk-maint-d { margin-top: 2px; font-size: 12px; line-height: 1.5; color: var(--text-3); }
.wk-maint-state { display: inline-flex; align-items: center; gap: 5px; font-size: 13px; color: var(--text-3); white-space: nowrap; }
.wk-dot.on { background: var(--success-solid); }
.wk-maint-rows { display: grid; grid-template-columns: 92px minmax(0, 1fr); gap: 7px 12px; font-size: 13.5px; line-height: 1.5; }
.wk-maint-rows > .k { color: var(--text-3); font-size: 12.5px; padding-top: 1px; }
.wk-maint-rows > .v { color: var(--text-1); min-width: 0; overflow-wrap: anywhere; }
.wk-maint-rows .dim { color: var(--text-3); }
.wk-maint-rows .wk-dot { margin-right: 2px; }
.wk-maint-foot { display: flex; align-items: center; gap: 8px; margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--border-subtle); }
.wk-setup { display: flex; flex-direction: column; }
.wk-setup-k { margin: 12px 0 6px; font-size: 13px; font-weight: 500; color: var(--text-1); }
.wk-setup-d { margin-top: 5px; font-size: 12px; line-height: 1.5; color: var(--text-3); }
.wk-setup-limit { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--text-2); }
.wk-setup-limit .ant-input-number { width: 72px; }
.wk-setup-days { margin-top: 8px; }
.wk-setup-refusal { margin: 14px 0 0; }
@media (max-width: 600px) {
  .wk-maint-off { grid-template-columns: minmax(0, 1fr) auto; }
  .wk-maint-off > .ant-btn { grid-column: 1 / -1; justify-self: start; }
}

.wk-markbar { display: flex; gap: 8px; align-items: flex-start; margin: 0 20px 6px; padding: 9px 12px; border-radius: 8px;
              border: 1px solid var(--border-subtle); background: var(--fill-inset); font-size: 13px; line-height: 1.5; color: var(--text-1); }
.wk-markbar > .ic { margin-top: 3px; font-size: 14px; color: var(--text-3); }
.wk-markbar b { font-weight: 600; }
.wk-markbar.tone-green { background: var(--success-bg); border-color: var(--success-border); }
.wk-markbar.tone-green > .ic, .wk-markbar.tone-green b { color: var(--success); }
.wk-markbar.tone-amber { background: var(--warning-bg); border-color: var(--warning-border); }
.wk-markbar.tone-amber > .ic, .wk-markbar.tone-amber b { color: var(--warning); }
.wk-markbar-line { margin-top: 2px; font-size: 12px; color: var(--text-3); }

.wk-run-meta { margin-top: 6px; font-size: 12.5px; color: var(--text-3); }
.wk-run-actions { display: flex; flex-wrap: wrap; gap: 8px; padding: 0 20px 12px; }
.wk-run-counts { display: flex; flex-wrap: wrap; gap: 4px 14px; margin: 0 20px; padding: 9px 12px; border-radius: 8px;
                 background: var(--fill-inset); font-size: 12.5px; color: var(--text-2); }
.wk-run-rows { border: 1px solid var(--border-subtle); border-radius: 8px; overflow: hidden; }
.wk-run-row { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 10px; align-items: center; padding: 8px 10px; }
.wk-run-row + .wk-run-row { border-top: 1px solid var(--border-subtle); }
.wk-run-row .main { min-width: 0; }
.wk-run-row .t { font-size: 13.5px; font-weight: 600; color: var(--text-1); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-run-row .t a { color: inherit; text-decoration: none; }
.wk-run-row .t a:hover { text-decoration: underline; }
.wk-run-row .d { margin-top: 1px; font-size: 12px; color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-run-reject, .wk-row-reject { display: none; padding: 0; border: 0; background: transparent; font: inherit; font-size: 12.5px;
                                 color: var(--error); cursor: pointer; white-space: nowrap; }
.wk-run-row:hover .wk-run-reject, .wk-run-row:focus-within .wk-run-reject { display: inline; }
.wk-erow:hover .wk-row-reject, .wk-erow:focus-within .wk-row-reject { display: inline; }
.wk-erow:hover .used .n, .wk-erow:focus-within .used .n { display: none; }
.wk-menu-foot { font-size: 12px; color: var(--text-3); }
.wk-revert-body p { margin: 0 0 8px; }
.wk-revert-body p:last-child { margin-bottom: 0; color: var(--text-3); }
.wk-tl-acts { display: flex; gap: 12px; margin-top: 2px; font-size: 12px; }
.wk-tl-acts a { color: var(--brand); text-decoration: none; }
.wk-tl-acts button { padding: 0; border: 0; background: transparent; font: inherit; color: var(--brand); cursor: pointer; }
.wk-tl-acts button.danger { color: var(--error); }
.wk-challenge-line .dim { color: var(--text-3); }
/* A phone has no pointer to hover with: a run's row is the way in, and Reject is on the entry. */
@media (max-width: 600px) {
  .wk-tl-acts { display: none; }
  .wk-run-row:hover .wk-run-reject { display: none; }
  .wk-erow:hover .wk-row-reject { display: none; }
  .wk-erow:hover .used .n { display: inline; }
}

/* ── phone: one column, in the order the phone mocks draw (07–09) ────────────────────────────── */
@media (max-width: 900px) {
  .rv-cols { grid-template-columns: minmax(0, 1fr); }
  .wk-sec-h .cols { display: none; }
  .wk-erow { grid-template-columns: 22px minmax(0, 1fr); row-gap: 4px; }
  .wk-erow > span:nth-child(3), .wk-erow > span:nth-child(4), .wk-erow .used { grid-column: 2; text-align: left; }
  .wk-topic-page .t-title, .wk-drawer .tdp-title { font-size: 22px; }
}
@media (max-width: 600px) {
  .wk-page, .rv-page { max-width: none; }
  .wk-drawer { width: 100%; }
  .wk-select select { max-width: 120px; }
  .wk-dkv, .wk-pkv { grid-template-columns: minmax(0, 1fr); }
  .wk-pkv > .k { padding-top: 6px; }
  .rv-head { flex-direction: column; align-items: flex-start; }
  .wk-seg { margin-left: 0; }
}

/* ── the articles (criterion 10, mocks 11–16): the directory, a topic's article, Browse, the A–Z index ──
   Ported from the mocks' own sheet (`docs/mocks/wiki/wiki-p2.css`) the way the phase-1 block above
   was: the directory is the app sidebar's rows one step smaller, the article's head is the topic
   page's (`.t-title`, `.t-meta`), its entries are the topic page's groups (`.wk-sec`, `.wk-erow`) and a
   footnote's card is antd's Popover — on a phone the Drawer from the bottom. The Contents drawer is
   the app drawer's own shape (`.app-nav` below 960px): 320px from the left over a 40% scrim. */
.wk-layout { display: grid; grid-template-columns: 224px minmax(0, 1fr); gap: 32px; align-items: start; margin-top: 18px; }
.wk-layout.home { gap: 24px; }
.wk-main { min-width: 0; }
.wk-layout .wk-cols { margin-top: 0; }
.wk-page .wk-contents-btn { display: none; }

.wk-toc { display: block; min-width: 0; margin-left: -8px; padding-top: 2px; }
.wk-toc-item { display: flex; align-items: center; gap: 9px; height: 32px; padding: 0 8px; border-radius: 6px;
               font-size: 13.5px; color: var(--text-1); white-space: nowrap; min-width: 0; text-decoration: none; }
.wk-toc-item:hover { background: var(--bg-hover); color: var(--text-1); }
.wk-toc-item .tp-ico { font-size: 15px; color: var(--text-2); display: inline-flex; }
.wk-toc-item .lb { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.wk-toc-item .n { flex: none; margin-left: 6px; font-size: 12px; color: var(--text-3); font-variant-numeric: tabular-nums; }
.wk-toc-item .caret { flex: none; font-size: 9px; color: var(--text-4); margin-left: -3px; }
.wk-toc-item.active, .wk-toc-item.active:hover { background: var(--brand-tint); color: var(--brand); font-weight: 600; }
.wk-toc-item.active .tp-ico, .wk-toc-item.active .n { color: var(--brand); }
.wk-toc-item.open { font-weight: 600; }
.wk-toc-item.sub { height: 28px; padding-left: 26px; font-size: 12.5px; color: var(--text-2); }
.wk-toc-item.sub.active { color: var(--brand); }
.wk-toc-cat { margin: 14px 8px 3px; font-size: 12px; font-weight: 600; color: var(--text-3); }
.wk-toc-sep { height: 1px; background: var(--border-subtle); margin: 8px 8px 0; }

.wk-contents-backdrop { position: fixed; inset: 0; z-index: 55; background: rgba(0, 0, 0, .4); }
.wk-contents { position: fixed; top: 0; left: 0; bottom: 0; z-index: 60; width: min(320px, 84vw); height: var(--app-vh, 100vh);
               display: flex; flex-direction: column; background: var(--bg-raised); box-shadow: 2px 0 16px rgba(0, 0, 0, .18); }
.wk-contents-h { display: flex; align-items: center; gap: 8px; height: 52px; flex: none; padding: 0 8px 0 16px;
                 border-bottom: 1px solid var(--border-subtle); }
.wk-contents-h b { flex: 1; font-size: 16px; font-weight: 600; color: var(--text-1); }
.wk-contents-x { display: inline-flex; align-items: center; justify-content: center; width: 36px; height: 36px; border: 0;
                 border-radius: 8px; background: transparent; color: var(--text-2); font-size: 15px; cursor: pointer; }
.wk-contents-body { flex: 1; overflow-y: auto; padding: 8px 8px 16px 16px; }
.wk-contents .wk-toc-item { height: 38px; font-size: 14.5px; }
.wk-contents .wk-toc-item.sub { height: 34px; font-size: 13.5px; }
.wk-contents .wk-toc-cat { font-size: 12.5px; }
.wk-contents .wk-toc-item .n { font-size: 12.5px; }

.wk-banner { display: none; align-items: center; gap: 9px; margin-top: 16px; padding: 10px 14px; border: 1px solid var(--warning-border);
             border-radius: 8px; background: var(--warning-bg); color: var(--text-1); font-size: 14px; text-decoration: none; }
.wk-banner .t { flex: 1; min-width: 0; }
.wk-banner .ic { font-size: 11px; color: var(--text-4); }
.wk-banner:hover { color: var(--text-1); }

.wk-art-page { min-width: 0; position: relative; }
.wk-topic-note { margin-top: 10px; }
.wk-art-crumbrow { display: flex; align-items: center; gap: 8px; min-width: 0; }
.wk-art-crumbrow .wk-crumb { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; }
.wk-art-page .t-title { font-size: 30px; line-height: 1.28; letter-spacing: -.02em; }
.wk-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; align-items: center; }
.wk-tag { display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px; border-radius: 999px;
          background: var(--fill-muted); color: var(--text-2); font-size: 12px; white-space: nowrap; }
.wk-tag.cat { background: var(--brand-tint); color: var(--brand-strong); }
.wk-art-page .t-meta { flex-wrap: wrap; gap: 6px 9px; }
.wk-art-page .t-meta .ic { font-size: 12px; color: var(--text-3); }
.wk-art-page .wk-art-updated { display: block; line-height: 1.6; }
.wk-art-page .wk-art-updated .ic { margin-right: 6px; }
.wk-art { margin-top: 20px; font-size: 15px; line-height: 1.85; color: var(--text-1); }
.wk-art p { margin: 0 0 12px; }
.wk-art h2 { margin: 26px 0 10px; padding-bottom: 6px; font-size: 18px; font-weight: 650; line-height: 1.4;
             border-bottom: 1px solid var(--border-subtle); }
.wk-art code, .wk-fncard code, .wk-fnlist code {
  font-family: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; font-size: .86em;
  background: var(--fill-inset); border-radius: 4px; padding: 1px 4px; overflow-wrap: anywhere; }
.wk-fn { font-size: 11px; line-height: 0; vertical-align: super; margin-left: 1px; white-space: nowrap; }
.wk-fn-n { display: inline-block; padding: 0 1px; border: 0; border-radius: 3px; background: transparent; font: inherit;
            line-height: 1.15; color: var(--brand); cursor: pointer; }
.wk-fn-n:hover { text-decoration: underline; }
.wk-fn-n.on { background: var(--brand); color: #fff; text-decoration: none; }
.wk-art .hl { background: color-mix(in srgb, var(--brand-tint) 80%, transparent); border-radius: 3px;
              box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand-tint) 80%, transparent); }

.wk-fncard { width: 380px; max-width: 100%; }
.wk-fncard .k { display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; color: var(--text-2); }
.wk-fncard .k .num { font: 600 11px/18px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--brand); }
.wk-fncard .k .kind { display: inline-flex; color: var(--text-3); }
.wk-fncard .k .tdp-badge { margin-left: auto; }
.wk-fncard .t { margin-top: 7px; font-size: 14.5px; font-weight: 650; line-height: 1.45; color: var(--text-1); }
.wk-fncard .d { margin-top: 5px; font-size: 13px; line-height: 1.6; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 3;
                -webkit-box-orient: vertical; overflow: hidden; }
.wk-fncard .f { display: flex; align-items: center; gap: 8px; margin-top: 10px; padding-top: 9px; border-top: 1px solid var(--border-subtle);
                font-size: 12px; color: var(--text-3); white-space: nowrap; }
.wk-fncard .f .go { margin-left: auto; padding: 0; border: 0; background: transparent; font: inherit; color: var(--brand);
                    font-weight: 600; font-size: 12.5px; cursor: pointer; }
.wk-fncard.sheet { width: auto; padding: 8px 16px 16px; }
.wk-fncard.sheet .k { font-size: 12.5px; }
.wk-fncard.sheet .t { margin-top: 8px; font-size: 16px; }
.wk-fncard.sheet .d { margin-top: 6px; font-size: 14px; line-height: 1.65; -webkit-line-clamp: 4; }
.wk-fncard.sheet .f { border-top: 0; padding-top: 0; font-size: 12.5px; }
.wk-fncard-open { margin-top: 14px; }
.wk-fnsheet .ant-drawer-content { border-radius: 12px 12px 0 0; }
.wk-fnsheet .ant-drawer-body::before { content: ""; display: block; width: 36px; height: 4px; border-radius: 2px; background: var(--border);
                                       margin: 8px auto 4px; }

.wk-fnlist { margin-top: 30px; }
.wk-fnlist h3, .wk-art-entries-h { margin: 0 0 8px; font-size: 15px; font-weight: 650; color: var(--text-1); display: flex;
                                   align-items: baseline; gap: 8px; }
.wk-fnlist h3 small, .wk-art-entries-h small { font-size: 12.5px; font-weight: 400; color: var(--text-3); }
.wk-fnlist ol { margin: 0; padding: 0; list-style: none; }
.wk-fnlist li { display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; gap: 6px; align-items: baseline; padding: 3px 0;
                font-size: 13px; line-height: 1.55; color: var(--text-2); }
.wk-fnlist li .no { text-align: right; color: var(--text-3); font-variant-numeric: tabular-nums; }
.wk-fnlist li .tt { min-width: 0; color: var(--text-1); text-decoration: underline; text-decoration-color: var(--border);
                    text-underline-offset: 3px; }
.wk-fnlist li .tt.gone { color: var(--text-3); text-decoration: none; }
.wk-fnlist li .mt { white-space: nowrap; font-size: 12px; color: var(--text-3); display: inline-flex; align-items: center; gap: 6px; }
.wk-fnlist li .tdp-badge { font-size: 11px; line-height: 16px; padding: 0 6px; }
.wk-art-entries { margin-top: 34px; }
.wk-art-entries .wk-sec:first-of-type { margin-top: 10px; }
.wk-art-entries .wk-sec-h h3 { white-space: nowrap; }
.wk-art-entries .wk-sec-h .note { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-art-entries .wk-sec-h .cols { flex: none; }

.wk-browse-cat { margin-top: 26px; }
.wk-browse-cat > h2 { display: flex; align-items: baseline; gap: 10px; margin: 0 0 4px; padding-bottom: 8px;
                      border-bottom: 1px solid var(--border-subtle); font-size: 18px; font-weight: 650; color: var(--text-1); }
.wk-browse-cat > h2 small { font-size: 12.5px; font-weight: 400; color: var(--text-3); }
.wk-browse-topic { padding: 12px 0 10px; border-bottom: 1px solid var(--border-subtle); }
.wk-browse-topic .h { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.wk-browse-topic .h a, .wk-browse-topic .h b { font-size: 14.5px; font-weight: 650; color: var(--brand); text-decoration: none; }
.wk-browse-topic .h b { color: var(--text-1); }
.wk-browse-topic .h .n { font-size: 12px; color: var(--text-3); white-space: nowrap; }
.wk-browse-caret { display: none; margin-left: auto; padding: 0 2px; border: 0; background: transparent; font-size: 11px;
                   color: var(--text-4); cursor: pointer; }
.wk-browse-topic .ov { margin-top: 2px; font-size: 12.5px; line-height: 1.6; color: var(--text-2); display: -webkit-box;
                       -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.wk-browse-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 28px; margin-top: 6px; }
.wk-browse-list a { display: flex; gap: 8px; align-items: baseline; padding: 3px 0; font-size: 13px; min-width: 0; color: var(--text-1);
                    text-decoration: none; }
.wk-browse-list a:hover .tt { color: var(--brand); }
.wk-browse-list .tt { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-browse-list .n { flex: none; font-size: 11.5px; color: var(--text-3); font-variant-numeric: tabular-nums; }
.wk-browse-list .dash { flex: 1; border-bottom: 1px dotted var(--border); transform: translateY(-4px); min-width: 12px; }
.wk-browse-topic .wk-more { padding-top: 4px; }

.wk-az-bar { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 16px; }
.wk-az-bar > * { display: inline-flex; align-items: center; justify-content: center; min-width: 24px; height: 26px; padding: 0 4px;
                 border-radius: 6px; border: 1px solid var(--border-subtle); font-family: inherit; font-size: 12.5px; font-weight: 600;
                 line-height: 1; color: var(--brand);
                 background: var(--bg-raised); }
.wk-az-bar button { cursor: pointer; }
.wk-az-bar button:hover { background: var(--brand-tint); border-color: var(--brand-border); }
.wk-az-bar .off { color: var(--text-4); background: var(--bg-subtle); }
.wk-az-g { margin-top: 22px; scroll-margin-top: 12px; }
.wk-az-g > h2 { display: flex; align-items: baseline; gap: 8px; margin: 0 0 4px; padding-bottom: 6px; border-bottom: 1px solid var(--border-subtle);
                font-size: 18px; font-weight: 650; }
.wk-az-g > h2 small { font-size: 12px; font-weight: 400; color: var(--text-3); }
.wk-az-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 28px; }
.wk-az-list a { display: flex; align-items: baseline; gap: 8px; padding: 5px 0; border-bottom: 1px solid var(--border-subtle); min-width: 0;
                font-size: 13.5px; color: var(--text-1); text-decoration: none; }
.wk-az-list a:hover .t { color: var(--brand); }
.wk-az-list .t { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-az-list .t.ov { font-weight: 650; }
.wk-az-list .m { flex: none; margin-left: auto; font-size: 12px; color: var(--text-3); white-space: nowrap; }

/* A desktop too narrow for the home's rail beside its main column and the directory: one column. */
@media (min-width: 961px) and (max-width: 1320px) {
  .wk-layout .wk-cols { grid-template-columns: minmax(0, 1fr); }
}

/* ── narrower than the app's desktop layout (960px, `MOBILE_QUERY`): the phone mocks 12, 14, 16 ────
   One column in the phone's order: the head, the status line, the search, then the Review bar,
   Principles, Recent decisions, Recently changed and Agents used the wiki — the right rail's Review
   card is the bar above, and the rest of the rail follows the main column. The directory is the
   Contents drawer; a reading page other than the home drops the head for its crumb row, which
   carries the list button. iOS draws the same blocks in the same order. */
@media (max-width: 960px) {
  .wk-page { display: flex; flex-direction: column; }
  .wk-page > .wk-title-row { order: 0; }
  .wk-page > .wk-status-row { order: 1; margin-top: 8px; background: none; border: 0; border-radius: 0; }
  .wk-page > .wk-status-row .project-integration-row { padding: 0; cursor: default; }
  .wk-page > .wk-search { order: 2; margin-top: 12px; height: 40px; }
  .wk-page > .wk-layout, .wk-page > .wk-body { order: 3; }
  .wk-status-review { display: none; }
  /* The phone's status line is one sentence that wraps where its words do (mock 12 ④), not a row of chips. */
  .wk-page > .wk-status-row .project-integration-facts { display: block; line-height: 1.6; }
  .wk-page > .wk-status-row .project-integration-facts > :not(.wk-status-review),
  .wk-page > .wk-status-row .wk-maint { display: inline; white-space: normal; }
  .wk-page > .wk-status-row .wk-sep { margin: 0 6px; }
  .wk-maint-spin { display: none; }
  .wk-page--reading > .wk-title-row, .wk-page--reading > .wk-search, .wk-page--reading > .wk-status-row { display: none; }
  .wk-layout { display: block; margin-top: 0; }
  .wk-dir-col { display: none; }
  .wk-page .wk-contents-btn { display: inline-flex; }
  .wk-banner { display: flex; }
  .wk-review-card { display: none; }
  .wk-cols { display: flex; flex-direction: column; gap: 16px; }
  .wk-art-page .t-title, .wk-browse-page .t-title, .wk-az-page .t-title { margin-top: 10px; font-size: 24px; line-height: 1.35; letter-spacing: -.015em; }
  .wk-art { margin-top: 14px; font-size: 16px; line-height: 1.8; }
  .wk-art h2 { margin: 22px 0 8px; font-size: 17px; }
  .wk-fn { font-size: 11.5px; }
  .wk-fnlist li { grid-template-columns: 24px minmax(0, 1fr); padding: 9px 2px 10px; border-bottom: 1px solid var(--border-subtle); }
  .wk-fnlist li .no { text-align: left; }
  .wk-fnlist li .tt { font-size: 14px; text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .wk-fnlist li .mt { grid-column: 2; margin-top: 2px; font-size: 12.5px; }
  /* An article's entries on a phone: the title with its mark beside it, the summary under (mock 14 ④). */
  .wk-art-entries .wk-erow { grid-template-columns: minmax(0, 1fr) auto; column-gap: 10px; }
  .wk-art-entries .wk-erow > .wk-kind, .wk-art-entries .wk-erow > span:nth-child(4), .wk-art-entries .wk-erow .used { display: none; }
  .wk-browse-caret { display: inline-flex; }
  .wk-browse-list { grid-template-columns: minmax(0, 1fr); margin: 6px 0 0 14px; }
  .wk-browse-list a { padding: 9px 0; border-bottom: 1px solid var(--border-subtle); font-size: 14px; }
  .wk-browse-list .dash { display: none; }
  .wk-browse-list .n { margin-left: auto; }
  .wk-az-bar > * { width: 30px; height: 30px; font-size: 13px; }
  .wk-az-g { margin-top: 16px; }
  .wk-az-g > h2 { padding: 4px 8px; font-size: 13px; color: var(--text-2); background: var(--bg-subtle); border-radius: 4px 4px 0 0; }
  .wk-az-g > h2 small { display: none; }
  .wk-az-list { grid-template-columns: minmax(0, 1fr); }
  .wk-az-list a { flex-direction: column; align-items: stretch; gap: 1px; padding: 9px 2px; font-size: 14px; }
  .wk-az-list .m { margin-left: 0; font-size: 12.5px; }
}

/* ── the documents and the plan (criterion 10 revised 2026-09-28, criterion 11: mocks 21–28) ──────
   Ported from the mocks' own sheet (`docs/mocks/wiki/wiki-p3.css`), its short prefixes made the Wiki's:
   pl- → wk-pl- (the plan page), dc- → wk-dc- (a document's page), fn2 → wk-fn2 (a footnote's card and the
   footnotes' list), s- → wk-s- (a sentence's marks). Every colour is a shipped token; a change's card is
   Review's own `.approval-card`, the home's Plan card is the Open items card Review's is. */

/* the directory by the plan */
.wk-toc-item .no { flex: none; min-width: 24px; font-size: 12px; color: var(--text-3); font-variant-numeric: tabular-nums; }
.wk-toc-item.active .no { color: var(--brand); }
.wk-toc-item .st { flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--warning-solid); margin-left: 6px; }
.wk-toc-item.todo .lb { color: var(--text-3); }
.wk-toc-item.sec { height: 27px; padding-left: 34px; font-size: 12.5px; color: var(--text-2); }
.wk-toc-item.sec .no { min-width: 16px; font-size: 11.5px; }
.wk-toc-item.sec.active { color: var(--brand); font-weight: 600; background: none; }
.wk-toc-item .tp-count { margin-left: auto; font-size: 11px; }

/* a text button that reads as a link */
.wk-pl-page .lk, .wk-dc-tip .lk { padding: 0; border: 0; background: transparent; font: inherit; color: var(--brand); cursor: pointer; }
.wk-dc-tip .lk { color: #8fb5ff; }

/* the plan page's head: title and version, the line under them, the actions — one DOM, two arrangements */
.wk-pl-page { min-width: 0; position: relative; }
.wk-pl-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title acts" "meta meta"; align-items: center; gap: 0 10px; }
.wk-pl-head > .wk-pl-titlerow { grid-area: title; }
.wk-pl-head > .wk-pl-meta { grid-area: meta; }
.wk-pl-head > .wk-pl-acts { grid-area: acts; }
.wk-pl-titlerow { display: flex; align-items: center; gap: 10px; margin-top: 6px; min-width: 0; }
.wk-pl-titlerow .t-title { margin: 0; font-size: 30px; line-height: 1.28; letter-spacing: -.02em; min-width: 0; }
.wk-pl-titlerow .t-title .ic.lock { margin-left: 8px; font-size: 20px; color: var(--text-3); }
.wk-pl-acts { display: flex; align-items: center; gap: 8px; margin-top: 6px; }
.wk-pl-ver { display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 11px 0 12px; border: 1px solid var(--border); border-radius: 6px;
             background: var(--bg-raised); font: inherit; font-size: 14px; color: var(--text-1); white-space: nowrap; cursor: pointer; }
.wk-pl-ver .ic { font-size: 10px; color: var(--text-3); }
.wk-pl-ver .tdp-badge, .wk-pl-verrow .tdp-badge { font-size: 11px; line-height: 16px; padding: 0 6px; }
.wk-pl-verrow { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 8px; align-items: center; min-width: 300px; }
.wk-pl-verrow .v { font: 650 12.5px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-1); }
.wk-pl-verrow .d { color: var(--text-2); font-size: 12.5px; }
.wk-pl-meta { margin-top: 8px; font-size: 13px; color: var(--text-2); display: flex; flex-wrap: wrap; gap: 4px 9px; align-items: center; }
.wk-pl-meta .sep { color: var(--text-4); }
.wk-pl-meta .errn { color: var(--error); font-weight: 600; }
.wk-pl-hint { margin-top: 6px; font-size: 12.5px; color: var(--text-3); }

/* the plan check, and the job's card — an antd Alert-coloured card, one row a check */
.wk-pl-check { margin-top: 16px; border-radius: 10px; border: 1px solid var(--border-subtle); background: var(--bg-raised); overflow: hidden; }
.wk-pl-check > .h { display: flex; align-items: center; gap: 9px; padding: 11px 14px; border-bottom: 1px solid var(--border-subtle); font-size: 14px; }
.wk-pl-check > .h .ic { font-size: 16px; flex: none; }
.wk-pl-check > .h b { font-weight: 650; color: var(--text-1); white-space: nowrap; }
.wk-pl-check > .h .sub { color: var(--text-2); font-size: 13px; min-width: 0; }
.wk-pl-check > .h .r { margin-left: auto; font-size: 12.5px; color: var(--text-3); white-space: nowrap; }
.wk-pl-check > .h a.r { color: var(--brand); text-decoration: none; }
.wk-pl-check.solo > .h { border-bottom: 0; }
.wk-pl-check.fail { border-color: var(--error-border); }
.wk-pl-check.fail > .h { background: var(--error-bg); border-bottom-color: var(--error-border); }
.wk-pl-check.fail > .h .ic, .wk-pl-check.fail > .h b { color: var(--error); }
.wk-pl-check.pass { border-color: var(--success-border); }
.wk-pl-check.pass > .h { background: var(--success-bg); border-bottom-color: var(--success-border); }
.wk-pl-check.pass > .h .ic, .wk-pl-check.pass > .h b { color: var(--success); }
.wk-pl-check.run { border-color: var(--brand-border); }
.wk-pl-check.run > .h { background: var(--brand-tint); border-bottom-color: var(--brand-border); }
.wk-pl-check.run > .h b { color: var(--brand-strong); }
.wk-pl-check.run > .h .ic { color: var(--brand); }
.wk-pl-check.wait > .h { background: var(--bg-subtle); }
.wk-pl-check.wait > .h .ic { color: var(--text-3); }
.wk-pl-check.held { border-color: var(--warning-border); }
.wk-pl-check.held > .h { background: var(--warning-bg); border-bottom-color: var(--warning-border); }
.wk-pl-check.held > .h .ic, .wk-pl-check.held > .h b { color: var(--warning); }
.wk-pl-prog { padding: 10px 14px 12px; }
.wk-pl-prog .bar { height: 6px; border-radius: 3px; background: var(--fill-muted); overflow: hidden; }
.wk-pl-prog .bar i { display: block; height: 100%; border-radius: 3px; background: var(--brand); }
.wk-pl-prog .next { margin-top: 7px; font-size: 12.5px; color: var(--text-2); }
.wk-pl-ck { display: grid; grid-template-columns: 18px 150px minmax(0, 1fr); gap: 10px; align-items: baseline; padding: 8px 14px; font-size: 13px; line-height: 1.6; }
.wk-pl-ck + .wk-pl-ck { border-top: 1px solid var(--border-subtle); }
.wk-pl-ck > .ic { font-size: 13px; transform: translateY(2px); }
.wk-pl-ck.is-ok > .ic { color: var(--success); }
.wk-pl-ck.is-bad > .ic { color: var(--error); }
.wk-pl-ck .n { font-weight: 600; color: var(--text-1); }
.wk-pl-ck .r { color: var(--text-1); min-width: 0; font-weight: 400; overflow-wrap: anywhere; }
.wk-pl-ck code, .wk-pl-err code, .wk-pl-kv code, .wk-pl-src code, .wk-pl-sec code, .wk-fn2 code, .wk-dc-scope code {
  font: 12px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; background: var(--fill-inset); border-radius: 4px; padding: 0 4px; }
.wk-pl-errs { grid-column: 2 / -1; margin-top: 4px; border: 1px solid var(--border-subtle); border-radius: 8px; overflow: hidden; }
.wk-pl-errs .by { display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 6px 10px; background: var(--bg-subtle); border-bottom: 1px solid var(--border-subtle); font-size: 12px; color: var(--text-2); }
.wk-pl-errs .by b { color: var(--text-1); font-weight: 650; font-variant-numeric: tabular-nums; }
.wk-pl-err { display: grid; grid-template-columns: 58px 86px minmax(0, 1fr); gap: 8px; align-items: baseline; padding: 6px 10px; font-size: 12.5px; line-height: 1.5; }
.wk-pl-err + .wk-pl-err { border-top: 1px solid var(--border-subtle); }
.wk-pl-err .at { font: 600 11.5px/18px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--brand); }
.wk-pl-err .k { color: var(--text-3); white-space: nowrap; }
.wk-pl-err .m { color: var(--text-1); min-width: 0; overflow-wrap: anywhere; }
.wk-pl-err .m .why { color: var(--error); }
.wk-pl-errs .more { display: block; width: 100%; text-align: left; padding: 6px 10px 7px; border: 0; border-top: 1px solid var(--border-subtle); background: transparent;
                    font: inherit; font-size: 12.5px; color: var(--brand); cursor: pointer; }

/* no plan yet */
.wk-pl-empty { margin-top: 18px; padding: 36px 40px 30px; border: 1px dashed var(--border); border-radius: 12px; background: var(--bg-raised); text-align: center; }
.wk-pl-empty > .ic { font-size: 40px; color: var(--text-4); }
.wk-pl-empty > b { display: block; margin-top: 12px; font-size: 18px; font-weight: 650; color: var(--text-1); }
.wk-pl-empty > p { max-width: 560px; margin: 8px auto 16px; font-size: 13.5px; line-height: 1.7; color: var(--text-2); }
.wk-pl-empty > .note { max-width: 560px; margin: 12px auto 0; font-size: 12px; line-height: 1.6; color: var(--text-3); }

/* changes to review: the Review card (04), with the plan's parts */
.wk-pl-changes { margin-top: 18px; }
.wk-pl-changes > .h { display: flex; align-items: baseline; gap: 8px; margin-bottom: 10px; }
.wk-pl-changes > .h h2 { margin: 0; font-size: 16px; font-weight: 650; }
.wk-pl-changes > .h .n { font-size: 12.5px; color: var(--text-3); }
.wk-pl-changes .approval-card + .approval-card { margin-top: 14px; }
.wk-pl-prop .approval-head .by b { color: var(--brand); font-weight: 600; }
.wk-pl-prop .card-actions .grow { flex: 1; }
.wk-pl-prop .card-actions .note { font-size: 12px; color: var(--text-3); }
.wk-op.plan { min-width: 0; }
.wk-pl-okline { display: inline-flex; align-items: center; gap: 5px; color: var(--success); font-weight: 600; font-size: 12.5px; }
.wk-pl-new { margin-top: 2px; border: 1px solid var(--success-border); border-radius: 8px; overflow: hidden; }
.wk-pl-new .row { display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; gap: 8px; align-items: baseline; padding: 5px 10px; font-size: 13px; }
.wk-pl-new .row + .row { border-top: 1px solid var(--border-subtle); }
.wk-pl-new .row.add { background: var(--success-bg); }
.wk-pl-new .row.remove { background: var(--error-bg); }
.wk-pl-new .row .n { font: 600 11.5px/18px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-3); }
.wk-pl-new .row.add .n { color: var(--success); }
.wk-pl-new .row.remove .n { color: var(--error); }
.wk-pl-new .row.add .t { font-weight: 600; }
.wk-pl-new .row .ty { font-size: 12px; color: var(--text-3); white-space: nowrap; }
.wk-pl-new .row.ctx { color: var(--text-3); }
.wk-pl-fact + .wk-pl-fact, .wk-pkv .orbit-link-card + .wk-pl-fact { margin-top: 6px; }
.wk-pl-fact a { color: var(--brand); text-decoration: none; }
.wk-pl-more { margin-top: 6px; font-size: 12.5px; color: var(--brand); }
.wk-pl-refused { margin-top: 10px; padding: 8px 10px; border: 1px solid var(--error-border); border-radius: 8px; background: var(--error-bg); font-size: 12.5px; color: var(--error); }
.wk-pl-refused ul { margin: 4px 0 0; padding-left: 18px; }

/* the plan's body: category → document → section → sources */
.wk-pl-docs-h { display: flex; align-items: baseline; gap: 8px; margin-top: 24px; padding-bottom: 8px; border-bottom: 1px solid var(--border-subtle); }
.wk-pl-docs-h h2 { margin: 0; font-size: 16px; font-weight: 650; }
.wk-pl-docs-h .n { font-size: 12.5px; color: var(--text-3); }
.wk-pl-docs-h .c { margin-left: auto; font-size: 12px; color: var(--text-3); }
.wk-pl-cat { margin-top: 22px; }
.wk-pl-cat-h { display: flex; align-items: baseline; gap: 9px; padding-bottom: 7px; border-bottom: 1px solid var(--border-subtle); }
.wk-pl-cat-h .no { font: 650 14px/1 ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-3); }
.wk-pl-cat-h b { font-size: 16px; font-weight: 650; color: var(--text-1); white-space: nowrap; }
.wk-pl-cat-h .q { flex: 1; min-width: 0; font-size: 12.5px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-pl-cat-h .c { font-size: 12px; color: var(--text-3); white-space: nowrap; }
.wk-pl-doc { display: grid; grid-template-columns: 14px 34px minmax(0, 1fr) auto; gap: 0 8px; align-items: baseline; padding: 9px 4px 9px 2px; border-bottom: 1px solid var(--border-subtle); }
.wk-pl-doc > .caret { padding: 0; border: 0; background: transparent; font-size: 9px; color: var(--text-4); cursor: pointer; transform: translateY(-1px); }
.wk-pl-doc > .no { font: 600 12.5px/20px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-2); }
.wk-pl-doc > .main { display: block; min-width: 0; padding: 0; border: 0; background: transparent; font: inherit; text-align: left; cursor: pointer; }
.wk-pl-doc .main > .t { display: flex; align-items: center; gap: 7px; min-width: 0; font-size: 14px; font-weight: 600; line-height: 20px; color: var(--text-1); }
.wk-pl-doc .main > .t .tt { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wk-pl-doc .main > .t .ic.lock { flex: none; font-size: 12px; color: var(--text-3); }
.wk-pl-doc .main > .q { display: block; margin-top: 1px; font-size: 12.5px; line-height: 18px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-pl-doc > .meta { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-3); white-space: nowrap; }
.wk-pl-doc .errn { display: inline-flex; align-items: center; gap: 4px; color: var(--error); font-weight: 600; }
.wk-pl-doc .errn .ic { font-size: 12px; }
.wk-pl-chg { padding: 0 7px; border-radius: 999px; background: var(--warning-bg); color: var(--warning); font-weight: 600; font-size: 11.5px; line-height: 18px; }
.wk-pl-diff { flex: none; padding: 0 6px; border-radius: 4px; font-size: 11px; line-height: 16px; font-weight: 600; }
.wk-pl-diff.new { background: var(--success-bg); color: var(--success); }
.wk-pl-diff.changed { background: var(--brand-tint); color: var(--brand-strong); }
.wk-pl-doc.gone .main .tt { text-decoration: line-through; color: var(--text-3); }
.wk-pl-doc.open { background: var(--bg-raised); border: 1px solid var(--brand-border); border-radius: 10px; margin: 8px 0 6px; padding: 12px 14px 8px 12px; }
.wk-pl-doc.open > .caret { color: var(--brand); }
.wk-pl-body { grid-column: 2 / -1; margin-top: 10px; }
.wk-pl-kv { display: grid; grid-template-columns: 104px minmax(0, 1fr); gap: 7px 12px; font-size: 13px; line-height: 1.65; }
.wk-pl-kv > .k { color: var(--text-3); font-size: 12.5px; padding-top: 1px; white-space: nowrap; }
.wk-pl-kv > .v { color: var(--text-1); min-width: 0; }
.wk-pl-kv > .v ul { margin: 0; padding-left: 16px; }
.wk-pl-kv > .v li + li { margin-top: 1px; }
.wk-pl-kv > .v .see { color: var(--brand); white-space: nowrap; }
.wk-pl-kv > .v .lockline { display: inline-flex; align-items: center; gap: 6px; }
.wk-pl-kv > .v .lockline .ic { color: var(--text-3); }
.wk-pl-kv > .v .dim { color: var(--text-3); }
.wk-pl-secs { margin-top: 12px; border-top: 1px solid var(--border-subtle); }
.wk-pl-secs > .h { display: flex; align-items: baseline; gap: 8px; padding: 10px 0 4px; font-size: 13px; font-weight: 650; color: var(--text-1); }
.wk-pl-secs > .h .c { font-weight: 400; color: var(--text-3); font-size: 12px; }
.wk-pl-sec { display: grid; grid-template-columns: 22px minmax(0, 1fr) 92px 70px minmax(0, 190px); gap: 10px; align-items: baseline; padding: 7px 0;
             border-top: 1px solid var(--border-subtle); font-size: 13px; line-height: 1.5; }
.wk-pl-secs > .h + .wk-pl-sec { border-top: 0; }
.wk-pl-sec > .n { font: 600 12px/19px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-3); text-align: right; }
.wk-pl-sec > .t { display: block; min-width: 0; padding: 0; border: 0; background: transparent; font: inherit; text-align: left; color: var(--text-1); cursor: pointer; }
.wk-pl-sec .cov { display: block; margin-top: 1px; font-size: 12px; line-height: 1.55; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-pl-sec > .ty { font-size: 12px; color: var(--text-2); white-space: nowrap; }
.wk-pl-sec > .len { font-size: 12px; color: var(--text-3); white-space: nowrap; font-variant-numeric: tabular-nums; }
.wk-pl-sec > .src { font-size: 12px; color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-pl-sec.open { background: color-mix(in srgb, var(--brand-tint) 45%, var(--bg-raised)); margin: 0 -8px; padding: 7px 8px; border-radius: 6px; }
.wk-pl-sec.gone { background: var(--error-bg); margin: 0 -8px; padding: 7px 8px; border-radius: 6px; border-top-color: transparent; }
.wk-pl-sec.gone > .t { color: var(--text-3); text-decoration: line-through; cursor: default; }
.wk-pl-sec.gone + .wk-pl-sec { border-top-color: transparent; }
.wk-pl-sec .why { grid-column: 2 / -1; margin-top: -2px; font-size: 12px; color: var(--error); display: flex; align-items: center; gap: 6px; }
.wk-pl-src { grid-column: 2 / -1; margin: 4px 0 2px; padding: 8px 10px; border-radius: 8px; background: var(--bg-raised); border: 1px solid var(--border-subtle); }
.wk-pl-src .g { margin: 6px 0 2px; font-size: 11.5px; font-weight: 600; color: var(--text-3); letter-spacing: .2px; }
.wk-pl-src .g:first-child { margin-top: 0; }
.wk-pl-src .r { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; align-items: baseline; padding: 2px 0; font-size: 12.5px; line-height: 1.55; }
.wk-pl-src .r .p { min-width: 0; overflow-wrap: anywhere; color: var(--text-1); }
.wk-pl-src .r .p .sym { color: var(--text-2); }
.wk-pl-src .r .ok { color: var(--success); font-size: 11.5px; font-weight: 600; white-space: nowrap; }
.wk-pl-src .r .bad { color: var(--error); font-size: 11.5px; font-weight: 600; white-space: nowrap; }
.wk-pl-src .cond { display: grid; grid-template-columns: 92px minmax(0, 1fr); gap: 3px 10px; font-size: 12.5px; line-height: 1.55; }
.wk-pl-src .cond .k { color: var(--text-3); }
.wk-pl-src .cond .v { color: var(--text-1); min-width: 0; }
.wk-pl-src .cond .chip { display: inline-block; margin: 0 4px 3px 0; padding: 0 7px; border-radius: 999px; background: var(--fill-muted); font-size: 12px; line-height: 20px; color: var(--text-1); }
.wk-pl-src .cond code { margin-right: 4px; }

/* Edit (a document, in a right drawer) and Redraft… (a modal) */
.wk-pl-drawer-t .sub { font-size: 12px; font-weight: 500; color: var(--text-3); }
.wk-pl-form { padding: 0 0 8px; }
.wk-pl-f { display: block; margin-top: 12px; }
.wk-pl-f:first-child { margin-top: 0; }
.wk-pl-f .l { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; font-size: 13px; color: var(--text-1); }
.wk-pl-f .l .dim, .wk-pl-f .dim { color: var(--text-3); font-size: 12px; }
.wk-pl-f.row2 { display: flex; gap: 16px; align-items: flex-start; }
.wk-pl-f.row2 .grow { flex: 1; min-width: 0; }
.wk-pl-f .len, .wk-pl-f .sw { display: flex; align-items: center; gap: 8px; }
.wk-pl-f.hint { font-size: 12px; color: var(--text-3); }
.wk-pl-esec { display: grid; grid-template-columns: 16px 22px minmax(0, 1fr) 124px 22px; gap: 8px; align-items: center; padding: 6px 8px; border: 1px solid var(--border-subtle);
              border-radius: 6px; background: var(--bg-raised); font-size: 13px; cursor: grab; }
.wk-pl-esec + .wk-pl-esec { margin-top: 5px; }
.wk-pl-esec.dragging { opacity: .5; }
.wk-pl-esec .hd { color: var(--text-4); font-size: 13px; }
.wk-pl-esec .n { font: 600 11.5px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-3); text-align: right; }
.wk-pl-esec .t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-1); }
.wk-pl-esec .x { padding: 0; border: 0; background: transparent; color: var(--text-3); font-size: 12px; cursor: pointer; }
.wk-pl-add { margin-top: 8px; display: inline-flex; align-items: center; gap: 6px; padding: 0; border: 0; background: transparent; font: inherit; font-size: 13px; color: var(--brand); cursor: pointer; }
.wk-pl-dfoot { display: flex; justify-content: flex-end; align-items: center; gap: 8px; }
.wk-pl-dfoot .l { margin-right: auto; font-size: 12px; color: var(--text-3); }
.wk-pl-modal-t { display: inline-flex; align-items: center; gap: 8px; }
.wk-pl-modal-t .ic { color: var(--warning-solid); }
.wk-pl-modal-p { margin: 0 0 10px; font-size: 13px; line-height: 1.6; color: var(--text-2); }
.wk-pl-modal-note { margin-top: 8px; font-size: 12.5px; color: var(--text-3); }

/* a document's page */
.wk-dc-warn { color: var(--warning); }
.wk-dc-notwritten { display: flex; align-items: baseline; gap: 8px; margin-top: 12px; padding: 10px 14px; border: 1px solid var(--border-subtle); border-radius: 10px;
                    background: var(--bg-raised); font-size: 13.5px; line-height: 1.6; color: var(--text-1); }
.wk-dc-notwritten .ic { color: var(--text-2); }
.wk-dc-scope { margin-top: 14px; display: grid; grid-template-columns: 104px minmax(0, 1fr); gap: 6px 12px; padding: 11px 14px; border: 1px solid var(--border-subtle);
               border-radius: 10px; background: var(--bg-subtle); font-size: 13px; line-height: 1.65; }
.wk-dc-scope > .k { color: var(--text-3); font-size: 12.5px; padding-top: 1px; white-space: nowrap; }
.wk-dc-scope > .v { color: var(--text-1); min-width: 0; }
.wk-dc-scope > .v ul { margin: 0; padding-left: 16px; }
.wk-dc-scope > .v .see { color: var(--brand); white-space: nowrap; text-decoration: none; }
.wk-dc-scope > .v.q { font-weight: 600; }
.wk-dc-fold { grid-column: 1 / -1; display: flex; align-items: center; gap: 6px; margin: 2px -14px -11px; padding: 9px 14px; border: 0; border-top: 1px solid var(--border-subtle);
              background: transparent; font: inherit; font-size: 13.5px; color: var(--text-1); text-align: left; cursor: pointer; }
.wk-dc-fold .n { color: var(--text-3); font-size: 12.5px; }
.wk-dc-fold .ic { margin-left: auto; font-size: 11px; color: var(--text-4); }
.wk-dc-fold.up { justify-content: flex-end; padding: 6px 14px; }
.wk-dc-banner { display: flex; gap: 10px; margin-top: 14px; padding: 10px 14px; border-radius: 8px; border: 1px solid var(--warning-border); background: var(--warning-bg);
                font-size: 13.5px; line-height: 1.6; color: var(--text-1); }
.wk-dc-banner > .ic { flex: none; margin-top: 3px; font-size: 15px; color: var(--warning-solid); }
.wk-dc-banner b.h { color: var(--warning); font-weight: 650; }
.wk-dc-banner .lg { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; margin-top: 6px; font-size: 12.5px; color: var(--text-2); }
.wk-dc-banner .lg > span { white-space: nowrap; }
.wk-dc-banner .lg .go { margin-left: auto; padding: 0; border: 0; background: transparent; font: inherit; color: var(--brand); cursor: pointer; }
.wk-dc-body h2 .no { color: var(--text-3); font-weight: 600; margin-right: 6px; font-variant-numeric: tabular-nums; }
.wk-dc-sec { scroll-margin-top: 12px; }
.wk-dc-body h3 { margin: 16px 0 6px; font-size: 15px; font-weight: 650; }
.wk-dc-body ul { margin: 0 0 12px; padding-left: 20px; }
.wk-dc-code { margin: 0 0 12px; padding: 10px 12px; border-radius: 6px; background: var(--fill-inset); overflow-x: auto;
              font: 12.5px/1.6 ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; }
.wk-dc-unwritten { color: var(--text-3); font-size: 14px; }
.wk-dc-tag { display: inline-flex; align-items: center; gap: 5px; margin-left: 10px; height: 20px; padding: 0 8px; border-radius: 999px; background: var(--fill-muted);
             font-size: 11.5px; font-weight: 500; color: var(--text-2); vertical-align: 3px; letter-spacing: 0; }
.wk-dc-tag .ic { font-size: 11px; }
/* a sentence's marks: no source (amber), not verified (red), withdrawn (struck) — the status dots' colours,
   and the strike "Rejected by you" already uses */
.wk-s-nosrc { background: var(--warning-bg); box-shadow: inset 0 -1.5px 0 var(--warning-solid); border-radius: 2px; cursor: help; }
.wk-s-bad { background: var(--error-bg); box-shadow: inset 0 -1.5px 0 var(--error-solid); border-radius: 2px; cursor: help; }
.wk-s-gone { color: var(--text-3); text-decoration: line-through; text-decoration-color: var(--text-3); cursor: help; }
.wk-s-lab { display: inline-block; margin: 0 2px 0 3px; padding: 0 5px; border-radius: 4px; font-size: 11px; line-height: 16px; font-weight: 600; vertical-align: 2px;
            white-space: nowrap; letter-spacing: 0; }
.wk-s-lab.nosrc { background: var(--warning-bg); color: var(--warning); border: 1px solid var(--warning-border); }
.wk-s-lab.bad { background: var(--error-bg); color: var(--error); border: 1px solid var(--error-border); }
.wk-s-lab.gone { background: var(--fill-muted); color: var(--text-2); }
.wk-fn-n.x { color: var(--error); text-decoration: line-through; }
.wk-fn-n.x.on { background: var(--error-solid); color: #fff; }
.wk-dc-tip { max-width: 300px; font-size: 12.5px; line-height: 1.55; }
.wk-dc-tip b { font-weight: 650; }

/* a footnote's card: the words, where they are, what they came through */
.wk-fn2 { width: 440px; max-width: 100%; }
.wk-fn2 .k { display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 600; color: var(--text-2); }
.wk-fn2 .k .num { font: 600 11.5px/18px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--brand); }
.wk-fn2 .k .ic { display: inline-flex; font-size: 13px; color: var(--text-3); }
.wk-fn2 .k .ver { margin-left: auto; color: var(--success); font-weight: 600; font-size: 12px; white-space: nowrap; }
.wk-fn2 .k .ver.x { color: var(--error); }
.wk-fn2 .k .dim { font-weight: 400; color: var(--text-3); }
.wk-fn2 .olc-quote { margin-top: 8px; font-size: 13.5px; line-height: 1.6; padding: 8px 10px; }
.wk-fn2 .olc-quote.x .wk-quote-text { color: var(--text-2); text-decoration: line-through; text-decoration-color: var(--error); }
.wk-fn2 .xnote { margin-top: 6px; font-size: 12.5px; line-height: 1.55; color: var(--error); }
.wk-fn2 .code { margin-top: 8px; border-radius: 6px; background: var(--fill-inset); overflow: hidden; font: 11.5px/1.65 ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; }
.wk-fn2 .code .ln { display: grid; grid-template-columns: 34px minmax(0, 1fr); }
.wk-fn2 .code .ln .i { padding-right: 8px; text-align: right; color: var(--text-4); user-select: none; }
.wk-fn2 .code .ln .c { white-space: pre; overflow: hidden; text-overflow: ellipsis; color: var(--text-1); padding-right: 8px; }
.wk-fn2 .code .ln.q { background: color-mix(in srgb, var(--success-bg) 85%, transparent); }
.wk-fn2 .code .ln.q .i { color: var(--success); }
.wk-fn2 .code .ln.cut .c { color: var(--text-3); }
.wk-fn2 .loc { display: flex; align-items: baseline; gap: 6px; margin-top: 8px; font-size: 12.5px; line-height: 1.55; color: var(--text-2); }
.wk-fn2 .loc .ic { flex: none; display: inline-flex; font-size: 12px; color: var(--text-3); transform: translateY(1px); }
.wk-fn2 .loc .tx { min-width: 0; overflow-wrap: anywhere; }
.wk-fn2 .loc a { color: var(--brand); text-decoration: none; white-space: nowrap; }
.wk-fn2 .loc .mono { font: 12px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-1); }
.wk-fn2 .via { display: flex; align-items: center; gap: 7px; margin-top: 9px; padding-top: 9px; border-top: 1px solid var(--border-subtle); font-size: 12.5px; color: var(--text-3); min-width: 0; }
.wk-fn2 .via .lb { flex: none; }
.wk-fn2 .via .wk-kind { flex: none; width: 18px; height: 18px; font-size: 11px; }
.wk-fn2 .via .t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-1); font-weight: 600; text-decoration: none; }
.wk-fn2 .via .tdp-badge { flex: none; font-size: 11px; line-height: 16px; padding: 0 6px; margin-left: auto; }
.wk-fn2.sheet { width: auto; padding: 8px 16px 16px; }
.wk-fn2.sheet .olc-quote { padding: 9px 11px; font-size: 15px; }
.wk-fn2.sheet .loc { font-size: 13.5px; }
/* the footnotes at the end: one row a footnote — kind, where, the check; the words; what they came through */
.wk-fn2-list { margin-top: 30px; }
.wk-fn2-list > h3 { margin: 0 0 4px; font-size: 15px; font-weight: 650; color: var(--text-1); display: flex; align-items: baseline; gap: 8px; }
.wk-fn2-list > h3 small { font-size: 12.5px; font-weight: 400; color: var(--text-3); }
.wk-fn2-row { display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 8px; padding: 8px 0 9px; border-bottom: 1px solid var(--border-subtle); font-size: 13px; line-height: 1.55; }
.wk-fn2-row.on { background: var(--brand-tint); border-radius: 6px; margin: 0 -8px; padding: 8px 8px 9px; border-bottom-color: transparent; }
.wk-fn2-row .no { text-align: right; color: var(--text-3); font-variant-numeric: tabular-nums; }
.wk-fn2-row .main { min-width: 0; }
.wk-fn2-row .l1 { display: flex; align-items: center; gap: 7px; min-width: 0; }
.wk-fn2-row .kd { flex: none; display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 7px; border-radius: 4px; background: var(--fill-muted); font-size: 11.5px;
                  color: var(--text-2); white-space: nowrap; }
.wk-fn2-row .kd.s { background: var(--brand-tint); color: var(--brand-strong); }
.wk-fn2-row .kd .anticon { font-size: 11px; }
.wk-fn2-row .loc { min-width: 0; padding: 0; border: 0; background: transparent; font: inherit; text-align: left; cursor: pointer; overflow: hidden; text-overflow: ellipsis;
                   white-space: nowrap; color: var(--text-1); text-decoration: underline; text-decoration-color: var(--border); text-underline-offset: 3px; }
.wk-fn2-row .loc.mono { font: 12px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; }
.wk-fn2-row .ver { flex: none; margin-left: auto; font-size: 12px; font-weight: 600; color: var(--success); white-space: nowrap; }
.wk-fn2-row .ver.x { color: var(--error); }
.wk-fn2-row .q { margin-top: 3px; color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-fn2-row .q.x { text-decoration: line-through; text-decoration-color: var(--error); }
.wk-fn2-row .via { margin-top: 2px; font-size: 12px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wk-fn2-row .via b { font-weight: 600; color: var(--text-2); }
.wk-fn2-list .wk-more { padding: 8px 0 0 34px; }
.wk-dc-refs { flex: none; margin-left: 6px; font-size: 11.5px; color: var(--brand); font-weight: 500; }

/* Browse and the A–Z index, by document */
.wk-browse-cat > h2 .no, .wk-browse-doc .h .no { font: 600 12.5px ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace; color: var(--text-3); }
.wk-browse-cat > h2 .no { font-size: 15px; }
.wk-browse-q { margin: 0 0 4px; font-size: 12.5px; color: var(--text-3); }
.wk-browse-doc .h .n .st.warn { color: var(--warning); }
.wk-browse-doc .h .n .st.muted { color: var(--text-3); }
.wk-browse-list.secs a .sn { flex: none; min-width: 14px; color: var(--text-3); font-size: 12px; font-variant-numeric: tabular-nums; }
.wk-browse-list.secs a.todo .tt { color: var(--text-3); }

/* the home: the Plan card over Review, and the phone's second banner */
.wk-plan-card-text { font-size: 13px; line-height: 1.6; color: var(--text-2); }
.wk-plan-card-link { font-size: 12.5px; color: var(--brand); text-decoration: none; }
.wk-rv-row .wk-op.plan { font-size: 10px; }
.wk-banner.wk-plan-banner { margin-top: 10px; }
.wk-banner.wk-plan-banner.blue { border-color: var(--brand-border); background: var(--brand-tint); }
.wk-banner.wk-plan-banner.blue .wk-dot { background: var(--brand); }

/* narrower than the app's desktop layout: the phone mocks 22, 24, 26, 28 */
@media (max-width: 960px) {
  .wk-plan-card { display: none; }
  .wk-pl-head { grid-template-columns: minmax(0, 1fr); grid-template-areas: "title" "meta" "acts"; }
  .wk-pl-titlerow { justify-content: space-between; }
  .wk-pl-titlerow .t-title { font-size: 24px; line-height: 1.35; }
  .wk-pl-acts { margin-top: 12px; }
  .wk-pl-acts > .ant-btn:not(.ant-btn-icon-only) { flex: 1; height: 40px; }
  .wk-pl-ck { grid-template-columns: 16px minmax(0, 1fr); }
  .wk-pl-ck .r, .wk-pl-errs { grid-column: 2; }
  .wk-pl-err { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .wk-pl-empty { padding: 28px 20px 22px; }
  .wk-pl-empty .ant-btn { width: 100%; height: 40px; }
  .wk-pl-cat-h .q { display: none; }
  .wk-pl-doc.phone { grid-template-columns: 34px minmax(0, 1fr) 12px; gap: 6px; padding: 10px 2px 11px; text-decoration: none; color: inherit; }
  .wk-pl-doc.phone .main { display: block; }
  .wk-pl-doc.phone .main > .t { font-size: 15px; line-height: 21px; }
  .wk-pl-doc.phone .main > .q { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; font-size: 13px; }
  .wk-pl-doc.phone .l3 { display: block; margin-top: 3px; font-size: 12.5px; color: var(--text-3); }
  .wk-pl-doc.phone .chev, .wk-pl-sec.phone .chev { font-size: 11px; color: var(--text-4); }
  .wk-pl-kv { grid-template-columns: minmax(0, 1fr); gap: 2px; margin-top: 12px; }
  .wk-pl-kv > .k { margin-top: 8px; font-size: 12px; }
  .wk-pl-sec.phone { grid-template-columns: 22px minmax(0, 1fr) 12px; gap: 6px; padding: 9px 2px 10px; text-decoration: none; color: inherit; }
  .wk-pl-sec.phone > .t { font-size: 14.5px; line-height: 20px; }
  .wk-pl-sec.phone .cov { white-space: normal; font-size: 12.5px; }
  .wk-pl-sec.gone.phone { display: block; margin: 4px -4px; }
  .wk-pl-sec.gone.phone .why { display: block; margin-top: 2px; }
  .wk-pl-src { margin: 12px 0 0; }
  .wk-pl-src .cond { grid-template-columns: minmax(0, 1fr); }
  .wk-pl-prop .card-actions { flex-wrap: wrap; }
  .wk-pl-prop .card-actions .grow { display: none; }
  .wk-pl-prop .card-actions .note { flex-basis: 100%; }
  .wk-pl-new .row { grid-template-columns: 26px minmax(0, 1fr); }
  .wk-pl-new .row .ty { display: none; }
  .wk-pl-esec { grid-template-columns: 16px 22px minmax(0, 1fr) 110px 22px; }
  .wk-dc-scope { grid-template-columns: minmax(0, 1fr); gap: 2px; padding: 10px 12px; }
  .wk-dc-scope > .k { font-size: 12px; }
  .wk-dc-scope > .v.q { font-size: 14px; }
  .wk-dc-fold { margin: 6px -12px -10px; padding: 9px 12px; }
  .wk-dc-banner { font-size: 13.5px; padding: 10px 12px; }
  .wk-dc-banner .lg .go { margin-left: 0; }
  .wk-fn2-row { grid-template-columns: 24px minmax(0, 1fr); padding: 9px 2px 10px; }
  .wk-fn2-row .no { text-align: left; }
  .wk-browse-doc .h .n { margin-left: auto; }
}

/* ── The wiki in a conversation: the context a session was handed ──────────────────────────────
   Mock 05 (docs/mocks/wiki/05-session-touchpoints). One of its panels needs rules of its own: the
   entries under the task start card's folded Wiki context line. The link card borrows the Wiki's
   own marks and the search palette borrows `.ssearch-*`, so neither has a block here beyond the
   group heading. */

.wkctx { margin-top: 6px; }
.wkctx-list {
  list-style: none;
  margin: 0;
  padding: 6px 8px;
  border-radius: 8px;
  background: var(--fill-inset);
}
.wkctx-row { display: flex; align-items: center; gap: 7px; height: 23px; font-size: 12.5px; }
/* One word wide, the kind column, so the titles line up whatever they are filed as. */
.wkctx-kind { flex: none; width: 70px; color: var(--text-3); font-size: 12px; }
.wkctx-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--brand);
  text-decoration: none;
}
a.wkctx-title:hover { text-decoration: underline; }
.wkctx-foot { margin-top: 6px; font-size: 11.5px; line-height: 1.5; color: var(--text-3); }

/* The ⌘K palette's Wiki group: one heading, then rows that are `.ssearch-row`s like any other, so
   the cursor, the title line and the meta line stay the palette's rather than a second palette's. */
.wk-pal-group {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px 3px;
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: .03em;
  text-transform: uppercase;
  color: var(--text-3);
}
.wk-pal-group .n { font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text-4); }
.wk-pal-group + .ssearch-row { margin-top: 0; }
/* The wiki's rows put their own bits in the palette's slots: a kind tile where a session has its
   status glyph, and the anchor's tick where a hit says what it matched on. */
.ssearch-row > .wk-kind { flex: none; }
.ssearch-meta .ok { color: var(--success); }

@media (max-width: 600px) {
  .wkctx-kind { width: 58px; }
}

/* Background agent / workflow progress (TaskProgressBlock): the agents by phase, then the totals.
   Opens under a Workflow card in the conversation and under its row in the tray. */
.agent-progress {
  border-top: 1px dashed var(--border-subtle);
  padding: 4px 12px 8px 38px;
  background: var(--bg-subtle);
}
.agent-progress-head {
  display: flex;
  gap: 4px;
  margin: 8px 0 3px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--text-3);
}
.agent-progress-count {
  font-weight: 400;
  letter-spacing: 0;
}
.agent-progress-agent {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 2px 0;
  font-size: 12px;
}
button.agent-progress-agent {
  width: 100%;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
button.agent-progress-agent:hover {
  background: var(--bg-hover);
}
.agent-progress-caret {
  flex: none;
  font-size: 10px;
  color: var(--text-3);
}
.agent-progress-transcript {
  margin: 4px 0 8px 8px;
  padding-left: 8px;
  border-left: 1px solid var(--border-subtle);
}
.chat-workflow-source > summary {
  padding: 6px 12px;
  font-size: 12px;
  color: var(--text-3);
  cursor: pointer;
}
.agent-progress-label {
  flex: none;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color: var(--text-1);
}
.agent-progress-now {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color: var(--text-3);
}
.agent-progress-detail {
  margin-left: auto;
  white-space: nowrap;
  color: var(--text-3);
}
.agent-progress-queued {
  flex: none;
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1.5px solid var(--text-4);
}
.agent-progress-foot:first-child {
  margin-top: 0;
  padding-top: 0;
  border-top: none;
}
.agent-progress-foot {
  margin-top: 6px;
  padding-top: 5px;
  border-top: 1px solid var(--border-subtle);
  font-size: 11.5px;
  color: var(--text-3);
}
.bg-shell-detail .agent-progress {
  border-top: none;
  padding: 2px 2px 4px;
  background: transparent;
}
.bg-shell-kind {
  flex: none;
  padding: 0 5px;
  border-radius: 4px;
  font-size: 10.5px;
  color: var(--text-2);
  background: var(--bg-hover);
}
.bg-shell-sub {
  padding: 0 10px 6px 34px;
  font-size: 11.5px;
  color: var(--text-3);
}

.wt-recovery { margin: 0 12px 12px; padding: 14px; border: 1px solid var(--border); border-radius: 8px; background: var(--bg-subtle); font-size: 12px; overflow-wrap: anywhere; }
.wt-recovery p { margin: 10px 0; color: var(--text-2); }
.wt-recovery summary { cursor: pointer; margin: 10px 0; }
.wt-recovery-histories { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.wt-recovery-histories > :only-child { grid-column: 1 / -1; }
.wt-recovery-route code { font-size: 11px; }
.wt-recovery-origin.is-local { color: var(--warning); font-weight: 600; }
.wt-recovery-histories small { display: block; opacity: .7; margin-bottom: 8px; }
.wt-recovery pre { white-space: pre-wrap; max-height: 400px; overflow: auto; font-size: 11px; }
.wt-recovery-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
.wt-recovery-actions button { padding: 5px 10px; border-radius: 6px; cursor: pointer; }
.wt-recovery-actions button:not(.wt-merge-btn) { border: 1px solid var(--border); background: var(--bg); color: var(--text-1); font: inherit; }
.wt-recovery-actions button:disabled { opacity: .55; cursor: default; }
.wt-recovery-repair-status { display: flex; align-items: center; gap: 10px; width: 100%; margin: 10px 0 0; padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--bg-raised); color: var(--text-1); text-align: left; cursor: pointer; font: inherit; }
.wt-recovery-repair-status.is-running { border-color: color-mix(in srgb, var(--brand) 38%, var(--border)); background: color-mix(in srgb, var(--brand) 8%, var(--bg-raised)); }
.wt-recovery-repair-status.is-failed { border-color: color-mix(in srgb, var(--error) 38%, var(--border)); }
.wt-recovery-repair-status-copy { display: grid; gap: 2px; min-width: 0; flex: 1; }
.wt-recovery-repair-status-copy strong, .wt-recovery-repair-status-copy small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wt-recovery-repair-status-copy small { color: var(--text-2); }
.wt-recovery-repair-chevron { color: var(--text-2); font-size: 22px; line-height: 1; }
.wt-recovery-repair-hint { margin: 5px 0 0 !important; font-size: 11px; }
.wt-recovery-repair-error { color: var(--error) !important; }
@media (max-width: 680px) { .wt-recovery-histories { grid-template-columns: 1fr; } }

/* Timed pauses keep identity and quota visible while showing when the account returns. */
.re-row.account-paused {
  background: color-mix(in srgb, var(--warning, #d89614) 7%, transparent);
}
.account-pause-remaining {
  margin-top: 4px;
  font-size: 11px;
  color: var(--text-3);
}
.re-act:has(.account-pause-actions) {
  flex-wrap: wrap;
}
.account-pause-actions {
  display: inline-flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 4px;
}
.account-pause-name {
  margin: 14px 0 10px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.account-pause-copy {
  color: var(--text-2);
  line-height: 1.65;
}
.account-pause-scope {
  padding: 10px 12px;
  margin: 12px 0;
  background: color-mix(in srgb, var(--warning, #d89614) 10%, transparent);
  border-radius: 8px;
  font-size: 13px;
}
.account-pause-durations {
  display: flex;
  margin: 20px 0 16px;
}
.account-pause-durations .ant-radio-button-wrapper {
  flex: 1;
  text-align: center;
}
.account-pause-custom {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}
.account-pause-custom > span,
.account-pause-preview {
  font-size: 12px;
  color: var(--text-3);
}
@media (max-width: 700px) {
  .re-row:has(.account-pause-actions) > .re-act {
    grid-column: 1 / -1;
    grid-row: auto;
    justify-content: flex-start;
    margin-left: 38px;
  }
}

/* Orbit control foundations. The existing index.css palette remains authoritative
   for surfaces/text/borders. These additional roles come from P0.2 computed styles,
   including darkAlgorithm output (not the brand seed). See this directory's README.
   Variables only: no second reset, global control styles, or new stacking context. */
:root {
  --orbit-font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Hiragino Sans GB',
    'Microsoft YaHei', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --orbit-font-size: 14px;
  --orbit-line-height: 22px;
  --orbit-control-height: 32px;
  --orbit-control-height-sm: 24px;
  --orbit-control-height-lg: 40px;
  --orbit-radius: 6px;
  --orbit-radius-sm: 4px;
  --orbit-radius-popup: 8px;
  --orbit-radius-dialog: 10px;
  --orbit-control-padding-inline: 15px;
  --orbit-control-padding-inline-sm: 7px;
  --orbit-control-gap: 8px;
  --orbit-control-primary: #3370ff;
  --orbit-control-primary-hover: #5c92ff;
  --orbit-control-primary-active: #2152d9;
  --orbit-control-link-hover: #85b1ff;
  --orbit-control-active-bg: rgba(0, 0, 0, 0.15);
  --orbit-control-error: #f54a45;
  --orbit-control-error-hover: #ff7a70;
  --orbit-control-error-active: #cf3030;
  --orbit-control-error-bg: #fff3f0;
  --orbit-control-error-bg-active: #ffcac2;
  --orbit-control-error-outline: rgba(255, 55, 5, 0.06);
  --orbit-input-error-hover: #ffa399;
  --orbit-input-focus-shadow: 0 0 0 2px rgba(5, 122, 255, 0.06);
  --orbit-input-invalid-shadow: 0 0 0 2px var(--orbit-control-error-outline);
  --orbit-badge-default-bg: #f5f5f5;
  --orbit-badge-info-bg: #f0f7ff;
  --orbit-badge-success: #2ea121;
  --orbit-badge-success-bg: #d7e0d3;
  --orbit-badge-warning: #ff8800;
  --orbit-badge-warning-bg: #fff7e6;
  --orbit-badge-blue: #0958d9;
  --orbit-badge-blue-bg: #e6f4ff;
  --orbit-control-on-primary: #ffffff;
  --orbit-control-hover-bg: rgba(0, 0, 0, 0.04);
  --orbit-control-disabled-text: rgba(0, 0, 0, 0.25);
  --orbit-control-disabled-bg: rgba(0, 0, 0, 0.04);
  --orbit-control-disabled-border: #d9d9d9;
  --orbit-focus-color: #adceff;
  --orbit-focus-width: 3px;
  --orbit-focus-offset: 1px;
  --orbit-bg-elevated: #ffffff;
  --orbit-border-split: rgba(17, 42, 80, 0.08);
  --orbit-option-selected-bg: #d6e8ff;
  --orbit-choice-chip-bg: rgba(0, 0, 0, .06);
  --orbit-menu-selected-bg: #f0f7ff;
  --orbit-empty-border: #d9d9d9;
  --orbit-empty-fill: #fafafa;
  --orbit-tooltip-bg: rgba(0, 0, 0, 0.85);
  --orbit-filter-popover: drop-shadow(0 6px 16px rgba(0, 0, 0, .08)) drop-shadow(0 3px 6px rgba(0, 0, 0, .12)) drop-shadow(0 9px 28px rgba(0, 0, 0, .05));
  --orbit-shadow-popup: 0 6px 16px 0 rgba(0, 0, 0, 0.08),
    0 3px 6px -4px rgba(0, 0, 0, 0.12), 0 9px 28px 8px rgba(0, 0, 0, 0.05);
  --orbit-shadow-drawer-right: -6px 0 16px 0 rgba(0, 0, 0, 0.08),
    -3px 0 6px -4px rgba(0, 0, 0, 0.12), -9px 0 28px 8px rgba(0, 0, 0, 0.05);
  --orbit-shadow-drawer-bottom: 0 -6px 16px 0 rgba(0, 0, 0, 0.08),
    0 -3px 6px -4px rgba(0, 0, 0, 0.12), 0 -9px 28px 8px rgba(0, 0, 0, 0.05);
}

:root[data-theme='dark'] {
  --orbit-control-primary: #2e62dc;
  --orbit-control-primary-hover: #5585e8;
  --orbit-control-primary-active: #2850ad;
  --orbit-control-link-hover: #223d7e;
  --orbit-control-active-bg: rgba(255, 255, 255, 0.18);
  --orbit-control-error: #cf726c;
  --orbit-control-error-hover: #e5a19a;
  --orbit-control-error-active: #a35c57;
  --orbit-control-error-bg: #291b1b;
  --orbit-control-error-bg-active: #563533;
  --orbit-control-error-outline: rgba(38, 4, 0, 0.41);
  --orbit-input-error-hover: #774642;
  --orbit-input-focus-shadow: 0 0 0 2px rgba(1, 58, 182, 0.33);
  --orbit-badge-default-bg: #3c3c3f;
  --orbit-badge-info-bg: #14192c;
  --orbit-badge-success: #399c50;
  --orbit-badge-success-bg: #152119;
  --orbit-badge-warning: #c18d35;
  --orbit-badge-warning-bg: #271f15;
  --orbit-badge-blue: #3c89e8;
  --orbit-badge-blue-bg: #111a2c;
  --orbit-control-hover-bg: rgba(255, 255, 255, 0.08);
  --orbit-control-disabled-text: rgba(255, 255, 255, 0.25);
  --orbit-control-disabled-bg: rgba(255, 255, 255, 0.08);
  --orbit-control-disabled-border: #5b5b6c;
  --orbit-focus-color: #1d305b;
  --orbit-bg-elevated: #343437;
  --orbit-border-split: rgba(223, 223, 226, 0.05);
  --orbit-option-selected-bg: #223d7e;
  --orbit-choice-chip-bg: rgba(255, 255, 255, .12);
  --orbit-menu-selected-bg: #1d305b;
  --orbit-empty-border: #515154;
  --orbit-empty-fill: #333336;
  --orbit-tooltip-bg: #5b5b6c;
  --orbit-filter-popover: drop-shadow(0 6px 16px rgba(255, 255, 255, .016)) drop-shadow(0 3px 6px rgba(255, 255, 255, .024)) drop-shadow(0 9px 28px rgba(255, 255, 255, .01));
  --orbit-shadow-popup: 0 6px 16px 0 rgba(255, 255, 255, 0.016),
    0 3px 6px -4px rgba(255, 255, 255, 0.024), 0 9px 28px 8px rgba(255, 255, 255, 0.01);
  --orbit-shadow-drawer-right: -6px 0 16px 0 rgba(255, 255, 255, 0.016),
    -3px 0 6px -4px rgba(255, 255, 255, 0.024), -9px 0 28px 8px rgba(255, 255, 255, 0.01);
  --orbit-shadow-drawer-bottom: 0 -6px 16px 0 rgba(255, 255, 255, 0.016),
    0 -3px 6px -4px rgba(255, 255, 255, 0.024), 0 -9px 28px 8px rgba(255, 255, 255, 0.01);
}

.orbit-button {
  box-sizing: border-box;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--orbit-control-gap);
  height: var(--orbit-control-height);
  padding: 0 var(--orbit-control-padding-inline);
  border: 1px solid var(--border);
  border-radius: var(--orbit-radius);
  color: var(--text-1);
  background: var(--bg-raised);
  font-family: var(--orbit-font-family);
  font-size: var(--orbit-font-size);
  font-weight: 400;
  line-height: var(--orbit-line-height);
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  outline: none;
  transition: color .2s, background-color .2s, border-color .2s, opacity .2s;
}
.orbit-button-small { height: var(--orbit-control-height-sm); padding-inline: var(--orbit-control-padding-inline-sm); border-radius: var(--orbit-radius-sm); }
.orbit-button-large { height: var(--orbit-control-height-lg); border-radius: var(--orbit-radius-popup); font-size: 16px; line-height: 1.5714285714; }
.orbit-button-icon-only { width: var(--orbit-control-height); padding-inline: 0; }
.orbit-button-icon-only.orbit-button-small { width: var(--orbit-control-height-sm); }
.orbit-button-icon-only.orbit-button-large { width: var(--orbit-control-height-lg); }
.orbit-button-icon { display: inline-flex; align-items: center; }
.orbit-button-icon > .anticon { vertical-align: middle; }
.orbit-button-icon > .anticon::before { content: '\00a0'; display: inline-block; width: 0; }
.orbit-button:hover:where(:not(:disabled)) { color: var(--orbit-control-primary-hover); border-color: var(--orbit-control-primary-hover); }
.orbit-button:active:where(:not(:disabled)) { color: var(--orbit-control-primary-active); border-color: var(--orbit-control-primary-active); }
.orbit-button-primary { color: var(--orbit-control-on-primary); background: var(--orbit-control-primary); border-color: transparent; }
.orbit-button-primary:hover:where(:not(:disabled)) { color: var(--orbit-control-on-primary); background: var(--orbit-control-primary-hover); border-color: transparent; }
.orbit-button-primary:active:where(:not(:disabled)) { color: var(--orbit-control-on-primary); background: var(--orbit-control-primary-active); border-color: transparent; }
.orbit-button-text, .orbit-button-link { background: transparent; border-color: transparent; }
.orbit-button-text:hover:where(:not(:disabled)) { color: var(--text-1); background: var(--orbit-control-hover-bg); border-color: transparent; }
.orbit-button-text:active:where(:not(:disabled)) { color: var(--text-1); background: var(--orbit-control-active-bg); border-color: transparent; }
.orbit-button-link { color: var(--orbit-control-primary); }
.orbit-button-link:hover:where(:not(:disabled)) { color: var(--orbit-control-link-hover); border-color: transparent; }
.orbit-button-link:active:where(:not(:disabled)) { color: var(--orbit-control-primary-active); border-color: transparent; }
.orbit-button-danger { color: var(--orbit-control-error); border-color: var(--orbit-control-error); }
.orbit-button-danger.orbit-button-default { box-shadow: 0 2px 0 var(--orbit-control-error-outline); }
.orbit-button-danger:hover:where(:not(:disabled)) { color: var(--orbit-control-error-hover); border-color: var(--orbit-control-error-hover); }
.orbit-button-danger:active:where(:not(:disabled)) { color: var(--orbit-control-error-active); border-color: var(--orbit-control-error-active); }
.orbit-button-danger.orbit-button-primary { color: var(--orbit-control-on-primary); background: var(--orbit-control-error); border-color: transparent; box-shadow: 0 2px 0 var(--orbit-control-error-outline); }
.orbit-button-danger.orbit-button-primary:hover:where(:not(:disabled)) { background: var(--orbit-control-error-hover); }
.orbit-button-danger.orbit-button-primary:active:where(:not(:disabled)) { background: var(--orbit-control-error-active); }
.orbit-button-danger.orbit-button-text, .orbit-button-danger.orbit-button-link { border-color: transparent; }
.orbit-button-danger.orbit-button-text:hover:where(:not(:disabled)) { background: var(--orbit-control-error-bg); }
.orbit-button-danger.orbit-button-text:active:where(:not(:disabled)) { background: var(--orbit-control-error-bg-active); }
.orbit-button:focus-visible { outline: var(--orbit-focus-width) solid var(--orbit-focus-color); outline-offset: var(--orbit-focus-offset); }
.orbit-button[data-loading] { opacity: .65; cursor: default; }
.orbit-button:disabled {
  color: var(--orbit-control-disabled-text);
  background: var(--orbit-control-disabled-bg);
  border-color: var(--orbit-control-disabled-border);
  box-shadow: none;
  cursor: not-allowed;
}
.orbit-button-text:disabled, .orbit-button-link:disabled { background: transparent; border-color: transparent; }
@media (prefers-reduced-motion: reduce) { .orbit-button { transition: none; } }

.orbit-overlay-backdrop { position: fixed; inset: 0; width: 100vw; background: rgba(0, 0, 0, .45); }
.orbit-overlay[hidden], .orbit-overlay-viewport[hidden], .orbit-overlay-backdrop[hidden] { display: none; }
.orbit-overlay-viewport { position: fixed; inset: 0; width: 100vw; overflow: auto; overscroll-behavior: contain; }
.orbit-dialog-viewport, .orbit-confirm-viewport { padding: 100px 16px 24px; }
.orbit-overlay {
  position: relative; box-sizing: border-box; margin: 0 auto;
  max-width: 100%; color: var(--text-1); background: var(--orbit-bg-elevated);
  font-family: var(--orbit-font-family); font-size: var(--orbit-font-size); line-height: var(--orbit-line-height);
  box-shadow: var(--orbit-shadow-popup); outline: none; overflow-wrap: break-word;
}
.orbit-dialog, .orbit-confirm { padding: 20px 24px; border-radius: var(--orbit-radius-dialog); }
.orbit-overlay-header { margin-bottom: 8px; }
.orbit-overlay-title { margin: 0; color: var(--text-1); font-size: 16px; font-weight: 600; line-height: 24px; }
.orbit-overlay-description { margin: 0; }
.orbit-overlay-footer { display: flex; justify-content: flex-end; gap: 8px; margin-top: 12px; }
.orbit-overlay-close {
  display: inline-flex; align-items: center; justify-content: center; position: absolute;
  top: 12px; right: 12px; width: 32px; height: 32px; padding: 0; border: 0; border-radius: 4px;
  color: var(--text-3); background: transparent; font-size: 16px; line-height: 1; cursor: pointer;
}
